import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const projectRoot = path.resolve(__dirname, '..');

export const EMBEDDED_CONTENT = {"content/protocols/01-water-purification.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"흙탕물을 깨끗한 식수로 바꾸는 법 (숯·모래 정수기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"고여 있거나 흐린 야생 물을 그냥 마시면 심한 배탈과 설사로 사흘 안에 위험해질 수 있습니다. 주변에서 구한 숯과 모래, 자갈을 순서대로 쌓아 흙먼지와 나쁜 독소를 먼저 걸러낸 뒤, 불에 팔팔 끓여 세균까지 없애는 가장 확실한 방법입니다.\",\n  \"timeRequired\": \"15분\",\n  \"successRate\": \"99.8% (걸러낸 뒤 끓였을 때)\",\n  \"difficulty\": \"쉬움 (누구나 가능)\",\n  \"outputPerHour\": \"1시간에 약 1.5리터\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"잘게 부순 모닥불 숯\",\n      \"desc\": \"불을 피우고 남은 까만 숯을 콩알 크기로 부숴 준비합니다. 물속의 나쁜 독소와 불쾌한 냄새를 빨아들입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"깨끗한 강모래와 작은 자갈\",\n      \"desc\": \"물에 한 번 씻어낸 고운 모래와 작은 조약돌입니다. 흙먼지와 나뭇잎 같은 찌꺼기를 걸러냅니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"대나무 통 또는 나무껍질 깔때기\",\n      \"desc\": \"속이 빈 대나무 마디를 뚫거나 자작나무 껍질을 고깔 모양으로 말아 물을 부을 통으로 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"나무통 아랫부분을 천이나 이끼로 막기\",\n      \"description\": \"속을 뚫은 대나무 통이나 고깔 모양으로 만 나무껍질 통을 거꾸로 세웁니다. 물이 빠져나갈 가장 아랫부분 입구에 깨끗한 천 조각이나 물이끼를 단단히 채워 넣어, 위에 올릴 숯과 모래가 쏟아지지 않게 막아줍니다.\",\n      \"actionNote\": \"> 핵심 팁: 아랫부분 마개를 너무 느슨하게 막으면 숯가루가 물과 함께 다 빠져나갑니다. 손가락으로 꾹 눌러 단단히 고정하세요.\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"흙탕물 붓기\",\n        \"1. 자갈 (큰 먼지 걸러냄)\",\n        \"2. 고운 모래 (작은 먼지)\",\n        \"숯가루\",\n        \"3. 숯가루 (독소·냄새 제거)\",\n        \"4. 천·이끼 마개 (입구 막기)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"아래부터 숯·모래·자갈 순서로 차곡차곡 쌓기\",\n      \"description\": \"막아둔 입구 바로 위부터 순서대로 재료를 채웁니다. 맨 아래에 잘게 부순 숯(약 6cm 두께)을 깔고, 그 위에 고운 모래(약 5cm 두께), 맨 위에 작은 자갈(약 3cm 두께)을 차곡차곡 올립니다.\",\n      \"actionNote\": \"> 핵심 원리: 맨 위의 자갈이 나뭇잎 같은 큰 찌꺼기를 먼저 막아주고, 모래가 고운 흙먼지를 잡아주며, 마지막으로 숯의 미세한 구멍들이 독소와 나쁜 냄새를 빨아들입니다.\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[첫 1~2컵 버리기]\",\n        \"검은 숯가루 섞인 물\",\n        \"→\",\n        \"[맑은 물 받아 쓰기]\",\n        \"투명해진 깨끗한 물\",\n        \"떨어지는 속도: 1초에 1~2방울\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"흙탕물을 천천히 붓고 맑은 물 받아서 끓이기\",\n      \"description\": \"맨 위 자갈 층에 흙탕물을 천천히 붓습니다. 아래쪽 입구에서 물이 1초에 한두 방울씩 똑똑 떨어지도록 기다린 뒤, 투명하게 걸러진 물을 그릇에 받아 모닥불에서 팔팔 끓입니다.\",\n      \"actionNote\": \"> 주의할 점: 처음 빠져나오는 물 한두 컵(약 250ml)에는 검은 숯가루가 섞여 나오니 마시지 말고 버리세요. 물이 완전히 투명해지면 그때부터 받아서 끓이면 됩니다.\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C 불에 끓이기\",\n        \"100°C\",\n        \"3분 이상 끓이기\",\n        \"세균 99.9% 제거\",\n        \"팔팔 끓이는 시간 (분)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 맑게 걸러진 물이라고 끓이지 않고 바로 마시기\",\n    \"description\": \"숯과 모래 필터는 흙먼지와 나쁜 화학 성분만 걸러낼 뿐, 눈에 보이지 않는 세균이나 기생충 알은 그대로 통과합니다. 물이 아무리 깨끗하고 투명해 보여도 그냥 마시면 배탈과 설사로 몸속 수분을 다 잃게 됩니다.\",\n    \"consequence\": \"결과: 반드시 큰 거품이 올라올 때까지 최소 1~3분 이상 팔팔 끓인 뒤 식혀서 마셔야 안전합니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"3중 여과 숯·모래 원시 정수기 완성 형태\",\n    \"description\": \"나뭇가지 삼각대에 매단 원통 용기 내부에 숯, 고운 모래, 자갈, 섬유 필터가 5중으로 압축 적층되어 상단의 흙탕물이 하단 배출구에서 맑고 투명한 식수로 정수 낙하하는 완성 구조입니다.\"\n  }\n}\n","content/protocols/02-friction-fire.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"나뭇가지 마찰로 불 피우는 법 (활비비 불피우기)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"라이터나 성냥이 없을 때 주변의 마른 나뭇가지와 끈을 이용해 불을 피우는 방법입니다. 활 모양의 나무로 가운데 막대를 빠르게 회전시켜 뜨거운 까만 불씨 가루를 만들고, 마른 풀 뭉치에 옮겨 불꽃을 피워냅니다.\",\n  \"timeRequired\": \"20분\",\n  \"successRate\": \"85% (바싹 마른 나무 사용 시)\",\n  \"difficulty\": \"보통 (연습 필요)\",\n  \"outputPerHour\": \"20분당 불씨 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"활대와 질긴 천연 끈\",\n      \"desc\": \"길이 60~70cm 정도의 살짝 휘어진 튼튼한 나뭇가지와, 칡덩굴이나 나무껍질을 꼬아 만든 질긴 끈입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"가운데 회전 막대 (비비는 나무)\",\n      \"desc\": \"엄지손가락 굵기(약 2cm), 길이 25cm 정도의 곧고 바싹 마른 나뭇가지입니다. 아랫부분을 연필심처럼 뾰족하게 깎아 씁니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바닥 받침 나무와 마른 풀 뭉치\",\n      \"desc\": \"손바닥만 한 평평한 마른 나무판과, 불씨를 옮겨 붙일 새둥지 모양의 바싹 마른 풀·억새 솜털 뭉치입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"바닥 받침 나무에 불씨 가루가 모일 V자 홈 파기\",\n      \"description\": \"바닥 받침 나무에 회전 막대가 들어갈 작은 오목한 구멍을 먼저 낸 뒤, 나무 가장자리에서 그 구멍 한가운데까지 피자 조각 모양(약 45도 각도)으로 V자 홈을 파냅니다. 홈 바로 아래에는 불씨 가루를 받아낼 마른 나뭇잎을 한 장 깔아둡니다.\",\n      \"actionNote\": \"> 핵심 팁: 나무가 갈리면서 나오는 뜨거운 까만 가루가 이 V자 홈을 타고 한곳에 모여야 불씨가 됩니다. 홈 끝이 구멍 한가운데에 정확히 닿도록 파주세요.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"불씨 받침 나뭇잎\",\n        \"45° V자 홈 (막대 중심까지 파기)\",\n        \"두께 2cm 가운데 회전 막대\",\n        \"판 두께: 1.5~2cm\",\n        \"바닥 받침 나무\",\n        \"V자 홈 끝점 (구멍 한가운데와 일치)\",\n        \"핵심 준비 포인트:\",\n        \"V자 홈 끝이 막대 중심에 딱 닿아야 함\",\n        \"까만 불씨 가루가 모이는 자리\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"위에서 체중으로 누르며 활대를 앞뒤로 빠르게 당기기\",\n      \"description\": \"왼발로 바닥 받침 나무를 움직이지 않게 밟고, 손잡이 나무(또는 돌)로 회전 막대 윗부분을 수직으로 누릅니다. 활대 끈에 회전 막대를 한 바퀴 감은 뒤, 톱질하듯 활대를 앞뒤로 길게 움직여 회전시킵니다. 하얀 연기가 자욱하게 나기 시작하면 마지막 5초 동안 온 힘을 다해 빠르게 왕복합니다.\",\n      \"actionNote\": \"> 핵심 원리: 연기가 조금 난다고 바로 멈추면 안 됩니다. 하얀 연기가 뿜어져 나온 뒤에도 10~15번 더 힘껏 당겨야 가루에 열이 충분히 쌓여 스스로 타는 불씨가 됩니다.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"손잡이 누름판\",\n        \"위에서 체중 실어 누르기 (12~15kg)\",\n        \"활대 (길이 65cm 휘어진 나뭇가지)\",\n        \"활대 끝에서 끝까지 길게 당기고 밀기\",\n        \"빠르게 양방향 회전\",\n        \"바닥 받침 나무\",\n        \"하얀 연기가 피어오름\",\n        \"불씨 만드는 핵심:\",\n        \"마찰 열기: 400°C 이상\",\n        \"누르는 힘: 약하게 → 세게\",\n        \"활대 전체 길이를 끝까지 사용\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"마른 풀 뭉치에 불씨를 옮기고 살살 불어 불붙이기\",\n      \"description\": \"V자 홈 아래 나뭇잎에 모인 까만 가루 덩어리에서 혼자 연기가 모락모락 피어오르면, 새둥지처럼 만든 마른 풀 뭉치 한가운데에 조심스럽게 쏟아 넣습니다. 풀 뭉치를 살짝 감싸 쥐고 45도 위로 든 채, 불씨를 향해 길고 부드럽게 입김을 불어넣으면 불꽃이 확 피어오릅니다.\",\n      \"actionNote\": \"> 주의할 점: 풀 뭉치를 눈높이보다 살짝 위로 들면 연기가 눈에 들어가지 않고, 따뜻한 공기가 위로 올라가면서 불이 훨씬 잘 붙습니다.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"달궈진 불씨 덩어리 (450°C)\",\n        \"길고 부드럽게 입김 불기\",\n        \"불꽃이 확 피어오름\",\n        \"45도 기울여 들기\",\n        \"입김 불어 불붙이는 온도 변화\",\n        \"시간 (초)\",\n        \"온도 (°C)\",\n        \"600°C 불꽃이 타오르는 온도\",\n        \"400°C 불씨가 유지되는 온도\",\n        \"30초 기다린 뒤 옮기기 (0초)\",\n        \"불꽃 점화 (15~20초)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 막 모인 불씨 가루에 급하게 세찬 입김 불기\",\n    \"description\": \"활대질을 멈추자마자 마음이 급해 나뭇잎 위의 까만 가루에 입김을 세게 확 불어버리면, 아직 단단하게 뭉치지 못한 불씨 가루가 바람에 다 날아가 버려 열기가 순식간에 꺼집니다.\",\n    \"consequence\": \"결과: 불씨 가루에서 연기가 나면 건드리지 말고 30초 동안 스스로 단단히 뭉쳐질 때까지 기다린 뒤에 옮기세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"보우 드릴 마찰열 발화 및 불씨 착화 완성 형태\",\n    \"description\": \"화판의 45도 V홈에 마찰열로 생성된 검은 숯가루 잉걸불(400°C)이 붉게 타오르며 연기를 피워 올리고, 이를 마른 껍질 부싯깃 둥지로 안전하게 옮겨 불꽃을 피워 올린 실전 발화 완성 상태입니다.\"\n  }\n}\n","content/protocols/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"불 없이 체온을 지키는 낙엽 움막 만드는 법\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[중요도: 필수 생존]\",\n  \"summary\": \"찬 바람과 비가 치는 야생에서 맨몸으로 밤을 보내면 3시간 안에 체온이 떨어져 위험해집니다. 불을 피울 수 없을 때 주변의 나뭇가지와 마른 낙엽을 두껍게 쌓아, 두꺼운 침낭처럼 내 몸의 온기를 가두어 따뜻하게 자는 방법입니다.\",\n  \"timeRequired\": \"90~120분\",\n  \"successRate\": \"92% (낙엽 두께 60cm 이상 쌓았을 때)\",\n  \"difficulty\": \"보통 (도구 없이 가능)\",\n  \"outputPerHour\": \"1인용 보온 움막 1개 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"중심 기둥 나무 (긴 통나무 1개)\",\n      \"desc\": \"어른 키의 두 배 정도 길이(3.0~3.5m), 팔뚝 굵기(10~15cm)의 튼튼하고 곧은 마른 나무 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y자 기둥 나무 2개와 양옆에 기댈 나뭇가지들\",\n      \"desc\": \"끝이 Y자로 갈라진 가슴 높이(1.5m) 나무 2개와, 양옆 벽을 만들 팔 길이(1~1.5m)의 나뭇가지 40~50개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"바싹 마른 낙엽과 마른 풀 (최대한 많이)\",\n      \"desc\": \"물기가 전혀 없는 마른 낙엽, 솔잎, 마른 풀을 큰 자루 수십 개 분량으로 넉넉히 모읍니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Y자 기둥 두 개를 세우고 중심 기둥 나무 올리기\",\n      \"description\": \"끝이 Y자로 갈라진 나무 두 개를 마주 보게 세워 윗부분을 맞물리거나 칡덩굴로 묶어 삼각 다리를 만듭니다. 그 위에 긴 중심 기둥 나무의 한쪽 끝을 올리고(입구 높이 80cm~1m), 반대쪽 끝은 바람이 불어오는 쪽 바닥에 닿게 내려놓습니다.\",\n      \"actionNote\": \"> 핵심 팁: 움막 안이 넓으면 내 몸의 열기로 공기를 데울 수 없어 춥습니다. 누웠을 때 어깨 양옆으로 주먹 하나(10cm) 정도만 남을 만큼 좁게 만드세요.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"움막 크기 핵심 규칙:\",\n        \"몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)\",\n        \"바람 불어오는 쪽 (바닥에 고정)\",\n        \"중심 기둥 나무: 길이 3.0~3.5m\",\n        \"Y자 기둥 2개 맞물려 묶기\",\n        \"내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)\",\n        \"입구 높이: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"양옆에 나뭇가지를 촘촘히 기대고 바닥에 낙엽 두껍게 깔기\",\n      \"description\": \"중심 기둥 나무 양옆에 나뭇가지들을 45~60도 각도로 빈틈없이 기대어 세웁니다. 그다음 움막 안쪽 바닥에 바싹 마른 낙엽을 무릎 높이(40cm 이상)만큼 수북하게 깔아줍니다. 내가 누워서 눌렸을 때도 바닥 낙엽 두께가 최소 한 뼘(20cm) 이상 유지되어야 합니다.\",\n      \"actionNote\": \"> 핵심 원리: 차가운 맨땅은 찬 공기에 비해 체온을 수십 배나 빠르게 빼앗아 갑니다. 지붕보다 바닥에 까는 낙엽 이불이 두꺼워야 얼지 않습니다.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"바닥 냉기 차단 핵심:\",\n        \"마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지\",\n        \"중심 기둥 나무 (단면)\",\n        \"양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기\",\n        \"낙엽 이불: 40cm → 눌린 뒤 20cm\",\n        \"땅에서 올라오는 찬 기운 완벽 차단\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"지붕에 낙엽을 팔 길이만큼 쌓고 무거운 가지로 덮기\",\n      \"description\": \"나뭇가지 벽 위에 잔가지를 얹은 뒤, 마른 낙엽을 아래에서 위쪽으로 내 팔 전체 길이(60~90cm) 두께가 될 때까지 산더미처럼 쌓아 올립니다. 마지막으로 바람에 낙엽이 날아가지 않도록 무거운 나뭇가지들을 위에 덮어 눌러주고, 안에 들어간 뒤 입구도 낙엽 뭉치로 막아 찬 바람을 차단합니다.\",\n      \"actionNote\": \"> 주의할 점: 젖은 낙엽을 섞어 쓰면 물기가 마르면서 오히려 체온을 뺏어갑니다. 반드시 바싹 마른 낙엽만 골라 쓰세요.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"지붕 낙엽 쌓기 & 입구 막기:\",\n        \"지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기\",\n        \"마른 낙엽 벽: 60~90cm 두께\",\n        \"바람에 안 날리게 무거운 가지 덮기\",\n        \"빗물이 타고 흐르는 경사면\",\n        \"따뜻한 공기가 갇힌 내부 & 낙엽 마개\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 편하게 앉으려고 움막을 크게 짓거나 젖은 낙엽 쓰기\",\n    \"description\": \"텐트처럼 안에서 앉아 있으려고 천장을 높이고 공간을 넓게 만들면, 사람 몸에서 나오는 열기만으로는 그 넓은 공간의 찬 공기를 절대 데울 수 없습니다. 또한 젖은 낙엽을 깔면 밤새 냉기가 올라와 체온이 급격히 떨어집니다.\",\n    \"consequence\": \"결과: 반드시 몸이 겨우 들어갈 만큼 좁게 만들고, 바싹 마른 낙엽만 두껍게 쌓아야 밤새 체온을 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A-프레임 데브리 헛 (낙엽 단열 은신처) 완성 외관\",\n    \"description\": \"2.5m 굵은 용마루와 45도 갈비뼈 가지 프레임 위에 1미터 두께의 마른 낙엽층을 압축 적층하고 겉가지 격자를 덮어 강풍과 비바람을 막는 무난방 체온 보존 은신처 완성 외관입니다.\"\n  }\n}\n","content/protocols/04-stone-axe-making.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"깬 돌과 칡덩굴로 나무 베는 돌도끼 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[중요도: 핵심 도구]\",\n  \"summary\": \"맨손으로는 움막 기둥이나 땔감으로 쓸 굵은 나뭇가지를 자를 수 없습니다. 강가에서 주운 단단한 돌 두 개를 45도 각도로 부딪쳐 날카로운 돌날을 떼어내고, 나무 자루 틈에 송진과 젖은 칡덩굴로 단단히 묶어 튼튼한 돌도끼를 만드는 방법입니다.\",\n  \"timeRequired\": \"60분\",\n  \"successRate\": \"90% (45도 각도로 모서리를 칠 경우)\",\n  \"difficulty\": \"보통 (초보자 가능)\",\n  \"outputPerHour\": \"돌도끼 1자루 완성\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"단단한 강돌 1개와 둥근 망치돌 1개\",\n      \"desc\": \"깨졌을 때 유리처럼 날카로운 모서리가 생기는 단단한 강돌(어른 주먹 2개 크기) 1개와, 손에 쥐고 내리칠 둥글고 묵직한 망치돌 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"팔뚝 길이의 단단한 나무 자루 (참나무·물푸레나무)\",\n      \"desc\": \"세게 내리쳐도 부러지지 않는 단단한 생나무 가지(길이 40~50cm, 손목보다 조금 가는 지름 3.5~4cm 굵기) 1개입니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"물에 적신 칡덩굴 속껍질과 소나무 송진\",\n      \"desc\": \"마르면서 스스로 오그라들어 꽉 조여지는 젖은 칡덩굴 속껍질(길이 3m 이상)과, 나무 상처에서 굳은 소나무 송진 한 주먹입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"돌과 돌을 45도 각도로 부딪쳐 날카로운 돌날 떼어내기\",\n      \"description\": \"바닥에 큰 강돌을 흔들리지 않게 받쳐 놓고, 손에 쥔 둥근 망치돌로 강돌의 가장자리 모서리를 45도 각도로 비스듬히 세게 내리칩니다. 돌 한가운데를 수직으로 치면 돌만 깨지지만, 모서리를 45도로 치면 손바닥만 하고 끝이 면도날처럼 날카로운 돌날 조각이 한 번에 떨어져 나옵니다.\",\n      \"actionNote\": \"> 핵심 팁: 돌의 평평한 한가운데를 치지 마세요. 모서리 끝에서 손가락 한 마디(1~2cm) 안쪽을 노려 한 번에 강하게 쳐야 길고 날카로운 돌날이 떨어집니다.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 둥근 망치돌 (내리치는 돌)\",\n        \"② 모서리 45° 비스듬히 치기\",\n        \"날카로운 돌날 (두께 1~2cm)\",\n        \"④ 쪼개져 나온 도끼날 돌조각\",\n        \"③ 바닥에 받친 큰 강돌 (너비 15~20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"나무 자루 윗부분을 쪼개어 돌날 끼우고 송진 채우기\",\n      \"description\": \"단단한 나무 자루의 윗부분을 날카로운 돌로 손가락 길이(5~7cm)만큼 세로로 쪼개어 틈을 만듭니다. 자루가 밑으로 더 쪼개지지 않도록 갈라진 끝부분 아래쪽을 끈으로 먼저 묶어 둔 뒤, 틈 사이에 돌날의 두꺼운 뒷부분을 깊숙이 끼워 넣습니다. 그다음 불에 녹인 소나무 송진에 고운 숯가루를 섞어 빈틈에 가득 채워 넣습니다.\",\n      \"actionNote\": \"> 핵심 원리: 송진만 녹여서 바르면 식은 뒤에 유리처럼 쉽게 깨집니다. 불 피우고 남은 까만 숯가루를 3분의 1 정도 섞어 주면 충격에도 깨지지 않는 튼튼한 천연 접착제가 됩니다.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 위에서 아래로 돌날 끼우기\",\n        \"나무 자르는 앞날\",\n        \"② 쪼갠 나무 자루 틈 (5~7cm)\",\n        \"③ 녹인 송진 + 숯가루 채우기\",\n        \"④ 더 안 갈라지게 아래쪽 먼저 묶기\",\n        \"생나무 자루 굵기: 지름 3.5~4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"젖은 칡덩굴 줄기로 X자 모양으로 단단히 감아 말리기\",\n      \"description\": \"물에 충분히 적셔 부드러워진 칡덩굴 속껍질로 돌날과 나무 자루를 대각선 X자 모양으로 번갈아 가며 10바퀴 이상 힘껏 당겨 감습니다. 이어서 자루 아래쪽도 가로로 칭칭 감아 매듭을 묶은 뒤 그늘에서 말립니다. 젖은 칡덩굴은 마르면서 길이가 30% 가까이 줄어들기 때문에, 마른 뒤에는 쇠줄로 조인 것처럼 돌날을 꽉 잡아줍니다.\",\n      \"actionNote\": \"> 주의할 점: 다 마른 뒤 손으로 돌날을 세게 흔들어 보아 조금도 흔들리지 않아야 안전합니다. 빨리 말리겠다고 불에 가까이 대면 칡덩굴이 타서 끊어지니 꼭 바람 불고 그늘진 곳에서 말리세요.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 젖은 칡 속껍질 X자로 감기\",\n        \"② 날카로운 도끼 앞날\",\n        \"③ 자루 아래쪽 가로로 칭칭 감기\",\n        \"④ 마르면서 30% 줄어들며 꽉 조임\",\n        \"완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 평평한 돌 한가운데를 치거나 마른 덩굴로 묶기\",\n    \"description\": \"돌의 평평한 한가운데를 90도로 내려치면 날카로운 날이 만들어지지 않고 돌 전체가 쓸모없는 자갈로 부서집니다. 또한 물에 적시지 않은 마른 덩굴이나 거친 겉껍질로 묶으면, 나무를 찍는 순간 줄이 끊어지면서 무거운 돌날이 얼굴이나 눈으로 튀어 크게 다칠 수 있습니다.\",\n    \"consequence\": \"결과: 반드시 강돌 모서리를 45도로 쳐서 날을 만들고, 물에 불린 질긴 속껍질로 X자로 감아 그늘에서 말려야 안전하게 나무를 벨 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"깬 돌과 칡덩굴 결속 원시 돌도끼 완성 형태\",\n    \"description\": \"단단한 참나무 Y자 자루 홈에 양면 타제된 날카로운 수석 날을 깊숙이 물리고, 질긴 칡덩굴과 송진 접착제로 X자 십자 결속하여 나무를 거침없이 베어 넘기는 실전 석기 돌도끼 완성 형태입니다.\"\n  }\n}\n","content/protocols/05-natural-cordage.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"나무껍질과 칡덩굴을 꼬아 끊어지지 않는 야생 밧줄 만드는 법\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[필수 생존]\",\n  \"summary\": \"움막 기둥을 묶거나 돌도끼를 고정하고 활비비로 불을 피우려면 튼튼한 끈이 꼭 필요합니다. 줄기를 그냥 묶으면 마르면서 뚝 부러지거나 풀려버리지만, 식물 속껍질 섬유를 발라내어 두 가닥을 서로 반대 방향으로 비틀어 꼬면 어른 몸무게도 거뜬히 버티는 질긴 야생 밧줄을 만들 수 있습니다.\",\n  \"timeRequired\": \"40분\",\n  \"successRate\": \"95% (역방향 꼬기 준수 시)\",\n  \"difficulty\": \"보통 (맨손 작업 가능)\",\n  \"outputPerHour\": \"5m / 40분\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"살아있는 칡덩굴 또는 참피나무·버드나무·쐐기풀 줄기 (팔 길이 10~15줄기)\",\n      \"desc\": \"구부렸을 때 '톡' 부러지지 않고 부드럽게 휘어지며, 손톱으로 겉을 긁었을 때 연두색 물기가 도는 싱싱한 줄기를 골라야 질긴 속껍질을 얻을 수 있습니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"겉껍질을 긁어낼 날카로운 돌조각 1개\",\n      \"desc\": \"줄기 바깥의 거칠고 잘 부서지는 갈색 겉껍질만 살짝 긁어 벗겨낼 때 씁니다. 너무 날카로워 속껍질 섬유까지 끊어지지 않도록 모서리가 적당히 각진 돌을 고릅니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"섬유를 두드릴 평평한 바닥 돌과 주먹만 한 둥근 돌\",\n      \"desc\": \"물에 불린 뻣뻣한 속껍질을 바닥 돌 위에 올려놓고 둥근 돌로 살살 두드려, 머리카락처럼 가늘고 부드러운 실 결로 풀어줄 때 사용합니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"속껍질을 불릴 냇물 또는 고인 물\",\n      \"desc\": \"갓 벗긴 속껍질을 20~30분 동안 담가 두어 뻣뻣한 나무 진액을 빼고, 꼬는 동안 섬유가 꺾이지 않게 촉촉한 상태를 유지하는 데 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 휘어지는 줄기 골라 거친 겉껍질 긁어내고 하얀 속껍질 벗기기\",\n      \"description\": \"먼저 줄기를 반으로 구부려 보아 부러지지 않고 탄력 있게 휘어지는지 확인합니다. 돌 모서리를 줄기에 비스듬히 대고 바깥의 거친 갈색 겉껍질만 살살 긁어내면, 그 아래에서 하얗고 질긴 속껍질 섬유층이 드러납니다. 줄기 아래쪽 끝을 손톱으로 살짝 들춰낸 뒤, 줄기 위쪽을 향해 길게 잡아당기면 딱딱한 가운데 나무 속심에서 리본 모양의 속껍질만 쭉 벗겨져 나옵니다.\",\n      \"actionNote\": \"> 핵심 팁: 바닥에 떨어져 말라비틀어진 줄기는 이미 섬유가 삭아 힘을 주면 먼지처럼 끊어집니다. 반드시 살아있는 줄기나 갓 꺾인 줄기에서 속껍질을 채취하세요.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 돌 모서리로 거친 겉껍질만 살살 긁어내기\",\n        \"② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)\",\n        \"③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)\",\n        \"④ 가운데 딱딱한 나무 속심 (빼내고 버림)\",\n        \"⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 냇물에 20분 불린 뒤 돌로 두드려 실처럼 부드럽게 풀기\",\n      \"description\": \"벗겨낸 속껍질 리본을 냇물에 20~30분 동안 푹 담가 불립니다. 물기를 머금어 부드러워진 속껍질을 평평한 강돌 위에 펴 놓고, 둥근 돌로 위에서 아래로 톡톡 두드립니다. 거친 나무 결이 부서지면서 머리카락이나 실처럼 가늘고 부드러운 섬유 다발로 풀립니다. 손으로 비벼 보았을 때 뻣뻣한 가시 느낌이 없고, 손가락에 감아 세게 당겨도 끊어지지 않으면 굵기가 똑같은 두 가닥으로 나눕니다.\",\n      \"actionNote\": \"> 핵심 원리: 너무 세게 내려치면 섬유가 끊어집니다. 고기를 다지듯 끊어 치지 말고, 둥근 돌로 살살 짓누르며 밀어주듯 두드려야 긴 섬유가 상하지 않습니다.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 냇물에 20분 이상 담가 부드럽게 불린 속껍질\",\n        \"② 둥근 돌로 살살 두드려 섬유 결 쪼개기\",\n        \"③ 머리카락처럼 부드럽게 풀어진 섬유 다발\",\n        \"④ 손가락 굵기로 똑같이 나눈 두 가닥\",\n        \"⑤ 바닥에 흔들리지 않게 받친 평평한 강돌\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 바깥으로 비틀고 안쪽으로 넘기는 '역방향 꼬기' 반복하기\",\n      \"description\": \"긴 섬유 다발의 한가운데를 왼손 엄지와 검지로 꽉 쥐고 반으로 접어 위쪽 가닥과 아래쪽 가닥 두 줄을 만듭니다. 오른손으로 위쪽 가닥을 잡고 내 몸 바깥쪽(앞쪽)으로 팽팽하게 비틀어 줍니다. 그 상태 그대로 비튼 위쪽 가닥을 아래쪽 가닥 너머 내 몸 쪽(뒤쪽)으로 교차해 넘기면, 아까 아래에 있던 가닥이 새로 위쪽 가닥이 됩니다. 왼손 엄지를 한 칸 옮겨 방금 교차한 자리를 꽉 눌러 잡은 뒤, 다시 새로 올라온 위쪽 가닥을 '바깥쪽으로 비틀고 ➔ 몸 쪽으로 넘기기'를 계속 반복합니다.\",\n      \"actionNote\": \"> 핵심 원리: 두 가닥을 같은 방향으로만 감으면 손을 놓는 순간 스르륵 다 풀려버립니다. 각 가닥은 바깥으로 비틀고, 두 가닥 전체는 안쪽으로 넘겨야 풀리려는 힘이 서로 맞물려 절대 풀리지 않습니다.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기\",\n        \"② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬\",\n        \"③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기\",\n        \"④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기\",\n        \"⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 짧은 섬유를 10cm씩 겹쳐 꼬아 원하는 길이만큼 끝없이 잇기\",\n      \"description\": \"밧줄을 꼬다 보면 한쪽 가닥이 끝에서 10cm쯤 남아 점점 얇아집니다. 이때 새 섬유 다발의 끝부분을 얇아진 기존 가닥 옆에 10cm 길이로 나란히 겹쳐 대고, 두 줄을 마치 원래 한 가닥이었던 것처럼 함께 쥐고 똑같이 바깥으로 비틀어 몸 쪽으로 넘깁니다. 3~4번만 꼬아 넘기면 새 섬유가 단단히 물려 빠지지 않습니다. 단, 위쪽 가닥과 아래쪽 가닥을 동시에 같은 자리에서 이어 붙이지 말고, 두 이음매 사이가 최소 어른 손 한 뼘(15cm) 이상 어긋나게 배치해야 합니다.\",\n      \"actionNote\": \"> 주의할 점: 두 가닥의 이음매가 같은 위치에 겹치면 그 부분만 볼록하게 두꺼워지고 힘을 받았을 때 그 자리에서 뚝 끊어집니다.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 끝이 10cm쯤 남아 가늘어진 기존 가닥\",\n        \"② 새 섬유 다발을 10cm 나란히 겹쳐 대기\",\n        \"③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기\",\n        \"④ 불룩해지지 않고 매끄럽게 이어진 연결부\",\n        \"⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 끝부분 풀림 방지 매듭 묶고 나무 기둥에 걸어 몸무게로 당겨보기\",\n      \"description\": \"필요한 길이(5m 이상)까지 다 꼬았으면, 끝에서 3cm 지점을 고리 모양으로 한 번 돌려 묶어(기본 홀치기 매듭) 끝이 풀리지 않게 마감합니다. 밧줄 겉면으로 삐져나온 잔털들을 날카로운 돌날로 살짝 긁어 정리해 주면 마찰에 쓸리지 않습니다. 마지막으로 완성된 밧줄을 팔뚝 굵기 이상의 튼튼한 나무 기둥에 감고 내 몸무게(50kg 이상)를 실어 힘껏 당겨봅니다. 이음매가 밀리지 않고 매듭이 더 단단하게 조여지면 실전 사용 준비가 끝난 것입니다.\",\n      \"actionNote\": \"> 실전 확인: 당겼을 때 '투둑' 하고 섬유 끊어지는 소리가 나거나 이음매가 미끄러지면 그 구간 위에 얇은 섬유를 한 번 더 감아 보강하세요.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭\",\n        \"② 삐져나온 잔털을 돌날로 깔끔하게 정리\",\n        \"③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기\",\n        \"④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)\",\n        \"⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 껍질을 벗기지 않은 초록색 생줄기를 그대로 묶어 쓰기\",\n    \"description\": \"급하다고 칡덩굴이나 나뭇가지를 통째로 감아 움막 기둥이나 돌도끼를 묶으면, 당장은 단단해 보여도 반나절만 지나 수분이 마르면 부피가 줄어들면서 헐거워지고 작은 충격에도 과자처럼 바스라져 부러집니다. 반드시 겉껍질과 나무 속심을 버리고 질긴 속껍질 섬유만 발라내어 역방향으로 꼬아서 써야 마른 뒤에도 끊어지지 않습니다.\",\n    \"consequence\": \"결과: 자는 도중 움막 지붕이 무너지거나 나무를 찍던 돌도끼 날이 빠져 큰 부상을 입음\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"산속에서 끈이 하나도 없을 때, 절대 끊어지지 않는 야생 밧줄을 맨손으로 꼬는 법입니다.\",\n    \"body\": \"죽은 가지는 부러져서 못 씁니다. 휘어지는 칡덩굴의 거친 겉껍질을 돌로 긁어내고 하얀 속껍질만 길게 벗기세요. 물에 20분 불려 돌로 살살 두드리면 실처럼 부드러워집니다. 이제 반으로 접어 위 가닥은 몸 바깥쪽으로 비틀고, 아래 가닥 너머 몸 쪽으로 넘기세요. 짧아지면 새 섬유를 10cm 겹쳐 꼬아 끝없이 이을 수 있습니다.\",\n    \"outro\": \"나무에 걸고 몸무게를 실어 당겨도 안 끊어집니다. 움막 짓기와 돌도끼 고정에 바로 써보세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2가닥 역방향 꼬임 천연 밧줄 완성 코일 다발\",\n    \"description\": \"나무 내피와 칡 줄기 섬유를 시계 방향으로 꼬고 반시계 방향으로 교차 엮어 인장 강도 90kg 이상을 견디는 촘촘하고 매끄러운 2가닥 천연 생존 밧줄 코일 완성 다발입니다.\"\n  }\n}\n","content/protocols/06-clay-hearth.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"진흙과 돌을 쌓아 비바람을 막고 열기를 가두는 원시 화덕 만드는 법\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[체온·식량 필수]\",\n  \"summary\": \"야생에서 바닥에 맨 불을 피우면 바람에 불티가 날려 위험하고 열기의 80%가 허공으로 날아가 장작이 세 배 넘게 듭니다. 찰흙과 모래, 마른 풀을 섞어 이긴 진흙 반죽으로 돌을 감싸 돔 형태의 화덕을 쌓으면, 비바람이 몰아쳐도 꺼지지 않고 밥을 짓거나 밤새 은은한 온기를 품는 훌륭한 생존 열원이 됩니다.\",\n  \"timeRequired\": \"3시간\",\n  \"successRate\": \"90% (초벌 건조 준수 시)\",\n  \"difficulty\": \"보통 (흙 반죽과 돌 쌓기)\",\n  \"outputPerHour\": \"1기 완성 (영구 사용 가능)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"점토질 붉은 찰흙 2바가지 (개울가나 흙벽에서 파낸 끈끈한 흙)\",\n      \"desc\": \"손으로 쥐었을 때 차진 찰떡처럼 뭉쳐지고 손가락 사이에 끈적하게 달라붙는 흙을 고릅니다. 화덕 벽체를 하나로 굳혀주는 주원료입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"굵은 강모래 1바가지 (돌 알갱이가 섞인 마른 흙)\",\n      \"desc\": \"찰흙만 쓰면 마를 때 부피가 줄어들며 산산조각 갈라집니다. 굵은 모래를 섞어주면 단단한 뼈대가 되어 균열을 막아줍니다.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"손가락 길이로 자른 마른 풀잎 또는 짚 1바가지\",\n      \"desc\": \"진흙 반죽 속에서 섬유질 철근 역할을 하여, 불의 뜨거운 열기에도 벽체가 쪼개지거나 부서지지 않게 질기게 잡아줍니다.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"물기 없는 단단한 깬 돌 15~20개 (주먹~머리 크기)\",\n      \"desc\": \"물속에 잠겨 있던 강돌은 열을 받으면 폭발하므로, 물가에서 10m 떨어진 마른 언덕의 햇볕에 바짝 마른 돌만 골라 씁니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 찰흙 2, 모래 1, 마른 풀 1을 물과 함께 발로 밟아 차진 반죽 만들기\",\n      \"description\": \"평평한 땅 위에 붉은 찰흙 2바가지, 굵은 모래 1바가지, 손가락 마디 길이로 자른 마른 풀 1바가지를 골고루 붓습니다. 물을 한 번에 많이 붓지 말고 조금씩 끼얹어가며 발뒤꿈치로 꾹꾹 밟아 치댑니다. 흙더미를 반으로 접어 다시 밟기를 10분 이상 반복하여, 주먹만 한 공 모양으로 둥글게 뭉쳐 손바닥 위에 올려놓아도 겉면에 실금이 가지 않고 쫀득하게 찰기가 돌 때까지 반죽합니다.\",\n      \"actionNote\": \"> 핵심 비결: 물이 너무 많으면 반죽이 죽처럼 흘러내려 벽을 쌓을 수 없고, 물이 적으면 푸석해져 부서집니다. 만두피 반죽처럼 약간 뻑뻑하면서 찰진 상태가 가장 좋습니다.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 붉은 찰흙 2바가지\",\n        \"끈끈한 점력의 기본 바탕재\",\n        \"+\",\n        \"② 굵은 모래 1바가지\",\n        \"마를 때 오그라듦 방지\",\n        \"+\",\n        \"③ 잘게 자른 마른 풀잎\",\n        \"뼈대 역할을 하는 보강 섬유\",\n        \"④ 물을 조금씩 부어가며 발로 치대기\",\n        \"한 번에 많이 붓지 말고 뒤집으며 밟기\",\n        \"⑤ 차진 반죽 덩어리 완성\",\n        \"주먹 크기로 둥글게 뭉쳐도\",\n        \"겉면에 실금이 가지 않는 상태\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 마른 땅 위에 주먹 크기 돌을 U자 모양으로 놓아 바닥 기초 다지기\",\n      \"description\": \"바람이 불어오는 반대쪽을 향해 장작 넣는 입구(어른 한 뼘 너비, 약 20cm)를 비워두고, 주먹보다 큰 단단한 마른 돌들을 말발굽(U자) 모양으로 둘러놓습니다. 바닥에는 마른 모래와 잔자갈을 2~3cm 두께로 깔아 차가운 땅바닥 습기와 냉기를 차단합니다. 돌과 돌 사이 틈새마다 1단계에서 만든 진흙 반죽을 주먹으로 꾹꾹 찔러 넣어 빈틈없이 메우고 바닥과 단단히 밀착시킵니다.\",\n      \"actionNote\": \"> 방풍 요령: 입구가 바람을 정면으로 마주 보면 강풍에 불티가 솟구쳐 위험합니다. 반드시 바람이 등 뒤에서 불어오는 방향이나 비스듬한 쪽으로 입구를 내세요.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\",\n        \"불길 조절과 공기 공급에 알맞은 입구 폭\",\n        \"② U자형 주먹만 한 마른 돌\",\n        \"기초를 지탱하는 1차 뼈대\",\n        \"③ 틈새를 메운 진흙 반죽\",\n        \"돌 사이 공기 누출 완전 차단\",\n        \"④ 바닥 마른 모래·자갈 단열층\",\n        \"차가운 땅바닥 습기와 냉기 차단\",\n        \"⑤ 바람 불어오는 반대쪽으로 입구 배치\",\n        \"강풍에 불티가 역류하거나 꺼지지 않도록 보호\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 돌과 진흙을 엇갈려 쌓으며 무릎 높이의 돔형 벽체 올리기\",\n      \"description\": \"기초 돌 위에 진흙 반죽을 손바닥 두께(약 5cm)로 두껍게 깔고, 그 위에 다음 돌을 얹는 방식으로 지그재그 엇갈려 올립니다. 위로 올라갈수록 조금씩 안쪽으로 오므려 가며 무릎 높이(약 45cm)까지 둥근 이글루 모양의 돔을 만듭니다. 벽을 다 쌓은 뒤에는 손에 물을 묻혀 안쪽 벽면을 매끄럽게 문질러 다듬습니다. 벽면이 매끄러울수록 연소실 안에서 열기가 맴돌며 높은 온도를 유지합니다.\",\n      \"actionNote\": \"> 붕괴 방지: 진흙만 높이 바르면 아래쪽이 무게를 못 이기고 무너집니다. 반드시 돌을 뼈대로 삼고 그 겉과 속을 진흙 반죽으로 두껍게 감싸듯이 발라야 합니다.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 엇갈려 쌓은 벽체 단면\",\n        \"돌 틈에 진흙을 채워 무너짐 방지\",\n        \"② 손바닥 두께(약 5cm) 진흙벽\",\n        \"바깥으로 새는 열 손실 완벽 차단\",\n        \"③ 매끄러운 열 반사 곡면\",\n        \"손에 물을 묻혀 반질반질하게 다듬기\",\n        \"④ 열기가 모여 회전하는 둥근 연소실 내부\",\n        \"⑤ 무릎 높이(약 45cm) 외형선\",\n        \"취사 안정성과 축열 용적 최적화\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 화덕 윗부분에 냄비 받침 구멍을 내고 뒤쪽에 굴뚝 구멍 뚫기\",\n      \"description\": \"돔 천장 한가운데에 돌그릇이나 냄비를 얹을 수 있는 둥근 구멍(지름 약 15~20cm)을 남겨 마감합니다. 냄비를 얹었을 때 불길이 막혀 꺼지지 않도록 구멍 둘레에 작은 돌 3개를 삼각형으로 박아 1cm 정도의 통기 틈새를 둡니다. 그리고 화덕 뒤편 상단에는 손목 굵기 나뭇가지로 비스듬히 찔러 넣어 매운 연기가 쏙 빠져나갈 굴뚝 구멍을 뚫어줍니다. 이렇게 하면 아래 입구로 들어온 신선한 공기가 불길을 키우고 위로 연기가 빠져나가는 강한 상승 기류가 형성됩니다.\",\n      \"actionNote\": \"> 공기 순환 원리: 굴뚝이 없으면 연기가 앞쪽 장작 입구로 쏟아져 나와 눈이 맵고 불이 잘 붙지 않습니다. 뒤쪽 굴뚝을 앞 입구보다 높은 위치에 뚫어야 연기가 잘 빨려 나갑니다.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 앞쪽 하부 공기 흡입구 (산소 유입)\",\n        \"차가운 신선한 공기가 빨려 들어가는 길목\",\n        \"② 윗부분 평평한 조리용 구멍\",\n        \"냄비나 평평한 돌판을 얹는 화구\",\n        \"③ 뒤편 상단 굴뚝 구멍\",\n        \"매운 연기를 뒤로 뽑아내는 배출구\",\n        \"④ 솟구치는 열기 순환선\",\n        \"연소실 안을 회전하며 냄비 바닥을 달굼\",\n        \"⑤ 냄비 받침 통기 틈새 돌기\",\n        \"냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 작은 잔가지 불씨로 3시간 서서히 말려 벽돌처럼 단단하게 굽기\",\n      \"description\": \"완성된 화덕에 처음부터 큰 장작을 넣고 센 불을 피우면 흙 속의 수분이 급격히 끓어올라 벽이 쩍쩍 갈라집니다. 마른 나뭇잎과 작은 잔가지로 주먹만 한 작은 불씨를 만들어 입구 근처에서 은은하게 지핍니다. 3~4시간 동안 약한 열기를 쐬어주면 외벽에서 하얀 김(수증기)이 모락모락 빠져나가며 축축한 짙은 고동색이 밝은 황토색으로 바뀝니다. 외벽을 손으로 만졌을 때 물기가 묻어나지 않고 따뜻한 열감이 전해지면 단단한 영구 화덕이 완성된 것입니다.\",\n      \"actionNote\": \"> 건조 중 보수: 말리는 도중 외벽에 머리카락 같은 미세한 금이 생기면, 남은 묽은 진흙 반죽을 손가락에 묻혀 쓱 문질러 메워주면 감쪽같이 결합됩니다.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 입구 작은 잔가지 불씨 (약한 열기)\",\n        \"강한 불 대신 은은한 열기로 시작\",\n        \"② 외벽 수증기 증발선\",\n        \"내부 수분이 천천히 기화\",\n        \"③ 색상 변화 관찰\",\n        \"짙은 고동색 → 밝은 황토색\",\n        \"④ 따뜻한 건조 완료 판정\",\n        \"축축함 없이 외벽 전체가 훈훈\",\n        \"⑤ 미세 실금 덧바름 보수\",\n        \"남은 진흙 반죽으로 틈새 메우기\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 물속에 젖어 있던 강돌을 화덕 불길 닿는 자리에 쌓기\",\n    \"description\": \"물가에서 방금 주워 온 강돌이나 자갈은 겉이 말라 보여도 돌 내부의 미세한 틈새에 물 분자가 갇혀 있습니다. 이 돌에 300도 이상의 뜨거운 불길이 직접 닿으면 갇힌 수분이 급격히 팽창하여 수류탄처럼 굉음을 내며 산산조각 폭발합니다. 날카로운 돌 파편이 눈과 얼굴로 날아와 실명하거나 큰 부상을 입을 수 있습니다. 반드시 물가에서 10m 떨어진 마른 언덕의 돌만 쓰고, 돌 표면을 진흙 반죽으로 5cm 이상 두껍게 덮어 불길이 돌에 직접 닿지 않도록 감싸야 합니다.\",\n    \"consequence\": \"결과: 돌 내부 수증기 폭발로 날카로운 파편이 비산하여 실명 및 중증 열상 유발\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"야생에서 바닥에 불을 피우면 열기의 80%가 날아갑니다. 비바람에도 꺼지지 않는 화덕 만드는 법입니다.\",\n    \"body\": \"찰흙 2, 모래 1, 마른 풀 1을 물과 함께 10분간 발로 밟아 차진 반죽을 만드세요. 주먹만 한 마른 돌을 U자로 놓고 앞쪽에 장작 입구를 둡니다. 돌과 진흙을 엇갈려 무릎 높이까지 돔으로 쌓고, 윗부분엔 냄비 구멍, 뒤편엔 연기가 빠질 굴뚝을 뚫으세요. 작은 불로 3시간 서서히 말려 수분을 빼면 벽돌처럼 단단해집니다. 절대 젖은 강돌을 불길에 직접 대지 마세요. 수증기 압력으로 돌이 폭발합니다.\",\n    \"outro\": \"비바람이 몰아쳐도 밥을 짓고 밤새 은은한 온기를 지킬 수 있습니다.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"점토 미장 돌 화덕 (원시 화덕 및 조리구) 완성 형태\",\n    \"description\": \"U자형 강돌 기초 위에 볏짚과 황토 반죽을 5cm 두께로 매끄럽게 미장하고, 상단 조리용 내열 상판과 후면 배기 굴뚝을 구비하여 650°C 고열을 가두는 원시 화덕 완성 형태입니다.\"\n  }\n}\n","content/protocols/07-survival-knots.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"강한 힘을 받아도 절대 풀리지 않고 1초 만에 푸는 '매듭의 왕' 보울라인(Bowline) 완벽 가이드\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[생명줄·인양 필수]\",\n  \"summary\": \"야생에서 무거운 통나무를 끌어올리거나 사람을 구조할 때, 텐트 스트링을 고정할 때 가장 신뢰받는 '매듭의 왕' 보울라인(Bowline)의 5단계 실전 결속법입니다. 체중 이상의 극한 하중이 실려도 고리의 크기가 절대 줄어들지 않아 질식이나 절단 위험이 없으며, 비에 젖고 돌처럼 굳어져도 뒤통수(칼라 루프)를 꺾으면 손가락 힘만으로 1초 만에 풀립니다. 전 세계 생존 전문가들이 입을 모아 찬양하는 '토끼와 나무' 4단계 암기 공식과 실전 락킹 기술을 한 컷 한 컷 완벽하게 마스터하세요.\",\n  \"timeRequired\": \"5분 (3회 반복 실습 시 완전 체화)\",\n  \"successRate\": \"99% (토끼굴 순서 준수 시 불변)\",\n  \"difficulty\": \"쉬움 (토끼와 나무 4박자 공식)\",\n  \"outputPerHour\": \"보울라인 매듭 마스터 (단일 고정 루프)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2m 길이의 튼튼한 밧줄 1가닥 (패러코드 또는 로프)\",\n      \"desc\": \"손가락 굵기(6~8mm)의 마찰력이 우수하고 인장 강도가 확보된 밧줄을 준비합니다. 매듭 연습과 실전 결속의 기본 바탕재입니다.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"연습용 기둥 또는 손잡이 (팔뚝 굵기의 나무 기둥)\",\n      \"desc\": \"고리를 걸어 하중을 걸고 당겨볼 수 있는 지름 5~7cm의 단단한 나무 기둥이나 손잡이입니다.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"1단계: 원줄 위에 작동 줄을 얹어 숫자 '6' 모양의 토끼굴 만들기\",\n      \"description\": \"밧줄의 긴 쪽(원줄, Standing Part)을 잡고, 손바닥 크기 정도의 작은 원형 고리를 만듭니다. 이때 가장 중요한 핵심은 끝단(작동 줄, Working End)이 원줄의 '위(Over)'를 가로지르도록 얹어야 한다는 점입니다. 위에서 내려다보았을 때 숫자 '6' 모양이 나오면 완벽한 토끼굴이 완성된 것입니다. 반대로 원줄 아래로 깔리면 매듭 구조가 성립되지 않으므로 반드시 윗면으로 교차시킵니다.\",\n      \"actionNote\": \"> 체크포인트: 원줄 위에 작동 줄이 덮여 숫자 6 모양이 되었는지 확인하세요. 이 고리가 밧줄 전체의 하중을 분산하고 잠가주는 핵심 관문이 됩니다.\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BOWLINE STEP 1: 토끼굴 고리 형성\",\n        \"STANDING PART\",\n        \"원줄 (서 있는 나무)\",\n        \"RABBIT HOLE (고리)\",\n        \"숫자 6 모양의 토끼굴\",\n        \"WORKING END (토끼)\",\n        \"작동 끝단이 원줄 '위'로 교차\",\n        \"[1단계 핵심] 원줄 위에 작동 줄을 얹어 6자 루프 형성\",\n        \"작동 줄이 반드시 원줄의 위쪽에 위치해야 잠금 구조가 완성됩니다.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"2단계: 토끼굴 밑바닥에서 위쪽으로 토끼(줄 끝)를 쑥 뽑아 올리기\",\n      \"description\": \"이제 줄 끝(토끼)을 쥐고, 방금 만든 토끼굴(원형 고리)의 아래쪽에서 위쪽 방향으로 쏙 밀어 올려 밖으로 뽑아냅니다. 이때 토끼의 머리(작동 끝단)는 최소 15~20cm 이상 넉넉한 여유 길이를 두고 뽑아내야 다음 단계에서 나무를 감고 돌아올 때 줄이 모자라지 않습니다. 위에서 아래로 찌르면 매듭이 아니라 스스로 조여지는 올가미(Slip Knot)가 되므로, 반드시 '땅속(아래)에서 지상(위)으로' 탈출시키는 방향을 엄수해야 합니다.\",\n      \"actionNote\": \"> 방향 확인: 토끼가 땅속 굴에서 고개를 내밀 듯 [밑 ➔ 위]로 통과해야 합니다. 반대로 꽂으면 하중을 받을 때 고리가 목을 죄는 올가미로 변질됩니다.\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // BOWLINE STEP 2: 토끼굴 상향 탈출\",\n        \"EMERGE FROM HOLE\",\n        \"굴 아래에서 위로 탈출\",\n        \"토끼 머리 15cm\",\n        \"충분한 길이 인출\",\n        \"MAIN EYE LOOP\",\n        \"최종 하중을 받을 큰 고리\",\n        \"[2단계 핵심] 굴 밑바닥에서 위쪽으로 토끼를 쑥 뽑아 올림\",\n        \"위에서 아래로 찌르면 매듭이 풀리는 올가미가 되므로 절대 주의하십시오.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"3단계: 토끼가 곧게 뻗은 큰 나무(원줄)의 뒤편을 한 바퀴 빙 둘러 감기\",\n      \"description\": \"토끼굴을 빠져나온 토끼(줄 끝)를 이끌고, 수직으로 곧게 서 있는 원줄(나무)의 '뒤쪽(Back)'을 감싸 안듯이 시계 반대 방향으로 빙 돌아 나옵니다. 이때 원줄의 앞쪽을 가로지르면 결속 잠금 루프가 형성되지 않습니다. 원줄의 등 뒤를 한 바퀴 감아 돌리는 이 동작이 훗날 엄청난 하중이 걸려도 1초 만에 매듭을 풀어주는 기적의 '칼라(Collar, 깃) 루프'를 만들어냅니다.\",\n      \"actionNote\": \"> 배면 회전 원칙: 토끼는 반드시 나무의 '등 뒤'로 돌아 나와야 합니다. 앞쪽으로 돌리면 매듭 형태가 깨지고 마찰 잠금력이 발생하지 않습니다.\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // BOWLINE STEP 3: 나무(원줄) 뒤편 선회\",\n        \"AROUND THE TREE\",\n        \"원줄 '뒤쪽'을 감아 돔\",\n        \"TREE (나무 기둥줄)\",\n        \"토끼가 돌아 나갈 중심 축\",\n        \"RE-ENTRY READY\",\n        \"다시 굴로 진입할 준비\",\n        \"[3단계 핵심] 굴에서 나온 토끼가 원줄 뒤편을 감싸 돎\",\n        \"반드시 원줄의 '뒤'로 돌아야 단단히 조여지는 칼라(Collar) 루프가 만들어집니다.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"4단계: 토끼가 나왔던 토끼굴 속으로 다시 위에서 아래로 쏙 들어가기\",\n      \"description\": \"나무 뒤를 한 바퀴 돌아 나온 토끼(줄 끝)를, 2단계에서 처음 뛰쳐나왔던 그 토끼굴 속으로 다시 밀어 넣습니다. 이때의 진입 방향은 2단계와 정반대인 '위에서 아래로(Down)'입니다. 굴 속으로 토끼를 찔러 넣으면, 굴 안쪽에서 들어가는 줄과 2단계에서 나왔던 줄 두 가닥이 나란히 평행(Parallel)을 이루게 됩니다. 이로써 모든 기하학적 엮임 구조가 완벽하게 정렬되었습니다.\",\n      \"actionNote\": \"> 나란한 정렬 확인: 토끼굴 안에 토끼의 몸통 두 가닥이 나란히 겹쳐 있는지 확인하세요. 줄이 꼬이지 않고 평행해야 마찰력이 고르게 분산됩니다.\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // BOWLINE STEP 4: 토끼굴 재진입\",\n        \"BACK INTO HOLE\",\n        \"위에서 아래로 재진입\",\n        \"PARALLEL STRANDS\",\n        \"두 가닥이 나란히 정렬\",\n        \"COLLAR LOOP\",\n        \"나무를 감싼 뒤통수 고리\",\n        \"[4단계 핵심] 토끼가 굴 속으로 다시 쏙 들어감\",\n        \"나무를 돌아 나온 끝단을 처음 나왔던 토끼굴에 위에서 아래로 찔러 넣습니다.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"5단계: 양손으로 쥐고 4방향 락킹 체결 및 1초 해체 비법 체화하기\",\n      \"description\": \"한 손으로는 토끼(줄 끝)와 고리의 오른쪽 가닥을 함께 단단히 쥐고, 다른 손으로는 위쪽 원줄(Standing Part)을 잡은 뒤 반대 방향으로 힘차게 팽팽하게 잡아당깁니다. 사방으로 장력이 가해지며 밧줄들이 서로를 강하게 쥐어짜 매듭이 단단하게 잠깁니다(Locking). 이렇게 완성된 루프는 트럭이 끌어도 크기가 변하지 않습니다. 사용 후 풀 때는 매듭 뒤편의 U자형 둥근 칼라(Collar)를 엄지손가락으로 툭 뒤로 젖히면(Break the back), 밧줄 사이의 마찰각이 즉시 무너지며 1초 만에 스르륵 분리됩니다.\",\n      \"actionNote\": \"> 1초 쾌속 해체 요령: 절대 손톱으로 매듭을 뜯지 마세요! 매듭 뒤편을 보면 원줄을 안고 있는 U자형 고리가 보입니다. 이 뒤통수 고리를 엄지로 바깥쪽으로 젖히면 거짓말처럼 스르륵 풀립니다.\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // BOWLINE STEP 5: 락킹 및 1초 해체\",\n        \"1-SEC QUICK RELEASE\",\n        \"뒤통수(칼라) 꺾기 비법\",\n        \"엄지로 칼라를 꺾으면 즉시 해체\",\n        \"PULL STANDING\",\n        \"원줄을 위로 강하게 당김\",\n        \"GRIP TOGETHER\",\n        \"끝단과 고리를 한 손에 쥠\",\n        \"LOCKED FIXED LOOP\",\n        \"하중을 받아도 크기 불변\",\n        \"[5단계 핵심] 양손으로 잡고 반대로 당겨 락킹 체결\",\n        \"풀 때는 매듭 뒤편 칼라 링을 엄지로 젖히면 칼 없이 1초 만에 풀립니다.\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"절대 하면 안 되는 실수: 줄 끝(토끼)이 완성된 고리 바깥쪽으로 튀어나온 '변형 보울라인'\",\n    \"description\": \"보울라인 매듭의 정격 완성 상태에서는 줄 끝(토끼 꼬리)이 반드시 완성된 큰 원형 고리(루프)의 '안쪽(Inside)'에 자리 잡아야 합니다. 만약 줄 끝이 고리 바깥쪽(Outside)으로 삐져나온 채 묶이면, 이를 '카우보이 보울라인(또는 네덜란드 해군 보울라인)' 혹은 불완전 변형이라 부릅니다. 이 상태에서 은신처를 세우거나 짐을 끌면, 바깥으로 노출된 줄 끝이 나뭇가지나 바위에 스치며 쓸리는 순간 매듭이 자가 해제되어 짐이 추락하거나 텐트가 와르르 무너지는 치명적 사고를 초래합니다.\",\n    \"consequence\": \"결과: 외부 마찰 및 횡방향 비틀림에 의한 매듭 자가 풀림, 은신처 붕괴 및 지탱 하중 추락 사고\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"트럭이 끌어도 안 풀리고, 손가락 하나로 1초 만에 푸는 '매듭의 왕' 보울라인입니다.\",\n    \"body\": \"야생에서 딱 하나의 매듭만 배워야 한다면 무조건 이것입니다. 토끼와 나무 딱 4박자만 외우세요. 1단계, 줄 위에 원을 얹어 숫자 6 모양 토끼굴을 만듭니다. 2단계, 토끼가 굴 밑에서 위로 쏙 나옵니다. 3단계, 앞에 선 큰 나무 뒤편을 한 바퀴 빙 돌아 나옵니다. 4단계, 원래 나왔던 굴 속으로 위에서 아래로 쏙 들어갑니다. 끝단과 고리를 잡고 원줄을 당기면 락킹 끝! 체중이 실려도 고리 크기가 절대 줄지 않습니다. 풀 때는 칼 필요 없이, 뒤통수 U자 고리를 엄지로 툭 꺾으면 1초 만에 스르륵 풀립니다. 단, 줄 끝이 고리 바깥으로 삐져나오면 나뭇가지에 걸려 풀리니 꼭 고리 안쪽으로 넣으세요.\",\n    \"outro\": \"비바람 속에서도 스마트폰 없이 꺼내보는 오프라인 생존 도면은 프로필 링크에서 확인하세요.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"보울라인 매듭 (매듭의 왕) 완성도\",\n    \"description\": \"하중이 실려도 크기가 변하지 않는 견고한 루프와 1초 만에 푸는 뒤통수 꺾기(Break the Back) 해체 구조를 보여주는 보울라인 매듭 표준 제원도입니다.\"\n  }\n}\n","content/protocols/locales/01-water-purification.de.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Aufbereitung von Wildwasser (Aktivkohle-Filtration)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Das Trinken von unbehandeltem Wildwasser führt durch bakterielle Ruhr und Giardiasis innerhalb von 72 Stunden zum Tod. Das Wasser muss mechanisch über Holzkohle gefiltert und anschließend zwingend abgekocht werden.\",\n  \"timeRequired\": \"15 MINUTEN\",\n  \"successRate\": \"99.8% (Nach Abkochen)\",\n  \"difficulty\": \"Stufe 1 (Grundlegende Bushcraft)\",\n  \"outputPerHour\": \"1.5 Liter / Stunde\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Zerkleinerte Hartholzkohle\",\n      \"desc\": \"Abgekühlte Glutreste aus Hartholz, erbsengroß zerstoßen zur Adsorption von Toxinen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Gereinigter Flusssand & Feinkies\",\n      \"desc\": \"Gewaschener Sand und kleine Kieselsteine zur physischen Rückhaltung von Schwebstoffen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Bambusrohr oder Rindentrichter\",\n      \"desc\": \"Hohles Bambussegment (Ø 8 cm) als vertikale Schwerkraft-Filtersäule.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Behältervorbereitung & Filterbasis-Aufbau\",\n      \"description\": \"Bereiten Sie ein zylindrisches Gefäß mit oberer Einfüllöffnung und verengtem Auslass an der Unterseite vor.\",\n      \"actionNote\": \"> Maßnahme: Stopfen Sie Pflanzenfasergewebe oder Torfmoos fest in die untere Öffnung, um das Ausspülen der Kohle zu verhindern.\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"ROHWASSER\",\n        \"1. Kies (Grobschmutz)\",\n        \"2. Sand (Feinsediment)\",\n        \"KOHLE\",\n        \"3. Aktivkohle (Toxine)\",\n        \"4. Textilnetz (Stütze)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schichtung der Filtermedien (Umgekehrte Pyramide)\",\n      \"description\": \"Schichten Sie präzise von unten nach oben: Textilnetz → 6 cm zerstoßene Holzkohle → 5 cm Feinsand → 3 cm grober Kies.\",\n      \"actionNote\": \"> Prinzip: Kies blockiert Grobschmutz, Sand fängt Trübungen ab und poröse Aktivkohle bindet organische Gifte und Gerüche.\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[500ml VERWERFEN]\",\n        \"Kohlestaub-Spülung\",\n        \"→\",\n        \"[AUFFANGEN]\",\n        \"95% Klarheit\",\n        \"Durchfluss: 1~2 Tropfen/Sek\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Filtration & Thermische Entkeimung (100°C)\",\n      \"description\": \"Gießen Sie Rohwasser langsam auf die Kiesschicht (Durchfluss: 1–2 Tropfen/Sek.) und kochen Sie das klare Filtrat anschließend sprudelnd ab.\",\n      \"actionNote\": \"> Warnung: Verwerfen Sie die ersten 500 ml wegen Kohlestaub. Danach mindestens 3 Minuten bei 100°C sprudelnd abkochen.\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C Direktfeuer\",\n        \"100°C\",\n        \"3 Min Halten\",\n        \"99.9% Steril\",\n        \"Kochzeit (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"TÖDLICHER IRRTUM: Gefiltertes klares Wasser niemals ungekocht trinken.\",\n    \"description\": \"Mechanische Kohlefiltration entfernt nur Schwebstoffe und Chemikalien. Viren, Giardia-Zysten und Kryptosporidien passieren den Filter ungehindert. Erst 1 bis 3 Minuten sprudelndes Kochen tötet 99.9% aller Erreger ab.\",\n    \"consequence\": \"Folge bei Verzicht auf Abkochen: Akute Kryptosporidiose und tödliche Dehydrierung binnen 96 Stunden.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Vollendeter Schicht-Wasserfilter aus Kohle und Sand\",\n    \"description\": \"Ein am Dreibein aufgehängter Zylinder mit 5 verdichteten Filterschichten aus Holzkohle, feinem Sand und Kies, der Schlammwasser in klares Trinkwasser umwandelt.\"\n  }\n}\n","content/protocols/locales/01-water-purification.en.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"How to Drink Dirty Water (Wild Charcoal Filter)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"Drinking untreated wild water can lead to fatal bacterial dysentery and giardiasis, resulting in death from dehydration within 72 hours. Water must undergo mechanical active charcoal filtration followed by compulsory thermal boiling.\",\n  \"timeRequired\": \"15 MINUTES\",\n  \"successRate\": \"99.8% (Post-Boiling)\",\n  \"difficulty\": \"Tier 1 (Primitive Bushcraft)\",\n  \"outputPerHour\": \"1.5 Liters / Hour\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Crushed Hardwood Charcoal\",\n      \"desc\": \"Remnants from campfire. Crush to pea-sized bits to chemically adsorb toxins and heavy metals.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Clean River Sand & Fine Gravel\",\n      \"desc\": \"Rinsed coarse sand and small pebbles to physically trap micro-sediments and debris.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Cut Plastic Bottle or Hollow Bamboo Tube\",\n      \"desc\": \"Cut bottom off a 2L bottle and invert, or use hollow 3-inch diameter bamboo stalk.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Vessel Preparation & Filter Base Assembly\",\n      \"description\": \"Using a sharp survival knife, cut 3 inches (7-8cm) off the bottom of a plastic bottle to form a wide funnel. Invert with spout facing down.\",\n      \"actionNote\": \"> Action: Pierce 3 small pinholes in the cap, or tightly pack cotton cloth/sphagnum moss to prevent filtration medium loss.\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"RAW WATER\",\n        \"1. Gravel (Coarse Debris)\",\n        \"2. Sand (Fine Sediment)\",\n        \"CHARCOAL\",\n        \"3. Charcoal (Toxin Adsorb)\",\n        \"4. Cloth Mesh (Base Plug)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Layering the Filter Media (Inverted Pyramid Hierarchy)\",\n      \"description\": \"Strictly stack layers in reverse order: Spout cloth plug -> 2.5 inches (6cm) crushed charcoal -> 2 inches (5cm) fine sand -> 1.2 inches (3cm) coarse gravel.\",\n      \"actionNote\": \"> Science: Gravel blocks floating leaves, sand captures particulates, and porous activated charcoal adsorbs organic toxins and odors.\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[DISCARD 500ml]\",\n        \"Charcoal Dust Flush\",\n        \"→\",\n        \"[COLLECT CLEAN]\",\n        \"95% Clarity Reached\",\n        \"Flow Rate: 1~2 drops / sec\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Pouring Turbid Water & Clear Water Collection\",\n      \"description\": \"Slowly pour murky water onto the top gravel bed. Gravity will draw water through the column at roughly one steady drop per second into a clean container.\",\n      \"actionNote\": \"> Warning: Discard the initial 250ml containing loose charcoal dust. Continue running water until output runs crystal clear.\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C Direct Boil\",\n        \"100°C\",\n        \"3 Min Hold\",\n        \"99.9% Sterile\",\n        \"Rolling Boil Time (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"FATAL MISTAKE: Never drink filtered water directly without boiling.\",\n    \"description\": \"Mechanical charcoal filtration only removes sediments, heavy metals, and odors. Viruses, Giardia cysts, and Cryptosporidium easily pass through. Filtered water MUST be boiled at a rolling boil for at least 1 minute (3 minutes above 6,500 ft elevation) to ensure total survival safety.\",\n    \"consequence\": \"Consequence of skipping boil: Acute Cryptosporidiosis infection and lethal dehydration within 96 hours.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Completed Stratified Charcoal & Sand Water Purifier\",\n    \"description\": \"A suspended cylinder packed with 5 distinct layers of charcoal, fine sand, coarse sand, gravel, and fiber filter that clarifies turbid surface water into clear potable water.\"\n  }\n}\n","content/protocols/locales/01-water-purification.es.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Purificación de Agua Contaminada (Filtro de Carbón)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"Beber agua silvestre sin tratar provoca disentería bacteriana y giardiasis letal en menos de 72 horas. El agua debe pasar por filtración mecánica de carbón activado seguida obligatoriamente de ebullición térmica.\",\n  \"timeRequired\": \"15 MINUTOS\",\n  \"successRate\": \"99.8% (Tras Ebullición)\",\n  \"difficulty\": \"Nivel 1 (Supervivencia Básica)\",\n  \"outputPerHour\": \"1.5 Litros / Hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carbón de Madera Dura Triturado\",\n      \"desc\": \"Brasas frías de hoguera trituradas al tamaño de un guisante para adsorber toxinas y metales.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Arena de Río Limpia y Grava Fina\",\n      \"desc\": \"Arena lavada y guijarros pequeños para retener sedimentos y partículas en suspensión.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tubo de Bambú Hueco o Cono de Corteza\",\n      \"desc\": \"Sección de bambú de 8 cm de diámetro invertida como columna de filtración por gravedad.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Preparación del Recipiente y Base del Filtro\",\n      \"description\": \"Prepare un cilindro hueco de bambú o recipiente cónico invertido con abertura inferior estrecha para dirigir el flujo por gravedad.\",\n      \"actionNote\": \"> Acción: Coloque un tapón denso de tela de fibra vegetal o musgo esfagno en la boquilla inferior para evitar la fuga del carbón.\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"AGUA CRUDA\",\n        \"1. Grava (Residuos)\",\n        \"2. Arena (Sedimentos)\",\n        \"CARBÓN\",\n        \"3. Carbón (Toxinas)\",\n        \"4. Malla Textil (Base)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Estratificación del Medio Filtrante (Pirámide Invertida)\",\n      \"description\": \"Apile las capas en orden inverso estricto desde abajo hacia arriba: malla de fibra → 6 cm de carbón triturado → 5 cm de arena fina → 3 cm de grava gruesa.\",\n      \"actionNote\": \"> Ciencia: La grava detiene residuos grandes, la arena atrapa micropartículas y la matriz porosa del carbón adsorbe toxinas químicas.\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[DESCARTAR 500ml]\",\n        \"Purga de Polvo\",\n        \"→\",\n        \"[RECOGER AGUA]\",\n        \"95% Claridad\",\n        \"Flujo: 1~2 gotas / seg\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Vertido de Agua Turbia y Esterilización por Ebullición\",\n      \"description\": \"Vierta el agua turbia lentamente sobre la grava superior. Recoja el agua filtrada a un ritmo constante de 1 a 2 gotas por segundo y hiérvala a 100°C.\",\n      \"actionNote\": \"> Advertencia: Descarte los primeros 500 ml con polvo de carbón. Hierva el agua clara durante al menos 3 minutos antes de beber.\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C Fuego Directo\",\n        \"100°C\",\n        \"3 Minutos\",\n        \"99.9% Letal\",\n        \"Tiempo Ebullición (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"ERROR FATAL: Nunca beba el agua filtrada sin hervirla primero.\",\n    \"description\": \"La filtración mecánica con carbón elimina sedimentos y químicos, pero los virus, quistes de Giardia y Cryptosporidium atraviesan el filtro. Debe hervir el agua filtrada vigorosamente durante al menos 1 a 3 minutos.\",\n    \"consequence\": \"Consecuencia de omitir la ebullición: Infección parasitaria aguda y muerte por deshidratación en 96 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Purificador Primitivo de Carbón y Arena Completado\",\n    \"description\": \"Un cilindro suspendido en un trípode con 5 capas compactadas de carbón, arena y grava que clarifica el agua turbia en agua potable transparente.\"\n  }\n}\n","content/protocols/locales/01-water-purification.ja.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"泥水を安全に飲む方法 (野生炭ろ過)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険度: 致命的(CRITICAL)]\",\n  \"summary\": \"汚染された自然水をそのまま飲用すると、細菌性赤痢やジアルジア症（原虫感染）により72時間以内に脱水死に至る恐れがあります。木炭の多孔質吸着による物理ろ過工程を経て、必ず加熱沸騰による滅菌を行わなければなりません。\",\n  \"timeRequired\": \"15分 (15 MINUTES)\",\n  \"successRate\": \"99.8% (煮沸滅菌後)\",\n  \"difficulty\": \"第1等級 (原始ブッシュクラフト技術)\",\n  \"outputPerHour\": \"1.5リットル / 時間\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"粉砕した広葉樹の木炭 (HARDWOOD CHARCOAL)\",\n      \"desc\": \"焚き火の残り炭。エンドウ豆大に細かく砕き、毒素や有害物質を吸着させる。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"清潔な川砂 ＆ 小砂利 (SAND & GRAVEL)\",\n      \"desc\": \"水洗いした川砂と小石。微細な浮遊物や濁りを物理的に遮断する。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"切断したペットボトルまたは竹筒 (BOTTLE/TUBE)\",\n      \"desc\": \"底を切り抜いた2Lペットボトルを逆さにするか、直径8cm以上の太い竹を活用。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"容器の切断とろ過ベースの構築\",\n      \"description\": \"サバイバルナイフでペットボトルの底から7〜8cmの箇所を水平に切り、広い漏斗状にします。飲み口を下にして逆さに配置してください。\",\n      \"actionNote\": \"> 処置事項: キャップにピンで3箇所穴を開けるか、綿布や乾燥したミズゴケを飲み口に固く詰め、ろ過材の流出を防ぎます。\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"RAW WATER\",\n        \"1. 砂利層 (大型不純物)\",\n        \"2. 砂層 (微細沈殿物)\",\n        \"CHARCOAL\",\n        \"3. 活性炭 (毒素吸着)\",\n        \"4. 繊維網 (基底支持)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ろ過材の階層充填 (逆ピラミッド構造)\",\n      \"description\": \"逆三角形の層状構造で厳密に充填します: 飲み口の綿布プラグ → 粉砕木炭(6cm) → 細かい砂(5cm) → 粗い砂利(3cm)の順序です。\",\n      \"actionNote\": \"> 科学的根拠: 砂利が枯葉等の粗いゴミを遮断し、砂が泥濁りを捕集し、多孔質活性炭が化学物質や異臭を化学吸着します。\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[初期500ml廃棄]\",\n        \"炭粉排出区間\",\n        \"→\",\n        \"[本ろ過水採取]\",\n        \"透明度95%達成\",\n        \"流速規格: 毎秒1〜2滴滴下\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"汚濁水の注入と透明ろ過水の採取\",\n      \"description\": \"最上部の砂利層に濁水を静かに注ぎます。重力浸透により、毎秒約1滴の安定したペースで清潔な受け皿に滴下させます。\",\n      \"actionNote\": \"> 注意: 最初に抽出された約250mlのろ過水は微細な炭粉を含むため廃棄してください。完全に透明な水が出るまで通水し続けます。\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C 直火加熱\",\n        \"100°C\",\n        \"3分間維持\",\n        \"死滅率 99.9%\",\n        \"沸騰維持時間 (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な過誤: ろ過された透明な水も、絶対にそのまま飲んではいけません。\",\n    \"description\": \"木炭ろ過は浮遊物や化学物質、臭気を取り除くだけで、ウイルスやジアルジア胞嚢、クリプトスポリジウムなどの微小な病原体はそのまま通過します。ろ過された水を必ず最低1分間以上（標高2000m以上では3分）激しく沸騰させて初めて、安全に飲用可能となります。\",\n    \"consequence\": \"煮沸を省略した場合の結末: 急性感染症による激しい下痢および96時間以内の脱水死\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"炭・砂3重ろ過原始浄水器の完成形態\",\n    \"description\": \"木の枝の三脚に吊るした円筒容器の内部に、炭、細砂、砂利、繊維フィルターを多層圧縮充填し、上部の濁水を下部から透明な飲料水へとろ過する完成構造です。\"\n  }\n}\n","content/protocols/locales/01-water-purification.pt.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"Purificação de Água Selvagem (Filtro de Carvão)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"Beber água selvagem não tratada causa disenteria bacteriana e giardíase letal em até 72 horas. A água deve passar por filtragem mecânica de carvão ativado seguida obrigatoriamente de fervura térmica.\",\n  \"timeRequired\": \"15 MINUTOS\",\n  \"successRate\": \"99.8% (Pós-Fervura)\",\n  \"difficulty\": \"Nível 1 (Sobrevivência Primitiva)\",\n  \"outputPerHour\": \"1.5 Litros / Hora\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Carvão de Madeira Dura Triturado\",\n      \"desc\": \"Brasas frias de fogueira trituradas do tamanho de ervilhas para adsorver toxinas.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Areia Limpa de Rio e Cascalho Fino\",\n      \"desc\": \"Areia lavada e pequenos seixos para retenção física de micropartículas e lodo.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tubo de Bambu Oco ou Cone de Casca\",\n      \"desc\": \"Coluna cilíndrica de bambu (Ø 8 cm) posicionada verticalmente para filtragem por gravidade.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Preparação do Recipiente e Base do Filtro\",\n      \"description\": \"Prepare o cilindro coletor invertido formando um funil largo no topo e saída estreita na base.\",\n      \"actionNote\": \"> Ação: Compacte fibra vegetal trançada ou musgo esfagno no bocal inferior para reter os grãos de carvão.\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"ÁGUA BRUTA\",\n        \"1. Cascalho (Detritos)\",\n        \"2. Areia (Sedimentos)\",\n        \"CARVÃO\",\n        \"3. Carvão (Toxinas)\",\n        \"4. Malha Têxtil (Base)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Camadas do Meio Filtrante (Pirâmide Invertida)\",\n      \"description\": \"Empilhe rigorosamente de baixo para cima: malha têxtil → 6 cm de carvão triturado → 5 cm de areia fina → 3 cm de cascalho grosso.\",\n      \"actionNote\": \"> Ciência: O cascalho barra detritos maiores, a areia retém sedimentos finos e o carvão poroso adsorve toxinas químicas.\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[DESCARTAR 500ml]\",\n        \"Purga de Pó\",\n        \"→\",\n        \"[COLETAR ÁGUA]\",\n        \"95% Limpeza\",\n        \"Fluxo: 1~2 gotas / seg\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Filtragem Lenta e Esterilização por Fervura\",\n      \"description\": \"Despeje a água bruta lentamente sobre o cascalho (1 a 2 gotas/seg) e submeta a água limpa coletada à fervura direta a 100°C.\",\n      \"actionNote\": \"> Atenção: Descarte os primeiros 500 ml escuros com pó de carvão. Ferva a água límpida por 3 minutos contínuos.\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C Fogo Direto\",\n        \"100°C\",\n        \"3 Minutos\",\n        \"99.9% Estéril\",\n        \"Tempo Fervura (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"ERRO FATAL: Nunca beba a água filtrada diretamente sem ferver.\",\n    \"description\": \"A filtragem mecânica com carvão remove apenas turbidez e compostos químicos; vírus, cistos de Giardia e Cryptosporidium atravessam o filtro. É obrigatório ferver vigorosamente por pelo menos 1 a 3 minutos.\",\n    \"consequence\": \"Consequência ao pular a fervura: Infecção aguda por protozoários e morte por desidratação em 96 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"Purificador Primitivo de Carvão e Areia Concluído\",\n    \"description\": \"Um cilindro suspenso em tripé com 5 camadas compactadas de carvão, areia e cascalho que clarifica água turva em água potável transparente.\"\n  }\n}\n","content/protocols/locales/01-water-purification.zh-TW.json":"{\n  \"protocolId\": \"PR-01\",\n  \"category\": \"WATER\",\n  \"title\": \"野外受污染水源淨化指南 (活性木炭過濾法)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命 (CRITICAL)]\",\n  \"summary\": \"直接飲用未經處理的野外水源會導致細菌性痢疾與梨形鞭毛蟲感染，於72小時內脫水死亡。必須先透過多層木炭物理過濾懸浮雜質，再進行強制高溫沸騰滅菌。\",\n  \"timeRequired\": \"15分鐘 (15 MINUTES)\",\n  \"successRate\": \"99.8% (沸騰滅菌後)\",\n  \"difficulty\": \"第1級 (基礎原始求生技術)\",\n  \"outputPerHour\": \"1.5公升 / 小時\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"粉碎硬木木炭 (HARDWOOD CHARCOAL)\",\n      \"desc\": \"營火殘留的完全碳化硬木炭，敲碎至豌豆大小以吸附毒素與重金屬。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"潔淨河砂與細礫石 (SAND & GRAVEL)\",\n      \"desc\": \"淘洗過的河砂與小鵝卵石，物理攔截微細懸浮物與泥沙。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"中空竹筒或樹皮漏斗容器 (TUBE/VESSEL)\",\n      \"desc\": \"直徑約8公分之竹筒或倒置容器，作為重力滲透過濾柱。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"容器裁切與過濾基底構築\",\n      \"description\": \"準備上寬下窄的漏斗狀竹筒或容器，將出水口朝下垂直固定，建立四層重力過濾結構。\",\n      \"actionNote\": \"> 處置要領：於底部出水口緊密塞入植物纖維網或乾燥水苔，防止上方木炭顆粒隨水流流失。\",\n      \"svgFileName\": \"step-01.svg\",\n      \"svgLabels\": [\n        \"原水輸入\",\n        \"1. 礫石層 (大型雜質)\",\n        \"2. 細砂層 (微細沉澱)\",\n        \"CHARCOAL\",\n        \"3. 活性木炭 (毒素吸附)\",\n        \"4. 纖維網 (濾材支撐)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"濾材分層填充與初段炭粉排空\",\n      \"description\": \"由下往上依序嚴格鋪設：底部纖維網 → 6公分粉碎木炭 → 5公分細砂 → 3公分粗礫石，並控制流速為每秒1至2滴。\",\n      \"actionNote\": \"> 科學原理：礫石阻擋大型雜質，細砂攔截泥濁微粒，多孔木炭吸附有機毒素；初段500ml含炭粉黑水必須捨棄。\",\n      \"svgFileName\": \"step-02.svg\",\n      \"svgLabels\": [\n        \"[捨棄初段500ml]\",\n        \"炭粉排出區間\",\n        \"→\",\n        \"[收集淨化水]\",\n        \"達成95%透明度\",\n        \"流速規格：每秒滴落1~2滴\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"收集淨化水與100°C強制沸騰滅菌\",\n      \"description\": \"達成95%透明度的過濾水收集後，必須置於營火上以100°C直火劇烈沸騰至少3分鐘，達到99.9%病原體滅絕率。\",\n      \"actionNote\": \"> 警告：即使過濾後水質清澈見底，未經沸騰滅菌前絕對禁止飲用。\",\n      \"svgFileName\": \"step-03.svg\",\n      \"svgLabels\": [\n        \"100°C 直火沸騰\",\n        \"100°C\",\n        \"持續3分鐘\",\n        \"滅菌率 99.9%\",\n        \"沸騰維持時間 (MIN)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：過濾後的清澈水絕對不可直接生飲。\",\n    \"description\": \"木炭物理過濾僅能去除泥沙、化學物質與異味，病毒、梨形鞭毛蟲囊體與隱孢子蟲仍會穿透濾層。過濾水必須經過100°C滾沸至少1至3分鐘方可安全飲用。\",\n    \"consequence\": \"省略沸騰之後果：急性隱孢子蟲感染引發劇烈腹瀉，於96小時內脫水死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr01-outcome.svg\",\n    \"title\": \"木炭細沙三重過濾原始淨水器完成形態\",\n    \"description\": \"懸掛於樹枝三腳架上的圓筒內部，由木炭、細沙、碎石與纖維濾層緊密壓實分層，使上方泥水於下方出水口滴濾為清澈透明的飲用水。\"\n  }\n}\n","content/protocols/locales/02-friction-fire.de.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Feuerbohren durch Reibungswärme (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Primitive Pyrotechnik, die durch mechanische Reibung zwischen trockenem Weichholz und einer Bogenspindel über 400°C heiße Glutkohle erzeugt und durch gezielte Sauerstoffzufuhr entzündet.\",\n  \"timeRequired\": \"20 MINUTEN\",\n  \"successRate\": \"85% (Trockenholz)\",\n  \"difficulty\": \"Stufe 2 (Fortgeschrittene Technik)\",\n  \"outputPerHour\": \"1 Feuer / 20 Min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bogenstab & Pflanzenfasersehne (BOW & STRING)\",\n      \"desc\": \"60–70 cm langer, leicht gebogener Hartholzast (Esche/Hasel) und reißfeste Naturfaserschnur.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Rotationsspindel (SPINDLE)\",\n      \"desc\": \"Gerader Zylinder (Ø 20 mm) aus trockener Zeder oder Weide. Oben abgerundet, unten 45°-Kegel.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Feuerbrett mit V-Kerbe & Zundernest (HEARTH & TINDER)\",\n      \"desc\": \"15–20 mm dickes Feuerbrett mit 45° V-Kerbe, Glutauffangblatt und trockenem Zundernest.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"45° V-Kerben-Zuschnitt & Spindelzentrierung\",\n      \"description\": \"Schnitzen Sie eine präzise 45-Grad-V-Kerbe von der Vorderkante des Feuerbretts exakt bis zum Mittelpunkt der Spindelbohrung. Legen Sie ein trockenes Blatt als Glutauffang darunter.\",\n      \"actionNote\": \"> Feldregel: Überschreitet der Kerbenwinkel 60 Grad, entweicht die Wärme und der Zündpunkt von 400°C wird nicht erreicht.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"GLUTAUFFANGBLATT [RINDENBASIS]\",\n        \"45° V-KERBE (Spitze am Achszentrum)\",\n        \"Ø 20mm SPINDELACHSE\",\n        \"DICKE: 15~20mm\",\n        \"FEUERBRETT (HEARTH BOARD)\",\n        \"KERBENSPITZE (Exakt im Bohrlochzentrum)\",\n        \"KRITISCHE AUFBAUREGEL:\",\n        \"V-Kerbenspitze muss Achszentrum berühren\",\n        \"KOHLESTAUB-SAMMELZONE (GLUTBETT)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90° Vertikaldruck & Vollhub-Hochgeschwindigkeitsrotation\",\n      \"description\": \"Fixieren Sie das Feuerbrett mit dem linken Fuß und üben Sie über das Drucklager 12–15 kg Vertikallast aus. Bewegen Sie den Bogen waagerecht über die volle Länge (300–400 RPM), bis dichter weißer Rauch aufsteigt.\",\n      \"actionNote\": \"> Feldregel: Nicht beim ersten Rauch stoppen! Mindestens 10–15 kraftvolle Endhübe durchführen, damit der Kohlestaub vollständig verschmilzt.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"DRUCKLAGER (HANDSTÜCK)\",\n        \"F_DOWN: 12~15 kg (Vertikallast)\",\n        \"BOGENSTAB (65cm Hartholz)\",\n        \"VOLLHUB-PENDELBEWEGUNG (Volle Bogenlänge)\",\n        \"ω: 300~400 RPM\",\n        \"FEUERBRETT\",\n        \"WEISSER RAUCH (Dichter Rauch)\",\n        \"KRITISCHER SCHWELLENWERT:\",\n        \"Zündtemp.: 400°C+\",\n        \"Druck: Start 30% → Ende 100%\",\n        \"Hub: 100% Bogenlänge nutzen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Glutkern-Einbettung & Sanfte Belüftungszündung (600°C)\",\n      \"description\": \"Lassen Sie den glimmenden Kohlestaub 30 Sekunden lang zu einem festen Glutkern (450°C) reifen. Betten Sie ihn in das Zundernest um, halten Sie es im 45°-Winkel und blasen Sie sanft bis zur Flammenzündung bei 600°C.\",\n      \"actionNote\": \"> Feldregel: Zundernest im 45°-Winkel leicht über Augenhöhe halten – der thermische Aufwind verdoppelt die Sauerstoffzufuhr.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"GLUTKERN (450°C)\",\n        \"SANFTER KONTINUIERLICHER LUFTSTROM\",\n        \"FLAMMENZÜNDUNG (Durchzündung)\",\n        \"45° HALTEWINKEL\",\n        \"TEMPERATURANSTIEG & ZÜNDMATRIX\",\n        \"ZEIT (Sek)\",\n        \"TEMP (°C)\",\n        \"600°C FLAMMEN-ZÜNDSCHWELLE\",\n        \"400°C GLIMMPUNKT (KOHLE)\",\n        \"30s Reifen & Einsetzen (0s)\",\n        \"Flammenausbruch (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Niemals hastig in unfertigen Kohlestaub blasen\",\n    \"description\": \"Wer sofort nach dem Bohren stark auf das lose schwarze Pulver bläst, zerstreut die feinen Kohlepartikel im Wind und löscht die Kernwärme augenblicklich.\",\n    \"consequence\": \"Ein Scheitern der Feuerzündung bei Kälte beschleunigt das Absinken der Körperkerntemperatur und führt binnen 72 Stunden zum Tod durch Unterkühlung.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Vollendete Bogenbohrer-Reibungszündung mit Glut\",\n    \"description\": \"Eine 400°C heiße Holzkohleglut aus der 45°-V-Kerbe, die sicher in das trockene Zundernest überführt und zu einer offenen Flamme entfacht wurde.\"\n  }\n}\n","content/protocols/locales/02-friction-fire.en.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Bow Drill Friction Fire Method\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"A primitive pyrotechnology protocol using mechanical friction between dry softwood and a bow drill to generate carbon dust embers exceeding 400°C, followed by concentrated aeration to achieve ignition.\",\n  \"timeRequired\": \"20 MINUTES\",\n  \"successRate\": \"85% (Dry Timber)\",\n  \"difficulty\": \"Tier 2 (Skilled Primitive)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Bow & Vine String (BOW & STRING)\",\n      \"desc\": \"Flexible hardwood limb (ash/hazel, 60-70cm) and durable wild kudzu vine cord\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Rotational Spindle (SPINDLE)\",\n      \"desc\": \"Straight 2cm dia x 20cm dry cedar or willow shaft. Blunt top, 45-degree tapered bottom.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hearth Board & Tinder Nest (HEARTH & TINDER)\",\n      \"desc\": \"15-20mm thick hearth board with 45° V-notch, ember collection leaf, and dry tinder nest\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"V-Notch Carving & Spindle Axis Seating\",\n      \"description\": \"Carve a precise 45-degree V-notch from the outer edge of the hearth board penetrating directly to the socket center. Place a dry ember collector leaf beneath to trap hot carbon dust.\",\n      \"actionNote\": \"> Field Rule: If the notch angle exceeds 60 degrees, thermal dissipation will prevent the dust from reaching the 400°C ignition threshold.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [DRY BARK/LEAF]\",\n        \"45° V-NOTCH (Apex Meets Axis Center)\",\n        \"Ø 20mm SPINDLE AXIS\",\n        \"THICKNESS: 15~20mm\",\n        \"HEARTH BOARD (SOFTWOOD)\",\n        \"NOTCH APEX (Aligned with Socket Center)\",\n        \"CRITICAL SETUP RULE:\",\n        \"Notch apex must touch spindle axis center\",\n        \"CARBON DUST ACCUMULATION ZONE (EMBER BED)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90° Downward Load & High-Speed Reciprocating Sawing\",\n      \"description\": \"Anchor the hearth board firmly with your left foot and apply 12-15kg downward load using the bearing block. Saw the bow horizontally with full-length strokes at 300-400 RPM until dense white smoke bursts.\",\n      \"actionNote\": \"> Field Rule: Do not stop when smoke first appears. Continue 10-15 full-power acceleration strokes to ensure complete carbonization in the notch.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (HAND SOCKET)\",\n        \"F_DOWN: 12~15 kg (Vertical Load)\",\n        \"BOW STICK (65cm Curved Limb)\",\n        \"FULL-STROKE RECIPROCATING MOTION (Full Bow Length)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (Dense Smoke Plume)\",\n        \"CRITICAL THRESHOLD:\",\n        \"Ignition Temp: 400°C+\",\n        \"Load: Start 30% → Final 100%\",\n        \"Stroke: Use 100% Bow Length\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Ember Transfusion & Gentle Aeration Ignition\",\n      \"description\": \"Allow the smoking carbon dust to coalesce into a cohesive coal for 30 seconds. Carefully transfer it into the center of a dry tinder nest, cup at a 45-degree elevation, and supply steady, gentle breaths to ignite flame.\",\n      \"actionNote\": \"> Field Rule: Hold the nest at a 45-degree angle slightly above eye level. Rising thermal updrafts double oxygen intake while keeping smoke away from eyes.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"EMBER CORE (450°C)\",\n        \"GENTLE CONTINUOUS BREATH (Steady Low Airflow)\",\n        \"FLAME IGNITION BURST (Flashover Stage)\",\n        \"45° ELEVATION CUPPING\",\n        \"TEMPERATURE RISE & IGNITION MATRIX\",\n        \"TIME (sec)\",\n        \"TEMP (°C)\",\n        \"600°C FLAME IGNITION THRESHOLD\",\n        \"400°C CARBON SMOLDER POINT\",\n        \"Coalesce 30s & Transfer (0s)\",\n        \"Flame Ignition (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Never blow rashly on premature uncoalesced embers\",\n    \"description\": \"Blowing prematurely on loose carbon dust will scatter the delicate ember particles, extinguishing the core heat immediately.\",\n    \"consequence\": \"Failure to start a fire in wilderness freezing conditions leads to irreversible hypothermia and death within 72 hours.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Completed Bow Drill Friction Fire & Ember Ignition\",\n    \"description\": \"A glowing 400°C charcoal ember generated in the 45° V-notch smoking heavily, transferred safely into a dry tinder nest and fanned into an open flame.\"\n  }\n}\n","content/protocols/locales/02-friction-fire.es.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Fuego por Fricción con Arco Táctico (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"Técnica pirotécnica primitiva que utiliza la fricción mecánica entre madera blanda seca y un huso giratorio para generar brasas de carbón a más de 400°C, seguida de oxigenación controlada.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madera Seca)\",\n  \"difficulty\": \"Nivel 2 (Habilidad Técnica)\",\n  \"outputPerHour\": \"1 Fuego / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco y Cuerda de Fibra Natural (BOW & STRING)\",\n      \"desc\": \"Rama firme y flexible de 60-70 cm (fresno/avellano) y cuerda resistente de fibra de kudzu.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Huso Giratorio (SPINDLE)\",\n      \"desc\": \"Cilindro recto de cedro o sauce seco de Ø 20 mm. Extremo superior romo, punta inferior a 45°.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Tabla Base con Muesca V y Yesca (HEARTH & TINDER)\",\n      \"desc\": \"Tabla de 15-20 mm con muesca en V de 45°, hoja recolectora y nido de yesca seca.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Tallado de Muesca en V (45°) y Asiento del Huso\",\n      \"description\": \"Talle una muesca en V precisa de 45 grados desde el borde exterior de la tabla hasta el centro exacto del eje del huso. Coloque una hoja seca debajo para recoger el polvo de carbón caliente.\",\n      \"actionNote\": \"> Regla de Campo: Si el ángulo de la muesca supera los 60°, el calor se dispersa y nunca alcanzará el umbral de ignición de 400°C.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"HOJA RECOLECTORA [BASE DE BRASA]\",\n        \"MUESCA EN V 45° (Vértice en Centro)\",\n        \"EJE HUSO Ø 20mm\",\n        \"ESPESOR: 15~20mm\",\n        \"TABLA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alineado al Centro del Huso)\",\n        \"REGLA CRÍTICA DE AJUSTE:\",\n        \"El vértice en V debe tocar el centro del eje\",\n        \"ZONA DE ACUMULACIÓN DE POLVO DE CARBÓN\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Carga Vertical de 90° yRotación Recíproca de Alta Velocidad\",\n      \"description\": \"Fije la tabla con el pie izquierdo y aplique 12-15 kg de carga vertical con el bloque de apoyo. Deslice el arco horizontalmente usando el 100% de su longitud a 300-400 RPM hasta que brote humo blanco denso.\",\n      \"actionNote\": \"> Regla de Campo: No se detenga al ver el primer humo. Realice 10-15 carreras adicionales a máxima potencia para consolidar la brasa.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOQUE DE APOYO (SOCKET MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁCTICO (Rama 65cm)\",\n        \"MOVIMIENTO RECÍPROCO DE CARRERA COMPLETA\",\n        \"ω: 300~400 RPM\",\n        \"TABLA BASE\",\n        \"HUMO BLANCO (Emisión Densa)\",\n        \"UMBRAL CRÍTICO:\",\n        \"Temp. Ignición: 400°C+\",\n        \"Presión: Inicio 30% → Final 100%\",\n        \"Carrera: 100% Longitud del Arco\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Trasplante de Brasa y Oxigenación Suave a 45°\",\n      \"description\": \"Espere 30 segundos para que el polvo humeante se cohesione en una brasa sólida (450°C). Trasládela al nido de yesca, elévelo a 45° y sople suave y continuamente hasta alcanzar 600°C y encender la llama.\",\n      \"actionNote\": \"> Regla de Campo: Sostenga la yesca a 45° por encima del nivel de los ojos para aprovechar la corriente térmica ascendente y evitar el humo.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPLO SUAVE Y CONTINUO (Flujo Lento)\",\n        \"IGNICIÓN DE LLAMA (Brote Térmico)\",\n        \"ELEVACIÓN A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNICIÓN\",\n        \"TIEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C UMBRAL DE LLAMA ABIERTA\",\n        \"400°C PUNTO DE BRASA ACTIVA\",\n        \"30s Cohesión y Traslado (0s)\",\n        \"Ignición Llama (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Nunca sople bruscamente sobre polvo de carbón recién formado\",\n    \"description\": \"Soplar con fuerza inmediatamente después de detener la fricción dispersará las partículas de carbón no cohesionadas, apagando el núcleo térmico al instante.\",\n    \"consequence\": \"El fallo de ignición en condiciones invernales acelera la pérdida de calor corporal, causando muerte por hipotermia en 72 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignición de Brasa por Fricción con Arco Completada\",\n    \"description\": \"Una brasa incandescente a 400°C generada en la ranura en V, transferida con éxito al nido de yesca seca y avivada hasta producir una llama viva.\"\n  }\n}\n","content/protocols/locales/02-friction-fire.ja.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"ボウドリル摩擦発火法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険等級: 致命的(CRITICAL)]\",\n  \"summary\": \"乾燥した軟木と弓を組み合わせた機械的摩擦熱により、400℃以上の微細炭化粉末(火種)を形成し、集中通気により炎を着火させる原始中核熱源技術。\",\n  \"timeRequired\": \"20分 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥材基準)\",\n  \"difficulty\": \"第2等級 (熟練技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓と葛繊維の弦 (BOW & STRING)\",\n      \"desc\": \"長さ60~70cmの弾力ある堅木(トネリコ等)と強靭な天然葛繊維コード\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"回転軸スピンドル (SPINDLE)\",\n      \"desc\": \"直径2cm×長さ20cmの乾燥スギ/ヤナギの直棒。先端は鈍角、下端は45度円錐加工。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"V字溝火床板＆火口 (HEARTH & TINDER)\",\n      \"desc\": \"厚さ15~20mmの45°Vノッチ火床板、火種受け葉、乾燥した鳥の巣型火口\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"V字溝(ノッチ)加工およびスピンドル軸セットアップ\",\n      \"description\": \"火床板の外縁からソケット中心に向かって45度の鋭利なV字溝を切り込みます。削り出された炭化粉末が逃げずに集積できるよう、板の下に幅広の乾燥葉を敷きます。\",\n      \"actionNote\": \"> 野戦核心: ノッチの頂角が60度以上に広がると熱が逃げ、発火点(400℃)に到達しません。厳密な45度を維持してください。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER LEAF [火種受け葉]\",\n        \"45° V-NOTCH (溝頂点: 軸中心に接触)\",\n        \"Ø 20mm スピンドル軸\",\n        \"板厚: 15~20mm\",\n        \"HEARTH BOARD (火床板)\",\n        \"ノッチ頂点 (ソケット中心と一致)\",\n        \"重要セットアップ規則:\",\n        \"V溝の頂点はスピンドル軸中心と正確に接触\",\n        \"CARBON DUST ZONE (炭化火種集積区域)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90度垂直加圧および高速往復摩擦回転\",\n      \"description\": \"左足で火床板を踏み込み、ハンドブロックでスピンドルを垂直に12~15kgの荷重で押さえ込みます。弓を水平に保ち全ストロークで往復させ、濃厚な白煙が出るまで300~400RPMで回転させます。\",\n      \"actionNote\": \"> 野戦核心: 煙が出てもすぐに止めないでください。発煙後、最低10~15回の全力加速ストロークを継続し、完全に炭化結合させます。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BEARING BLOCK (ハンドソケット)\",\n        \"F_DOWN: 12~15 kg (垂直荷重)\",\n        \"BOW STICK (長さ65cm 弓枝)\",\n        \"FULL-STROKE MOTION (弓全長での往復ストローク)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"WHITE SMOKE (濃密な白煙放出)\",\n        \"臨界しきい値:\",\n        \"発火温度: 400°C+\",\n        \"加圧比率: 初期30% → 終期100%\",\n        \"ストローク: 弓全長100%使用\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"炭化火種の火口移植および緩慢通気着火\",\n      \"description\": \"火種受け葉に落ちた黒色粉末が自活煙を維持するまで30秒待機します。固まった火種を火口の中央に移し、45度の角度で持ち上げて穏やかで均一な息を吹き込み、600℃以上に急上昇させて発火させます。\",\n      \"actionNote\": \"> 野戦核心: 目線より少し高い45度上方に火口を掲げてください。煙が目を刺激するのを防ぎ、上昇気流が酸素吸入効率を倍増させます。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種コア (450°C)\",\n        \"GENTLE BREATH (均一な低速送風)\",\n        \"FLAME IGNITION (自然発火・着火段階)\",\n        \"45° 上方保持\",\n        \"温度上昇＆着火マトリックス\",\n        \"時間 (秒)\",\n        \"温度 (°C)\",\n        \"600°C 火炎発火しきい値\",\n        \"400°C 炭化燻焼ポイント\",\n        \"30秒凝集後に移植 (0秒)\",\n        \"火炎着火 (15~20秒)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"未形成の火種に性急に強い息を吹き込んではならない\",\n    \"description\": \"摩擦停止直後に焦ってバラバラの黒色木粉に直接強い息を吹き込むと、微細炭化粒子が飛散し、中核熱源が瞬時に消滅します。\",\n    \"consequence\": \"寒冷荒野環境での着火失敗は深部体温低下を加速させ、72時間以内の低体温症死に直結します。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"ボウドリル摩擦発火および火種着火の完成形態\",\n    \"description\": \"火床板の45度V溝に摩擦熱で生じた黒い炭粉の熾火(400°C)が赤く燃え上がり、これを乾燥した火口の巣に移して炎を立ち上げた実戦発火の完成状態です。\"\n  }\n}\n","content/protocols/locales/02-friction-fire.pt.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"Fogo por Fricção com Arco e Fuso (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"Tecnologia primitiva de ignição que utiliza o atrito mecânico entre madeira macia seca e um fuso rotativo para gerar brasa de carvão acima de 400°C, seguida de oxigenação controlada.\",\n  \"timeRequired\": \"20 MINUTOS\",\n  \"successRate\": \"85% (Madeira Seca)\",\n  \"difficulty\": \"Nível 2 (Habilidade Técnica)\",\n  \"outputPerHour\": \"1 Fogo / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Arco e Corda de Fibra Natural (BOW & STRING)\",\n      \"desc\": \"Galho resistente de 60-70 cm (freixo/aveleira) e corda firme de fibra natural de kudzu.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Fuso Rotativo (SPINDLE)\",\n      \"desc\": \"Haste cilíndrica reta de cedro ou salgueiro seco (Ø 20 mm). Topo arredondado, ponta inferior a 45°.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Prancha Base com Entalhe V e Isca (HEARTH & TINDER)\",\n      \"desc\": \"Prancha de 15-20 mm com entalhe em V de 45°, folha coletora de brasa e ninho de fibras secas.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Entalhe em V de 45° e Assentamento do Eixo do Fuso\",\n      \"description\": \"Esculpa um entalhe em V de 45 graus da borda frontal da prancha até o centro exato do soquete do fuso. Posicione uma folha seca abaixo da abertura para acumular o pó de carvão quente.\",\n      \"actionNote\": \"> Regra de Campo: Se o ângulo do entalhe passar de 60°, o calor se dissipa e o pó nunca atingirá o ponto de ignição de 400°C.\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"FOLHA COLETORA [BASE DE BRASA]\",\n        \"ENTALHE EM V 45° (Vértice no Centro)\",\n        \"EIXO FUSO Ø 20mm\",\n        \"ESPESSURA: 15~20mm\",\n        \"PRANCHA BASE (HEARTH BOARD)\",\n        \"VÉRTICE (Alinhado ao Centro do Fuso)\",\n        \"REGRA CRÍTICA DE MONTAGEM:\",\n        \"O vértice em V deve tocar o centro do eixo\",\n        \"ZONA DE ACÚMULO DE PÓ DE CARVÃO (BRASA)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Carga Vertical de 90° e Rotação Recíproca de Curso Total\",\n      \"description\": \"Trave a prancha com o pé esquerdo e aplique 12-15 kg de pressão vertical no bloco de apoio. Movimente o arco horizontalmente usando 100% do comprimento a 300-400 RPM até emitir fumaça branca densa.\",\n      \"actionNote\": \"> Regra de Campo: Não pare na primeira fumaça. Execute mais 10 a 15 cursos em potência máxima para fundir a brasa no entalhe.\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"BLOCO DE APOIO (SOQUETE MANUAL)\",\n        \"F_DOWN: 12~15 kg (Carga Vertical)\",\n        \"ARCO TÁTICO (Galho 65cm)\",\n        \"MOVIMENTO RECÍPROCO DE CURSO TOTAL\",\n        \"ω: 300~400 RPM\",\n        \"PRANCHA BASE\",\n        \"FUMAÇA BRANCA (Emissão Densa)\",\n        \"LIMIAR CRÍTICO:\",\n        \"Temp. Ignição: 400°C+\",\n        \"Pressão: Início 30% → Final 100%\",\n        \"Curso: 100% do Arco\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Transplante da Brasa e Sopro Suave de Ignição (600°C)\",\n      \"description\": \"Aguarde 30 segundos para o pó fumegante coalescer em uma brasa firme (450°C). Transfira para o centro do ninho de isca, eleve a 45° e sopre de forma suave e contínua até romper em chama a 600°C.\",\n      \"actionNote\": \"> Regra de Campo: Segure o ninho a 45° acima da linha dos olhos; a corrente térmica ascendente dobra a oxigenação e afasta a fumaça.\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"NÚCLEO BRASA (450°C)\",\n        \"SOPRO SUAVE E CONTÍNUO (Fluxo Lento)\",\n        \"IGNIÇÃO DE CHAMA (Combustão)\",\n        \"ELEVAÇÃO A 45°\",\n        \"MATRIZ DE TEMPERATURA E IGNIÇÃO\",\n        \"TEMPO (s)\",\n        \"TEMP (°C)\",\n        \"600°C LIMIAR DE CHAMA ABERTA\",\n        \"400°C PONTO DE BRASA ATIVA\",\n        \"30s Coesão e Transplante (0s)\",\n        \"Ignição Chama (15~20s)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Nunca sopre com força sobre a brasa recém-formada\",\n    \"description\": \"Soprar precipitadamente sobre o pó de carvão solto espalhará as partículas incandescentes pelo ar, extinguindo a fonte de calor instantaneamente.\",\n    \"consequence\": \"A falha na obtenção de fogo em ambiente frio acelera a queda da temperatura corporal central, levando à morte por hipotermia em 72 horas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"Ignição por Fricção com Arco e Brasa Concluída\",\n    \"description\": \"Uma brasa incandescente a 400°C gerada na ranhura em V, transferida com sucesso para o ninho de mecha seca e soprada até formar chamas vivas.\"\n  }\n}\n","content/protocols/locales/02-friction-fire.zh-TW.json":"{\n  \"protocolId\": \"PR-02\",\n  \"category\": \"FIRE\",\n  \"title\": \"弓鑽摩擦生火技術 (Bow Drill)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命 (CRITICAL)]\",\n  \"summary\": \"結合乾燥軟木與弓弦往復機械摩擦，產生400°C以上之高溫碳化木屑火種(Ember)，並透過精準供氧引燃明火的核心原始熱源技術。\",\n  \"timeRequired\": \"20分鐘 (20 MINUTES)\",\n  \"successRate\": \"85% (乾燥木材基準)\",\n  \"difficulty\": \"第2級 (進階求生技術)\",\n  \"outputPerHour\": \"1 Fire / 20 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"弓桿與葛藤纖維繩 (BOW & STRING)\",\n      \"desc\": \"長60~70公分具韌性之硬木枝條，搭配強韌天然葛藤纖維繩。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"旋轉鑽軸 (SPINDLE)\",\n      \"desc\": \"直徑20mm之乾燥香杉或柳木直圓棒，頂端鈍角減阻、底端削成45度圓錐。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"V型槽鑽火底板與火絨巢 (HEARTH & TINDER)\",\n      \"desc\": \"厚15~20mm之45度V槽底板、火種收集乾葉，以及鳥巢狀乾燥植物纖維火絨。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"45° V型槽切削與鑽軸中心定位\",\n      \"description\": \"從底板外緣向凹槽中心精準切出45度V型集屑槽，使V槽頂點正好接觸鑽軸中心。底板下方緊貼乾燥寬葉片以完整收集高溫碳化木屑。\",\n      \"actionNote\": \"> 野戰核心：若V型槽角度超過60度，摩擦熱將迅速散失而無法達到400°C燃點，務必維持精準45度楔形開口。\",\n      \"svgFileName\": \"02-step-01.svg\",\n      \"svgLabels\": [\n        \"EMBER CATCHER [火種收集葉片]\",\n        \"45° V型槽 (槽頂點接觸鑽軸中心)\",\n        \"Ø 20mm 鑽軸 (SPINDLE)\",\n        \"板厚: 15~20mm\",\n        \"鑽火底板 (HEARTH BOARD)\",\n        \"V槽頂點 (與凹槽中心點完全重疊)\",\n        \"關鍵設置法則:\",\n        \"V型槽頂點必須精準接觸鑽軸中心\",\n        \"碳化木屑堆積區 (火種凝聚處)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"90度垂直加壓與全行程高速往復拉弓\",\n      \"description\": \"左腳踩穩底板，手塊垂直施加12~15公斤下壓力。保持弓桿水平並使用100%弓長進行全行程推拉(300~400 RPM)，直至噴出濃密白煙。\",\n      \"actionNote\": \"> 野戰核心：冒出白煙時切勿立即停手，必須再全力加速推拉10~15次，使V槽內的碳化木屑完全凝聚成火種。\",\n      \"svgFileName\": \"02-step-02.svg\",\n      \"svgLabels\": [\n        \"頂壓手塊 (BEARING BLOCK)\",\n        \"F_DOWN: 12~15 kg (垂直下壓力)\",\n        \"弓桿 (長65cm 堅韌木枝)\",\n        \"全行程往復拉動 (100%弓長推拉)\",\n        \"ω: 300~400 RPM\",\n        \"HEARTH BOARD\",\n        \"濃密白煙 (炭化達標訊號)\",\n        \"臨界指標:\",\n        \"燃點溫度: 400°C+\",\n        \"加壓比例: 初期30% → 末期100%\",\n        \"行程: 使用100%弓桿全長\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"火種移植火絨巢與45度仰角緩慢吹氣點火\",\n      \"description\": \"靜置30秒讓碳粉凝聚為450°C穩固火種後，小心移入火絨巢中央。以45度仰角托舉火絨，持續吹入均勻低速氣流，使溫度突破600°C引燃明火。\",\n      \"actionNote\": \"> 野戰核心：托舉高度應略高於視線呈45度角，避免濃煙嗆傷眼睛並利用熱對流使供氧效率倍增。\",\n      \"svgFileName\": \"02-step-03.svg\",\n      \"svgLabels\": [\n        \"火種核心 (450°C)\",\n        \"平穩緩慢吹氣 (均勻低速供氧)\",\n        \"火焰爆發點燃 (自燃階段)\",\n        \"45° 仰角托舉\",\n        \"溫度攀升與點火矩陣\",\n        \"時間 (秒)\",\n        \"溫度 (°C)\",\n        \"600°C 明火點燃臨界線\",\n        \"400°C 碳粉悶燒點\",\n        \"凝聚30秒後移植 (0秒)\",\n        \"明火點燃 (15~20秒)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"切勿對尚未凝聚成形的碳粉急促吹氣\",\n    \"description\": \"停止摩擦後若急忙對鬆散的黑色木屑用力吹氣，未結合的微細碳粒會瞬間被吹散，導致核心熱源立即熄滅。\",\n    \"consequence\": \"在寒冷野外環境中生火失敗將加速核心體溫流失，於72小時內引發不可逆之失溫死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr02-outcome.svg\",\n    \"title\": \"弓鑽摩擦生火與火種點燃完成形態\",\n    \"description\": \"火板45度V型槽內藉由摩擦熱生成的400°C黑炭灰餘燼劇烈冒煙，安全轉移至乾燥引火鳥巢並吹拂出明火的實戰生火完成狀態。\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.de.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Laubhütte (Debris Hut) A-Rahmen-Isolationsunterstand\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[GEFAHRENSTUFE: KRITISCH]\",\n  \"summary\": \"Ungeschützte Kälte- und Nässeexposition führt binnen 3 Stunden zu tödlicher Unterkühlung. Durch geometrisches Schichten von trockenem Laub und Totholz entsteht eine stehende Luftschicht (Dead Air Space), die allein durch 80–100W Körperwärme das Überleben sichert.\",\n  \"timeRequired\": \"90–120 MINUTEN\",\n  \"successRate\": \"92.4% (bei ≥60cm Isolationsschicht)\",\n  \"difficulty\": \"Stufe 2 (Schwerer Primitivbau)\",\n  \"outputPerHour\": \"1 Unterstand (≥1.5m³ Isolationsvolumen)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Firstbalken (Ridge Pole)\",\n      \"desc\": \"1 gerader, trockener Hartholzstamm (Länge 3.0–3.5m, Ø 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y-Stützgabeln & Rippenäste (Rib Sticks)\",\n      \"desc\": \"2 Y-Stützen (1.5m, Ø 5–8cm) sowie 40–50 Seitenäste (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Trockenes Laub & Waldstreu (Dry Debris)\",\n      \"desc\": \"2–3m³ knochentrockenes Laub, Kiefernnadeln, trockenes Gras und Rinde\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"A-Rahmen-Stütze errichten & Firstbalken verankern\",\n      \"description\": \"Verschränken Sie zwei Y-Gabelhölzer an der Spitze (oder binden Sie diese mit Ranken) und legen Sie den Firstbalken in 0.8–1.0m Höhe auf. Verankern Sie das hintere Ende direkt auf der Windseite im Boden. Der Innenraum darf nur so breit sein, dass Sie knapp hineinkriechen können.\",\n      \"actionNote\": \"> FELDREGEL: Zu großes Innenvolumen verhindert die Erwärmung durch Körperwärme. Striktes Sargmaß einhalten: maximal eine Faustbreit (≤10cm) Abstand.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INNENVOLUMEN]:\",\n        \"Striktes Sargmaß: max. +10cm (1 Faust) Körperabstand\",\n        \"WINDWARD (Windseitiger Anker)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Firstbalken)\",\n        \"Y-BIPOD & VINE LASHING (Y-Stützverbindung)\",\n        \"COFFIN CLEARANCE: +10cm (Max. 1 Faust Spielraum)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rippengitter anlegen & Boden-Isoliermatratze verdichten\",\n      \"description\": \"Lehnen Sie Rippenäste im 45°–60°-Winkel dicht an beide Seiten des Firstbalkens. Schichten Sie sofort mindestens 40cm trockenes Laub auf den Boden, sodass auch unter Körpergewicht 15–20cm Isolierstärke verbleiben.\",\n      \"actionNote\": \"> PHYSIK-PRINZIP: Kalter Boden leitet Wärme dutzendfach schneller ab als Luft. Ohne 15–20cm Bodenisolierung droht rascher Kälteschock.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [BODENISOLIERUNG]:\",\n        \"Bodenkälte blockieren: ≥15~20cm komprimierte Matte\",\n        \"RIDGEPOLE SPINE (Firstbalken-Schnitt)\",\n        \"RIB LATTICE: 45°~60° (Rippengitter)\",\n        \"MATTRESS: 40cm → 20cm (Laubmatratze)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"60–90cm Außenisolierung & Sturmsicherung\",\n      \"description\": \"Decken Sie das Gitter mit Reisig ab und schichten Sie trockenes Laub von unten nach oben 60–90cm (Armlänge) dick auf. Beschweren Sie die Hülle mit schweren Totholzästen gegen Wind und verschließen Sie den Eingang mit einem Laubpfropfen.\",\n      \"actionNote\": \"> WARNUNG: Nasses Laub isoliert nicht und entzieht Wärme durch Verdunstung. Steile Außenneigung zur Regenabweisung beibehalten.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WANDAUFBAU]:\",\n        \"60~90cm trockene Laubschicht + Eingangspfropfen\",\n        \"DEBRIS WALL: 60~90cm (Laubdämmung)\",\n        \"DEADWOOD ARMOR (Windschutz-Äste)\",\n        \"WATER SHEDDING SLOPE (Regenablauf)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermokammer)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Zu großer Innenraum & feuchtes Laub\",\n    \"description\": \"Ein hoher Innenraum zum Sitzen kann durch 80–100W menschliche Stoffwechselwärme nicht erwärmt werden. Feuchtes Laub verwandelt den Unterstand zudem in eine tödliche Kühlkammer.\",\n    \"consequence\": \"Folge: Wärmeverlust durch Leitung und Konvektion senkt die Kerntemperatur im Schlaf unter 30°C – Tod durch Unterkühlung.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Vollendete A-Rahmen Laub-Notunterkunft (Debris Hut)\",\n    \"description\": \"Ein massiver 2,5m Dachfirst und ein 45°-Rippenrahmen, umhüllt von einer 1 Meter dicken Schicht aus trockenem Laub, die Körperwärme ohne Feuer speichert.\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.en.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Debris Hut A-Frame Thermal Shelter Construction\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[THREAT LEVEL: CRITICAL]\",\n  \"summary\": \"Direct exposure to freezing wind and rain causes fatal hypothermia within 3 hours. By geometrically layering dry forest litter and deadwood to trap Dead Air Space, you build a zero-fire survival shelter that maintains core body temperature purely through human metabolic radiant heat (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTES\",\n  \"successRate\": \"92.4% (with ≥60cm insulation depth)\",\n  \"difficulty\": \"Tier 2 (Heavy Primitive Construction)\",\n  \"outputPerHour\": \"1 Shelter (≥1.5m³ insulated volume)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Ridge Pole (Primary Spine)\",\n      \"desc\": \"1 straight, solid dry hardwood log (length 3.0–3.5m, diameter 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y-Frame Bipod & Rib Sticks\",\n      \"desc\": \"2 Y-forked support poles (length 1.5m, Ø 5–8cm) and 40–50 rib branches (length 1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Dry Forest Debris (Thermal Mass)\",\n      \"desc\": \"2–3m³ of bone-dry leaves, pine needles, dry ferns, and shredded bark\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erect A-Frame Bipod & Anchor Ridgepole\",\n      \"description\": \"Interlock two Y-forked support sticks at the apex (or lash with wild vine) to form a sturdy bipod, then seat one end of the ridgepole into the fork at 0.8–1.0m height. Anchor the tail end directly into the ground facing into the wind (windward). Size the interior strictly so your body barely crawls inside.\",\n      \"actionNote\": \"> FIELD RULE: Excess interior volume prevents metabolic heat from warming the air pocket, resulting in death by hypothermia. Enforce strict coffin clearance—leave only one fist (≤10cm) around your shoulders.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [INTERIOR SPEC]:\",\n        \"Strict Coffin Spec: max +10cm (1 fist) body clearance\",\n        \"WINDWARD (Ground Anchor)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Hardwood Spine)\",\n        \"Y-BIPOD & VINE LASHING (Apex Joint)\",\n        \"COFFIN CLEARANCE: +10cm (1 Fist Max Gap)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Lay Rib Lattice & Pack High-Density Floor Mattress\",\n      \"description\": \"Lean rib sticks tightly along both sides of the ridgepole at a 45°–60° angle to form a dense lattice wall that prevents debris from falling through. Immediately pack at least 40cm of bone-dry leaves onto the floor so that even under full body weight it remains 15–20cm thick.\",\n      \"actionNote\": \"> PHYSICS PRINCIPLE: Cold ground conducts heat away dozens of times faster than still air. Without a compressed 15–20cm floor mattress, conductive heat loss triggers hypothermia shock rapidly.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [FLOOR INSULATION]:\",\n        \"Block ground conduction: keep ≥15~20cm compressed bed\",\n        \"RIDGEPOLE SPINE (Cross-Section)\",\n        \"RIB LATTICE: 45°~60° (Branch Grid)\",\n        \"MATTRESS: 40cm → 20cm (Leaf Bed)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Shingle 60–90cm Outer Debris & Armor Against Wind\",\n      \"description\": \"Cover the rib lattice with fine brush, then pile dry leaves from bottom to top like roof shingles to a thickness of 60–90cm (full arm's length). Lay heavy dead branches over the entire mound to prevent wind stripping, and seal the entrance tightly with a dense leaf plug.\",\n      \"actionNote\": \"> CAUTION: Wet debris has zero insulation value and steals body heat via evaporative cooling. Maintain a steep outer slope to shed rain while keeping the inner core bone-dry.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [WALL SPEC]:\",\n        \"60~90cm dry leaf mound + full entrance plug seal\",\n        \"DEBRIS WALL: 60~90cm (Dry Leaves)\",\n        \"DEADWOOD ARMOR (Wind-Weight Branches)\",\n        \"WATER SHEDDING SLOPE (Rain Drain)\",\n        \"DEAD AIR CORE & PLUG SEAL (Thermal Chamber)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Error: Building an Oversized Cabin & Mixing Wet Debris\",\n    \"description\": \"Raising the ceiling for sitting comfort creates a large air pocket that human basal metabolism (80–100W) cannot heat. Furthermore, packing damp leaves into the floor or walls turns the shelter into a conductive evaporative cooler.\",\n    \"consequence\": \"Consequence: Combined conductive and convective heat loss drops core body temperature below 30°C during sleep, causing fatal hypothermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Completed A-Frame Debris Hut Thermal Shelter\",\n    \"description\": \"A 2.5m heavy ridgepole and 45° rib frame blanketed by 1 meter of compressed dry leaves and thatch branches, trapping body heat down to sub-zero temperatures without fire.\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.es.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Construcción de Refugio Térmico A-Frame (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NIVEL DE AMENAZA: CRÍTICO]\",\n  \"summary\": \"La exposición al frío y la lluvia causa hipotermia mortal en 3 horas. Al apilar hojarasca seca y madera muerta para atrapar aire estancado (Dead Air Space), se construye un refugio sin fuego que conserva el calor metabólico humano (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92.4% (con ≥60cm de aislamiento)\",\n  \"difficulty\": \"Nivel 2 (Construcción Primitiva Intensiva)\",\n  \"outputPerHour\": \"1 Refugio (volumen aislado ≥1.5m³)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga Cumbrera (Ridge Pole)\",\n      \"desc\": \"1 tronco recto y seco de madera dura (longitud 3.0–3.5m, diámetro 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Soportes en Y y Costillas (Rib Sticks)\",\n      \"desc\": \"2 horquillas en Y (1.5m, Ø 5–8cm) y 40–50 ramas laterales (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Hojarasca Seca Aislante (Dry Debris)\",\n      \"desc\": \"2–3m³ de hojas secas, agujas de pino, helechos secos y corteza suelta\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erigir Bípode en A y Anclar Viga Cumbrera\",\n      \"description\": \"Entrelace dos horquillas en Y en la cúspide (o átelas con lianas) y apoye un extremo de la viga cumbrera a 0.8–1.0m de altura. Ancle el extremo opuesto en el suelo hacia el viento (barlovento). El interior debe ser tan estrecho que apenas permita entrar arrastrándose.\",\n      \"actionNote\": \"> REGLA DE CAMPO: Un volumen excesivo impide calentar el aire con calor corporal. Mantenga espacio de ataúd: solo un puño (≤10cm) alrededor del cuerpo.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUMEN INTERIOR]:\",\n        \"Espacio tipo ataúd: máx. +10cm (1 puño) de holgura\",\n        \"WINDWARD (Anclaje Barlovento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Cumbrera)\",\n        \"Y-BIPOD & VINE LASHING (Unión en Y)\",\n        \"COFFIN CLEARANCE: +10cm (Holgura 1 Puño)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Colocar Costillas y Colchón Térmico de Suelo\",\n      \"description\": \"Apoye ramas laterales a 45°–60° a ambos lados de la viga para formar una rejilla cerrada. Cubra inmediatamente el suelo con al menos 40cm de hojas secas para que, al comprimirse con el peso corporal, conserve 15–20cm de espesor aislante.\",\n      \"actionNote\": \"> PRINCIPIO FÍSICO: La conducción térmica del suelo frío es decenas de veces mayor que la del aire. Sin aislamiento basal, el suelo drena todo el calor corporal.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [AISLAMIENTO BASAL]:\",\n        \"Bloquear conducción: mantener ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Sección Cumbrera)\",\n        \"RIB LATTICE: 45°~60° (Costillas)\",\n        \"MATTRESS: 40cm → 20cm (Cama de Hojas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Apilar 60–90cm de Hojarasca y Blindaje Cortavientos\",\n      \"description\": \"Cubra la rejilla con ramitas finas y apile hojas secas desde abajo hacia arriba hasta alcanzar 60–90cm de grosor. Coloque ramas pesadas encima para evitar que el viento vuele el aislamiento y selle la entrada con un tapón denso de hojas.\",\n      \"actionNote\": \"> PRECAUCIÓN: La hojarasca húmeda no aísla y roba calor por evaporación. Mantenga una pendiente pronunciada para evacuar la lluvia.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [ESPEC. DE MURO]:\",\n        \"Muro de hojas de 60~90cm + tapón de entrada sellado\",\n        \"DEBRIS WALL: 60~90cm (Capa Aislante)\",\n        \"DEADWOOD ARMOR (Ramas de Peso)\",\n        \"WATER SHEDDING SLOPE (Drenaje)\",\n        \"DEAD AIR CORE & PLUG SEAL (Cámara Sellada)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Mortal: Construir un Interior Amplio y Usar Hojas Húmedas\",\n    \"description\": \"Hacer el techo alto para sentarse crea una bolsa de aire demasiado grande para los 80–100W del metabolismo humano. Además, mezclar hojas húmedas convierte el refugio en una cámara frigorífica.\",\n    \"consequence\": \"Consecuencia: La pérdida térmica por conducción y convección reduce la temperatura central bajo 30°C durante el sueño, causando muerte por hipotermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Refugio Térmico Debris Hut en Marco A Completado\",\n    \"description\": \"Una viga maestra de 2.5 m y costillas a 45° cubiertas por 1 metro de hojas secas compactadas y ramas, conservando el calor corporal bajo cero sin fuego.\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.ja.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"デブリハット(Debris Hut) Aフレーム断熱シェルター構築法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[危険度: 致命的(CRITICAL)]\",\n  \"summary\": \"極寒の風雨に晒されると3時間以内に致命的な低体温症に陥る。乾燥した落ち葉と枯れ木を幾何学的に積層して静止空気層(Dead Air Space)を形成し、火気なしで人体の代謝放射熱(80〜100W)のみで内部温度を生存圏に保つ原始シェルターを構築する。\",\n  \"timeRequired\": \"90〜120分 (90-120 MINUTES)\",\n  \"successRate\": \"92.4% (断熱厚60cm以上確保時)\",\n  \"difficulty\": \"等級2 (高強度原始築造技術)\",\n  \"outputPerHour\": \"1棟完成 (有効断熱容積1.5㎥以上)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"棟木・リッジポール(Ridge Pole)\",\n      \"desc\": \"長さ3.0〜3.5m、直径10〜15cmの曲がりのない堅고な乾燥広葉樹丸太 1本\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y字支柱および肋木枝(A-Frame & Rib Sticks)\",\n      \"desc\": \"長さ1.5m・直径5〜8cmのY字支柱2本、および長さ1.0〜1.5mの肋木用枝40〜50本\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"乾燥断熱デブリ(Dry Debris)\",\n      \"desc\": \"水分を含まない乾燥落葉、松葉、枯れ草、樹皮屑など大量(最低2〜3立方メートル)\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Aフレーム支柱の架設と棟木の固定\",\n      \"description\": \"2本のY字支柱を上端で噛み合わせるか蔓で結束して三角支柱を立て、棟木の一端を交差部に乗せる(高さ0.8〜1.0m)。反対側の端は風上側の地面に密着させる。内部空間は身体が辛うじて潜り込める狭さに制限する。\",\n      \"actionNote\": \"> 野戦鉄則: 内部容積が広すぎると体温で空気を温められず凍死する。棺(Coffin)のように身体周囲に拳1個分(10cm)の隙間だけを残せ。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [内部容積規格]:\",\n        \"棺(Coffin)規格厳守: 身体周囲に拳1個(10cm)の余裕のみ\",\n        \"WINDWARD (風上側地面密着)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主棟木)\",\n        \"Y-BIPOD & VINE LASHING (Y字支柱結束)\",\n        \"COFFIN CLEARANCE: +10cm (拳1個分の隙間制限)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"肋木フレーム配置と高密度断熱マットレス敷設\",\n      \"description\": \"棟木の両側に肋木枝を45〜60度の角度で密に立てかけ、落ち葉が内部に崩れ落ちない格子壁を作る。直ちに床面へ乾いた落ち葉を40cm以上敷き詰め、体重で圧縮されても15〜20cm以上の断熱厚を維持させる。\",\n      \"actionNote\": \"> 科学的原理: 土壌の熱伝導率は静止空気の数十倍に達する。床断熱がなければ全لا体温が地面へ奪われ短時間で低体温ショックに陥る。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [床断熱原則]:\",\n        \"地面熱伝導遮断: 圧縮後も最低15~20cm厚を維持\",\n        \"RIDGEPOLE SPINE (中心棟木断面)\",\n        \"RIB LATTICE: 45°~60° (肋木格子壁)\",\n        \"MATTRESS: 40cm → 20cm (落葉寝床)\",\n        \"GROUND COLD CONDUCTION BLOCKED (地面冷気遮断)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"外壁断熱材60〜90cm積層と防風被覆\",\n      \"description\": \"骨格の上に小枝を薄く被せた後、乾いた落ち葉を下から上へ鱗状に60〜90cm(腕全体の長さ)の厚さで積み上げる。強風で飛ばないよう重い枯れ枝を外壁全体に被せて荷重をかけ、入口は落ち葉の栓で完全密閉する。\",\n      \"actionNote\": \"> 注意: 濡れた落ち葉は断熱効果がなく気化熱で体温を奪う。外壁の傾斜で雨水を流し、内部は完全な乾燥状態を保て。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [断熱積層規格]:\",\n        \"外壁60~90cm乾燥落葉積層 + 入口プラグ完全密閉\",\n        \"DEBRIS WALL: 60~90cm (落葉断熱層)\",\n        \"DEADWOOD ARMOR (防風荷重枝)\",\n        \"WATER SHEDDING SLOPE (排水傾斜)\",\n        \"DEAD AIR CORE & PLUG SEAL (静止空気層・入口栓)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的誤認: 快適性のための大型空間確保および湿った落ち葉の使用\",\n    \"description\": \"座って休めるように天井を高くすると、人間の基礎代謝(約80〜100W)では内部空気を温めきれず体温が急速に奪われる。また湿った落ち葉を混ぜると高い熱容量と気化熱により氷の洞窟のような冷却装置へと変質する。\",\n    \"consequence\": \"誤判断時の結末: 睡眠中の伝導・対流複合熱損失により深部体温が30°C以下に急降下し、致命的な低体温症(Hypothermia)で死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Aフレーム・デブリハット（落ち葉断熱シェルター）完成外観\",\n    \"description\": \"太さ2.5mの主棟木と45度の肋骨枝フレームの上に、厚さ1メートルの乾燥落ち葉層を圧縮積層し、強風と風雨を遮断する無暖房体温保持シェルターの完成外観です。\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.pt.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Construção de Abrigo Térmico A-Frame (Debris Hut)\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[NÍVEL DE AMEAÇA: CRÍTICO]\",\n  \"summary\": \"A exposição ao frio e à chuva causa hipotermia fatal em até 3 horas. Ao empilhar folhagem seca e galhos mortos para criar uma camada de ar estagnado (Dead Air Space), constrói-se um abrigo sem fogo que preserva o calor metabólico humano (80–100W).\",\n  \"timeRequired\": \"90–120 MINUTOS\",\n  \"successRate\": \"92.4% (com ≥60cm de isolamento)\",\n  \"difficulty\": \"Nível 2 (Construção Primitiva Pesada)\",\n  \"outputPerHour\": \"1 Abrigo (volume isolado ≥1.5m³)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Viga Mestra (Ridge Pole)\",\n      \"desc\": \"1 tronco reto e seco de madeira dura (comprimento 3.0–3.5m, Ø 10–15cm)\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Forquilhas em Y e Costelas (Rib Sticks)\",\n      \"desc\": \"2 apoios em Y (1.5m, Ø 5–8cm) e 40–50 galhos laterais (1.0–1.5m)\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Folhagem Seca Isolante (Dry Debris)\",\n      \"desc\": \"2–3m³ de folhas secas, agulhas de pinheiro, capim seco e cascas\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Erguer Bipé em A e Ancorar Viga Mestra\",\n      \"description\": \"Encaixe duas forquilhas em Y no topo (ou amarre com cipó) e apoie uma ponta da viga mestra a 0.8–1.0m de altura. Fixe a outra extremidade no solo contra o vento (barlavento). O espaço interno deve permitir apenas entrar rastejando.\",\n      \"actionNote\": \"> REGRA DE CAMPO: Volume interno excessivo impede o aquecimento pelo corpo. Mantenha padrão caixão: apenas um punho (≤10cm) de folga.\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [VOLUME INTERNO]:\",\n        \"Padrão caixão: máx. +10cm (1 punho) de folga corporal\",\n        \"WINDWARD (Fixação Barlavento)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (Viga Mestra)\",\n        \"Y-BIPOD & VINE LASHING (Amarração em Y)\",\n        \"COFFIN CLEARANCE: +10cm (Folga Máx. 1 Punho)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Posicionar Costelas e Colchão Isolante de Piso\",\n      \"description\": \"Apoie galhos laterais a 45°–60° em ambos os lados da viga formando uma grade densa. Forre imediatamente o chão com pelo menos 40cm de folhas secas para manter 15–20cm de espessura mesmo comprimido pelo peso do corpo.\",\n      \"actionNote\": \"> PRINCÍPIO FÍSICO: A condução térmica do solo frio é dezenas de vezes maior que a do ar. Sem colchão isolante, o solo drena todo o calor vital.\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [ISOLAMENTO DO PISO]:\",\n        \"Bloquear condução do solo: manter ≥15~20cm comprimido\",\n        \"RIDGEPOLE SPINE (Seção da Viga)\",\n        \"RIB LATTICE: 45°~60° (Grade de Galhos)\",\n        \"MATTRESS: 40cm → 20cm (Colchão de Folhas)\",\n        \"GROUND COLD CONDUCTION BLOCKED\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Empilhar 60–90cm de Folhagem e Blindagem Contra Vento\",\n      \"description\": \"Cubra a grade com gravetos finos e acumule folhas secas de baixo para cima até 60–90cm de espessura. Coloque galhos pesados por fora para conter rajadas de vento e feche a entrada com um tampão denso de folhas.\",\n      \"actionNote\": \"> ATENÇÃO: Folhagem úmida não isola e rouba calor por evaporação. Mantenha inclinação externa para escoar a chuva.\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [PAREDE TÉRMICA]:\",\n        \"60~90cm de folhas secas + tampão de entrada vedado\",\n        \"DEBRIS WALL: 60~90cm (Camada Isolante)\",\n        \"DEADWOOD ARMOR (Galhos de Contrapeso)\",\n        \"WATER SHEDDING SLOPE (Escoamento)\",\n        \"DEAD AIR CORE & PLUG SEAL (Câmara Vedada)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Construir Espaço Amplo e Usar Folhas Úmidas\",\n    \"description\": \"Elevar o teto para sentar cria um bolsão de ar que o metabolismo humano (80–100W) não consegue aquecer. Além disso, folhas úmidas transformam o abrigo em uma câmara de resfriamento.\",\n    \"consequence\": \"Consequência: Perda térmica por condução e convecção reduz a temperatura central abaixo de 30°C durante o sono, causando morte por hipotermia.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"Abrigo Térmico Debris Hut em Estrutura A Concluído\",\n    \"description\": \"Uma viga mestra de 2,5m e costelas a 45° cobertas por 1 metro de folhas secas compactadas e galhos, retendo o calor corporal abaixo de zero sem fogo.\"\n  }\n}\n","content/protocols/locales/03-프로토콜-03-데브리-헛-debris-hut-a프레임-단열-은신처-구축법.zh-TW.json":"{\n  \"protocolId\": \"PR-03\",\n  \"category\": \"SHELTER\",\n  \"title\": \"落葉屋（Debris Hut）A字型斷熱避難所構築法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[威脅等級：致命(CRITICAL)]\",\n  \"summary\": \"在嚴寒風雨中暴露於野外會在3小時內導致致命失溫。透過幾何堆疊乾燥落葉與枯木形成靜止空氣層（Dead Air Space），無需火源即可僅憑人體代謝輻射熱（80～100W）維持核心體溫。\",\n  \"timeRequired\": \"90～120分鐘 (90-120 MINUTES)\",\n  \"successRate\": \"92.4% (確保60cm以上斷熱厚度時)\",\n  \"difficulty\": \"2級 (高強度原始構築技術)\",\n  \"outputPerHour\": \"完成1棟 (有效斷熱體積1.5㎥以上)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"主脊柱木 (Ridge Pole)\",\n      \"desc\": \"長3.0～3.5m、直徑10～15cm且筆直堅固的乾燥硬木原木1根\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Y型支撐木與肋骨枝條 (A-Frame & Rib Sticks)\",\n      \"desc\": \"長1.5m、直徑5～8cm的Y型支撐木2根，以及長1.0～1.5m的肋骨樹枝40～50根\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"乾燥斷熱殘骸 (Dry Debris)\",\n      \"desc\": \"含水量極低的乾落葉、松針、乾草與碎樹皮等大量材料（至少2～3立方公尺）\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"架設A字型主腳與錨定主脊柱木\",\n      \"description\": \"將兩根Y型支撐木在頂端交錯咬合或以藤蔓綁紮成三角支架，將主脊柱木一端架於交點（高約0.8～1.0m），另一端緊貼迎風面地面。內部空間必須嚴格限制在僅容身體爬入的窄度。\",\n      \"actionNote\": \"> 野戰鐵則：內部體積過大將無法以體溫加熱空氣而凍死。務必遵守棺木規格：身體周圍僅留一個拳頭（≤10cm）的空隙。\",\n      \"svgFileName\": \"pr03-step-01.svg\",\n      \"svgLabels\": [\n        \"CRITICAL VOLUME RULE [內部體積規格]:\",\n        \"嚴守棺木規格：身體周圍僅留1個拳頭(10cm)裕度\",\n        \"WINDWARD (迎風面地面錨定)\",\n        \"MAIN RIDGEPOLE: 3.0~3.5m (主脊柱木)\",\n        \"Y-BIPOD & VINE LASHING (Y型支撐綁紮)\",\n        \"COFFIN CLEARANCE: +10cm (僅限1拳間隙)\",\n        \"HEIGHT: 0.8~1.0m\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"排列肋骨格柵與鋪設高密度地面斷熱床墊\",\n      \"description\": \"在主脊柱木兩側以45～60度角緊密斜靠肋骨樹枝，形成防止落葉坍塌的格柵牆。完成骨架後立即在地面鋪設至少40cm厚的乾落葉，確保躺下受壓後仍維持15～20cm以上的斷熱厚度。\",\n      \"actionNote\": \"> 科學原理：冰冷土壤的熱傳導率是靜止空氣的數十倍。若無地面斷熱層，體熱將迅速被大地吸乾並引發失溫休克。\",\n      \"svgFileName\": \"pr03-step-02.svg\",\n      \"svgLabels\": [\n        \"THERMAL CONDUCTION SHIELD [地面斷熱原則]:\",\n        \"阻斷地面熱傳導：受壓後仍需維持15~20cm厚度\",\n        \"RIDGEPOLE SPINE (主脊柱木斷面)\",\n        \"RIB LATTICE: 45°~60° (肋骨格柵牆)\",\n        \"MATTRESS: 40cm → 20cm (落葉床墊)\",\n        \"GROUND COLD CONDUCTION BLOCKED (阻絕地面寒氣)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"堆疊60～90cm外部斷熱層與防風壓重披覆\",\n      \"description\": \"在骨架外覆蓋細枝後，由下往上如魚鱗般堆疊60～90cm（整條手臂長度）厚的乾落葉。最後在外牆覆蓋沉重枯枝防止強風吹散落葉，並以高密度落葉塞封死入口。\",\n      \"actionNote\": \"> 注意：潮濕落葉毫無斷熱效果且會透過蒸發奪走體溫。外牆必須維持陡峭斜度以排出雨水，確保內部乾燥。\",\n      \"svgFileName\": \"pr03-step-03.svg\",\n      \"svgLabels\": [\n        \"INSULATION & SEALING [斷熱堆疊規格]:\",\n        \"外牆60~90cm乾落葉堆疊 + 入口落葉塞完全密封\",\n        \"DEBRIS WALL: 60~90cm (落葉斷熱層)\",\n        \"DEADWOOD ARMOR (防風壓重外枝)\",\n        \"WATER SHEDDING SLOPE (排水斜面)\",\n        \"DEAD AIR CORE & PLUG SEAL (靜止空氣層與入口塞)\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命誤判：為求舒適擴大內部空間與混用潮濕落葉\",\n    \"description\": \"為了能坐起而加高天花板會使內部空氣袋過大，人體基礎代謝（80～100W）無法將其加熱。此外，若混入潮濕落葉，水分的高熱容與蒸發熱將使避難所變成冰窖。\",\n    \"consequence\": \"誤判後果：睡眠中因傳導與對流複合熱損失，核心體溫驟降至30°C以下，導致致命失溫死亡。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr03-outcome.svg\",\n    \"title\": \"A字型落葉斷熱避難所（Debris Hut）完成外觀\",\n    \"description\": \"2.5米粗壯脊木與45度肋骨支架上覆蓋1米厚的緊實乾落葉層與防風枝條格子網，形成無暖氣下鎖住體溫的野外避難所完成外觀。\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.de.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Steinaxt aus Flusssteinen und Ranken bauen\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[WICHTIGKEIT: KERNWERKZEUG]\",\n  \"summary\": \"Mit bloßen Händen lassen sich keine dicken Äste für Unterschlupf oder Feuerholz fällen. So schlagen Sie zwei harte Flusssteine im 45-Grad-Winkel gegeneinander, um eine scharfe Steinklinge abzuspalten, und befestigen sie mit Kiefernharz und nasser Rankenrinde fest an einem Holzstiel.\",\n  \"timeRequired\": \"60 Min.\",\n  \"successRate\": \"90% (bei 45°-Schlag auf die Kante)\",\n  \"difficulty\": \"Mittel (Anfängerfreundlich)\",\n  \"outputPerHour\": \"1 fertige Steinaxt\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 harter Flussstein & 1 runder Schlagstein\",\n      \"desc\": \"Ein dichter Flussstein (etwa zwei Fäuste groß), der mit glasartigen, scharfen Kanten bricht, sowie ein schwerer runder Stein zum Zuschlagen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Unterarmlanger Stiel aus Hartholz (Eiche oder Esche)\",\n      \"desc\": \"Ein zäher, frischer Ast (40–50cm lang, 3,5–4cm dick), der harte Schläge aushält, ohne zu brechen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"In Wasser eingeweichte Ranken-Innenrinde & Kiefernharz\",\n      \"desc\": \"Mindestens 3 Meter nasse Innenrinde von Ranken (zieht sich beim Trocknen stark zusammen) und eine Handvoll festes Kiefernharz.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Steine im 45-Grad-Winkel schlagen, um eine scharfe Klinge abzuspalten\",\n      \"description\": \"Legen Sie den großen Flussstein fest auf den Boden und schlagen Sie mit dem runden Schlagstein schräg im 45-Grad-Winkel kräftig auf seine Außenkante. Ein senkrechter Schlag in die Mitte zertrümmert nur den Stein, aber ein 45-Grad-Schlag auf die Kante löst mit einem Schlag eine handtellergroße, rasiermesserscharfe Steinklinge.\",\n      \"actionNote\": \"> Tipp: Schlagen Sie nicht flach in die Mitte. Zielen Sie 1–2cm innerhalb der Außenkante und schlagen Sie einmal kräftig zu.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Runder Schlagstein\",\n        \"2. Kante mit 45° treffen\",\n        \"Scharfe Klinge (1-2cm)\",\n        \"4. Abgespaltene Axtklinge\",\n        \"3. Unterer Flussstein (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Holzstiel oben spalten, Klinge einsetzen und mit Harz füllen\",\n      \"description\": \"Spalten Sie das obere Ende des Holzstiels mit einem scharfen Stein 5–7cm tief senkrecht ein. Binden Sie direkt unter dem Spalt zuerst eine Schnur fest herum, damit das Holz nicht weiter reißt, und klemmen Sie das dicke hintere Ende der Steinklinge tief hinein. Schmelzen Sie Kiefernharz über dem Feuer, mischen Sie feines Holzkohlepulver darunter und füllen Sie alle Lücken.\",\n      \"actionNote\": \"> Prinzip: Reines Harz wird nach dem Abkühlen spröde wie Glas. Mit einem Drittel Holzkohlepulver gemischt wird es zu einem schlagfesten Naturkleber.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Klinge von oben einsetzen\",\n        \"Scharfe Schneide\",\n        \"2. Holzspalt (5-7cm)\",\n        \"3. Harz + Holzkohlepulver\",\n        \"4. Unten abbinden gegen Risse\",\n        \"Stieldicke: 3,5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Mit nasser Rankenrinde X-förmig umwickeln und im Schatten trocknen\",\n      \"description\": \"Wickeln Sie die eingeweichte, biegsame Ranken-Innenrinde mehr als 10-mal straff über Kreuz (X-Form) um Steinklinge und Holzstiel. Umwickeln Sie danach den unteren Hals quer, verknoten Sie das Ende und lassen Sie die Axt im Schatten trocknen. Beim Trocknen schrumpft die nasse Ranke um fast 30% und klemmt den Stein fest wie Stahldraht.\",\n      \"actionNote\": \"> Achtung: Prüfen Sie nach dem Trocknen mit der Hand, ob die Klinge absolut wackelfrei sitzt. Nicht direkt am Feuer trocknen, sonst verbrennen die Fasern.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Nasse Ranke X-Wicklung\",\n        \"2. Freie Schneidkante\",\n        \"3. Untere Querwicklung\",\n        \"4. Schrumpft 30% beim Trocknen\",\n        \"Fertig: Feste einteilige Steinaxt\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Häufiger Fehler: Flach in die Steinmitte schlagen oder trockene Ranken nutzen\",\n    \"description\": \"Wer im 90-Grad-Winkel flach auf die Steinmitte schlägt, erhält keine scharfe Klinge, sondern zertrümmert den Stein zu nutzlosem Kies. Wer trockene, spröde Ranken oder raue Außenrinde verwendet, riskiert, dass die Bindung beim ersten Schlag reißt und die schwere Steinklinge ins Gesicht fliegt.\",\n    \"consequence\": \"Ergebnis: Immer die Kante im 45-Grad-Winkel schlagen und eingeweichte Innenrinde im Schatten trocknen lassen.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Vollendete primitive Steinaxt mit Ast- und Harzbindung\",\n    \"description\": \"Eine beidseitig geschlagene Feuersteinklinge, tief im gespaltenen Eichenstiel verankert, mit X-Kreuz-Lianenbindung verschnürt und mit Kiefernharz versiegelt.\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.en.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Make a Stone Axe with River Stones and Vines\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[PRIORITY: CORE TOOL]\",\n  \"summary\": \"You cannot chop thick branches for shelter posts or firewood with your bare hands. Here is how to strike two hard river stones together at a 45-degree angle to split off a sharp stone blade, then lock it into a split wooden handle using pine resin and wet vine bark.\",\n  \"timeRequired\": \"60 mins\",\n  \"successRate\": \"90% (when striking the edge at 45°)\",\n  \"difficulty\": \"Medium (Beginner friendly)\",\n  \"outputPerHour\": \"1 Stone Axe Completed\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Hard River Stone & 1 Round Hammerstone\",\n      \"desc\": \"One dense river stone (about the size of two fists) that breaks with sharp glass-like edges, plus one heavy round stone to hold and strike with.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Forearm-Length Hard Wooden Handle (Oak or Ash)\",\n      \"desc\": \"One tough green branch (40–50cm long, 3.5–4cm thick) that absorbs heavy impact without snapping.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Water-Soaked Vine Inner Bark & Pine Resin\",\n      \"desc\": \"At least 3 meters of wet inner vine bark (which shrinks and tightens as it dries) and a handful of hardened pine sap from tree bark.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Strike Stones Together at 45 Degrees to Split Off a Sharp Blade\",\n      \"description\": \"Brace the large river stone firmly on the ground, then strike its outer edge at a 45-degree angle using your round hammerstone. Hitting flat in the middle only crushes the rock, but striking the edge at 45 degrees cleanly splits off a palm-sized stone flake with a razor-sharp cutting edge.\",\n      \"actionNote\": \"> Key Tip: Do not hit the flat center of the stone. Aim 1–2cm inside the outer rim and strike firmly in one clean motion to split off a long, sharp blade.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Round Hammerstone\",\n        \"2. Strike Edge at 45°\",\n        \"Sharp Blade (1-2cm)\",\n        \"4. Split Stone Axe Blade\",\n        \"3. Base River Stone (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Split the Top of the Wooden Handle, Wedge the Blade, and Fill with Resin\",\n      \"description\": \"Use a sharp stone flake to split the top of your wooden handle 5–7cm down the center. Tie a cord tightly right below the split first so the wood does not crack any further down, then push the thick back end of the stone blade deep into the slot. Melt pine resin over a fire, mix in fine charcoal powder, and pack it into every gap.\",\n      \"actionNote\": \"> How It Works: Pure pine resin cools brittle like glass and cracks on impact. Mixing in about one-third crushed charcoal powder turns it into a tough, shock-absorbing natural glue.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Push Blade Down In\",\n        \"Sharp Cutting Edge\",\n        \"2. Split Wood Slot (5-7cm)\",\n        \"3. Melted Resin + Charcoal\",\n        \"4. Tie Below Split First\",\n        \"Handle Width: 3.5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Wrap Tightly in an X-Pattern with Wet Vine Bark and Dry in the Shade\",\n      \"description\": \"Take water-soaked, flexible inner vine bark and wrap it tightly in a diagonal X-pattern across both the stone blade and the wooden handle for more than 10 full turns. Wrap horizontally around the lower neck, tie off the knot, and let it dry in the shade. Wet vine bark shrinks by nearly 30% as it dries, clamping the stone blade like steel wire.\",\n      \"actionNote\": \"> Watch Out: Once dry, shake the stone head hard by hand—there must be zero wobble before swinging. Never dry it right next to flames or the vine fibers will scorch and snap.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Wet Vine X-Lashing\",\n        \"2. Exposed Sharp Edge\",\n        \"3. Lower Collar Wrap\",\n        \"4. Shrinks 30% When Dry\",\n        \"Finished: Solid One-Piece Stone Axe\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Critical Mistake: Striking the Flat Center of the Rock or Binding with Dry Vines\",\n    \"description\": \"Smashing the flat center of a stone at 90 degrees shatters the rock into useless gravel instead of forming a sharp edge. Also, tying the blade with dry, brittle vines or rough outer bark will cause the lashing to snap on the first swing, sending a heavy stone blade flying toward your face or eyes.\",\n    \"consequence\": \"Result: Always strike the stone edge at 45 degrees for a clean blade, and lash with water-soaked inner bark dried slowly in the shade.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Completed Primitive Chipped Stone Axe\",\n    \"description\": \"A bifacially flaked flint blade seated deeply into a split oak haft, bound firmly with criss-cross vine lashing and sealed with pine pitch resin composite.\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.es.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo hacer un hacha de piedra con rocas de río y lianas\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTANCIA: HERRAMIENTA CLAVE]\",\n  \"summary\": \"Con las manos vacías no puedes cortar ramas gruesas para tu refugio o para leña. Aprende a golpear dos piedras duras de río en un ángulo de 45 grados para sacar una hoja afilada y fijarla en un mango de madera con resina de pino y corteza de liana húmeda.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (golpeando el borde a 45°)\",\n  \"difficulty\": \"Media (Apto para principiantes)\",\n  \"outputPerHour\": \"1 hacha de piedra lista\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 piedra dura de río y 1 piedra martillo redonda\",\n      \"desc\": \"Una piedra compacta de río (del tamaño de dos puños) que al romperse deje bordes afilados como vidrio, y una piedra redonda y pesada para golpear.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Mango de madera dura del largo del antebrazo (roble o fresno)\",\n      \"desc\": \"Una rama verde y resistente (40–50cm de largo y 3.5–4cm de grosor) que soporte golpes fuertes sin partirse.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Corteza interna de liana remojada y resina de pino\",\n      \"desc\": \"Más de 3 metros de corteza interna de liana húmeda (que se encoge y aprieta al secarse) y un puñado de resina de pino seca.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Golpear dos piedras a 45 grados para sacar una hoja afilada\",\n      \"description\": \"Apoya bien la piedra grande en el suelo y golpea su borde exterior en un ángulo inclinado de 45 grados con la piedra martillo. Si golpeas el centro en vertical solo romperás la roca, pero al golpear el borde a 45 grados se desprende de una vez una lasca del tamaño de la mano con filo de navaja.\",\n      \"actionNote\": \"> Consejo clave: No golpees el centro plano de la piedra. Apunta 1–2cm hacia adentro desde el borde exterior y da un golpe seco y firme.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Piedra martillo redonda\",\n        \"2. Golpear borde a 45°\",\n        \"Filo agudo (1-2cm)\",\n        \"4. Hoja de piedra separada\",\n        \"3. Piedra base (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rajar la punta del mango de madera, encajar la hoja y rellenar con resina\",\n      \"description\": \"Usa una piedra afilada para abrir unahendidura vertical de 5–7cm en la punta del mango de madera. Ata primero una cuerda justo debajo de la abertura para que la madera no se siga rajando, y mete la parte trasera gruesa de la hoja de piedra. Luego derrite resina de pino al fuego, mézclala con polvo fino de carbón y rellena todos los huecos.\",\n      \"actionNote\": \"> Por qué funciona: La resina sola se vuelve frágil como el vidrio al enfriarse. Mezclar un tercio de polvo de carbón crea un pegamento natural súper resistente a los golpes.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encajar hoja hacia abajo\",\n        \"Filo delantero\",\n        \"2. Ranura en madera (5-7cm)\",\n        \"3. Resina + polvo de carbón\",\n        \"4. Atar abajo para no rajar\",\n        \"Grosor del mango: 3.5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Atar fuerte en forma de X con liana húmeda y secar a la sombra\",\n      \"description\": \"Con la corteza interna de liana bien mojada y flexible, envuelve la hoja de piedra y el mango cruzando en diagonal en forma de X más de 10 vueltas bien tensas. Después enrolla la parte inferior en horizontal, haz un nudo firme y déjalo secar a la sombra. Al secarse, la liana se encoge casi un 30% y aprieta la piedra como si fuera alambre de acero.\",\n      \"actionNote\": \"> Precaución: Cuando esté seco, mueve la piedra con fuerza con la mano; no debe moverse ni un milímetro. No la acerques al fuego para secarla rápido o la fibra se quemará y se romperá.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarre en X con liana\",\n        \"2. Filo cortante expuesto\",\n        \"3. Vueltas inferiores\",\n        \"4. Encoge 30% al secar\",\n        \"Listo: Hacha firme de una sola pieza\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error grave: Golpear el centro plano de la roca o atar con lianas secas\",\n    \"description\": \"Si golpeas el centro plano de la piedra a 90 grados, no saldrá ningún filo y toda la roca se romperá en grava inútil. Además, si atas con lianas secas o corteza exterior áspera, la cuerda se partirá al primer golpe y la piedra pesada puede salir disparada hacia tu cara o tus ojos.\",\n    \"consequence\": \"Resultado: Golpea siempre el borde a 45 grados y ata con fibra interna remojada en agua, secándola a la sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Hacha Primitiva de Piedra y Liana Completada\",\n    \"description\": \"Una hoja de pedernal tallada bifacialmente incrustada en un mango de roble hendido, atada firmemente en X con lianas y sellada con resina de pino.\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.ja.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"割った石とツルで作る木切り用の石斧\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度: 基本道具]\",\n  \"summary\": \"素手では小屋の柱や薪にする太い枝を切ることはできません。河原の硬い石を45度の角度でぶつけて鋭い石の刃を割り出し、木の柄の割れ目に松ヤニと濡らしたツルの皮でしっかり固定して丈夫な石斧を作る方法です。\",\n  \"timeRequired\": \"60分\",\n  \"successRate\": \"90% (角を45度で叩いた場合)\",\n  \"difficulty\": \"普通 (初心者でも可能)\",\n  \"outputPerHour\": \"石斧 1本完成\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"硬い川石 1個と丸いハンマー石 1個\",\n      \"desc\": \"割れるとガラスのように鋭い縁ができる硬い川石（こぶし2個分）1個と、手に持って叩きつける丸くて重い石1個です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"腕の長さの硬い木の枝（ナラやトネリコの生木）\",\n      \"desc\": \"強く振り下ろしても折れにくい丈夫な生木の枝（長さ40〜50cm、太さ3.5〜4cmほど）1本です。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"水に浸したツルの内皮と松ヤニ\",\n      \"desc\": \"乾くと縮んで強く締まるツルの内皮（長さ3m以上）と、松の木の傷口で固まった松ヤニひと握りです。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"石と石を45度の角度でぶつけて鋭い石の刃を割り出す\",\n      \"description\": \"地面に大きな川石を動かないように置き、手に持った丸い石で川石の端の角を45度の角度で斜めに強く叩きます。真ん中を真上から叩くと石が砕けるだけですが、角を45度で叩くと手のひらサイズでカミソリのように鋭い石の刃が一発で剥がれ落ちます。\",\n      \"actionNote\": \"> コツ: 石の平らな真ん中を叩かないでください。角の端から指関節1つ分（1〜2cm）内側を狙って一気に強く叩くと、長くて鋭い石の刃が取れます。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 丸いハンマー石（叩く石）\",\n        \"② 角を45°で斜めに叩く\",\n        \"鋭い石の刃（厚さ1〜2cm）\",\n        \"④ 剥がれた石斧の刃\",\n        \"③ 土台の川石（幅15〜20cm）\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"木の柄の上部を割って石の刃を挟み、松ヤニを詰める\",\n      \"description\": \"硬い木の柄の上側を鋭い石で指の長さ（5〜7cm）ほど縦に割って隙間を作ります。それ以上下まで割れないように割れ目のすぐ下を先に紐で縛ってから、隙間に石の刃の厚い後ろ側を奥まで差し込みます。次に火で溶かした松ヤニに細かい炭の粉を混ぜ、隙間にぎっしり詰めて固めます。\",\n      \"actionNote\": \"> 仕組み: 松ヤニだけを溶かして塗ると、冷えた後にガラスのように割れてしまいます。黒い炭の粉を3分の1ほど混ぜると、衝撃でも割れない強力な天然接着剤になります。\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 上から下へ石刃を差し込む\",\n        \"木を切る前の刃\",\n        \"② 割った木の隙間（5〜7cm）\",\n        \"③ 溶けた松ヤニ＋炭粉充填\",\n        \"④ 割れ止め用の下部縛り\",\n        \"生木の柄の太さ: 直径3.5〜4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"濡れたツルの皮でX字に強く巻きつけて日陰で乾かす\",\n      \"description\": \"水に浸して柔らかくなったツルの内皮で、石の刃と木の柄を斜めのX字に交互に10周以上力いっぱい引っ張りながら巻きます。続けて柄の下側も横にぐるぐる巻いて結び、日陰で乾かします。濡れたツルは乾くと長さが約30%縮むため、乾いた後は針金で締めたように石の刃をガッチリ固定します。\",\n      \"actionNote\": \"> 注意点: 完全に乾いた後、手で石の刃を強く揺すって少しもグラつかないか確認してください。早く乾かそうとして火に近づけるとツルが焦げて切れるので、必ず風通しの良い日陰で乾かしてください。\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濡れたツルをX字に巻く\",\n        \"② 鋭い石斧の先端\",\n        \"③ 柄の下側を横に強く巻く\",\n        \"④ 乾燥で30%縮んで圧着\",\n        \"完成状態: 強く叩いても抜けない一体型石斧\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にしてはいけないミス: 平らな石の真ん中を叩く・乾いたツルで縛る\",\n    \"description\": \"石の平らな中央を90度で叩くと、鋭い刃ができずに石全体がただの砂利に砕けてしまいます。また、水に濡らしていない乾いたツルや硬い外皮で縛ると、木を叩いた瞬間に紐が切れ、重い石の刃が顔や目に飛んで大ケガをします。\",\n    \"consequence\": \"結果: 必ず石の角を45度で叩いて刃を作り、水に浸した丈夫な内皮でX字に巻いて日陰で乾かしてから安全に使ってください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"割り石と葛蔓結束の原始石斧の完成形態\",\n    \"description\": \"硬い樫の木のY字柄の溝に両面打製された鋭利なフリント刃を深く噛み合わせ、強靭な葛蔓と松脂接着剤でX字十字結束した実戦石斧の完成形態です。\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.pt.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como fazer um machado de pedra com pedras de rio e cipó\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[IMPORTÂNCIA: FERRAMENTA ESSENCIAL]\",\n  \"summary\": \"Com as mãos vazias não é possível cortar galhos grossos para abrigo ou lenha. Veja como bater duas pedras duras de rio em um ângulo de 45 graus para tirar uma lâmina afiada e prendê-la em um cabo de madeira com resina de pinheiro e cipó úmido.\",\n  \"timeRequired\": \"60 min\",\n  \"successRate\": \"90% (batendo na borda a 45°)\",\n  \"difficulty\": \"Média (Iniciantes conseguem)\",\n  \"outputPerHour\": \"1 machado de pedra pronto\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 pedra dura de rio e 1 pedra redonda de bater\",\n      \"desc\": \"Uma pedra firme de rio (do tamanho de dois punhos) que quebre formando bordas afiadas como vidro, e uma pedra redonda e pesada para usar como martelo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Cabo de madeira dura do tamanho do antebraço (carvalho ou freixo)\",\n      \"desc\": \"Um galho verde e resistente (40–50cm de comprimento, 3,5–4cm de espessura) que aguente pancadas fortes sem quebrar.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Fibra interna de cipó molhada e resina de pinheiro\",\n      \"desc\": \"Mais de 3 metros de casca interna de cipó deixada de molho na água (encolhe e aperta ao secar) e um punhado de resina seca de pinheiro.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Bater as pedras a 45 graus para soltar uma lâmina afiada\",\n      \"description\": \"Apoie bem a pedra grande no chão e bata na borda dela em um ângulo inclinado de 45 graus usando a pedra redonda. Bater reto no meio só esfarela a rocha, mas bater na quina a 45 graus destaca de uma só vez uma lasca do tamanho da palma da mão com fio de navalha.\",\n      \"actionNote\": \"> Dica principal: Não bata no meio plano da pedra. Mire 1–2cm para dentro da borda e dê uma pancada firme e rápida.\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"1. Pedra redonda (martelo)\",\n        \"2. Bater na borda a 45°\",\n        \"Lâmina afiada (1-2cm)\",\n        \"4. Lasca de machado solta\",\n        \"3. Pedra base (15-20cm)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Rachar a ponta do cabo de madeira, encaixar a lâmina e preencher com resina\",\n      \"description\": \"Use uma pedra afiada para abrir uma fenda vertical de 5–7cm no topo do cabo de madeira. Amarre primeiro uma fibra logo abaixo da fenda para a madeira não rachar mais para baixo, e encaixe a parte traseira grossa da lâmina de pedra. Depois, derreta a resina de pinheiro no fogo, misture pó fino de carvão e preencha todos os espaços.\",\n      \"actionNote\": \"> Como funciona: A resina pura fica quebradiça como vidro depois que esfria. Misturar um terço de pó de carvão cria uma cola natural super resistente a impactos.\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"1. Encaixar lâmina por cima\",\n        \"Fio de corte frontal\",\n        \"2. Fenda no cabo (5-7cm)\",\n        \"3. Resina + pó de carvão\",\n        \"4. Amarrar embaixo antes\",\n        \"Espessura do cabo: 3,5-4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Amarrar firme em X com cipó úmido e secar na sombra\",\n      \"description\": \"Com a fibra interna do cipó bem molhada e macia, dê mais de 10 voltas bem apertadas cruzando em X sobre a lâmina de pedra e o cabo de madeira. Em seguida, enrole a base na horizontal, dê um nó firme e deixe secar na sombra. O cipó molhado encolhe quase 30% ao secar, prendendo a pedra como se fosse arame de aço.\",\n      \"actionNote\": \"> Atenção: Depois de seco, balance a pedra com força usando a mão; ela não pode ter nenhuma folga. Não tente secar perto do fogo para não queimar e romper as fibras.\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"1. Amarração em X com cipó\",\n        \"2. Fio afiado exposto\",\n        \"3. Voltas horizontais na base\",\n        \"4. Encolhe 30% ao secar\",\n        \"Pronto: Machado firme em peça única\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro grave: Bater no meio plano da pedra ou amarrar com cipó seco\",\n    \"description\": \"Bater em ângulo reto (90 graus) no centro plano da pedra não cria lâmina e só quebra a pedra em pedregulhos inúteis. Além disso, amarrar com cipó seco ou casca grossa faz a amarração arrebentar na primeira batida, podendo lançar a pedra pesada contra o seu rosto.\",\n    \"consequence\": \"Resultado: Bata sempre na borda a 45 graus e amarre com fibra interna molhada, secando na sombra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"Machado Primitivo de Pedra e Cipó Concluído\",\n    \"description\": \"Uma lâmina de sílex lascada bifacialmente encaixada em cabo de carvalho fendido, amarrada firmemente em X com cipós e selada com resina de pinho.\"\n  }\n}\n","content/protocols/locales/04-stone-axe-making.zh-TW.json":"{\n  \"protocolId\": \"PR-04\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用碎石與藤蔓製作砍樹石斧的方法\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[重要度：核心工具]\",\n  \"summary\": \"徒手無法砍斷用來蓋避難所或當柴燒的粗樹枝。只要將兩塊堅硬的河石以45度角互相敲擊，就能剝離出鋒利的石刃，接著嵌入木柄縫隙中，並用松脂與泡過水的濕藤皮牢牢綁緊，做出一把堅固耐用的石斧。\",\n  \"timeRequired\": \"60分鐘\",\n  \"successRate\": \"90% (以45度角敲擊邊緣時)\",\n  \"difficulty\": \"普通 (新手可完成)\",\n  \"outputPerHour\": \"完成 1 把石斧\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"堅硬河石 1 塊與圓形錘石 1 塊\",\n      \"desc\": \"敲碎後會產生如玻璃般鋒利邊緣的堅硬河石（約兩個拳頭大）1 塊，以及握在手中用來敲擊的沉重圓石 1 塊。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"前臂長度的堅硬木柄（橡木或白蠟木）\",\n      \"desc\": \"用力揮砍也不易折斷的強韌生木枝條（長 40～50cm，直徑約 3.5～4cm）1 根。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"泡水軟化的葛藤內皮與松樹樹脂\",\n      \"desc\": \"乾燥後會自動收縮勒緊的濕葛藤內皮（長 3m 以上），以及從松樹樹皮上採集的凝固松脂一把。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"以45度角敲擊石頭，剝離出鋒利的石刃\",\n      \"description\": \"將大塊河石穩穩固定在地面上，手持圓形錘石，對準大河石的邊緣角落以 45 度角斜向用力敲下去。垂直敲打正中央只會把石頭砸碎，但以 45 度角敲擊邊緣，就能一次劈下巴掌大小、邊緣如刀片般鋒利的石刃。\",\n      \"actionNote\": \"> 關鍵訣竅：千萬不要敲打石頭平坦的正中央。瞄準距離邊緣內側約一節手指（1～2cm）處，果斷用力一擊才能打出又長又利的石刃。\",\n      \"svgFileName\": \"pr04-step-01.svg\",\n      \"svgLabels\": [\n        \"① 圓形錘石（敲擊石）\",\n        \"② 對準邊緣 45° 斜敲\",\n        \"鋒利石刃（厚 1～2cm）\",\n        \"④ 劈下的石斧刀片\",\n        \"③ 底部墊石（寬 15～20cm）\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"劈開木柄頂端，嵌入石刃並填滿松脂\",\n      \"description\": \"用鋒利的石片將硬木柄頂端垂直劈開約手指長度（5～7cm）的縫隙。為了防止木柄繼續往下裂開，先在裂縫正下方用繩子緊緊綁住，再將石刃較厚的後端深深塞進縫隙裡。接著把用火融化的松脂混入細木炭粉，填滿所有空隙並冷卻凝固。\",\n      \"actionNote\": \"> 核心原理：只塗純松脂的話，冷卻後會像玻璃一樣脆裂。混入約三分之一的細黑炭粉，就能變成耐衝擊又不碎裂的天然強力膠。\",\n      \"svgFileName\": \"pr04-step-02.svg\",\n      \"svgLabels\": [\n        \"① 由上往下嵌入石刃\",\n        \"砍樹的前方刀刃\",\n        \"② 劈開的木柄縫隙（5～7cm）\",\n        \"③ 填入融化松脂＋木炭粉\",\n        \"④ 下方先綁緊防裂開\",\n        \"生木柄粗度：直徑 3.5～4cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"用濕藤皮以X字形緊緊纏繞並在陰涼處晾乾\",\n      \"description\": \"用充分泡水變軟的葛藤內皮，在石刃與木柄交界處以對角線 X 字形交替用力拉緊纏繞 10 圈以上，接著在木柄下方橫向繞緊打結，放在通風陰涼處晾乾。濕藤皮在乾燥過程中會縮短將近 30%，乾透後會像鐵絲一樣把石刃死死鎖住。\",\n      \"actionNote\": \"> 注意事項：完全乾透後，用手用力搖晃石刃，必須連一點點鬆動都沒有才安全。千萬別為了快乾而拿到火邊烤，藤皮烤焦後一砍就會斷裂。\",\n      \"svgFileName\": \"pr04-step-03.svg\",\n      \"svgLabels\": [\n        \"① 濕藤皮 X 字形交叉纏繞\",\n        \"② 外露的鋒利斧刃\",\n        \"③ 木柄下方橫向繞緊固定\",\n        \"④ 乾燥收縮 30% 強力鎖緊\",\n        \"完成狀態：重擊也不脫落的一體成型石斧\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：垂直敲打石頭中央或用乾藤蔓綁縛\",\n    \"description\": \"以 90 度垂直敲擊平坦的石頭中央，只會把整塊石頭震碎成沒用的碎石。此外，若用沒泡水的乾枯藤蔓或粗糙外皮捆綁，揮斧砍樹的瞬間繩子就會斷裂，沉重的石刃會直接飛向臉部或眼睛造成嚴重傷害。\",\n    \"consequence\": \"結果：務必以 45 度角敲擊河石邊緣取刃，並用泡水軟化的強韌內皮以 X 字形纏繞後陰乾。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr04-outcome.svg\",\n    \"title\": \"敲石碎屑與葛藤結紮原始石斧完成形態\",\n    \"description\": \"堅韌橡木柄凹槽中深嵌雙面打製鋒利燧石刃，以強韌葛藤與松脂黏合劑進行X型十字結紮，具備砍伐原木威力的實戰石斧完成形態。\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.de.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Reißfestes Wildnisseil aus Baumrinde und Ranken drehen\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[ÜBERLEBENSWICHTIG]\",\n  \"summary\": \"Eine stabile Schnur ist unverzichtbar für Unterstände, Steinäxte und Feuerbohrer. Ganze grüne Ranken schrumpfen und brechen beim Trocknen; wenn man jedoch die weiße Innenrinde (Bastfaser) abzieht und zwei Stränge gegenläufig zusammendreht, entsteht ein selbstsicherndes Seil, das das Gewicht eines Erwachsenen trägt.\",\n  \"timeRequired\": \"40 Min.\",\n  \"successRate\": \"95% (Mit Gegendrehung)\",\n  \"difficulty\": \"Mittel (Mit bloßen Händen)\",\n  \"outputPerHour\": \"5m / 40 Min.\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lebende Kudzu-Ranken, Linden-, Weiden- oder Brennnesselstängel (10~15 armlange Triebe)\",\n      \"desc\": \"Wählen Sie biegsame Triebe, die beim Knicken nicht brechen und unter dem Fingernagel grüne Feuchtigkeit zeigen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 scharfkantiger Steinabschlag zum Abschaben\",\n      \"desc\": \"Zum vorsichtigen Abschaben der spröden braunen Außenrinde, ohne die zähen weißen Innenfasern zu beschädigen.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flacher Unterlegstein und faustgroßer runder Klopfstein\",\n      \"desc\": \"Um die eingeweichte Innenrinde sanft weichzuklopfen, bis sie sich in feine, haarähnliche Fasern teilt.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Bach- oder Tümpelwasser zum Einweichen\",\n      \"desc\": \"Frisch abgezogene Innenrinde 20~30 Minuten wässern, um steifen Pflanzensaft zu lösen und die Fasern geschmeidig zu halten.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Biegsame Stängel wählen, Außenrinde abschaben und weiße Innenfaser abziehen\",\n      \"description\": \"Biegen Sie den Stängel zur Hälfte, um zu prüfen, ob er elastisch bleibt. Schaben Sie mit einer Steinkante vorsichtig die raue braune Außenrinde ab, bis die helle, zähe Bastschicht sichtbar wird. Heben Sie das untere Ende mit dem Fingernagel an und ziehen Sie lange Faserbänder vom harten Holzkern ab.\",\n      \"actionNote\": \"> Tipp: Abgestorbene, trockene Stängel am Boden haben morsche Fasern, die sofort reißen. Immer frische Triebe nutzen.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raue Außenrinde mit Steinkante abschaben\",\n        \"② Spröde braune Außenrinde (abschaben & wegwerfen)\",\n        \"③ Zähe weiße Innenfaser (Hauptmaterial fürs Seil)\",\n        \"④ Harter Holzkern in der Mitte (entfernen)\",\n        \"⑤ Biegsamer lebender Stängel bricht nicht\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: 20 Minuten im Bach wässern und mit rundem Stein weichklopfen\",\n      \"description\": \"Legen Sie die abgezogenen Rindenstreifen für 20~30 Minuten ins Wasser. Breiten Sie die aufgeweichten Streifen auf einem flachen Flussstein aus und klopfen Sie sie mit einem runden Stein sanft von oben nach unten. Sobald sich feine, weiche Faserbündel lösen, teilen Sie diese in zwei fingerdicke Stränge.\",\n      \"actionNote\": \"> Grundprinzip: Zu harte Schläge durchtrennen die Fasern. Sanft drücken und klopfen, damit die Fasern lang bleiben.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Innenrinde 20+ Min. im Bachwasser eingeweicht\",\n        \"② Sanft mit rundem Stein klopfen zum Auffasern\",\n        \"③ Weiches, haarfein gelöstes Faserbündel\",\n        \"④ Zwei gleichmäßige, fingerdicke Faserstränge\",\n        \"⑤ Stabiler flacher Flussstein als Unterlage\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Nach außen zwirbeln und zum Körper kreuzen (Gegendrehung)\",\n      \"description\": \"Klemmen Sie die Mitte des Faserbündels zwischen linken Daumen und Zeigefinger, sodass ein oberer und ein unterer Strang entstehen. Drehen Sie den oberen Strang mit der rechten Hand fest vom Körper weg (nach außen) und legen Sie ihn dann über den unteren Strang zu Ihrem Körper hin. Linken Daumen nachsetzen, Kreuzungspunkt festhalten und wiederholen.\",\n      \"actionNote\": \"> Grundprinzip: Dreht man beide Stränge in dieselbe Richtung, rollt sich das Seil sofort wieder auf. Die Gegendrehung verriegelt beide Stränge.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Oberer Strang: fest vom Körper wegdrehen (↑)\",\n        \"② Verzahntes Fischgrät-Seilmuster\",\n        \"③ Kreuzungspunkt mit linkem Daumen & Zeigefinger halten\",\n        \"④ Gedrehten Strang über unteren zum Körper legen (↓)\",\n        \"⑤ Selbstsichernde Gegendreh-Verriegelung\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Neue Fasern 10cm überlappen für endlose Seillänge\",\n      \"description\": \"Wenn ein Strang auf die letzten 10cm dünner wird, legen Sie ein neues Faserbündel 10cm überlappend direkt daneben. Halten Sie altes Ende und neues Bündel gemeinsam wie einen einzigen Strang und drehen Sie normal weiter. Versetzen Sie die Verbindungsstellen von oberem und unterem Strang um mindestens eine Handspanne (15cm).\",\n      \"actionNote\": \"> Achtung: Liegen beide Spleißstellen an derselben Stelle, entsteht ein dicker Knotenpunkt, der unter Zug reißt.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Alter Strang wird bei 10cm Restlänge dünner\",\n        \"② Neues Faserbündel 10cm daneben überlappen\",\n        \"③ Beide Enden gemeinsam als einen Strang drehen\",\n        \"④ Glatte Verbindung ohne dicke Schwachstelle\",\n        \"⑤ Obere & untere Spleißstelle 15cm versetzen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Endknoten setzen und am Baumstamm mit Körpergewicht testen\",\n      \"description\": \"Nach Erreichen der gewünschten Länge (ab 5m) die letzten 3cm zu einer Schlaufe legen und mit einem festen Überhandknoten sichern. Abstehende Fasern mit einer Steinklinge glätten. Zuletzt das Seil um einen dicken Baumstamm legen und mit vollem Körpergewicht (50kg+) daran ziehen.\",\n      \"actionNote\": \"> Praxistest: Knacken Fasern oder rutscht eine Verbindung, diese Stelle sofort mit zusätzlichen Fasern umwickeln.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Sicherungsknoten 3cm vor dem Seilende\",\n        \"② Abstehende Fasern mit Steinklinge säubern\",\n        \"③ Um Baumstamm legen & mit Körpergewicht (50kg+) ziehen\",\n        \"④ Fertiges 5mm Wildnisseil (5m Länge)\",\n        \"⑤ Bereit für Unterstand, Steinaxt & Feuerbohrer\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Ungeschälte grüne Ranken direkt zum Binden verwenden\",\n    \"description\": \"Wickelt man ganze grüne Ranken oder Zweige direkt um Unterstand oder Steinaxt, wirkt das nur anfangs fest. Sobald der Pflanzensaft trocknet, schrumpft die Ranke, lockert sich und der holzige Kern bricht bei Belastung sofort durch. Immer nur die abgezogene Innenfaser gegenläufig verdrillen.\",\n    \"consequence\": \"Folge: Das Dach des Unterstands bricht nachts ein oder der Steinaxtkopf löst sich beim Schlagen\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Wie man im Wald ohne Hilfsmittel mit bloßen Händen ein reißfestes Seil dreht.\",\n    \"body\": \"Braune Außenrinde von lebenden Ranken abschaben und weiße Innenfaser abziehen. 20 Minuten wässern und mit rundem Stein weichklopfen. Halbieren, oberen Strang vom Körper wegdrehen und zum Körper hin überkreuzen. Neue Fasern 10cm überlappen für endlose Länge.\",\n    \"outro\": \"Hält über 50kg Körpergewicht am Baumstamm. Perfekt für Unterstände, Steinäxte und Feuerbohrer.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Vollendeter 2-Strang-Naturseilbund mit Gegenverdrallung\",\n    \"description\": \"Ein gleichmäßiger 8-mm-Seilbund aus im Uhrzeigersinn gedrehten und gegenläufig verzwirnten Bastfasern, der über 90 kgf Zuglast ohne Aufdröseln standhält.\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.en.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"How to Twist Unbreakable Wild Cordage from Bark and Vines\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[CRITICAL SURVIVAL]\",\n  \"summary\": \"Strong cordage is essential for lashing shelter frames, hafting stone axes, and spinning a bow drill. Whole raw vines shrink and snap brittlely once dry, but extracting inner bast fibers and reverse-wrapping two strands creates a self-locking rope strong enough to hold adult body weight.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (With Reverse Wrap)\",\n  \"difficulty\": \"Medium (Bare Hands)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Live Kudzu Vines, Basswood, Willow, or Nettle Stems (10~15 arm-length stalks)\",\n      \"desc\": \"Choose live stalks that bend smoothly without snapping and show green moisture when scratched with a fingernail.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Sharp-Edged Stone Flake for Scraping\",\n      \"desc\": \"Used to gently scrape off the brittle brown outer bark without cutting into the tough white inner fibers beneath.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Flat Anvil Stone and Fist-Sized Round Hammer Stone\",\n      \"desc\": \"Used to gently pound soaked inner bark strips until they separate into soft, hair-like fiber strands.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Stream or Standing Water for Soaking\",\n      \"desc\": \"Soak freshly peeled inner bark for 20~30 minutes to soften stiff sap and keep fibers flexible while twisting.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Select Flexible Stalks, Scrape Outer Bark, and Peel White Inner Bark\",\n      \"description\": \"Bend the stalk in half to confirm it flexes without snapping. Hold a stone edge at an angle and lightly scrape away the rough brown outer bark until the pale, tough inner fiber layer appears. Lift the bottom edge with your fingernail and peel long ribbon strips upward away from the woody core.\",\n      \"actionNote\": \"> Key Tip: Dead, dry stalks on the ground have rotted fibers that crumble under tension. Always harvest inner bark from live or freshly cut stalks.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Scrape off rough outer bark with stone edge\",\n        \"② Brittle brown outer bark (scrape & discard)\",\n        \"③ Tough white inner bast fiber (core rope material)\",\n        \"④ Stiff woody center core (peel off & discard)\",\n        \"⑤ Flexible live stalk that bends without snapping\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Soak in Water for 20 Minutes and Pound into Soft Hair-Like Fibers\",\n      \"description\": \"Submerge the peeled inner bark ribbons in stream water for 20~30 minutes. Lay the softened strips across a flat river stone and tap gently from top to bottom with a round stone. Once the stiff grain breaks down into soft, hair-like strands, divide them evenly into two equal bundles.\",\n      \"actionNote\": \"> Core Principle: Striking too hard with a sharp rock severs the fibers. Press and roll gently with a smooth stone to separate long intact strands.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Inner bark soaked 20+ min in stream water\",\n        \"② Gently tap with round stone to split fibers\",\n        \"③ Softened hair-like fiber bundle\",\n        \"④ Two equal finger-thick fiber strands\",\n        \"⑤ Stable flat river stone anvil beneath\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Twist Away and Cross Toward You (Reverse-Wrap Locking Method)\",\n      \"description\": \"Pinch the middle of a fiber bundle between your left thumb and forefinger, folding it into an upper and lower strand. With your right hand, twist the upper strand tightly away from your body, then bring that twisted strand over the lower strand toward your body. Move your left thumb forward to pinch the new crossing point and repeat: twist the top strand away, then wrap it toward you.\",\n      \"actionNote\": \"> Core Principle: Twisting both strands in the same direction causes the rope to unravel immediately. Twisting away while wrapping toward you locks opposing forces together.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Top strand: twist tightly away from body (↑)\",\n        \"② Interlocked chevron rope pattern\",\n        \"③ Pinch junction firmly with left thumb & index\",\n        \"④ Cross twisted top strand over toward body (↓)\",\n        \"⑤ Self-locking reverse-wrap structure\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Overlap New Fibers by 10cm to Splice Endless Length\",\n      \"description\": \"When either strand thins down with about 10cm remaining, lay a fresh fiber bundle alongside the old tail with a 10cm overlap. Hold both together as a single strand and continue twisting away and wrapping toward you. Always stagger splices between the upper and lower strands by at least one hand-span (15cm).\",\n      \"actionNote\": \"> Warning: Splicing both strands at the exact same spot creates a weak, bulky lump that snaps under load.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Existing strand thinning with 10cm left\",\n        \"② Lay new fiber bundle alongside (10cm overlap)\",\n        \"③ Twist overlapped tails together as one strand\",\n        \"④ Smooth splice without bulky weak lumps\",\n        \"⑤ Stagger top & bottom splices by 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Tie an End Stopper Knot and Test with Full Body Weight on a Tree\",\n      \"description\": \"Once you reach your target length (5m or more), fold the last 3cm into a loop and tie a tight overhand stopper knot. Lightly scrape off loose fuzz along the rope with a stone flake to reduce friction wear. Wrap the finished cordage around a sturdy tree trunk and pull back with your full body weight (50kg+) to verify no splices slip.\",\n      \"actionNote\": \"> Field Check: If you hear fibers snapping or see a splice slipping, wrap an extra thin fiber bundle around that section.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Overhand stopper knot 3cm from the end\",\n        \"② Trim loose fuzz cleanly with stone flake\",\n        \"③ Wrap around tree & pull with body weight (50kg+)\",\n        \"④ Finished 5mm wild rope (5m length)\",\n        \"⑤ Ready for shelter lashing, stone axe & bow drill\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Tying Whole Unpeeled Green Vines Directly\",\n    \"description\": \"Wrapping whole raw vines or green twigs directly around a shelter frame or stone axe feels tight at first, but within hours the sap dries, the vine shrinks and loosens, and the woody core snaps like a dry cracker under impact. Always strip the outer bark and woody core, and reverse-wrap the inner bast fibers.\",\n    \"consequence\": \"Consequence: Shelter roof collapses overnight or stone axe head flies off mid-swing causing severe injury\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"When you have zero rope in the wild, here is how to twist unbreakable cordage with bare hands.\",\n    \"body\": \"Scrape the brown outer bark off live kudzu vines and peel out the white inner fibers. Soak for 20 minutes and tap with a round stone until soft. Fold in half, twist the top strand away from you, and cross it over toward you. Overlap new fibers by 10cm to splice endless length.\",\n    \"outro\": \"Tested against 50kg of body weight on a tree trunk. Ready for shelters, stone axes, and bow drills.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Completed 2-Ply Reverse-Wrapped Natural Cordage Coil\",\n    \"description\": \"A uniform 8mm braided rope coil made by twisting bast fibers clockwise and counter-wrapping plies, sustaining over 90 kgf tensile load without slipping.\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.es.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Cómo trenzar cuerda salvaje irrompible con corteza y lianas\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SUPERVIVENCIA CRÍTICA]\",\n  \"summary\": \"Una cuerda resistente es indispensable para atar refugios, fijar hachas de piedra y encender fuego con arco. Atar lianas verdes enteras falla porque encogen y se quiebran al secarse; en cambio, extraer la fibra blanca interna y trenzar dos cabos en sentido inverso crea una soga autobloqueante capaz de soportar el peso de un adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Con trenzado inverso)\",\n  \"difficulty\": \"Media (Con las manos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Lianas vivas de kudzu, tilo, sauce o tallos de ortiga (10~15 tallos del largo del brazo)\",\n      \"desc\": \"Elija tallos vivos que se doblen sin romperse y muestren humedad verde al rasparlos con la uña.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de piedra con borde afilado para raspar\",\n      \"desc\": \"Se usa para raspar suavemente la corteza exterior marrón sin cortar las fibras blancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Piedra plana de base y canto rodado del tamaño del puño\",\n      \"desc\": \"Para golpear suavemente la corteza interna remojada hasta separarla en hebras suaves como cabellos.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Agua de arroyo o charca para remojar\",\n      \"desc\": \"Remoje la corteza interna durante 20~30 minutos para ablandar la savia y mantener las fibras flexibles.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Elegir tallos flexibles, raspar la corteza exterior y pelar la fibra blanca interna\",\n      \"description\": \"Doble el tallo por la mitad para comprobar que se curva sin partirse. Raspe suavemente la corteza marrón exterior con el borde de una piedra hasta descubrir la capa blanca y fibrosa. Levante el extremo inferior con la uña y tire hacia arriba para desprender tiras largas separándolas del núcleo leñoso.\",\n      \"actionNote\": \"> Consejo clave: Los tallos secos caídos en el suelo tienen fibras podridas que se rompen al tensarlas. Use siempre tallos vivos.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar corteza exterior con borde de piedra\",\n        \"② Corteza marrón quebradiza (raspar y tirar)\",\n        \"③ Fibra interna blanca y firme (material clave)\",\n        \"④ Núcleo central de madera dura (desechar)\",\n        \"⑤ Tallo vivo flexible que se dobla sin partirse\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Remojar 20 minutos en el arroyo y machacar con piedra hasta suavizar\",\n      \"description\": \"Sumerja las tiras de corteza interna en agua durante 20~30 minutos. Extiéndalas sobre una piedra plana y golpéelas suavemente con una piedra redonda de arriba abajo. Cuando la fibra rígida se separe en hebras finas y suaves como hilos, divídalas en dos manojos iguales del grosor de un dedo.\",\n      \"actionNote\": \"> Principio clave: Golpear demasiado fuerte corta las fibras. Presione y machaque con suavidad para conservar hebras largas.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Corteza interna remojada 20+ min en agua\",\n        \"② Golpear suave con piedra redonda para abrir fibras\",\n        \"③ Manojo de fibras suaves como cabellos\",\n        \"④ Dos cabos iguales del grosor de un dedo\",\n        \"⑤ Piedra plana firme apoyada en el suelo\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Retorcer hacia afuera y cruzar hacia el cuerpo (Trenzado Inverso)\",\n      \"description\": \"Sujete la mitad del manojo con el pulgar e índice izquierdos y dóblelo para formar un cabo superior y otro inferior. Con la mano derecha, retuerza con fuerza el cabo superior hacia afuera (alejándolo de usted) y luego crúcelo por encima del cabo inferior hacia su cuerpo. Avance el pulgar izquierdo para sujetar el cruce y repita siempre: retorcer hacia afuera y cruzar hacia adentro.\",\n      \"actionNote\": \"> Principio clave: Si gira ambos cabos en la misma dirección, la cuerda se deshará sola. El giro opuesto bloquea las tensiones entre sí.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: retorcer firme hacia afuera (↑)\",\n        \"② Trenzado en espiga autobloqueado\",\n        \"③ Sujetar cruce con pulgar e índice izquierdos\",\n        \"④ Cruzar cabo superior hacia el cuerpo (↓)\",\n        \"⑤ Cierre inverso que no se deshace al soltar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Superponer 10cm de fibra nueva para empalmar longitud infinita\",\n      \"description\": \"Cuando a un cabo le queden unos 10cm y se adelgace, coloque un manojo nuevo junto al extremo viejo superponiendo 10cm. Sujete ambos como si fueran un solo cabo y siga retorciendo hacia afuera y cruzando hacia usted. Separe siempre los empalmes del cabo superior e inferior al menos un palmo (15cm).\",\n      \"actionNote\": \"> Precaución: Empalmar ambos cabos en el mismo punto crea un bulto débil que se rompe al tirar.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo viejo adelgazado con 10cm restantes\",\n        \"② Colocar fibra nueva al lado (10cm superpuestos)\",\n        \"③ Retorcer ambos extremos juntos como uno solo\",\n        \"④ Empalme liso sin bultos ni puntos débiles\",\n        \"⑤ Desfasar empalmes superior e inferior por 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Hacer nudo de tope final y probar con el peso del cuerpo en un árbol\",\n      \"description\": \"Al alcanzar la longitud deseada (5m o más), doble los últimos 3cm y haga un nudo simple bien apretado para que no se deshilache. Raspe los pelos sueltos con una lasca de piedra. Por último, rodee el tronco de un árbol firme con la cuerda y tire con todo su peso (50kg+) para comprobar que ningún empalme resbale.\",\n      \"actionNote\": \"> Verificación: Si oye crujir fibras o nota que un empalme cede, refuerce ese tramo envolviendo más fibra encima.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nudo final de tope a 3cm del extremo\",\n        \"② Recortar fibras sueltas con lasca de piedra\",\n        \"③ Rodear árbol y tirar con peso corporal (50kg+)\",\n        \"④ Cuerda salvaje terminada de 5mm (5m largo)\",\n        \"⑤ Lista para refugios, hacha de piedra y arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Atar lianas verdes enteras sin pelar la corteza\",\n    \"description\": \"Atar ramas o lianas enteras directamente al refugio o al hacha parece firme al principio, pero al secarse la savia en pocas horas se encogen, quedan flojas y el centro leñoso se parte como una galleta seca. Siempre pele la corteza y trence solo la fibra interna.\",\n    \"consequence\": \"Consecuencia: El techo del refugio se desploma mientras duerme o la hoja del hacha sale despedida causando heridas graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Cómo hacer una cuerda salvaje irrompible con las manos cuando no tienes nada en el bosque.\",\n    \"body\": \"Raspa la corteza marrón de una liana viva y saca la fibra blanca interna. Remójala 20 minutos y machácala con una piedra redonda hasta suavizarla. Dóblala, retuerce el cabo superior hacia afuera y crúzalo hacia ti. Superpón 10cm de fibra nueva para alargarla sin límite.\",\n    \"outro\": \"Soporta más de 50kg colgada de un árbol. Lista para atar tu refugio o fijar un hacha de piedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rollo de Cuerda Natural de 2 Cabos con Torsión Inversa Completado\",\n    \"description\": \"Una bobina de cuerda uniforme de 8 mm trenzada en sentido inverso con fibras de corteza, capaz de resistir más de 90 kgf de carga de tracción.\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.ja.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"木の皮とクズのつるを撚って切れない野生ロープを作る方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必須サバイバル]\",\n  \"summary\": \"シェルターの柱を結んだり、石斧を固定したり、火起こしをするには丈夫な紐が不可欠です。生のつるをそのまま結ぶと乾いた時に縮んで折れますが、内側の白い繊維を取り出して2本を逆方向にねじり合わせれば、大人の体重にも耐える強靭な野生ロープが作れます。\",\n  \"timeRequired\": \"40分\",\n  \"successRate\": \"95% (逆撚り法を守った場合)\",\n  \"difficulty\": \"普通 (素手で作業可能)\",\n  \"outputPerHour\": \"5m / 40分\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"生きているクズのつる、シナノキ・ヤナギ・イラクサの茎 (腕の長さ10〜15本)\",\n      \"desc\": \"曲げた時にポキッと折れずにしなやかに曲がり、爪で表面を削ると緑色の水分が見える新鮮な茎を選びます。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"外皮を削り落とす鋭い石の欠片 1個\",\n      \"desc\": \"茎の外側にある茶色い外皮だけを軽く削り落とすために使います。内側の繊維を切らないよう適度な角がある石を選びます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"繊維を叩く平らな台石と拳大の丸石\",\n      \"desc\": \"水に浸した内皮を平らな石の上に置き、丸石で優しく叩いて髪の毛のように細く柔らかい繊維にほぐします。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"内皮を浸す川の水または溜まり水\",\n      \"desc\": \"剥ぎ取った内皮を20〜30分間浸して硬い樹液を抜き、撚っている間に繊維が折れないよう湿り気を保ちます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ1: しなやかな茎を選び、茶色い外皮を削って白い内皮を剥ぎ取る\",\n      \"description\": \"まず茎を半分に曲げて折れないか確認します。石の角を斜めに当てて外側の茶色い外皮だけを優しく削り落とすと、下から白くて丈夫な内皮繊維が現れます。根元を爪で少しめくり、上に向かって長く引っ張ると、硬い木の芯からリボン状の内皮だけがきれいに剥がれます。\",\n      \"actionNote\": \"> コツ: 地面に落ちて乾いた枯れ枝は繊維が腐っており、引っ張るとすぐ切れます。必ず生きた茎から採取してください。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 石の角で粗い外皮だけを優しく削り落とす\",\n        \"② 折れやすい茶色い外皮 (削って捨てる)\",\n        \"③ 強靭で白い内皮繊維層 (ロープの主材料)\",\n        \"④ 中央の硬い木の芯 (剥がして捨てる)\",\n        \"⑤ 曲げても折れずにしなる生きた茎\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ2: 川の水に20分浸し、丸石で叩いて糸のように柔らかくほぐす\",\n      \"description\": \"剥ぎ取った内皮リボンを川の水に20〜30分間しっかり浸します。柔らかくなった内皮を平らな川石の上に広げ、丸石で上から下へトントンと優しく叩きます。硬い筋がほぐれて髪の毛のように細く柔らかい繊維束になったら、指の太さほどの均等な2束に分けます。\",\n      \"actionNote\": \"> 原理: 強く叩きすぎると繊維が切れます。押し潰しながら滑らせるように叩くのが長い繊維を保つ秘訣です。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 川の水に20分以上浸して柔らかくした内皮\",\n        \"② 丸石で優しく叩いて繊維の筋をほぐす\",\n        \"③ 髪の毛のように柔らかくほぐれた繊維束\",\n        \"④ 指の太さに均等に分けた2本の束\",\n        \"⑤ 下に敷いた安定した平らな川石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ3: 外側にねじって手前に交差させる「逆撚り」を繰り返す\",\n      \"description\": \"長い繊維束の真ん中を左手の親指と人差し指でしっかりつまみ、半分に折って上の束と下の束の2本にします。右手で上の束を持ち、体の外側（前方）へ強くねじります。そのままねじった上の束を下の束の上を越えて自分の体側（手前）へ交差させて渡します。左手の親指をずらして交差点をしっかり押さえ、「外側へねじって➔手前へ渡す」を繰り返します。\",\n      \"actionNote\": \"> 原理: 2本を同じ方向に巻くだけだと手を離した瞬間にほどけます。外へねじりながら手前へ交差させることで戻る力が噛み合い、絶対にほどけません。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上の束：体の外側(↑)へ強くねじる\",\n        \"② 互いに噛み合ったV字のロープ模様\",\n        \"③ 左手の親指と人差し指で交差点を押さえる\",\n        \"④ ねじった上の束を下の束越しに手前(↓)へ渡す\",\n        \"⑤ 手を離してもほどけない二重ロック構造\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ4: 短くなった繊維に新しい束を10cm重ねて無限に継ぎ足す\",\n      \"description\": \"編み進めて片方の束が残り10cmほどになり細くなったら、新しい繊維束の端を古い束の横に10cm重ねて添えます。2本を最初から1本だったかのように一緒に持ち、同じく外側へねじって手前へ渡します。上下の継ぎ目が同じ位置に重ならないよう、最低でも一咫（15cm）以上ずらして配置します。\",\n      \"actionNote\": \"> 注意: 上下の継ぎ目が同じ場所に重なると、そこだけ太くなって引っ張った時に切れやすくなります。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 残り10cmほどになり細くなった元の束\",\n        \"② 新しい繊維束を10cm並べて重ねる\",\n        \"③ 重ねた2本を1本として一緒にねじり込む\",\n        \"④ 膨らまず滑らかに繋がった継ぎ目\",\n        \"⑤ 上下の継ぎ目を15cm以上ずらして配置\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ5: 端から3cmに止め結びを作り、木の幹に掛けて体重で引っ張りテスト\",\n      \"description\": \"必要な長さ（5m以上）まで撚り終えたら、端から3cmの位置を輪にして止め結びを作り、ほどけないように仕上げます。表面にはみ出た毛羽立ちを石の刃で軽く削って整えます。最後に太い木の幹にロープを掛け、自分の体重（50kg以上）をかけて強く引っ張り、継ぎ目が滑らないか確認します。\",\n      \"actionNote\": \"> 実戦確認: 引っ張った時にプツッと音がしたり継ぎ目が滑る場合は、その部分に薄い繊維をもう一周巻き付けて補強します。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 端から3cmを折って結んだほどけ防止結び\",\n        \"② はみ出た毛羽立ちを石の刃できれいに整える\",\n        \"③ 木の幹に掛けて体重(50kg+)で引っ張りテスト\",\n        \"④ 完成した太さ5mmの野生ロープ (長さ5m)\",\n        \"⑤ シェルター結束・石斧固定・火起こし紐に活用\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけないミス：皮を剥いていない緑の生づるをそのまま結んで使う\",\n    \"description\": \"急いでいるからといってクズのつるや枝を丸ごと巻いてシェルターの柱や石斧を結ぶと、最初は固く見えても半日ほどで水分が抜けて縮み、緩んでしまいます。さらに乾燥した木の芯は少しの衝撃で煎餅のように折れます。必ず外皮と芯を除き、白い内皮繊維だけを逆撚りして使ってください。\",\n    \"consequence\": \"結果：就寝中にシェルターの屋根が崩落するか、木を伐採中に石斧の刃が外れて大怪我をする\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"山の中で紐が1本もない時、素手で切れない野生ロープを撚る方法です。\",\n    \"body\": \"生きたクズのつるの茶色い外皮を石で削り、白い内皮だけを長く剥ぎ取ります。水に20分浸して丸石で叩くと糸のように柔らかくなります。半分に折り、上の束を外側にねじって手前に交差させましょう。短くなったら新しい繊維を10cm重ねれば無限に伸ばせます。\",\n    \"outro\": \"木に掛けて体重で引っ張っても切れません。シェルター作りや石斧の固定にすぐ使えます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"2本撚り逆回転編み天然ロープ完成コイル束\",\n    \"description\": \"樹皮の内皮と葛の繊維を時計回りに撚り、反時計回りに交差編みして引張強度90kg以上に耐える、均一で滑らかな2本撚り天然サバイバルロープ束です。\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.pt.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Como trançar corda selvagem inquebrável com casca de árvore e cipó\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[SOBREVIVÊNCIA CRÍTICA]\",\n  \"summary\": \"Uma corda forte é indispensável para amarrar abrigos, fixar machados de pedra e fazer fogo com arco. Cipós verdes inteiros encolhem e quebram ao secar; porém, extrair a fibra branca interna e torcer dois cabos em sentidos opostos cria uma corda autotravante capaz de suportar o peso de um adulto.\",\n  \"timeRequired\": \"40 min\",\n  \"successRate\": \"95% (Com torção reversa)\",\n  \"difficulty\": \"Média (Apenas com as mãos)\",\n  \"outputPerHour\": \"5m / 40 min\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"Cipós vivos, tília, salgueiro ou caules de urtiga (10~15 hastes do comprimento do braço)\",\n      \"desc\": \"Escolha hastes vivas que dobrem sem quebrar e mostrem umidade verde ao raspar com a unha.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 lasca de pedra com borda afiada para raspar\",\n      \"desc\": \"Usada para raspar suavemente a casca externa marrom sem cortar as fibras brancas internas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"Pedra plana de base e pedra redonda do tamanho do punho\",\n      \"desc\": \"Para bater suavemente na casca interna demolhada até soltar fios macios como cabelo.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"Água de riacho ou poça para demolhar\",\n      \"desc\": \"Deixe a casca interna de molho por 20~30 minutos para amolecer a seiva e manter as fibras flexíveis.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Escolher hastes flexíveis, raspar a casca externa e puxar a fibra branca interna\",\n      \"description\": \"Dobre a haste ao meio para confirmar que ela curva sem partir. Raspe levemente a casca marrom externa com a quina de uma pedra até revelar a camada branca e resistente de fibra. Levante a ponta inferior com a unha e puxe para cima para destacar fitas longas do miolo lenhoso.\",\n      \"actionNote\": \"> Dica essencial: Galhos secos caídos no chão têm fibras apodrecidas que arrebentam ao puxar. Use sempre hastes vivas.\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① Raspar casca externa com quina de pedra\",\n        \"② Casca marrom quebradiça (raspar e descartar)\",\n        \"③ Fibra interna branca e forte (material da corda)\",\n        \"④ Miolo central de madeira dura (descartar)\",\n        \"⑤ Haste viva flexível que dobra sem quebrar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Deixar 20 minutos na água e bater com pedra redonda até amaciar\",\n      \"description\": \"Mergulhe as fitas de casca interna na água do riacho por 20~30 minutos. Estenda-as sobre uma pedra plana e bata suavemente de cima para baixo com uma pedra redonda. Quando as fibras se soltarem em fios macios como cabelo, divida-as em dois feixes iguais da espessura de um dedo.\",\n      \"actionNote\": \"> Princípio básico: Bater com muita força corta as fibras. Pressione e amasse suavemente para preservar fios longos.\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① Casca interna de molho 20+ min no riacho\",\n        \"② Bater suave com pedra redonda para abrir fibras\",\n        \"③ Feixe de fibras macias como fios de cabelo\",\n        \"④ Dois cabos iguais da grossura de um dedo\",\n        \"⑤ Pedra plana firme apoiada no chão\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Torcer para fora e cruzar para o corpo (Torção Reversa)\",\n      \"description\": \"Segure o meio do feixe com o polegar e o indicador esquerdos e dobre ao meio formando um cabo superior e outro inferior. Com a mão direita, torça firmemente o cabo superior para fora (longe do corpo) e depois cruze-o por cima do cabo inferior em direção ao seu corpo. Avance o polegar esquerdo para prender o cruzamento e repita sem parar.\",\n      \"actionNote\": \"> Princípio básico: Girar os dois cabos para o mesmo lado faz a corda desenrolar sozinha. A torção oposta trava os cabos entre si.\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① Cabo superior: torcer firme para fora (↑)\",\n        \"② Padrão de corda travado em escama\",\n        \"③ Prender cruzamento com polegar e indicador\",\n        \"④ Cruzar cabo superior sobre o inferior para si (↓)\",\n        \"⑤ Trava reversa que não desmancha ao soltar\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Sobrepor 10cm de fibra nova para emendar comprimento infinito\",\n      \"description\": \"Quando um dos cabos estiver afinando com cerca de 10cm restantes, encoste um feixe novo ao lado da ponta antiga com 10cm de sobreposição. Segure os dois juntos como se fossem um único cabo e continue torcendo para fora e cruzando para dentro. Desencontre as emendas de cima e de baixo em pelo menos um palmo (15cm).\",\n      \"actionNote\": \"> Atenção: Fazer as duas emendas no mesmo ponto cria um caroço fraco que arrebenta sob tensão.\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① Cabo antigo afinando com 10cm restantes\",\n        \"② Encostar fibra nova ao lado (10cm sobrepostos)\",\n        \"③ Torcer as duas pontas juntas como um cabo só\",\n        \"④ Emenda lisa sem caroços ou pontos fracos\",\n        \"⑤ Desencontrar emendas de cima e de baixo em 15cm\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Dar nó de trava na ponta e testar com o peso do corpo em uma árvore\",\n      \"description\": \"Ao atingir o comprimento desejado (5m ou mais), dobre os últimos 3cm e dê um nó simples bem apertado para não desfiar. Raspe os fiapos soltos com uma lasca de pedra. Por fim, passe a corda ao redor de um tronco firme e puxe com todo o peso do corpo (50kg+) para garantir que nenhuma emenda escorregue.\",\n      \"actionNote\": \"> Teste prático: Se ouvir fibras estalando ou notar deslizamento, enrole mais fibra fina sobre o trecho para reforçar.\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① Nó de trava a 3cm da ponta final\",\n        \"② Aparar fiapos soltos com lasca de pedra\",\n        \"③ Passar na árvore e puxar com peso do corpo (50kg+)\",\n        \"④ Corda selvagem pronta de 5mm (5m compr.)\",\n        \"⑤ Pronta para abrigo, machado de pedra e arco\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Amarrar cipós verdes inteiros sem descascar\",\n    \"description\": \"Enrolar cipós ou galhos verdes inteiros diretamente no abrigo ou no machado parece firme na hora, mas em poucas horas a seiva seca, o cipó encolhe e afrouxa, e o miolo de madeira quebra como biscoito seco no primeiro impacto. Sempre descasque e trance apenas a fibra interna.\",\n    \"consequence\": \"Consequência: O teto do abrigo desaba durante o sono ou a lâmina do machado escapa causando ferimentos graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Como fazer uma corda selvagem inquebrável com as mãos quando você não tem nada na mata.\",\n    \"body\": \"Raspe a casca marrom de um cipó vivo e puxe a fibra branca interna. Deixe 20 minutos na água e bata com uma pedra redonda até amaciar. Dobre ao meio, torça o cabo de cima para fora e cruze para o seu lado. Sobreponha 10cm de fibra nova para emendar sem limite.\",\n    \"outro\": \"Aguenta mais de 50kg presa em uma árvore. Pronta para amarrar abrigos e fixar machados de pedra.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"Rolo de Corda Natural de 2 Pernas com Torção Reversa Concluído\",\n    \"description\": \"Uma bobina de corda uniforme de 8 mm trançada com fibras de casca interna em torção reversa, suportando mais de 90 kgf de tração sem deslizar.\"\n  }\n}\n","content/protocols/locales/05-natural-cordage.zh-TW.json":"{\n  \"protocolId\": \"PR-05\",\n  \"category\": \"TOOLS\",\n  \"title\": \"用樹皮與葛藤搓出不斷裂野生繩索的方法\",\n  \"threatLevel\": \"CRITICAL\",\n  \"threatLevelText\": \"[必備求生]\",\n  \"summary\": \"搭建避難所綁木柱、固定石斧或使用弓鑽生火時，堅固的繩索不可或缺。若直接拿整根青藤捆綁，乾掉後會收縮並脆裂；只有刮除粗外皮、取出白色內皮纖維，並將兩股纖維反向扭轉交疊，才能做出放手也不會散開、能承受成人體重的強韌野生繩索。\",\n  \"timeRequired\": \"40分鐘\",\n  \"successRate\": \"95% (遵守反向搓繩法時)\",\n  \"difficulty\": \"中等 (徒手即可完成)\",\n  \"outputPerHour\": \"5公尺 / 40分鐘\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"活的葛藤，或椴樹、柳樹、蕁麻莖幹 (手臂長約10~15根)\",\n      \"desc\": \"選擇對折時不會「啪」一聲斷裂、能柔韌彎曲，且用指甲刮表皮會露出翠綠水氣的新鮮藤蔓或樹枝。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"刮除外皮用的帶稜角石片 1塊\",\n      \"desc\": \"用來輕輕刮掉莖幹最外層粗糙易碎的褐色外皮。挑選邊緣適中、不會割斷內部白色纖維的石片。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"敲打纖維用的平坦墊石與拳頭大的圓石\",\n      \"desc\": \"將泡軟的內皮攤在平坦大石上，用圓石輕輕敲打，使纖維鬆開成如頭髮般細軟的絲束。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"浸泡內皮的溪水或積水\",\n      \"desc\": \"將剛剝下的內皮浸泡20~30分鐘以軟化僵硬樹液，並在搓繩過程中保持纖維濕潤不斷裂。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1步：挑選柔韌藤莖，刮除褐色粗外皮並撕下白色內皮\",\n      \"description\": \"先將藤莖對折，確認其有彈性且不會折斷。拿石片邊緣斜貼著莖幹，輕輕刮除表面粗糙的褐色外皮，底下就會露出雪白強韌的內皮纖維層。用指甲挑起底部邊緣，朝上方長長地拉扯，就能將絲帶般的白色內皮從堅硬的木質中心完整剝離下來。\",\n      \"actionNote\": \"> 核心訣竅：掉在地上乾枯的死枝纖維已經腐朽，一拉就會斷成碎屑，務必從活藤或剛折下的新鮮枝條取皮。\",\n      \"svgFileName\": \"pr05-step-01.svg\",\n      \"svgLabels\": [\n        \"① 用石頭稜角輕輕刮除粗糙外皮\",\n        \"② 易碎的褐色外皮 (刮除丟棄)\",\n        \"③ 強韌雪白的內皮纖維層 (做繩核心材料)\",\n        \"④ 中央堅硬的木質內芯 (剝離丟棄)\",\n        \"⑤ 彎曲時不會折斷的鮮活柔韌藤莖\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2步：泡溪水20分鐘後，用圓石敲打成細軟絲束\",\n      \"description\": \"將剝下的內皮絲帶放入溪水中浸泡20~30分鐘。把吸飽水分變軟的內皮攤在平坦河石上，拿圓石由上往下輕輕敲打。當僵硬的木紋被敲散、變成如頭髮或棉線般細軟的纖維束後，用手搓揉確認沒有硬刺感，再均勻分成兩股手指粗的纖維束。\",\n      \"actionNote\": \"> 核心原理：敲得太用力會砸斷纖維。不要像剁肉一樣猛砍，而是用圓石輕壓推揉，才能保留長而完整的纖維。\",\n      \"svgFileName\": \"pr05-step-02.svg\",\n      \"svgLabels\": [\n        \"① 泡溪水20分鐘以上軟化的內皮\",\n        \"② 用圓石輕輕敲打使纖維紋理鬆開\",\n        \"③ 如頭髮般細軟蓬鬆的纖維絲束\",\n        \"④ 均勻分成手指粗細的兩股纖維\",\n        \"⑤ 底部墊著穩固不搖晃的平坦河石\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3步：向外扭轉、向內交疊，重複「反向搓繩法」\",\n      \"description\": \"用左手拇指與食指捏住長纖維束正中央，對折成上股與下股兩條。右手抓住上股，朝遠離身體的外側（前方）用力扭緊，接著直接將這條扭緊的上股越過下股、朝自己身體方向（後方）交疊翻過來。左手拇指往前移一格捏緊剛交疊的結點，繼續重複「向外扭緊 ➔ 向內翻越」。\",\n      \"actionNote\": \"> 核心原理：若兩股都朝同方向捲，一放手就會全部鬆開。單股向外扭、兩股向內翻，回彈力才會互相咬死永不鬆脫。\",\n      \"svgFileName\": \"pr05-step-03.svg\",\n      \"svgLabels\": [\n        \"① 上股纖維：朝身體外側(↑)用力扭緊\",\n        \"② 互相回彈咬合成鋸齒狀的緊密繩紋\",\n        \"③ 左手拇指與食指捏緊剛交疊的結點\",\n        \"④ 將扭緊的上股越過下股朝身體側(↓)翻過來\",\n        \"⑤ 放手也絕對不會鬆開的反向互鎖結構\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4步：將新纖維重疊10公分捻入，無限延長繩索長度\",\n      \"description\": \"搓繩過程中，當其中一股剩下約10公分並逐漸變細時，取一束新纖維，將前端與變細的舊股並排重疊10公分。把新舊兩條當作同一股握在一起，照常向外扭緊並向內翻越，搓3~4圈後新纖維就會被牢牢咬住。注意上下兩股的接縫位置必須錯開至少一拃（15公分）以上。\",\n      \"actionNote\": \"> 注意事項：若上下兩股在同一個位置接線，該處會腫成一團且受力時極易從接縫處斷裂。\",\n      \"svgFileName\": \"pr05-step-04.svg\",\n      \"svgLabels\": [\n        \"① 剩下約10公分並逐漸變細的舊股\",\n        \"② 取新纖維束並排重疊10公分\",\n        \"③ 將重疊的兩條當作同一股一起扭緊\",\n        \"④ 不鼓包且平滑銜接的接縫部位\",\n        \"⑤ 上下兩股接縫位置錯開一拃(15公分)\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"第5步：末端打防鬆結，掛在樹幹上用全身體重拉扯測試\",\n      \"description\": \"搓到所需長度（5公尺以上）後，在距離末端3公分處繞圈打一個緊實的單結防止散開，並用鋒利石片輕刮修整繩身竄出的毛邊。最後將完成的繩索繞在手臂粗以上的堅固樹幹上，掛上自己的全身體重（50公斤以上）用力拉扯，確認接縫不滑脫且繩結越拉越緊即可投入實戰。\",\n      \"actionNote\": \"> 實戰確認：拉扯時若聽到纖維斷裂聲或發現接縫滑動，請在該區段外再纏繞一層薄纖維加固。\",\n      \"svgFileName\": \"pr05-step-05.svg\",\n      \"svgLabels\": [\n        \"① 距離末端3公分處打緊防鬆收尾結\",\n        \"② 用石片將竄出的毛邊刮除修整乾淨\",\n        \"③ 繞在樹幹上掛上體重(50kg+)用力拉扯測試\",\n        \"④ 完成粗度5mm的強韌野生繩索 (長5m)\",\n        \"⑤ 立即用於綁避難所木柱、固定石斧與弓鑽弦\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絕對不能犯的錯誤：直接拿未剝皮的綠色生藤捆綁重物\",\n    \"description\": \"若為了省事直接拿整根青藤或綠樹枝去綁避難所木柱或石斧，當下看似緊固，但只要過半天水分蒸發，藤條就會萎縮鬆脫，中間的木芯更會在受力時像乾餅乾一樣脆裂。務必去除外皮與木芯，只取白色內皮纖維反向搓成繩索。\",\n    \"consequence\": \"後果：睡覺時避難所屋頂坍塌砸傷自己，或砍樹時石斧刀刃飛出造成嚴重外傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在深山裡連一條繩子都沒有時，如何徒手搓出拉不斷的野生繩索？\",\n    \"body\": \"用石頭刮掉鮮活葛藤的褐色外皮，撕下白色內皮纖維。泡水20分鐘後用圓石敲軟成絲束。對折後將上股向外扭緊，再越過下股朝自己翻過來。變短時重疊10公分新纖維就能無限接長。\",\n    \"outro\": \"掛在樹幹上用50公斤體重拉扯也不斷裂，綁避難所、固定石斧都能馬上派上用場。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr05-outcome.svg\",\n    \"title\": \"雙股反向搓捻天然繩索完成捲束\",\n    \"description\": \"將樹皮內韌皮與葛藤纖維順時針搓捻、逆時針交叉纏繞，具備90公斤以上抗拉強度的勻稱平滑雙股天然生存繩索捲束完成形態。\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.de.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Wie man eine primitive Lehmofenfeuerstelle baut, um Wind abzuhalten und Hitze zu speichern\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LEBENSWICHTIGE WÄRME & UNTERKUNFT]\",\n  \"summary\": \"Ein offenes Bodenfeuer verliert über 80% seiner Wärme an den Wind und verbraucht dreimal mehr Brennholz, während umherfliegende Funken eine schwere Brandgefahr darstellen. Durch den Bau eines Kuppelofens aus Lehm, Sand, trockenem Gras und trockenen Steinen entsteht eine wetterfeste Koch- und Wärmestelle, die Hitze speichert und die ganze Nacht über warm hält.\",\n  \"timeRequired\": \"3 Stunden\",\n  \"successRate\": \"90% (Mit langsamer Vortrocknung)\",\n  \"difficulty\": \"Mittel (Lehmkneten & Steinmauern)\",\n  \"outputPerHour\": \"1 Dauerhafter Ofen\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Schalen klebriger roter Lehm (an Uferböschungen ausgegraben)\",\n      \"desc\": \"Wählen Sie dichten, bindigen Lehm, der sich wie Teig formen lässt, ohne zu zerbröckeln. Dient als thermisches Hauptbindemittel.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Schale grober Flusssand (trockener Sand mit Mineralkörnern)\",\n      \"desc\": \"Reiner Lehm schrumpft und reißt beim Trocknen. Grober Sand bildet das tragende Gerüst, das Rissbildung verhindert.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Schale fingerlang geschnittenes trockenes Gras oder Stroh\",\n      \"desc\": \"Wirkt als Faserarmierung in der Lehmmischung und verhindert, dass die Wände unter großer Hitze zerspringen.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 staubtrockene Bruchsteine (faust- bis kopf傚groß)\",\n      \"desc\": \"Wassergesättigte Flusssteine explodieren bei Hitzeeinwirkung. Verwenden Sie nur trockene Steine von sonnigen Hängen mindestens 10 m vom Wasser entfernt.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: 2 Teile Lehm, 1 Teil Sand und 1 Teil trockenes Gras mit Wasser zu zähem Cob-Mörtel stampfen\",\n      \"description\": \"Geben Sie 2 Schalen roten Lehm, 1 Schale groben Sand und 1 Schale fingerlanges trockenes Gras auf ebenen Boden. Geben Sie schrittweise kleine Mengen Wasser hinzu, während Sie das Gemisch mit den Fersen gründlich durchtreten. Falten Sie den Haufen wiederholt um und stampfen Sie mindestens 10 Minuten, bis sich eine faustgroße Kugel ohne Oberflächenrisse formen lässt.\",\n      \"actionNote\": \"> Wasser-Faustregel: Zu viel Wasser erzeugt schlammigen Brei, der einsackt; zu wenig hinterlässt bröckeligen Staub. Streben Sie eine zähe, teigartige Konsistenz an.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 Teile klebriger roter Lehm\",\n        \"Bindiges mineralisches Grundmaterial\",\n        \"+\",\n        \"② 1 Teil grober Flusssand\",\n        \"Verhindert Schrumpfung und Rissbildung\",\n        \"+\",\n        \"③ Fingerlange trockene Grasfasern\",\n        \"Strukturelle Armierungsmatrix\",\n        \"④ Wasser schrittweise zugeben und mit Fersen stampfen\",\n        \"Niemals überschwemmen; falten & durchtreten\",\n        \"⑤ Fertige zähe Lehmkugel\",\n        \"Zu fester faustgroßer Kugel formbar\",\n        \"Keine Risse an der Außenfläche\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Faustgroße trockene Steine hufeisenförmig auf trockenem Boden als Fundament anordnen\",\n      \"description\": \"Richten Sie die Brennholzöffnung (eine Handspanne breit, ca. 20 cm) windabgewandt aus. Legen Sie faustgroße trockene Steine hufeisenförmig aus. Bringen Sie im Innenbereich 2~3 cm trockenen Sand und Kies ein, um Bodenfeuchtigkeit und Kälte abzusperren. Verfüllen Sie alle Zwischenräume mit zähem Lehm unter festem Faustdruck.\",\n      \"actionNote\": \"> Windrichtung beachten: Wenn die Öffnung im Gegenwind liegt, schlagen Funken ins Gesicht. Richten Sie die Feueröffnung immer windabgewandt oder schräg aus.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Vordere Holzbeschickungsöffnung (20 cm breit)\",\n        \"Optimale Breite für Holz & Luftzufuhr\",\n        \"② Hufeisenförmige trockene Fundamentsteine\",\n        \"Tragendes Primärfundament\",\n        \"③ Dicker Lehmmörtel in Steinfugen\",\n        \"Dichtet Fugen gegen Nebenluft ab\",\n        \"④ Trockene Sand- & Kiesschicht am Boden\",\n        \"Wärmesperre gegen kalten Untergrund\",\n        \"⑤ Windabgewandte Ausrichtung der Öffnung\",\n        \"Schützt die Glut vor Windböen\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Steine und Lehm schichtweise versetzt zu einer kniehohen Kuppel aufmauern\",\n      \"description\": \"Bringen Sie eine handbreite Lehmschicht (ca. 5 cm) auf das Fundament auf, setzen Sie die nächste Steinreihe im Verband auf und neigen Sie die Wand nach innen, bis eine kniehohe Kuppel (ca. 45 cm) entsteht. Glätten Sie anschließend die Innenwand mit nassen Händen zu einer glatten Reflexionsfläche.\",\n      \"actionNote\": \"> Einsturzgefahr vermeiden: Mauern Sie niemals reine Lehmwände ohne Steinkerne hoch. Steine bilden das Skelett, während der Lehm die Wärme speichert.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Querschnitt aus Stein & Lehmmörtel\",\n        \"Verzahnte Steine verhindern Einsturz\",\n        \"② Handtellerdicke (5 cm) wärmedämmende Lehmwand\",\n        \"Hohe Speichermasse hält Wärme über Nacht\",\n        \"③ Glatte wärmereflektierende Innenfläche\",\n        \"Mit nasser Hand für guten Zug geglättet\",\n        \"④ Kreisförmige innere Brennkammer\",\n        \"Hitze zirkuliert und steigt auf\",\n        \"⑤ Kniehohe Gesamthöhe (45 cm)\",\n        \"Optimales Verhältnis aus Volumen & Kochhöhe\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Oberen Topfausschnitt anlegen und hinteren Kaminabzug ausstechen\",\n      \"description\": \"Lassen Sie am Scheitelpunkt der Kuppel eine 15~20 cm runde Öffnung für Tontöpfe oder Steinplatten frei. Drücken Sie drei kleine Abstandssteine in den Rand, damit 1 cm Luftspalt für den Zug bleibt. Durchstoßen Sie die obere Rückwand schräg mit einem Ast, um einen Kaminabzug für den Rauch anzulegen.\",\n      \"actionNote\": \"> Zugluftprinzip: Ohne Kamin drückt der Rauch vorn heraus. Der Kaminabzug erzeugt einen Unterdruck, der Sauerstoff kräftig durch den Fußbereich ansaugt.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Unterer vorderer Lufteinlass (Sauerstoff)\",\n        \"Frischluft strömt ins Glutbett\",\n        \"② Obere flache Kochöffnung\",\n        \"Sitz für Topf oder Bratstein\",\n        \"③ Oberer hinterer schräger Kaminabzug\",\n        \"Zieht beißenden Rauch sauber nach hinten ab\",\n        \"④ Aufsteigender thermischer Wirbelzug\",\n        \"Zirkuliert im Raum und erhitzt Topfboden\",\n        \"⑤ Topfabstandsnoppen für Dauerzug\",\n        \"Feuer erstickt nicht bei aufgesetztem Topf\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: Mit kleinem Zweigfeuer 3 Stunden vortrocknen und steinhart ausbrennen\",\n      \"description\": \"Entfachen Sie niemals sofort ein großes Holzfeuer in feuchtem Lehm; siedendes Porenwasser würde die Wände zersprengen. Halten Sie 3~4 Stunden lang ein winziges Zweigfeuer an der Vorderöffnung. Wenn Dampf austritt und der Lehm von feuchtem Dunkelbraun zu hellem Ocker wechselt und sich warm anfühlt, ist der Ofen einsatzbereit.\",\n      \"actionNote\": \"> Haarrisse ausbessern: Sollten beim Trocknen feine Haarrisse auftreten, streichen Sie diese einfach mit feuchtem Lehmschlicker mit dem Finger glatt.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Sanftes Zweigglutfeuer an der Öffnung\",\n        \"Gleichmäßige Wärme lässt Feuchte entweichen\",\n        \"② Abdampfende Wasserdampfschwaden\",\n        \"Porenwasser verdampft zerstörungsfrei\",\n        \"③ Farbwechsel-Prüfpunkt\",\n        \"Feuchtes Dunkelbraun → trockenes Hellocker\",\n        \"④ Trocken- & Wärmeprüfung von Hand\",\n        \"Wand fühlt sich trocken und warm an\",\n        \"⑤ Ausbesserungsschlicker für Haarrisse\",\n        \"Risse mit frischem Lehm zuschmieren\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Tödlicher Fehler: Verwendung nasser Flusssteine direkt im Brennraumfeuer\",\n    \"description\": \"Wassergesättigte Flusskiesel schließen selbst bei trockener Oberfläche Feuchtigkeit in mikroskopischen Poren ein. Bei Feuertemperaturen über 300°C wandelt sich dieses Wasser schlagartig in Hochdruckdampf um und detoniert wie eine Granate. Rasiermesserscharfe Splitter fliegen in Gesicht und Augen, was zu Erblindung und schweren Fleischwunden führt. Verwenden Sie nur trockene Steine 10 m abseits von Gewässern und ummanteln Sie diese mit mindestens 5 cm Lehm.\",\n    \"consequence\": \"Folge: Dampfexplosionen schleudern messerscharfe Steinsplitter, was zu Erblindung und schweren Verletzungen führt\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Ein Bodenfeuer verliert 80% seiner Wärme. So baut man einen sturmfesten Naturlehmofen.\",\n    \"body\": \"2 Teile Lehm, 1 Teil Sand und 1 Teil trockenes Gras mit Wasser zu zähem Teig stampfen. Trockene Steine hufeisenförmig windabgewandt anordnen. Steine und Lehm versetzt zu einer kniehohen Kuppel mit oberem Topfloch und Kaminabzug aufmauern. 3 Stunden mit kleiner Glut trockenbrennen. Niemals nasse Flusssteine verwenden; Dampfdruck lässt sie detonieren.\",\n    \"outro\": \"Kochen Sie warm und trotzen Sie Regen und stürmischen Winden die ganze Nacht.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Vollendeter Stein- und Lehmofen mit Kochöffnung\",\n    \"description\": \"Ein hufeisenförmiges Steinfundament, verputzt mit 5 cm strohbasiertem feuerfestem Lehm, mit ebener Stein-Kochplatte und hinterem Abzugskamin für 650°C Hitze.\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.en.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"How to Build a Primitive Clay & Stone Hearth to Block Wind and Trap Heat\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[ESSENTIAL SHELTER & WARMTH]\",\n  \"summary\": \"Building an open campfire on the ground loses over 80% of heat to the wind and burns firewood three times faster, while windborne sparks pose a severe fire hazard. By building a cob dome hearth with clay, sand, dry grass, and dry stones, you create a weatherproof cooking and heating shelter that traps heat and stays warm all night long.\",\n  \"timeRequired\": \"3 Hours\",\n  \"successRate\": \"90% (With Slow Pre-Cure)\",\n  \"difficulty\": \"Medium (Mud Mixing & Stone Stacking)\",\n  \"outputPerHour\": \"1 Permanent Hearth\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Bowls of Sticky Red Clay (dug from riverbank or exposed soil banks)\",\n      \"desc\": \"Choose dense, cohesive clay that squishes like dough without crumbling. Acts as the primary thermal binder.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Bowl of Coarse Sand or Gritty Soil (dry river sand)\",\n      \"desc\": \"Pure clay shrinks and cracks apart when drying. Coarse sand acts as a structural aggregate to prevent cracking.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Bowl of Dry Grass or Straw Cut to Finger Length\",\n      \"desc\": \"Acts as organic reinforcement fiber within the mud mixture, preventing the walls from shattering under intense fire heat.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Bone-Dry Fractured Stones (fist to head size)\",\n      \"desc\": \"Waterlogged river stones explode violently under heat. Use only bone-dry stones gathered from sunny ridges at least 10m away from water.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Stomp 2 Parts Clay, 1 Part Sand, and 1 Part Dry Grass with Water into Tough Cob\",\n      \"description\": \"Pour 2 bowls of red clay, 1 bowl of coarse sand, and 1 bowl of finger-length dry grass onto flat ground. Add small splashes of water while thoroughly stomping with bare heels. Fold the clay mound in half and stomp repeatedly for 10 minutes until you can roll a fist-sized ball without surface cracks.\",\n      \"actionNote\": \"> Key Principle: Too much water makes sloppy mud that slumps; too little leaves crumbly dust. Aim for a stiff, dough-like consistency that holds its shape firmly.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 parts sticky red clay\",\n        \"Cohesive binder base material\",\n        \"+\",\n        \"② 1 part coarse river sand\",\n        \"Prevents shrinkage and cracking\",\n        \"+\",\n        \"③ Finger-length dry grass fiber\",\n        \"Reinforcing structural tensile web\",\n        \"④ Add water gradually and stomp with heels\",\n        \"Never flood all at once; fold & stomp\",\n        \"⑤ Finished stiff cob ball\",\n        \"Roll into a solid fist-sized ball\",\n        \"Zero cracks on outer surface\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Lay Fist-Sized Dry Stones in a Horseshoe U-Shape to Anchor the Foundation\",\n      \"description\": \"Orient the fire mouth opening (one hand-span wide, approx. 20 cm) away from the prevailing wind. Place fist-sized dry stones in a horseshoe U-shape. Lay 2~3 cm of dry sand and gravel inside the floor to block ground moisture and cold. Pack thick cob mud between all stone crevices with your fists to anchor them firmly.\",\n      \"actionNote\": \"> Wind Direction: Facing the mouth straight into the wind blows hot embers into your face. Always point the opening downwind or crosswind.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Front firewood intake mouth (20 cm wide)\",\n        \"Optimal width for wood feeding & airflow\",\n        \"② Horseshoe U-shaped dry anchor stones\",\n        \"Primary foundation perimeter\",\n        \"③ Thick cob mortar in stone joints\",\n        \"Prevents drafts and air leaks\",\n        \"④ Dry sand & gravel base insulator\",\n        \"Thermal barrier against cold ground\",\n        \"⑤ Fire mouth facing away from wind\",\n        \"Protects ember bed from wind gusts\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Stagger Stones and Cob Layer by Layer into a Knee-High Dome\",\n      \"description\": \"Spread a palm-thick layer (approx. 5 cm) of cob over the foundation stones, bed down the next row of stones staggered over the joints, and corbel them slightly inward as you build up to knee height (approx. 45 cm). Once the dome is built, dip your hands in water and smooth the inner clay wall into a slick, continuous curved surface to reflect and circulate heat.\",\n      \"actionNote\": \"> Prevent Collapse: Never build pure mud walls high without stone cores. The stones provide the structural skeleton while the thick clay skin traps radiant heat.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Staggered stone & cob cross-section\",\n        \"Interlocking stones prevent structural failure\",\n        \"② Palm-thick (5 cm) thermal cob wall\",\n        \"Heavy thermal mass traps heat overnight\",\n        \"③ Smooth water-burnished heat reflector\",\n        \"Smoothed by wet hand for smooth draft\",\n        \"④ Spherical internal combustion chamber\",\n        \"Heat circulates and concentrates upward\",\n        \"⑤ Knee-high (45 cm) total profile\",\n        \"Optimal balance of volume and cooking height\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Cut a Top Cooking Pot Ring and Punch a Rear Exhaust Flue\",\n      \"description\": \"Leave a 15~20 cm circular opening at the very top of the dome for resting a clay pot or flat cooking stone. Embed three small stone spacers around the rim to create a 1 cm gap so sitting a pot will not choke the fire. Push a wrist-thick green stick angled through the upper back wall to pierce a chimney flue hole for smoke exhaust.\",\n      \"actionNote\": \"> Air Draft Principle: Without a high rear flue, smoke billows out the front wood opening into your eyes. The flue creates a strong thermal chimney effect that draws oxygen vigorously into the base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Lower front air intake (oxygen supply)\",\n        \"Cold fresh air drawn into burning ember bed\",\n        \"② Flat top circular cooking port\",\n        \"Seat for stone pan or clay pot\",\n        \"③ Upper rear angled chimney flue\",\n        \"Draws acrid smoke cleanly out the back\",\n        \"④ Updraft thermal vortex airflow\",\n        \"Vigorous draft heats cooking vessel base\",\n        \"⑤ Pot spacer nubs for continuous draft\",\n        \"Air passes freely even with pot seated\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Cure with a Low Twig Fire for 3 Hours to Bake the Clay into Brick Hardness\",\n      \"description\": \"Never light a raging log fire immediately in fresh wet cob; sudden boiling moisture will blow steam fissures through the walls. Build a tiny fist-sized twig fire near the front mouth and keep it gentle for 3~4 hours. Watch white steam vapor evaporate from the outer walls as the dark wet brown clay shifts to a warm light ochre. Once dry and warm to the touch, your permanent hearth is ready.\",\n      \"actionNote\": \"> Repairing Hairline Cracks: If minor hairline cracks appear while drying, smear a fingertip of wet clay paste over them to seal and fuse them instantly.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Gentle twig ember fire at mouth\",\n        \"Gentle heat allows gradual moisture exit\",\n        \"② Steam vapor plumes venting outward\",\n        \"Internal water evaporates safely\",\n        \"③ Color transition milestone\",\n        \"Dark damp brown → dry pale ochre\",\n        \"④ Warm & dry touch test\",\n        \"Wall feels warm without sticky dampness\",\n        \"⑤ Touch-up paste for hairline cracks\",\n        \"Seal minor fissures with wet clay paste\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Using Wet River Stones Directly Exposed to Fire Inside the Chamber\",\n    \"description\": \"Waterlogged river stones and creek pebbles have moisture trapped inside microscopic pores even if the surface feels dry. When exposed to fires over 300°C, trapped water violently flashes into high-pressure steam and detonates like a grenade. Razor-sharp shrapnel flies outward into your face and eyes, causing blindness and catastrophic lacerations. Always gather dry stones from sunny ridges 10m away from water, and coat them under at least 5 cm of thick cob mud.\",\n    \"consequence\": \"Consequence: Steam explosion shrapnel causes permanent blindness and severe trauma\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"An open ground fire loses 80% of its heat. Here is how to build a weatherproof primitive hearth.\",\n    \"body\": \"Mix 2 parts sticky clay, 1 part sand, and 1 part dry grass with water and stomp into dough. Lay dry stones in a U-shape facing away from the wind. Stagger stones and thick mud into a knee-high dome with a pot hole on top and a chimney flue out back. Cure with a tiny fire for 3 hours to bake it rock-solid. Never use wet river stones inside; steam pressure will cause them to detonate.\",\n    \"outro\": \"Cook your meals and stay warm all night through rain and howling winds.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Completed Stone & Tempered Clay Cooking Hearth\",\n    \"description\": \"A horseshoe stone base sealed under 5cm of straw-tempered refractory clay plaster, featuring a level stone cooktop and rear chimney flue holding intense 650°C heat.\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.es.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Cómo Construir un Fogón Primitivo de Barro y Piedras para Protegerse del Viento y Retener Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR Y REFUGIO ESENCIAL]\",\n  \"summary\": \"Hacer una fogata abierta directamente en el suelo pierde más del 80% del calor con el viento y consume tres veces más leña, mientras que las chispas voladoras representan un grave riesgo de incendio. Al levantar un fogón en cúpula con barro, arena, hierba seca y piedras secas, se crea un refugio térmico resistente al mal tiempo que permite cocinar y conservar calor durante toda la noche.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Con Curado Lento)\",\n  \"difficulty\": \"Media (Amasado de Barro y Apilado)\",\n  \"outputPerHour\": \"1 Fogón Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Cuencos de Arcilla Roja Pegajosa (excavada en riberas o taludes)\",\n      \"desc\": \"Elija tierra densa que se amase como masa de pan sin desmoronarse. Actúa como el aglutinante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Cuenco de Arena Gruesa de Río (arena seca con granos minerales)\",\n      \"desc\": \"La arcilla pura se encoge y se agrieta al secar. La arena gruesa proporciona el esqueleto estructural que evita grietas.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Cuenco de Hierba Seca o Paja Cortada a la Medida de un Dedo\",\n      \"desc\": \"Funciona como fibra de refuerzo dentro de la mezcla, impidiendo que las paredes colapsen bajo el calor del fuego.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Piedras Quebradas Completamente Secas (tamaño puño a cabeza)\",\n      \"desc\": \"Las piedras de río anegadas explotan con el calor. Utilice únicamente piedras secas recolectadas de lomas soleadas a más de 10 m del agua.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Pisar 2 partes de arcilla, 1 de arena y 1 de hierba seca con agua hasta formar barro maleable\",\n      \"description\": \"Vierta sobre tierra plana 2 cuencos de arcilla roja, 1 de arena gruesa y 1 de hierba seca cortada. Agregue pequeñas cantidades de agua mientras pisotea con los talones. Doble la masa por la mitad y pise durante más de 10 minutos hasta poder formar una bola del tamaño de un puño sin fisuras superficiales.\",\n      \"actionNote\": \"> Clave del Agua: Demasiada agua hace lodo aguado que se cae; muy poca deja polvo quebradizo. Busque una consistencia firme similar a masa de empanadas.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de arcilla roja pegajosa\",\n        \"Materia prima aglutinante base\",\n        \"+\",\n        \"② 1 parte de arena gruesa de río\",\n        \"Evita contracción y agrietamiento\",\n        \"+\",\n        \"③ Fibra de hierba seca cortada\",\n        \"Malla estructural de refuerzo interno\",\n        \"④ Agregar agua poco a poco y pisar con talones\",\n        \"Nunca inundar de golpe; doblar y pisar\",\n        \"⑤ Bola de barro firme terminada\",\n        \"Moldear en bola sólida tamaño puño\",\n        \"Superficie exterior sin fisuras\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Disponer piedras secas en herradura (forma de U) sobre suelo seco para la base\",\n      \"description\": \"Oriente la boca de alimentación de leña (ancho de una mano, aprox. 20 cm) en dirección opuesta al viento. Coloque piedras secas en forma de U. Extienda en el fondo interior 2~3 cm de arena y grava seca para bloquear la humedad del suelo. Rellene todas las juntas entre piedras con barro firme usando los puños para anclarlas.\",\n      \"actionNote\": \"> Dirección del Viento: Colocar la boca de frente al viento provocará llamaradas y chispas hacia su rostro. Apunte siempre en dirección contraria o perpendicular.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para leña (20 cm de ancho)\",\n        \"Ancho óptimo para leña y entrada de aire\",\n        \"② Piedras secas de anclaje en forma de U\",\n        \"Perímetro estructural de la base\",\n        \"③ Mortero de barro grueso en juntas\",\n        \"Sella fugas de aire entre piedras\",\n        \"④ Aislante de arena y grava en el fondo\",\n        \"Barrera térmica contra el suelo frío\",\n        \"⑤ Boca orientada en contra del viento\",\n        \"Protege las brasas de ráfagas violentas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Apilar piedras y barro de forma alternada hasta formar una cúpula a la altura de la rodilla\",\n      \"description\": \"Extienda una capa de barro del grosor de una palma (aprox. 5 cm) sobre las piedras base, asiente la siguiente hilera trabando las uniones y vaya inclinándolas hacia adentro hasta alcanzar la altura de la rodilla (aprox. 45 cm). Al terminar, humedezca sus manos en agua y alise la pared interior para crear una curva reflectora continua.\",\n      \"actionNote\": \"> Evitar Colapso: Nunca levante paredes altas solo con barro sin núcleo de piedra. Las piedras brindan el esqueleto y el barro retiene la radiación térmica.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de piedras y barro\",\n        \"Piedras trabadas evitan fallas estructurales\",\n        \"② Pared gruesa de barro (5 cm) aislante\",\n        \"Masa térmica retiene calor toda la noche\",\n        \"③ Superficie lisa reflectora de calor\",\n        \"Alisada con mano húmeda para buen tiro\",\n        \"④ Cámara de combustión esférica interior\",\n        \"El calor circula y se concentra arriba\",\n        \"⑤ Perfil total a la rodilla (45 cm)\",\n        \"Equilibrio ideal de volumen y cocción\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Abrir un orificio superior para ollas y perforar una chimenea trasera\",\n      \"description\": \"Deje una abertura circular de 15~20 cm en la cúspide para asentar ollas de barro o piedras planas de cocción. Incruste tres piedras pequeñas alrededor del borde para dejar 1 cm de separación que permita el paso del aire. En la parte superior trasera, introduzca una rama gruesa en diagonal para abrir el conducto de la chimenea.\",\n      \"actionNote\": \"> Principio de Tiro: Sin chimenea trasera, el humo sale por el frente cegando los ojos. El conducto genera un efecto térmico que atrae oxígeno fresco por la base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de aire (oxígeno fresco)\",\n        \"Aire fresco succionado hacia las brasas\",\n        \"② Orificio superior plano para cocinar\",\n        \"Asiento para olla o plancha de piedra\",\n        \"③ Salida trasera inclinada de chimenea\",\n        \"Expulsa el humo denso hacia atrás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Gira en la cámara calentando la base\",\n        \"⑤ Salientes espaciadoras para el tiro\",\n        \"El fuego no se ahoga al colocar la olla\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Curar con fuego suave de ramitas durante 3 horas para endurecer el barro como ladrillo\",\n      \"description\": \"Nunca encienda un fuego fuerte inmediato en barro fresco; la ebullición repentina del agua interna reventará las paredes. Encienda una pequeña fogata de ramitas cerca de la boca y manténgala suave durante 3~4 horas. Observe cómo sale vapor blanco mientras el barro cambia de marrón oscuro húmedo a ocre pálido seco. Cuando esté caliente y seco al tacto, el fogón permanente estará listo.\",\n      \"actionNote\": \"> Reparar Fisuras: Si aparecen grietas finas durante el secado, frote pasta de barro húmeda con la yema de los dedos para sellarlas de inmediato.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fuego suave de ramitas en la entrada\",\n        \"Calor moderado permite salida de vapor\",\n        \"② Penachos de vapor de agua evaporándose\",\n        \"El agua interna se evapora sin reventar\",\n        \"③ Transición visual de color\",\n        \"Marrón oscuro húmedo → ocre pálido seco\",\n        \"④ Prueba de tacto seco y caliente\",\n        \"Pared tibia sin humedad pegajosa\",\n        \"⑤ Pasta de retoque para fisuras finas\",\n        \"Sellar grietas con pasta de barro fresca\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Usar Piedras Húmedas de Río en Contacto Directo con el Fuego en la Cámara\",\n    \"description\": \"Las piedras de río anegadas retienen agua atrapada en microporos internos aunque su superficie parezca seca. Al someterse a fuegos de más de 300°C, el agua atrapada se convierte instantáneamente en vapor a alta presión y estalla como una granada. Esquirlas afiladas salen disparadas hacia el rostro y los ojos, provocando ceguera permanente y graves traumatismos. Use siempre piedras de lomas secas a 10 m del agua y cúbralas con 5 cm de barro grueso.\",\n    \"consequence\": \"Consecuencia: La explosión por vapor arroja metralla de piedra provocando ceguera y heridas graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Un fuego abierto en el suelo pierde el 80% de su calor. Así se construye un fogón primitivo resistente a la lluvia.\",\n    \"body\": \"Pise 2 partes de arcilla, 1 de arena y 1 de hierba seca con agua hasta lograr una masa firme. Forme una herradura de piedras secas con la boca en contra del viento. Levante una cúpula trabando piedras y barro con un orificio superior y una chimenea trasera. Cure 3 horas con fuego suave para dejarlo duro como ladrillo. Jamás use piedras húmedas de río adentro; estallarán por presión de vapor.\",\n    \"outro\": \"Cocine alimentos y mantenga calor agradable durante toda la noche bajo tormentas.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogón Primitivo de Piedra y Arcilla Revestida Completado\",\n    \"description\": \"Una base de piedra en herradura sellada con 5 cm de arcilla refractaria templada con paja, con una superficie de cocción nivelada y chimenea trasera a 650°C.\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.ja.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"粘土と石を積み上げて風雨を防ぎ熱を閉じ込める原始かまどの作り方\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[体温・食料必須]\",\n  \"summary\": \"野外で地面に直接火を起こすと、熱の80%が風で散り薪が3倍以上消費される上、火の粉が舞い上がり危険です。赤粘土、砂、枯草を練り合わせた泥ペーストで石を包み込みドーム状のかまどを築くことで、風雨の中でも消えず、煮炊きを行い朝まで熱を蓄え続ける堅牢な生存熱源になります。\",\n  \"timeRequired\": \"3時間\",\n  \"successRate\": \"90% (弱火乾燥を厳守した場合)\",\n  \"difficulty\": \"普通 (泥こねと石積み作業)\",\n  \"outputPerHour\": \"1基完成 (永久使用可能)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"粘性のある赤粘土 2杯 (川岸や露出した土手から採取した粘り土)\",\n      \"desc\": \"手で握ったときに餅のようにまとまり指に吸い付く土を選びます。かまどの壁を強固に固める主原料です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗い川砂 1杯 (粒状の砂利が混ざった乾いた砂)\",\n      \"desc\": \"粘土だけでは乾燥時に収縮して割れてしまいます。粗い砂を混ぜることで骨材となりひび割れを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"指の長さに切った枯草またはワラ 1杯\",\n      \"desc\": \"泥の中で繊維質の鉄筋の役割を果たし、炎の高熱を受けても壁体が割れたり崩れたりするのを防ぎます。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"水気のない硬い割り石 15〜20個 (拳〜頭大の乾いた石)\",\n      \"desc\": \"水に浸かっていた川石は加熱時に水蒸気爆発を起こすため、水辺から10m以上離れた日当たりの良い尾根の完全に乾いた石のみを選びます。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"ステップ 1: 粘土2、砂1、枯草1に水を少しずつ加え足で踏み込んで粘り強い泥生地を作る\",\n      \"description\": \"平らな地面に赤粘土2杯、粗砂1杯、指大に切った枯草1杯を広げます。水を一度に入れすぎず少しずつかけながら、かかとでしっかり踏み込んで練り合わせます。泥を二つ折りにしながら10分以上踏み続け、拳大の団子に丸めても表面にひびが入らない状態までしっかり練り上げます。\",\n      \"actionNote\": \"> 水加減の極意: 水が多すぎると泥が崩れて壁にならず、少なすぎるとパサついて割れます。餃子の皮のように少し硬めで粘りのある状態が最適です。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 粘性のある赤粘土 2杯\",\n        \"粘着力を持つ基本母材\",\n        \"+\",\n        \"② 粗い川砂 1杯\",\n        \"乾燥時の収縮・ひび割れ防止\",\n        \"+\",\n        \"③ 細かく切った枯草の繊維\",\n        \"骨組みとなる補強繊維層\",\n        \"④ 水を少しずつ加え足で踏み込む\",\n        \"一気に水を注がず折り返しながら踏む\",\n        \"⑤ 粘りのある泥団子の完成\",\n        \"拳大に丸めても崩れない\",\n        \"表面に細かな亀裂がない状態\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"ステップ 2: 乾いた地面に拳大の石をU字型に並べて基礎を築く\",\n      \"description\": \"風下に向けて薪の投入口(手のひら幅、約20cm)を空け、拳より少し大きめの乾いた石を馬蹄形(U字型)に並べます。内側の床には乾いた砂や砂利を2〜3cm敷き、地面からの湿気と冷気を遮断します。石と石の隙間にステップ1で作った泥を拳で強く押し込み、隙間なく埋めて地面と密着させます。\",\n      \"actionNote\": \"> 風向きの注意: 投入口が風上を向いていると突風で火の粉が逆流し危険です。必ず風下または風を斜めに受ける向きに口を設けてください。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方の薪投入口 (幅約20cm)\",\n        \"薪の補給と給気に最適な間口\",\n        \"② U字型に並べた拳大の乾いた石\",\n        \"基礎を支える一次骨組み\",\n        \"③ 隙間を埋めた厚手の泥ペースト\",\n        \"石の隙間からの空気漏れを完全遮断\",\n        \"④ 底面の乾いた砂・砂利断熱層\",\n        \"冷たい地表の湿気と冷気を遮断\",\n        \"⑤ 風下を向けた開口部の配置\",\n        \"突風による火の粉逆流と失火を防止\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"ステップ 3: 石と泥を交互に積み上げ膝丈のドーム壁を立ち上げる\",\n      \"description\": \"基礎石の上に手のひら厚(約5cm)の泥を敷き、その上に石を互い違いに載せながら、徐々に内側へすぼめて膝の高さ(約45cm)までドーム型に築きます。壁を積み終えたら、手に水をつけて内壁を滑らかに塗り固めます。内壁が滑らかなほど、燃焼室の中で熱気が対流し高温を保てます。\",\n      \"actionNote\": \"> 崩落防止: 泥だけで高く築くと自重で潰れます。必ず石を芯材にし、その外側と内側を厚い泥でしっかり包み込むように施工してください。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 互い違いに積んだ壁体断面\",\n        \"石の間に泥を詰め崩壊を防止\",\n        \"② 手のひら厚(約5cm)の泥断熱壁\",\n        \"外側への熱逃げを完全に防ぐ\",\n        \"③ 滑らかな熱反射曲面\",\n        \"水の手で平滑に撫で上げた内壁\",\n        \"④ 熱が対流する円形燃焼室内部\",\n        \"⑤ 膝丈(約45cm)の外形ライン\",\n        \"調理安定性と蓄熱容積の最適化\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"ステップ 4: 天面に鍋置き用の穴を残し後方に煙突穴を開ける\",\n      \"description\": \"ドームの頂上中央に鍋や平らな石板を載せるための円形の穴(直径15〜20cm)を残します。鍋を置いた際に火が消えないよう、穴の周囲に小石3個を三角形に埋め込んで1cmの通気隙間を確保します。そして後方上部には手首太さの小枝を斜めに突き刺して煙を逃がす煙突穴を開け、強力な上昇気流を作ります。\",\n      \"actionNote\": \"> 通気の原理: 煙突がないと煙が前の投入口から噴き出して目が痛くなります。後方の煙突を前口より高い位置に設けることで煙がきれいに抜けます。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前方下部の吸気口 (酸素供給)\",\n        \"冷たく新鮮な空気が引き込まれる通路\",\n        \"② 上部の平坦な調理用開口部\",\n        \"鍋や平石を安定して据える火口\",\n        \"③ 後方上部の煙突排気穴\",\n        \"煙を背後へ効率よく吸い出す排気口\",\n        \"④ 立ち昇る熱対流ライン\",\n        \"燃焼室内を旋回し鍋底を加熱\",\n        \"⑤ 鍋受け通気スペーサー突起\",\n        \"鍋を置いても炎が塞がれず消えない構造\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"ステップ 5: 小枝の弱火で3時間じっくり乾かしレンガのように焼き固める\",\n      \"description\": \"完成したかまどに最初から大木を入れて強火で燃やすと、土中の水分が一気に沸騰して壁が破裂します。枯れ葉や小枝で拳大の小さな火種を作り、投入口近くで弱火を3〜4時間維持します。外壁から白い水蒸気が立ち上り、濡れた濃い茶色から乾いた明るい黄土色へ変化したら完成です。\",\n      \"actionNote\": \"> 乾燥中の補修: 乾燥中に外壁へ髪の毛ほどの細いひび割れが出た場合は、残った緩い泥ペーストを指先で塗り込むだけで綺麗に塞がります。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 投入口の小枝の弱火 (穏やかな熱)\",\n        \"急熱を避け熱をゆっくり加える\",\n        \"② 外壁からの水蒸気蒸発線\",\n        \"内部水分が静かに気化して脱出\",\n        \"③ 色調変化の観察\",\n        \"濡れた濃褐色 → 乾いた明るい黄土色\",\n        \"④ 触手による乾燥完了確認\",\n        \"湿り気なく外壁全体に温かみが伝わる\",\n        \"⑤ 微細亀裂の泥ペースト補修\",\n        \"残った泥で表面の微小隙間を密閉\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"絶対にやってはいけない失敗: 水に濡れた川石を火が直接触れる燃焼室に積む\",\n    \"description\": \"川辺で拾ったばかりの濡れた川石や小石は、表面が乾いて見えても内部の微細な空隙に水が閉じ込められています。300℃を超える火炎にさらされると、内部の水が急激に高圧水蒸気となり手榴弾のように爆発します。鋭利な破片が顔や目に飛散し失明や重傷を負う危険があります。必ず水辺から10m以上離れた乾いた尾根の石を選び、石の表面を5cm以上の厚い泥で覆って直火を避けてください。\",\n    \"consequence\": \"結果: 石の水蒸気爆発により鋭利な破片が飛散し失明および重度の裂傷を負う\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"野外で地面に直接火を起こすと熱の80%が逃げます。風雨でも消えない原始かまどの作り方です。\",\n    \"body\": \"粘土2、砂1、枯草1に水を加えて10分踏み込み、硬い泥生地を作ります。乾いた石をU字に並べて風下に投入口を設置。石と泥を交互に膝丈までドーム状に積み、天面に鍋穴、後ろに煙突を開けます。小枝の弱火で3時間じっくり乾かせばレンガのように固まります。濡れた川石は絶対に使わないでください。水蒸気で爆発します。\",\n    \"outro\": \"風雨の中でも煮炊きができ、朝まで暖かい熱をキープできます。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"粘土左官石かまど（原始かまど及び調理口）完成形態\",\n    \"description\": \"U字型の川石基礎の上に藁と黄土の練り土を厚さ5cmで滑らかに左官し、上部調理用耐熱天板と後部排気煙突を備えて650°Cの高熱を閉じ込める原始かまどです。\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.pt.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"Como Construir um Fogão Primitivo de Barro e Pedras para Bloquear o Vento e Reter Calor\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[CALOR E ABRIGO ESSENCIAIS]\",\n  \"summary\": \"Fazer uma fogueira aberta no chão perde mais de 80% do calor com o vento e consome três vezes mais lenha, enquanto fagulhas representam risco crítico de incêndio. Construindo um fogão em cúpula com barro, areia, capim seco e pedras secas, você cria um ponto de cozimento à prova de tempestades que retém calor a noite toda.\",\n  \"timeRequired\": \"3 Horas\",\n  \"successRate\": \"90% (Com Cura Lenta)\",\n  \"difficulty\": \"Média (Amassar Barro e Assentar Pedras)\",\n  \"outputPerHour\": \"1 Fogão Permanente\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"2 Tigelas de Argila Vermelha Pegajosa (escavada em margens ou barrancos)\",\n      \"desc\": \"Escolha terra densa que amasse como massa de pão sem esfarelar. Atua como o ligante térmico principal.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"1 Tigela de Areia Grossa de Rio (areia seca com grãos minerais)\",\n      \"desc\": \"A argila pura encolhe e racha ao secar. A areia grossa fornece a estrutura que impede rachaduras.\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"1 Tigela de Capim Seco ou Palha Cortada no Tamanho de um Dedo\",\n      \"desc\": \"Funciona como fibra de reforço dentro da mistura, impedindo que as paredes rachem sob o calor intenso.\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"15~20 Pedras Quebradas Totalmente Secas (tamanho punho a cabeça)\",\n      \"desc\": \"Pedras de rio encharcadas explodem violentamente com o calor. Use apenas pedras secas coletadas em encostas ensolaradas a mais de 10 m da água.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Pisotear 2 partes de argila, 1 de areia e 1 de capim seco com água até formar massa firme\",\n      \"description\": \"Despeje no chão plano 2 tigelas de argila vermelha, 1 de areia grossa e 1 de capim seco cortado. Adicione água aos poucos enquanto pisoteia com os calcanhares. Dobre a massa ao meio e pise por mais de 10 minutos até conseguir enrolar uma bola do tamanho de um punho sem rachaduras superficiais.\",\n      \"actionNote\": \"> Ponto da Água: Água demais vira lama que escorre; pouca água vira pó quebradiço. Busque uma consistência firme parecida com massa de pão.\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 2 partes de argila vermelha pegajosa\",\n        \"Matéria-prima aglomerante de base\",\n        \"+\",\n        \"② 1 parte de areia grossa de rio\",\n        \"Evita retração e rachaduras\",\n        \"+\",\n        \"③ Fibra de capim seco picado\",\n        \"Malha estrutural de reforço interno\",\n        \"④ Adicionar água aos poucos e pisar\",\n        \"Nunca inundar de vez; dobrar e pisar\",\n        \"⑤ Bola de barro firme finalizada\",\n        \"Moldar bola sólida tamanho punho\",\n        \"Superfície externa sem trincas\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Dispor pedras secas em ferradura (formato de U) sobre chão seco como base\",\n      \"description\": \"Posicione a boca para lenha (largura de um palmo, aprox. 20 cm) contra a direção do vento. Coloque pedras secas em formato de U. Espalhe 2~3 cm de areia e cascalho seco no chão interno para barrar umidade e frio. Preencha todas as frestas com barro firme usando os punhos para travá-las.\",\n      \"actionNote\": \"> Sentido do Vento: A boca virada de frente para o vento lança fagulhas no rosto. Aponte sempre na direção contrária ao vento ou na diagonal.\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① Boca frontal para lenha (20 cm de largura)\",\n        \"Largura ideal para lenha e entrada de ar\",\n        \"② Pedras secas de fundação em formato U\",\n        \"Perímetro estrutural da base\",\n        \"③ Argamassa grossa de barro nas juntas\",\n        \"Veda vazamentos de ar entre pedras\",\n        \"④ Camada de areia e cascalho no fundo\",\n        \"Barreira térmica contra chão frio\",\n        \"⑤ Abertura virada contra o vento\",\n        \"Protege as brasas contra rajadas fortes\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Empilhar pedras e barro alternadamente formando uma cúpula até a altura do joelho\",\n      \"description\": \"Espalhe uma camada de barro da espessura de uma palma (aprox. 5 cm) sobre as pedras da base, assente a próxima fileira travando as juntas e vá inclinando para dentro até a altura do joelho (aprox. 45 cm). Depois de erguer, molhe as mãos na água e alise a parede interna criando uma curva contínua que reflete o calor.\",\n      \"actionNote\": \"> Evitar Quedas: Nunca levante paredes altas só de barro sem pedra. As pedras são o esqueleto e o barro espesso retém a radiação térmica.\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① Corte transversal de pedras e barro\",\n        \"Pedras travadas evitam colapso estrutural\",\n        \"② Parede grossa de barro (5 cm) isolante\",\n        \"Massa térmica retém calor a noite toda\",\n        \"③ Superfície lisa refletora de calor\",\n        \"Alisada com mão úmida para bom fluxo\",\n        \"④ Câmara esférica interna de combustão\",\n        \"O calor circula e se concentra no topo\",\n        \"⑤ Perfil total até o joelho (45 cm)\",\n        \"Equilíbrio ideal de volume e altura de cocção\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Abrir bocal superior para panela e perfurar chaminé traseira\",\n      \"description\": \"Deixe uma abertura redonda de 15~20 cm no topo da cúpula para apoiar panelas ou pedras planas. Crave três pedrinhas na borda para criar uma fresta de 1 cm para o ar passar. Na parte superior traseira, fure com um galho grosso na diagonal abrindo o duto da chaminé para exaustão.\",\n      \"actionNote\": \"> Princípio da Tiragem: Sem chaminé, a fumaça sai pela frente ardendo os olhos. O duto traseiro cria um vácuo térmico que puxa oxigênio fresco pela base.\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① Entrada inferior de ar (oxigênio)\",\n        \"Ar fresco puxado para a brasa\",\n        \"② Bocal plano superior de cozimento\",\n        \"Apoio para panela ou chapa de pedra\",\n        \"③ Chaminé traseira inclinada\",\n        \"Expele fumaça densa para trás\",\n        \"④ Vórtice térmico ascendente de calor\",\n        \"Circula na câmara aquecendo a panela\",\n        \"⑤ Ressaltos espaçadores para tiragem\",\n        \"O fogo não apaga com a panela apoiada\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Curar com fogo brando de gravetos por 3 horas para endurecer o barro como tijolo\",\n      \"description\": \"Nunca acenda fogo forte imediato em barro úmido; a água fervendo dentro dos poros explodirá as paredes. Acenda uma fogueirinha de gravetos perto da entrada e mantenha brando por 3~4 horas. Observe a fumaça branca de vapor saindo e a cor mudando de marrom escuro úmido para ocre claro seco. Quando estiver quente e seco ao toque, o fogão estará pronto.\",\n      \"actionNote\": \"> Reparar Trincas: Se surgirem pequenas rachaduras finas durante a secagem, passe pasta de barro fresca com a ponta dos dedos para vedá-las na hora.\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① Fogo brando de gravetos na entrada\",\n        \"Calor suave permite saída gradual de vapor\",\n        \"② Plumas de vapor d'água evaporando\",\n        \"Água interna evapora sem estourar\",\n        \"③ Mudança visual de coloração\",\n        \"Marrom escuro úmido → ocre claro seco\",\n        \"④ Teste de toque seco e quente\",\n        \"Parede morna sem umidade pegajosa\",\n        \"⑤ Pasta de barro para vedar trincas\",\n        \"Selar frestas com pasta fresca de barro\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Usar Pedras Úmidas de Rio em Contato Direto com o Fogo na Câmara\",\n    \"description\": \"Pedras de rio e seixos encharcados retêm água presa em microporos mesmo com a superfície seca. Ao receber fogo acima de 300°C, a água vira vapor de alta pressão instantaneamente e detona como uma granada. Estilhaços pontiagudos voam nos olhos e rosto, causando cegueira permanente e lacerações graves. Use apenas pedras de encostas secas a 10 m da água e cubra-as com 5 cm de barro grosso.\",\n    \"consequence\": \"Consequência: A explosão por vapor lança estilhaços afiados causando cegueira e ferimentos graves\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Fogueira no chão perde 80% do calor. Veja como construir um fogão primitivo resistente a temporais.\",\n    \"body\": \"Pise 2 partes de argila, 1 de areia e 1 de capim seco com água até virar massa firme. Monte pedras secas em U viradas contra o vento. Levante a cúpula alternando pedras e barro com bocal superior e chaminé traseira. Cure por 3 horas com fogo brando até endurecer como tijolo. Nunca use pedras úmidas de rio dentro; a pressão de vapor faz elas detonarem.\",\n    \"outro\": \"Cozinhe suas refeições e mantenha calor seguro a noite toda sob tempestades.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"Fogão Primitivo de Pedra e Argila Revestida Concluído\",\n    \"description\": \"Uma base de pedra em U selada com 5 cm de argila refratária temperada com palha, com tampa nivelada para cozimento e chaminé traseira que atinge 650°C.\"\n  }\n}\n","content/protocols/locales/06-clay-hearth.zh-TW.json":"{\n  \"protocolId\": \"PR-06\",\n  \"category\": \"SHELTER\",\n  \"title\": \"如何用泥土與石塊堆砌防風避雨且鎖住溫度的原始爐灶\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[保溫與食糧必備]\",\n  \"summary\": \"在野外直接於地面生火，八成以上的熱量會隨風散失，木柴消耗量暴增三倍，且飛散的火星極易引發火災。利用紅黏土、河砂、乾草揉合的泥漿包覆乾燥石塊築成圓頂泥灶，即使狂風暴雨也不會熄滅，能烹煮食物並整夜保持溫熱，是極佳的野外生存熱源。\",\n  \"timeRequired\": \"3小時\",\n  \"successRate\": \"90% (嚴格遵循微火烘烤時)\",\n  \"difficulty\": \"普通 (踩泥揉漿與疊石作業)\",\n  \"outputPerHour\": \"完成1座 (可永久重複使用)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"具黏性的紅黏土 2碗 (河岸邊或裸露土壁挖取的黏土)\",\n      \"desc\": \"挑選捏在手中如麵糰般緊密且具黏性的泥土。這是將整個灶體緊密黏合固化的核心原料。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"粗河砂 1碗 (混有細小石粒的乾燥砂土)\",\n      \"desc\": \"純黏土乾燥時會嚴重收縮碎裂。混入粗砂能提供堅固骨架，有效防止泥壁開裂。\"\n    },\n    {\n      \"id\": \"mat-03\",\n      \"name\": \"剪成手指長度的乾草或稻草 1碗\",\n      \"desc\": \"在泥漿中扮演如鋼筋般的拉力纖維，使爐壁即便承受高溫大火也不會裂開坍塌。\"\n    },\n    {\n      \"id\": \"mat-04\",\n      \"name\": \"完全乾燥的堅硬碎石 15~20顆 (拳頭至頭顱大小)\",\n      \"desc\": \"泡過水的河石受熱極易引發高壓水蒸氣爆炸。務必使用離水邊10公尺以上陽光曬乾的山丘乾石。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"步驟 1: 將黏土2份、粗砂1份、乾草1份加水踩踏揉成韌性泥糰\",\n      \"description\": \"在平坦地面上倒出紅黏土2碗、粗砂1碗、剪短的乾草1碗。不要一次倒入過多水，分次少量潑灑，同時用腳後跟用力踩踏揉合。將泥堆對折後反覆踩踏10分鐘以上，直到能揉出拳頭大小且表面沒有裂痕的緊實泥糰為止。\",\n      \"actionNote\": \"> 水量拿捏秘訣: 水分過多會變成稀泥流淌無法築壁；水分過少則乾澀易碎。應揉至如同包子皮麵糰般略硬且黏實的狀態最佳。\",\n      \"svgFileName\": \"pr06-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // CLAY TEMPERING & FIBER MATRIX BLUEPRINT\",\n        \"① 具黏性的紅黏土 2份\",\n        \"提供黏結力的基礎基底材\",\n        \"+\",\n        \"② 粗河砂 1份\",\n        \"防止乾燥收縮與開裂\",\n        \"+\",\n        \"③ 剪碎的乾草纖維\",\n        \"強化結構拉力的內部骨幹\",\n        \"④ 少量加水並用腳後跟踩踏\",\n        \"切勿一次倒滿水；對折反覆踩\",\n        \"⑤ 完成扎實有韌性的泥糰\",\n        \"揉成拳頭大實心糰不散落\",\n        \"外表無細微龜裂痕跡\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"步驟 2: 在乾燥地面以U字型排布拳頭大石塊奠定基座\",\n      \"description\": \"朝向背風方向預留放柴火的爐口(約一手掌寬，約20公分)，將拳頭大的乾石塊排成馬蹄形(U字型)。在底部鋪上2~3公分厚的乾砂與細石子以隔絕地面濕氣與冷氣。接著用拳頭將步驟1的泥糰用力塞滿石塊間的所有縫隙，使基底緊密貼合地面。\",\n      \"actionNote\": \"> 風向安全要領: 爐口若正面迎風，強風會將火星猛烈倒灌吹向臉部。務必將爐口設在背風面或斜向避風側。\",\n      \"svgFileName\": \"pr06-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // FOUNDATION LAYOUT & AIR ENTRY SCHEMATIC\",\n        \"① 前方柴火進料口 (寬約20公分)\",\n        \"兼顧添柴與進氣的最佳口徑\",\n        \"② U字型排布的拳頭大乾石塊\",\n        \"支撐基礎的主要骨幹\",\n        \"③ 填滿縫隙的厚實泥漿\",\n        \"完全阻斷石塊間漏氣縫隙\",\n        \"④ 底部乾砂與細石隔熱層\",\n        \"隔絕冰冷地面的濕氣與低溫\",\n        \"⑤ 背風方向配置爐口\",\n        \"防止強風倒灌吹散炭火\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"步驟 3: 交錯堆疊石塊與泥漿，砌出及膝高的圓頂爐壁\",\n      \"description\": \"在基座石上鋪上約一掌厚(約5公分)的泥漿，交錯疊放下一層石塊，逐漸向內收口，向上堆疊至膝蓋高度(約45公分)形成圓頂。爐壁砌好後，雙手沾水將內壁均勻抹平光滑。內壁越光滑，熱氣越能在燃燒室內部盤旋對流，保持極高溫度。\",\n      \"actionNote\": \"> 防止坍塌: 切勿不加石頭單純疊泥壁，重力會使下方坍塌。必須以石塊為核心骨架，內外包覆厚實泥漿。\",\n      \"svgFileName\": \"pr06-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // DOME CHAMBER CROSS-SECTION & THERMAL CURVATURE\",\n        \"45cm\",\n        \"① 石塊與泥漿交錯剖面\",\n        \"交錯互鎖防止結構坍塌\",\n        \"② 一掌厚(約5公分)泥保溫壁\",\n        \"巨大蓄熱層整夜鎖住溫度\",\n        \"③ 平整光滑的熱反射曲面\",\n        \"沾水手抹平確保良好通風\",\n        \"④ 熱氣盤旋的內部球形燃燒室\",\n        \"熱流盤旋集中朝上方蓄熱\",\n        \"⑤ 及膝高(約45公分)整體高度\",\n        \"兼顧烹飪穩定度與蓄熱體積\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"步驟 4: 在爐頂保留鍋座開孔並於後方上方開鑿排煙煙囪\",\n      \"description\": \"在圓頂最上方中央保留直徑15~20公分的圓孔，供放置陶鍋或石板。在孔緣邊緣三角形嵌入3顆小石子，形成1公分的透氣縫隙，以免放上鍋具時阻斷氣流熄火。在後側略高處以粗樹枝斜斜刺入貫穿，開出排煙煙囪孔，形成強勁的自然上升氣流。\",\n      \"actionNote\": \"> 氣流對流原理: 若無後方煙囪，濃煙會全部由前方爐口湧出刺眼嗆人。後方煙囪位置高於前爐口，才能產生強大的抽風效應。\",\n      \"svgFileName\": \"pr06-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AIR DRAFT PERSPECTIVE & EXHAUST BLUEPRINT\",\n        \"① 前下方進氣口 (供應氧氣)\",\n        \"新鮮冷空氣被吸入炭火堆\",\n        \"② 頂部平整烹飪開口\",\n        \"承放鍋具或石板的火口\",\n        \"③ 後上方傾斜排煙煙囪孔\",\n        \"將刺鼻濃煙乾淨導向後方排出\",\n        \"④ 向上迴旋的強烈熱流線\",\n        \"在爐室盤旋加熱鍋底\",\n        \"⑤ 鍋底透氣墊石凸起\",\n        \"放上鍋具也不會阻絕火勢\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"步驟 5: 以細枝微火烘烤3小時使泥壁如磚石般堅硬\",\n      \"description\": \"切勿在剛築好的濕爐中直接燃燒大木柴；泥土內水分暴沸會直接炸裂爐壁。先以乾燥落葉與細小樹枝在爐口點燃拳頭大的微火，溫和維持3~4小時。觀察白色水蒸氣自外壁緩緩蒸發，深褐色濕泥漸轉為乾燥淺黃褐色。外壁手觸溫熱且不沾手時，堅固的永久爐灶即告完成。\",\n      \"actionNote\": \"> 修補細縫技巧: 若烘乾過程中外壁出現如髮絲般的細裂縫，取剩餘的微濕泥漿以指尖抹入塗平即可立即結合。\",\n      \"svgFileName\": \"pr06-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // CONTROLLED DEHYDRATION & CERAMIC HARDENING\",\n        \"① 爐口細枝微弱餘燼火 (溫和熱源)\",\n        \"均勻熱力讓內部水分緩緩排出\",\n        \"② 外壁水蒸氣蒸散線\",\n        \"孔隙水分安全氣化排出\",\n        \"③ 顏色轉變判斷指標\",\n        \"濕潤深褐色 → 乾燥淺黃褐色\",\n        \"④ 溫熱乾燥觸摸檢驗\",\n        \"外壁觸感溫熱無濕黏感\",\n        \"⑤ 髮絲裂縫泥漿修補\",\n        \"以新鮮泥漿密封微小縫隙\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤: 將濕潤的河石直接砌在接觸爐火的核心位置\",\n    \"description\": \"自溪流中剛拾取的河石與卵石，即使表面看似乾燥，內部微細孔隙依然飽含水分。接觸超過300度的高溫烈火時，內部水氣會瞬間化為超高壓蒸氣並如手榴彈般引爆破裂。鋒利的石塊碎片會高速射向臉部與眼睛，造成永久失明與嚴重撕裂傷。務必使用離水邊10公尺以上的山丘乾石，並以至少5公分厚的泥漿徹底包覆隔離。\",\n    \"consequence\": \"結果: 蒸氣爆炸引發石片飛濺，造成永久失明與重度顏面撕裂傷\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"在野外直接於地面生火會散失80%熱量。教你如何用泥石建造防風避雨的原始爐灶。\",\n    \"body\": \"黏土2份、粗砂1份、乾草1份加水用腳踩成扎實泥糰。乾石塊排成U字型，爐口朝背風面。交錯疊砌石塊與厚泥形成及膝圓頂，上方留鍋口，後方開煙囪。以細枝微火烘烤3小時即可硬如磚石。絕對不能使用濕河石，內部水蒸氣會引發爆炸。\",\n    \"outro\": \"暴風雨中也能順利煮食，整夜保留溫暖熱度。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr06-outcome.svg\",\n    \"title\": \"黏土抹面石爐（原始土灶與烹飪口）完成形態\",\n    \"description\": \"U字型河石地基上均勻抹上5公分厚的稻草黃土灰漿，具備上方平整烹飪石板與後方排煙煙囪，鎖住650°C高溫的原始土灶完成形態。\"\n  }\n}\n","content/protocols/locales/07-survival-knots.de.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"Der 'König der Knoten': Vollständige 5-Schritte-Anleitung für den Palstek (Unlösbar unter Last & in 1 Sekunde lösbar)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LEBENSRETTUNG & SCHWERLAST-FIXIERUNG]\",\n  \"summary\": \"Der Palstek (Bowline) gilt weltweit als der unbestrittene 'König der Knoten' für Bergung, Schwerlastzüge und Notunterkünfte. Selbst unter extremer Zugspannung zieht sich seine feste Schlaufe niemals zu oder rutscht durch – Erstickungs- oder Schnittgefahren sind ausgeschlossen. Selbst nach tonnenschwerer Belastung und durchnässt von Schlamm und Regen verklemmt er nie: Durch Umklappen der hinteren Kragenschlaufe mit dem Daumen bricht die Reibungssperre zusammen und der Knoten löst sich in einer einzigen Sekunde. Meistere die zeitlose 'Teich & Baum'-Formel schrittweise mit technischen Vektor-Blaupausen.\",\n  \"timeRequired\": \"5 Minuten (Nach 3 Übungszyklen dauerhaft beherrscht)\",\n  \"successRate\": \"99% (Bei Befolgung der Kaninchen-Formel)\",\n  \"difficulty\": \"Leicht (4-Takt-Formel 'Teich & Baum')\",\n  \"outputPerHour\": \"Meisterhafter Palstek (Einzelne feste Schlaufe)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 langes robustes Seil (2m+ Paracord oder Seil)\",\n      \"desc\": \"6~8mm griffiges Seil oder 550er Paracord mit hoher Reißfestigkeit für Knotenübungen und robuste Feldtakelagen.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Übungsstamm oder Griff (Unterarmstarker Ast)\",\n      \"desc\": \"Ein 5~7cm dicker Hartholzast zur Belastungsprobe unter echtem Zug.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Schritt 1: Das Teich-Auge (Ziffer '6'-Schlaufe) über der stehenden Part formen\",\n      \"description\": \"Halte die lange stehende Part (den Stamm) und bilde eine handtellergroße kreisrunde Schlaufe. Der entscheidende Schlüssel hierbei: Das Arbeitsende (das Kaninchen) muss OBERHALB der stehenden Part kreuzen. Von oben betrachtet entsteht eine deutliche Ziffer '6'. Verläuft das Ende unterhalb, versagt der Verriegelungsmechanismus vollständig – stets oben kreuzen!\",\n      \"actionNote\": \"> Prüfpunkt: Kontrolliere, dass das Arbeitsende über der stehenden Part liegt und eine 6er-Schlaufe bildet. Diese Öse fängt die Zugkräfte auf.\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // PALSTEK SCHRITT 1: TEICH-SCHLAUFE\",\n        \"STANDING PART\",\n        \"Stehende Part (Baumstamm)\",\n        \"RABBIT HOLE (SCHLAUFE)\",\n        \"6er-förmige Teich-Schlaufe\",\n        \"WORKING END (KANINCHEN)\",\n        \"Arbeitsende kreuzt ÜBER stehender Part\",\n        \"[SCHRITT 1 FOKUS] Arbeitsende über Part zur '6' legen\",\n        \"Arbeitsende MUSS oben liegen, um die Blockade zu garantieren.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Schritt 2: Das Kaninchen (Arbeitsende) von unten nach oben aus dem Teich auftauchen lassen\",\n      \"description\": \"Führe das Arbeitsende (das Kaninchen) von unten nach oben durch die Schlaufe (den Teich). Ziehe mindestens 15~20cm Seilreserve (den Kaninchenkopf) heraus, damit beim späteren Umrunden des Stammes genügend Seil vorhanden ist. Niemals von oben nach unten stechen; dies würde eine unkontrollierte Würgeschlinge erzeugen, die unter Last kollabiert.\",\n      \"actionNote\": \"> Richtungsprüfung: Das Seil muss von [Unten ➔ Oben] heraustauchen wie ein Tier aus seinem Erdloch.\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // PALSTEK SCHRITT 2: AUFTAUCHEN AUS DEM TEICH\",\n        \"EMERGE FROM HOLE\",\n        \"Von unten nach oben auftauchen\",\n        \"Kaninchenkopf 15cm\",\n        \"Ausreichend Seillänge herausziehen\",\n        \"MAIN EYE LOOP\",\n        \"Haupt-Lastschlaufe\",\n        \"[SCHRITT 2 FOKUS] Kaninchen von unten aus dem Teich ziehen\",\n        \"Von oben einzustechen erzeugt eine gefährliche Würgeschlinge; streng vermeiden.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Schritt 3: Das Kaninchen um die Rückseite des stehenden Baumes führen\",\n      \"description\": \"Führe das herausragende Seilende gegen den Uhrzeigersinn um die RÜCKSEITE der stehenden Part (des Baumes). Eine Führung vor dem Stamm zerstört die Geometrie und verhindert die Reibungsverriegelung. Das saubere Umrunden hinter dem Baum erzeugt die charakteristische Kragenschlaufe (Collar Loop), die das 1-Sekunden-Lösen ermöglicht.\",\n      \"actionNote\": \"> Rückseiten-Regel: Das Ende muss zwingend hinter der stehenden Part herumlaufen, um den Sperrkragen zu bilden.\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // PALSTEK SCHRITT 3: UM DEN BAUM HERUM\",\n        \"AROUND THE TREE\",\n        \"HINTER der stehenden Part herum\",\n        \"TREE (BAUM / STEHENDE PART)\",\n        \"Zentrale Drehachse des Kaninchens\",\n        \"RE-ENTRY READY\",\n        \"Bereit zum erneuten Eintauchen\",\n        \"[SCHRITT 3 FOKUS] Kaninchen umrundet die Rückseite des Baumes\",\n        \"Die Führung hinter dem Stamm erzeugt die 1-Sekunden-Löseschlaufe.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Schritt 4: Das Kaninchen wieder von oben nach unten in den Teich eintauchen lassen\",\n      \"description\": \"Führe das Arbeitsende nach dem Umrunden des Baumes wieder in genau dieselbe Teichschlaufe zurück. Die Richtung ist diesmal von oben nach unten (abwärts). Beim Durchtritt legen sich die beiden Seilstränge in der Schlaufe parallel nebeneinander. Damit sind alle Hebelkräfte symmetrisch ausgerichtet.\",\n      \"actionNote\": \"> Parallele Stränge: Prüfe, dass beide Seile im Teich sauber parallel liegen, ohne sich zu verdrehen.\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // PALSTEK SCHRITT 4: ZURÜCK IN DEN TEICH\",\n        \"BACK INTO HOLE\",\n        \"Von oben nach unten eintauchen\",\n        \"PARALLEL STRANDS\",\n        \"Zwei Stränge parallel ausgerichtet\",\n        \"COLLAR LOOP\",\n        \"Hintere Kragenschlaufe um den Baum\",\n        \"[SCHRITT 4 FOKUS] Kaninchen taucht wieder in den Teich ein\",\n        \"Von oben nach unten durchstecken; Stränge müssen parallel liegen.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Schritt 5: 4-Wege-Blockade festziehen und 1-Sekunden-Schnelllösen meistern\",\n      \"description\": \"Greife das Arbeitsende und den rechten Strang der Schlaufe fest mit einer Hand. Mit der anderen Hand ziehst du kräftig an der oberen stehenden Part in Gegenrichtung. Die internen Schlingen pressen sich unverrückbar zusammen (Locking). Die fertige Schlaufe verformt sich selbst unter LKW-Zug nicht. Zum Lösen drückst du die hintere U-förmige Kragenschlaufe mit dem Daumen nach außen ('Rückgrat brechen'): Die Reibung bricht sofort zusammen und der Knoten löst sich in 1 Sekunde ohne Messer.\",\n      \"actionNote\": \"> 1-Sekunden-Lösetrick: Niemals mit den Fingernägeln am Knoten pulen! Drücke einfach den Kragen auf der Rückseite mit dem Daumen weg; der Knoten fällt von selbst ab.\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // PALSTEK SCHRITT 5: BLOCKIERUNG & 1-SEK-LÖSEN\",\n        \"1-SEC QUICK RELEASE\",\n        \"Kragen-Abknick-Technik\",\n        \"Mit dem Daumen gegen den Kragen drücken\",\n        \"PULL STANDING\",\n        \"Stehende Part kräftig aufwärts ziehen\",\n        \"GRIP TOGETHER\",\n        \"Ende und Schlaufe in einer Hand halten\",\n        \"LOCKED FIXED LOOP\",\n        \"Schlaufengröße bleibt unter Last konstant\",\n        \"[SCHRITT 5 FOKUS] Gegensinnig ziehen für 4-Wege-Sperre\",\n        \"Zum Lösen Daumen auf den hinteren Kragen drücken; öffnet in 1s ohne Schnitt.\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fataler Fehler: Arbeitsende außerhalb der Schlaufe ('Cowboy-Palstek'-Fehler)\",\n    \"description\": \"Bei einem korrekt geknüpften Standard-Palstek MUSS das Seilende (der Kaninchenschwanz) auf der INNENSEITE der Hauptschlaufe liegen. Zeigt das Ende nach außen, entsteht eine mangelhafte Variante (holländischer Palstek/Cowboy Bowline). Beim Schleppen von Lasten oder Verankern von Planen verfängt sich das außenliegende Ende an Ästen oder Felsen und zieht den Knoten unter Zug schlagartig auf.\",\n    \"consequence\": \"Konsequenz: Selbstständiges Öffnen durch Außenreibung, Einsturz des Unterstands und Absturz von Lasten\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Hält selbst einem LKW-Zug stand und löst sich mit einem Daumendruck in 1 Sekunde: der Palstek.\",\n    \"body\": \"Wenn du dir in der Wildnis nur einen Knoten merken kannst, dann diesen! Merke dir die 4 Schritte von Teich und Baum: 1. Eine 6er-Schlaufe über dem Seil legen. 2. Das Kaninchen taucht von unten aus dem Teich auf. 3. Einmal hinten um den großen Baum herum. 4. Von oben wieder zurück in den Teich abtauchen. Beide Seiten gegeneinander strammziehen – bombenfest verriegelt! Selbst bei 500 Kilo zieht sich die Schlaufe nicht zusammen. Zum Öffnen kein Messer nötig: Drücke einfach mit dem Daumen gegen den Kragen auf der Rückseite und er löst sich in 1 Sekunde. Seilende immer innen halten!\",\n    \"outro\": \"Lade dir die technischen Vektor-Pläne für die Offline-Nutzung über den Profil-Link herunter.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"Palstek (König der Knoten) Technische Meisterzeichnung\",\n    \"description\": \"Technische Spezifikation des Standard-Palsteks mit starrer Festhalteschlaufe und dem 1-Sekunden-Schnelllösemechanismus durch Abknicken des Kragens.\"\n  }\n}\n","content/protocols/locales/07-survival-knots.en.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"The 'King of Knots': Complete 5-Step Guide to the Bowline Knot (Jam-Proof & Unties in 1 Second)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LIFELINE & RIGGING ESSENTIAL]\",\n  \"summary\": \"The Bowline is globally recognized as the undisputed 'King of Knots' for wilderness hauling, heavy load rigging, and emergency rescue. Under severe tension, its fixed loop never slips or constricts, eliminating any danger of choking or cord damage. Even after taking tremendous strain and being soaked in mud and rain, it never jams: flexing its rear collar loop pops the friction lock and unties the entire knot in a single second. Master the timeless 4-beat mnemonic ('The Rabbit and The Tree') and full-locking sequence step by step.\",\n  \"timeRequired\": \"5 Minutes (Master in 3 practice cycles)\",\n  \"successRate\": \"99% (Follow rabbit hole steps)\",\n  \"difficulty\": \"Easy (4-beat Rabbit & Tree formula)\",\n  \"outputPerHour\": \"Mastered Bowline Knot (Single Fixed Loop)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Length of Durable Cordage (2m+ paracord or rope)\",\n      \"desc\": \"Prepare 6~8mm high-friction cordage or 550 paracord with dependable tensile strength for knot practice and heavy field rigging.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Practice Post or Handle (Forearm-thick branch)\",\n      \"desc\": \"A 5~7cm diameter hardwood branch or anchor handle to test the knot under real tensile load.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Step 1: Form the 'Rabbit Hole' Loop (Number 6 Shape) Over the Standing Line\",\n      \"description\": \"Hold the long standing line (the tree) and form a small palm-sized circular loop. The most critical requirement here is that the working end (the rabbit) must cross OVER the standing line. Viewed from above, this forms a clear number '6' geometry. If the working end passes underneath the standing line, the structural lock will fail completely; always ensure it crosses over the top surface.\",\n      \"actionNote\": \"> Checkpoint: Verify the working end rests on top of the standing line to form a clean number 6 shape. This loop serves as the anchor throat distributing tensile force.\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BOWLINE STEP 1: FORMING THE RABBIT HOLE\",\n        \"STANDING PART\",\n        \"Standing Line (Main Tree Trunk)\",\n        \"RABBIT HOLE (LOOP)\",\n        \"Number 6 Shaped Throat Loop\",\n        \"WORKING END (RABBIT)\",\n        \"Working end crosses OVER standing line\",\n        \"[STEP 1 KEY] Lay working end over standing line to form '6' loop\",\n        \"Working end MUST stay on top of the standing line for structural lock.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Step 2: Emerge the Rabbit (Working End) Upwards Through the Rabbit Hole\",\n      \"description\": \"Take the working end (the rabbit) and feed it through the bottom of the rabbit hole, pulling it upwards towards yourself. Pull out at least 15~20cm of slack (the rabbit's head) so you have ample length to circle the tree in the subsequent step without running out of cord. Never push from the top down; doing so creates an unstable slip knot that chokes and fails under tension.\",\n      \"actionNote\": \"> Direction Check: The rabbit must pop out from UNDER to OVER [Bottom ➔ Up], like an animal emerging from a subterranean burrow.\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // BOWLINE STEP 2: EMERGING UPWARD FROM HOLE\",\n        \"EMERGE FROM HOLE\",\n        \"Escape upward from bottom of hole\",\n        \"Rabbit Head 15cm\",\n        \"Extract sufficient tail slack\",\n        \"MAIN EYE LOOP\",\n        \"Primary load-bearing safety loop\",\n        \"[STEP 2 KEY] Pull rabbit upward from bottom of rabbit hole\",\n        \"Threading top-to-bottom turns it into an accidental slip knot; avoid strictly.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Step 3: Route the Rabbit Around the Back of the Standing Tree (Main Line)\",\n      \"description\": \"Lead the protruding rabbit tail around the BACK of the vertical standing line (the tree trunk) in a counter-clockwise sweep. Crossing in front of the tree will ruin the geometry and prevent the friction lock from engaging. Wrapping neatly behind the standing tree creates the signature 'Collar Loop' that grants the Bowline its legendary ability to untie in one second under severe load.\",\n      \"actionNote\": \"> Rear Wrap Rule: The rabbit must pass behind the standing line. Routing across the front prevents friction locking and breaks knot integrity.\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // BOWLINE STEP 3: ROUTING BEHIND THE TREE\",\n        \"AROUND THE TREE\",\n        \"Wrap behind the standing trunk\",\n        \"TREE (STANDING LINE)\",\n        \"Central axis for rabbit routing\",\n        \"RE-ENTRY READY\",\n        \"Prepared for re-entering hole\",\n        \"[STEP 3 KEY] Rabbit circles around the back of the standing tree\",\n        \"Passing strictly behind creates the critical collar loop for instant release.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Step 4: Dive the Rabbit Back Down Into the Original Rabbit Hole\",\n      \"description\": \"Guide the working end (the rabbit) after circling the tree trunk and push it back down into the exact same rabbit hole it originally emerged from. The direction this time is strictly top-to-bottom (Downwards). As the tail passes through the throat, it lies parallel to the strand that emerged in Step 2. This parallel alignment balances internal clamping forces across the knot.\",\n      \"actionNote\": \"> Parallel Strand Check: Ensure both strands inside the rabbit hole lie neatly parallel without crossing or twisting for maximum friction efficiency.\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // BOWLINE STEP 4: RE-ENTERING RABBIT HOLE\",\n        \"BACK INTO HOLE\",\n        \"Re-enter hole from top to bottom\",\n        \"PARALLEL STRANDS\",\n        \"Two strands neatly aligned\",\n        \"COLLAR LOOP\",\n        \"Rear collar loop embracing tree\",\n        \"[STEP 4 KEY] Rabbit dives back down into the rabbit hole\",\n        \"Push tail down through original hole; strands inside must align parallel.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Step 5: Lock the Knot Under 4-Way Tension and Master the 1-Second Release\",\n      \"description\": \"Grip the working tail and the right leg of the eye loop together in one hand. With your other hand, firmly grasp the upper standing part and pull in opposite directions with authoritative force. The internal loops cinch down firmly upon each other, creating an immovable lock. The completed loop will not shrink by even a millimeter under heavy strain. When ready to untie, push the rear U-shaped collar loop backwards with your thumb ('Break the Back'); the internal friction collapses instantly, allowing the knot to fall apart in one second without knife cuts.\",\n      \"actionNote\": \"> 1-Second Release Secret: Never pick at the knot with fingernails. Simply identify the U-shaped collar loop behind the knot and snap it backward with your thumb to release instantly.\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // BOWLINE STEP 5: LOCKING & 1-SEC RELEASE\",\n        \"1-SEC QUICK RELEASE\",\n        \"Break-The-Back collar snap technique\",\n        \"Push collar loop with thumb for instant release\",\n        \"PULL STANDING\",\n        \"Pull standing line firmly upward\",\n        \"GRIP TOGETHER\",\n        \"Hold tail and loop leg in one hand\",\n        \"LOCKED FIXED LOOP\",\n        \"Constant loop size under heavy load\",\n        \"[STEP 5 KEY] Pull opposite sides to cinch 4-way lock\",\n        \"To untie, snap rear collar ring with thumb; slips loose in 1s without blades.\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Fatal Mistake: Leaving the Working End Outside the Loop ('Cowboy Bowline' Defect)\",\n    \"description\": \"On a properly dressed standard Bowline, the finished tail (working end) MUST sit neatly on the INSIDE of the main loop. If the tail finishes on the outside, it forms an inferior variant (often called the Cowboy Bowline). When hauling gear or pitching shelters in dense woods, an externally exposed tail readily snags on brush, twigs, or rocks, causing the entire knot to unravel catastrophically under load.\",\n    \"consequence\": \"Consequence: External snagging causes self-untie, resulting in shelter collapse or heavy load drop hazards\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Holds a pickup truck without slipping, yet unties in one second with a single thumb flick: The King of Knots, Bowline.\",\n    \"body\": \"If you can only learn one survival knot, this is it. Memorize the 4-step Rabbit and Tree formula: 1, make a loop over the line to create a number 6 rabbit hole. 2, the rabbit pops out from under the hole. 3, wrap around the back of the tall standing tree. 4, dive right back down into the hole. Pull both sides tight, and it locks solid. Even under 500 kilos, the loop size never shrinks. When done, never reach for a knife—just snap the back collar with your thumb, and it slides loose in one second. Keep the tail inside the loop so branches won't snag it.\",\n    \"outro\": \"Download the offline survival vector blueprints via the link in our profile.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"Bowline Knot (King of Knots) Master Blueprint\",\n    \"description\": \"Engineering specification for the standard Bowline knot showing the non-collapsing fixed eye loop and the 1-second Break-the-Back quick-release mechanism.\"\n  }\n}\n","content/protocols/locales/07-survival-knots.es.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"El 'Rey de los Nudos': Guía Definitiva de 5 Pasos del As de Guía (No se Atasca y se Desata en 1 Segundo)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LÍNEA DE VIDA Y ANCLAJE VITAL]\",\n  \"summary\": \"El As de Guía (Bowline) es universalmente reconocido como el indiscutible 'Rey de los Nudos' para arrastre de cargas pesadas, salvamento y amarre de refugios. Sometido a tensiones extremas, su lazo fijo jamás se desliza ni se estrangula, eliminando peligros de asfixia o rotura. Incluso empapado de barro y agua tras soportar cientos de kilos, nunca se atasca: doblando el cuello (bucle collar) posterior con el pulgar, el nudo se deshace limpiamente en un solo segundo. Domina la clásica regla mnemotécnica ('El conejo y el árbol') paso a paso con esquemas vectoriales precisos.\",\n  \"timeRequired\": \"5 Minutos (Dominio tras 3 repeticiones)\",\n  \"successRate\": \"99% (Siguiendo la secuencia del conejo)\",\n  \"difficulty\": \"Fácil (Fórmula mnemotécnica del conejo)\",\n  \"outputPerHour\": \"As de Guía Maestro (Lazo Fijo Único)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Tramo de Cuerda Resistente (2m+ paracord o soga)\",\n      \"desc\": \"Cuerda de 6~8mm de buen agarre y alta resistencia a la tracción para prácticas y amarres pesados de campamento.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Poste o Tronco de Práctica (Grosor del antebrazo)\",\n      \"desc\": \"Rama o poste de 5~7cm para probar la resistencia del nudo bajo tensión real.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Paso 1: Formar el Ojo del Conejo (Forma de Número 6) sobre la Línea Firme\",\n      \"description\": \"Sostén la línea firme (el árbol) y forma un pequeño bucle circular. La regla fundamental es que el extremo de trabajo (el conejo) debe cruzar POR ENCIMA de la línea firme. Visto desde arriba, conforma un número '6' perfecto. Si pasa por debajo, la estructura de bloqueo fallará por completo; asegúrate siempre de que cruce por la superficie superior.\",\n      \"actionNote\": \"> Punto Clave: Comprueba que el cabo pase sobre el firme formando un número 6. Este bucle actuará como garganta distribuidora de la fuerza de tensión.\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // AS DE GUÍA PASO 1: BUCLE EN FORMA DE 6\",\n        \"STANDING PART\",\n        \"Línea Firme (Tronco del Árbol)\",\n        \"RABBIT HOLE (BUCLE)\",\n        \"Madriguera con forma de 6\",\n        \"WORKING END (CONEJO)\",\n        \"Extremo cruza POR ENCIMA del firme\",\n        \"[CLAVE PASO 1] Montar extremo sobre línea formando bucle '6'\",\n        \"El cabo activo DEBE quedar encima para asegurar el bloqueo estructural.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Paso 2: Sacar al Conejo (Extremo Activo) hacia Arriba por la Madriguera\",\n      \"description\": \"Toma el extremo activo (el conejo) e introdúcelo desde abajo hacia arriba a través del bucle. Extrae al menos 15~20cm de holgura (la cabeza del conejo) para tener suficiente longitud al rodear el árbol en el siguiente paso. Jamás introduzcas el cabo de arriba hacia abajo; eso crearía un nudo corredizo inestable que se estrangula peligrosamente bajo tensión.\",\n      \"actionNote\": \"> Verificación de Dirección: El conejo debe salir [Abajo ➔ Arriba], emergiendo de la madriguera hacia la superficie.\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // AS DE GUÍA PASO 2: SALIDA DE LA MADRIGUERA\",\n        \"EMERGE FROM HOLE\",\n        \"Sale desde abajo hacia arriba\",\n        \"Cabeza del conejo 15cm\",\n        \"Extraer suficiente cabo libre\",\n        \"MAIN EYE LOOP\",\n        \"Bucle principal de carga fija\",\n        \"[CLAVE PASO 2] Sacar el conejo desde el fondo de la madriguera\",\n        \"Introducirlo de arriba abajo forma un nudo corredizo defectuoso; evítalo.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Paso 3: Rodear con el Conejo la Parte Posterior del Árbol (Línea Firme)\",\n      \"description\": \"Lleva el extremo del conejo alrededor de la parte TRASERA de la línea firme vertical en sentido antihorario. Pasar por delante del árbol arruinará la geometría e impedirá el bloqueo por fricción. Rodear la espalda del árbol crea el característico 'bucle collar' que le otorga al As de Guía su capacidad mágica de desatarse en 1 segundo bajo cualquier carga.\",\n      \"actionNote\": \"> Regla de Paso Trasero: El conejo debe pasar obligatoriamente por detrás de la línea firme para formar el collarín de desbloqueo rápido.\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // AS DE GUÍA PASO 3: RODEANDO EL ÁRBOL\",\n        \"AROUND THE TREE\",\n        \"Pasa por DETRÁS de la línea firme\",\n        \"TREE (ÁRBOL / FIRME)\",\n        \"Eje central de giro del conejo\",\n        \"RE-ENTRY READY\",\n        \"Listo para volver a la madriguera\",\n        \"[CLAVE PASO 3] El conejo rodea la parte posterior del árbol firme\",\n        \"Pasar por detrás forma el collarín vital para el desbloqueo instantáneo.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Paso 4: Zambullir al Conejo de Vuelta en la Madriguera de Arriba hacia Abajo\",\n      \"description\": \"Tras rodear el árbol, introduce el extremo del conejo nuevamente dentro de la misma madriguera de la que salió. Esta vez la dirección es de 'arriba hacia abajo' (en sentido inverso al paso 2). Al pasar por la garganta, los dos cabos dentro del bucle deben quedar perfectamente paralelos, distribuyendo la tensión simétricamente.\",\n      \"actionNote\": \"> Verificación Paralela: Asegúrate de que los dos cabos dentro de la madriguera descansen paralelos sin cruzarse ni retorcerse.\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // AS DE GUÍA PASO 4: REGRESO A LA MADRIGUERA\",\n        \"BACK INTO HOLE\",\n        \"Entra de nuevo de arriba a abajo\",\n        \"PARALLEL STRANDS\",\n        \"Dos cabos alineados en paralelo\",\n        \"COLLAR LOOP\",\n        \"Collarín posterior rodeando el árbol\",\n        \"[CLAVE PASO 4] El conejo se sumerge de vuelta en la madriguera\",\n        \"Pasar de arriba hacia abajo; los cabos interiores deben quedar paralelos.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Paso 5: Ajuste de Bloqueo en 4 Direcciones y Liberación Rápida en 1 Segundo\",\n      \"description\": \"Sujeta el extremo activo y el lado derecho del lazo con una mano. Con la otra mano, agarra con firmeza la línea firme superior y tira en direcciones opuestas con fuerza. Los bucles internos se comprimen entre sí bloqueando el nudo rígidamente. El lazo resultante jamás encogerá. Para desatarlo, empuja el bucle collar trasero en forma de U con el pulgar hacia afuera ('Quebrar el lomo'): la fricción interna colapsa al instante y el nudo se deshace en 1 segundo sin usar cuchillo.\",\n      \"actionNote\": \"> Secreto de Liberación en 1s: ¡Jamás tires del nudo con las uñas! Dobla el bucle collar trasero hacia afuera con el pulgar y se desatará suavemente al instante.\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // AS DE GUÍA PASO 5: BLOQUEO Y LIBERACIÓN 1S\",\n        \"1-SEC QUICK RELEASE\",\n        \"Técnica de quebrar el collarín\",\n        \"Empujar el collar con el pulgar para liberar\",\n        \"PULL STANDING\",\n        \"Tirar del firme firmemente hacia arriba\",\n        \"GRIP TOGETHER\",\n        \"Sujetar cabo y lazo con una mano\",\n        \"LOCKED FIXED LOOP\",\n        \"Tamaño de lazo invariable bajo carga\",\n        \"[CLAVE PASO 5] Tirar de lados opuestos para asegurar bloqueo\",\n        \"Para desatar, empuja el collar trasero con el pulgar; se suelta en 1s sin corte.\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Error Fatal: Dejar el Extremo Activo Fuera del Lazo (Variante Cowboy Defectuosa)\",\n    \"description\": \"En un As de Guía estándar bien confeccionado, el cabo final (la cola del conejo) DEBE quedar dentro del lazo principal. Si queda hacia afuera, forma una variante defectuosa (As de Guía Holandés o Cowboy). Al arrastrar troncos o tensar refugios, el cabo exterior se engancha fácilmente con ramas y rocas, desatando el nudo por completo bajo carga.\",\n    \"consequence\": \"Consecuencia: Desarme accidental por fricción externa, derrumbe del refugio o caída de cargas pesadas\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Soporta el tirón de un camión sin deslizarse y se desata en un segundo con el pulgar: el As de Guía.\",\n    \"body\": \"Si solo puedes aprender un nudo de supervivencia, es este. Memoriza los 4 pasos del conejo: 1, forma un bucle en número 6. 2, el conejo sale por abajo de la madriguera. 3, rodea el árbol firme por detrás. 4, vuelve a zambullirse en la madriguera de arriba a abajo. Tira de ambos lados y queda trabado a prueba de bombas. El lazo nunca se encoge ni ahorca. Para desatarlo, dobla el collarín trasero con el pulgar y se afloja en 1 segundo sin navaja. Guarda el cabo dentro del lazo para evitar enganches.\",\n    \"outro\": \"Descarga las guías técnicas vectoriales para uso offline desde el enlace en el perfil.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"As de Guía (Rey de los Nudos) - Ficha Maestra\",\n    \"description\": \"Especificación técnica del As de Guía que muestra el lazo fijo indeformable y el mecanismo de desbloqueo rápido en 1 segundo (Break the Back).\"\n  }\n}\n","content/protocols/locales/07-survival-knots.ja.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"超荷重でも絶対に解けず、1秒でほどける「結びの王様」もやい結び（ボーライン）完全解説\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[生命線・牽引必須]\",\n  \"summary\": \"野生環境で重量物の引き上げや救助、テントの設営において世界中で最も信頼される「結びの王様」もやい結び（ボーラインノット）の5段階結索法です。自重以上の極限の荷重がかかっても輪の大きさが決して変わらないため、締め付けや破断の危険がなく、雨に濡れて岩のように固くなっても裏側の「カラー（首輪ループ）」を指先で倒すだけで、わずか1秒でほどけます。「ウサギと木」の4拍子の暗記公式と実戦ロッキング技術をステップごとに完全体得しましょう。\",\n  \"timeRequired\": \"5分（3回反復で完全習得）\",\n  \"successRate\": \"99%（ウサギ穴手順厳守時）\",\n  \"difficulty\": \"初級（ウサギと木の4拍子公式）\",\n  \"outputPerHour\": \"もやい結びマスター（単一固定ループ）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"耐久ロープ 1本（2m以上のパラコードまたは丈夫な紐）\",\n      \"desc\": \"指の太さ（6〜8mm）で摩擦力と引っ張り強度の高いパラコードを用意します。結索練習と過酷な現場リギングの基本素材です。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"練習用の丸太や柱 1本（前腕の太さ）\",\n      \"desc\": \"ループを掛けて荷重をかけられる直径5〜7cmの堅い木の枝や手すりです。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第1段階：元綱の上に動端を重ねて数字の「6」のウサギ穴を作る\",\n      \"description\": \"ロープの長い方（元綱、Standing Part）を持ち、手のひらサイズの小さな輪を作ります。最大の急所は、先端（動端、Working End）が元綱の「上（Over）」を交差するように重ねることです。上から見下ろしたときに数字の「6」の形になれば、完璧なウサギ穴の完成です。下を通してしまうと結びの構造が成り立たないため、必ず上に重ねます。\",\n      \"actionNote\": \"> チェックポイント：動端が元綱の上に重なり、数字の6の形になっているか確認してください。この輪が荷重を分散して固定する要となります。\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BOWLINE STEP 1: ウサギ穴ループ形成\",\n        \"STANDING PART\",\n        \"元綱（真っ直ぐな木）\",\n        \"RABBIT HOLE (LOOP)\",\n        \"数字の6の形をしたウサギ穴\",\n        \"WORKING END (RABBIT)\",\n        \"動端が元綱の「上」を交差\",\n        \"[第1段階要点] 元綱の上に動端を載せ6字ループを形成\",\n        \"動端が必ず元綱の上側に位置することで固定構造が成立します。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第2段階：ウサギ穴の底から上方へウサギ（ロープ先端）を引き抜く\",\n      \"description\": \"ロープ先端（ウサギ）を持ち、先ほど作ったウサギ穴の下側から上側へ向けて突き通し、外へ引き出します。このとき、ウサギの頭（動端）を少なくとも15〜20cm以上長めに引き出しておくことで、次のステップで木を回る際にロープが不足しません。上から下へ刺すと荷重で締まる罠（スリップノット）になってしまうため、必ず「下から上へ」通します。\",\n      \"actionNote\": \"> 方向確認：ウサギが地中の巣穴から顔を出すように［下 ➔ 上］へ通します。逆に通すと首を絞める罠に変わってしまいます。\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // BOWLINE STEP 2: ウサギ穴から上方脱出\",\n        \"EMERGE FROM HOLE\",\n        \"穴の底から上へ脱出\",\n        \"ウサギの頭 15cm\",\n        \"十分な長さを確保\",\n        \"MAIN EYE LOOP\",\n        \"最終荷重を受ける主ループ\",\n        \"[第2段階要点] 穴の底から上へ向けてウサギを引き抜く\",\n        \"上から刺すと荷重で首が締まる罠になるため絶対に避けてください。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第3段階：ウサギが真っ直ぐ立つ大木（元綱）の裏側を反時計回りに回る\",\n      \"description\": \"ウサギ穴を脱出したウサギ（ロープ先端）を引き連れ、直立する元綱（木）の「裏側（Back）」を抱きかかえるように反時計回りにぐるりと回します。元綱の表側を通してしまうと固定ループが形成されません。木の背中を回すこの動作が、どんな巨大荷重の後でも1秒で解ける奇跡の「首輪（カラー）ループ」を生み出します。\",\n      \"actionNote\": \"> 背面通過の法則：ウサギは必ず木の「裏側」を回らなければなりません。表側を通すと結びの形態が崩れ摩擦固定力が働きません。\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // BOWLINE STEP 3: 木（元綱）の裏側を旋回\",\n        \"AROUND THE TREE\",\n        \"元綱の「裏側」を回る\",\n        \"TREE（木の幹・元綱）\",\n        \"ウサギが旋回する中心軸\",\n        \"RE-ENTRY READY\",\n        \"再び穴へ潜る準備完了\",\n        \"[第3段階要点] 穴を出たウサギが元綱の裏側を一周する\",\n        \"必ず裏を通すことで、1秒で解ける重要なカラーループが作られます。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第4段階：木を回ったウサギが元のウサギ穴へ上から下へ飛び込む\",\n      \"description\": \"木の裏を回ってきたウサギ（動端）を、第2段階で飛び出したあの同じウサギ穴へ再び押し込みます。このときの進入方向は第2段階とは逆の「上から下へ（Down）」です。穴へ突き入れると、穴の中を通る2本のロープが綺麗に平行（Parallel）に並びます。これで全ての幾何学的噛み合わせが完璧に整いました。\",\n      \"actionNote\": \"> 平行整列の確認：ウサギ穴の中で2本のロープがねじれず平行に並んでいるか確認してください。平行であることで摩擦が均等に分散されます。\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // BOWLINE STEP 4: ウサギ穴へ再突入\",\n        \"BACK INTO HOLE\",\n        \"上から下へ穴に再突入\",\n        \"PARALLEL STRANDS\",\n        \"2本が綺麗に平行整列\",\n        \"COLLAR LOOP\",\n        \"木を抱き込む首輪ループ\",\n        \"[第4段階要点] ウサギがウサギ穴の中へ再び潜り込む\",\n        \"木を回った先端を元の穴へ上から下へ通し、平行に揃えます。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"第5段階：両手で引いて4方向ロッキング＆1秒解除の極意を体得する\",\n      \"description\": \"片手でウサギ（動端）とループの右側を一緒に固く握り、もう一方の手で上の元綱を掴んで反対方向に力強く引き締めます。四方に張力が加わり、ロープ同士が互いを強烈に噛み合ってロックされます。完成した輪は軽トラが牽引しても大きさが変わりません。解くときは結び目背面のU字型カラーを親指で後ろへパチッと倒せば（Break the Back）、内部摩擦が一瞬で消失し1秒でスルスルとほどけます。\",\n      \"actionNote\": \"> 1秒高速解除の秘訣：絶対に爪で結び目をほじくらないでください！裏側のU字型ループを親指で外側に倒すだけで、嘘のように一瞬でほどけます。\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // BOWLINE STEP 5: ロック完了と1秒解除\",\n        \"1-SEC QUICK RELEASE\",\n        \"カラー（首輪）倒しの秘技\",\n        \"親指でカラーを倒すと即座に解除\",\n        \"PULL STANDING\",\n        \"元綱を上方へ強く引く\",\n        \"GRIP TOGETHER\",\n        \"動端とループを片手で保持\",\n        \"LOCKED FIXED LOOP\",\n        \"荷重がかかっても輪の大きさ不変\",\n        \"[第5段階要点] 両手で反対方向へ強く引き完全ロック\",\n        \"解くときは裏のカラーを親指で倒すだけで、刃物を使わず1秒でほどけます。\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命的な失敗：ロープ先端が完成ループの外側に飛び出た「変形もやい結び」\",\n    \"description\": \"正しく結ばれたもやい結びでは、ロープの先端（ウサギの尾）が必ず完成した大きな輪の「内側（Inside）」に収まっていなければなりません。もし先端が外側（Outside）に飛び出たままだと、「カウボーイ・ボーライン」と呼ばれる不良変形になります。この状態で木々の間を牽引したりシェルターを張ると、露出した先端が小枝や岩に擦れた瞬間に結び目が自壊してほどけ、落下事故や倒壊を引き起こします。\",\n    \"consequence\": \"結果：外部摩擦による結び目の自壊、シェルター倒壊および吊り上げ荷物の落下事故\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"トラックが引っ張っても解けず、指先ひとつで1秒でほどける「結びの王様」もやい結びです。\",\n    \"body\": \"野生で結び目を一つだけ覚えるならこれです。ウサギと木の4拍子だけ覚えてください。1、数字の6の形のウサギ穴を作ります。2、ウサギが穴の下から上へピョコッと出ます。3、立っている木の裏側をぐるっと回ります。4、元来た穴へ上から下へ戻ります。先端と輪を持って元綱を引けば完全ロック！500キロの荷重でも輪の大きさは絶対変わりません。解くときは裏の首輪を親指でパチッと倒すだけ。1秒でスルスルほどけます。先端は必ず輪の内側に収めてください。\",\n    \"outro\": \"雨風の中でも役立つオフライン図面はプロフィールのリンクから保存してください。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"もやい結び（結びの王様）完成構造図\",\n    \"description\": \"荷重がかかっても縮まない固定アイ・ループと、1秒で解けるカラー倒し（Break the Back）機構を備えたもやい結びの標準仕様図です。\"\n  }\n}\n","content/protocols/locales/07-survival-knots.pt.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"O 'Rei dos Nós': Guia Definitivo em 5 Passos do Nó Lais de Guia (Nunca Emperra e Desata em 1 Segundo)\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[LINHA DA VIDA E AMARRAÇÃO VITAL]\",\n  \"summary\": \"O Lais de Guia (Bowline) é universalmente consagrado como o 'Rei dos Nós' para resgate, içamento de cargas pesadas e armação de abrigos. Sob extrema tensão, seu laço fixo jamais escorrega ou estrangula, eliminando qualquer perigo de asfixia ou corte da corda. Mesmo após suportar forças brutais e ficar ensopado de lama e chuva, nunca emperra: flexionando a alça do colar traseiro com o polegar, o atrito se desfaz e o nó se solta em um único segundo. Domine a clássica regra mnemônica ('O coelho e a árvore') passo a passo.\",\n  \"timeRequired\": \"5 Minutos (Domínio em 3 ciclos de treino)\",\n  \"successRate\": \"99% (Seguindo os passos da toca do coelho)\",\n  \"difficulty\": \"Fácil (Fórmula em 4 tempos: Coelho e Árvore)\",\n  \"outputPerHour\": \"Lais de Guia Mestre (Laço Fixo Único)\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"1 Pedaço de Corda Resistente (2m+ paracord ou corda)\",\n      \"desc\": \"Corda de 6~8mm com boa aderência e alta resistência à tração para treinos de amarração e fixações pesadas em campo.\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"Tronco ou Poste de Treino (Espessura do antebraço)\",\n      \"desc\": \"Galho ou haste de 5~7cm para testar a resistência sob tração real.\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"Passo 1: Formar a Toca do Coelho (Laço em Forma de '6') sobre a Linha Firme\",\n      \"description\": \"Segure o cabo principal (a linha firme/árvore) e faça um laço circular do tamanho da palma da mão. O segredo fundamental é que a ponta de trabalho (o coelho) deve cruzar POR CIMA da linha firme. Visto de cima, forma um número '6' perfeito. Se passar por baixo, a estrutura de trava falhará completamente; certifique-se de que cruze por cima.\",\n      \"actionNote\": \"> Ponto de Verificação: Verifique se o chicote cruza por cima da linha firme formando um '6'. Este laço servirá como garganta distribuidora de força.\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // LAIS DE GUIA PASSO 1: TOCA DO COELHO EM '6'\",\n        \"STANDING PART\",\n        \"Linha Firme (Tronco da Árvore)\",\n        \"RABBIT HOLE (LAÇO)\",\n        \"Toca do coelho em formato de 6\",\n        \"WORKING END (COELHO)\",\n        \"Chicote cruza POR CIMA da linha firme\",\n        \"[FOCO PASSO 1] Apoiar chicote sobre linha formando laço '6'\",\n        \"O chicote DEVE ficar por cima para garantir o travamento.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"Passo 2: Fazer o Coelho (Chicote) Sair de Baixo para Cima pela Toca\",\n      \"description\": \"Segure o chicote (o coelho) e passe-o de baixo para cima através da toca que acabou de formar. Puxe pelo menos 15~20cm de folga (a cabeça do coelho) para ter comprimento suficiente ao contornar a árvore no passo seguinte. Nunca empurre de cima para baixo; isso criaria um nó corrediço perigoso que estrangula sob carga.\",\n      \"actionNote\": \"> Sentido Correto: O coelho deve emergir de [Baixo ➔ Cima], saindo do fundo da toca para a superfície.\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // LAIS DE GUIA PASSO 2: SAÍDA DA TOCA\",\n        \"EMERGE FROM HOLE\",\n        \"Emerge do fundo para cima\",\n        \"Cabeça do coelho 15cm\",\n        \"Puxar sobra suficiente de cabo\",\n        \"MAIN EYE LOOP\",\n        \"Laço principal de sustentação\",\n        \"[FOCO PASSO 2] Puxar o coelho de baixo para cima pela toca\",\n        \"Passar de cima para baixo cria um nó corrediço perigoso; evite estritamente.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"Passo 3: Passar o Coelho por Trás do Tronco da Árvore (Linha Firme)\",\n      \"description\": \"Conduza o chicote do coelho em volta da parte DE TRÁS da linha firme vertical no sentido anti-horário. Cruzar pela frente arruína a geometria e impede a trava por fricção. Contornar as costas da árvore cria a alça do colar (Collar Loop) que confere ao nó a capacidade de se soltar em 1 segundo sob qualquer peso.\",\n      \"actionNote\": \"> Regra da Passagem Traseira: O coelho deve passar obrigatoriamente por trás da linha firme para criar o colar de liberação rápida.\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // LAIS DE GUIA PASSO 3: VOLTA POR TRÁS DA ÁRVORE\",\n        \"AROUND THE TREE\",\n        \"Passa por TRÁS da linha firme\",\n        \"TREE (TRONCO / LINHA FIRME)\",\n        \"Eixo central de rotação do coelho\",\n        \"RE-ENTRY READY\",\n        \"Pronto para retornar à toca\",\n        \"[FOCO PASSO 3] O coelho contorna as costas da árvore firme\",\n        \"Passar por trás cria o colar indispensável para a liberação instantânea.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"Passo 4: Mergulhar o Coelho de Volta na Toca de Cima para Baixo\",\n      \"description\": \"Após contornar a árvore, empurre a ponta do coelho de volta para dentro da mesma toca de onde ele saiu. A direção desta vez é estritamente de cima para baixo (descendente). Ao atravessar o laço, os dois cabos dentro da toca devem repousar perfeitamente paralelos, equilibrando a tensão.\",\n      \"actionNote\": \"> Alinhamento Paralelo: Certifique-se de que os dois cabos dentro da toca fiquem paralelos, sem torções ou cruzamentos.\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // LAIS DE GUIA PASSO 4: RETORNO À TOCA\",\n        \"BACK INTO HOLE\",\n        \"Entra de cima para baixo na toca\",\n        \"PARALLEL STRANDS\",\n        \"Dois cabos alinhados em paralelo\",\n        \"COLLAR LOOP\",\n        \"Collar traseiro abraçando a árvore\",\n        \"[FOCO PASSO 4] O coelho mergulha de volta para dentro da toca\",\n        \"Inserir de cima para baixo; cabos internos devem ficar paralelos.\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"Passo 5: Ajustar a Trava em 4 Direções e Dominar a Liberação em 1 Segundo\",\n      \"description\": \"Segure o chicote e a perna direita do laço com uma mão. Com a outra mão, segure firmemente a linha firme superior e puxe em direções opostas com vigor. Os laços internos se comprimem travando o nó de maneira inabalável. O laço formado nunca diminui de tamanho. Para desatar, empurre a alça em U do colar traseiro com o polegar ('Quebrar a espinha'): o atrito colapsa imediatamente e o nó se desfaz em 1 segundo sem faca.\",\n      \"actionNote\": \"> Segredo da Liberação em 1s: Nunca puxe com as unhas! Dobre o colar traseiro para fora com o polegar e o nó se soltará suavemente.\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // LAIS DE GUIA PASSO 5: TRAVA E LIBERAÇÃO EM 1S\",\n        \"1-SEC QUICK RELEASE\",\n        \"Técnica de quebrar o colar traseiro\",\n        \"Empurrar o colar com o polegar para soltar\",\n        \"PULL STANDING\",\n        \"Puxar a linha firme com força para cima\",\n        \"GRIP TOGETHER\",\n        \"Segurar chicote e laço com uma mão\",\n        \"LOCKED FIXED LOOP\",\n        \"Tamanho do laço inalterável sob carga\",\n        \"[FOCO PASSO 5] Puxar lados opostos para travar em 4 vias\",\n        \"Para soltar, empurre o colar traseiro com o polegar; desata em 1s sem corte.\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"Erro Fatal: Deixar a Ponta da Corda do Lado de Fora do Laço (Variação Cowboy)\",\n    \"description\": \"No Lais de Guia padrão bem executado, a ponta final (a cauda do coelho) DEBE ficar do lado de DENTRO do laço principal. Se a ponta ficar exposta para fora, cria-se uma variação defeituosa (Cowboy Bowline). Ao arrastar troncos ou montar abrigos na mata, a ponta externa se prende facilmente em galhos ou pedras, desatando o nó instantaneamente sob tração.\",\n    \"consequence\": \"Consequence: Abertura involuntária por atrito externo, colapso de abrigos ou queda de cargas suspensas\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"Aguenta o puxão de um caminhão sem escorregar e desata em um segundo com o polegar: o Lais de Guia.\",\n    \"body\": \"Se você só puder aprender um nó de sobrevivência, aprenda este. Memorize os 4 passos do coelho: 1, faça uma toca em forma de 6. 2, o coelho sai por baixo da toca. 3, dá uma volta por trás da árvore firme. 4, mergulha de volta na toca de cima para baixo. Puxe os dois lados e o nó trava como pedra. O laço nunca estrangula. Para soltar, dobre o colar traseiro com o polegar e ele desliza solto em 1 segundo sem navalha. Mantenha a ponta dentro do laço para não enroscar em galhos.\",\n    \"outro\": \"Baixe os manuais técnicos vetoriais para uso offline pelo link na bio.\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"Lais de Guia (Rei dos Nós) - Prancha Técnica Mestre\",\n    \"description\": \"Especificação de engenharia do Lais de Guia padrão demonstrando o laço fixo indeformável e o mecanismo de desate em 1 segundo (Break the Back).\"\n  }\n}\n","content/protocols/locales/07-survival-knots.zh-TW.json":"{\n  \"protocolId\": \"PR-07\",\n  \"category\": \"TOOLS\",\n  \"title\": \"承受千斤拉力絕不滑脫、1秒瞬間解開的「繩結之王」稱人結（Bowline）完整五步指南\",\n  \"threatLevel\": \"HIGH\",\n  \"threatLevelText\": \"[救命牽引·營地必備]\",\n  \"summary\": \"在野外環境進行重物起吊、傷患救援或搭建堅固庇護所時，被全球生存專家公認為「繩結之王」的稱人結（Bowline）五步實戰結法。即使承受超越體重的極限拉力，其固定環圈大小也絕不縮小，徹底消除絞勒與割斷繩索的危險；即便經歷風雨泥濘浸透、繩結緊繃如石，只需用大拇指扳開背後的「套領（Collar 環）」，即可在 1 秒內徒手滑脫解開。循序漸進掌握經典的「兔子與樹」四拍記憶公式與鎖定技術。\",\n  \"timeRequired\": \"5 分鐘（重複練習 3 次即可終身掌握）\",\n  \"successRate\": \"99%（遵循兔子洞步驟絕不失誤）\",\n  \"difficulty\": \"簡易（兔子與樹四拍公式）\",\n  \"outputPerHour\": \"精通稱人結（單一固定繩圈）\",\n  \"materials\": [\n    {\n      \"id\": \"mat-01\",\n      \"name\": \"耐磨長繩 1 條（2米以上傘繩或野外繩索）\",\n      \"desc\": \"準備粗細約 6~8mm、摩擦力良好且抗拉強度充足的高強度繩索，作為結繩練習與野外重型固定之基礎材。\"\n    },\n    {\n      \"id\": \"mat-02\",\n      \"name\": \"練習用樹幹或把手 1 根（手臂粗細）\",\n      \"desc\": \"直徑 5~7cm 的堅硬枝幹或拉手，用以實測高拉力下的繩結結構。\"\n    }\n  ],\n  \"steps\": [\n    {\n      \"stepNumber\": \"01\",\n      \"title\": \"第 1 步：在主繩上方搭成數字「6」字形的兔子洞環圈\",\n      \"description\": \"手持繩索長端（主繩，Standing Part），在上方做一個手掌大小的小圓圈。此處最關鍵的要領是：活動工作端（兔子，Working End）必須橫跨在主繩的「上方（Over）」。從上方俯視時呈現清晰的數字「6」字形。若從主繩下方穿過，整體鎖定結構將徹底失效，因此務必確保壓在主繩上層。\",\n      \"actionNote\": \"> 檢查要點：確認活動端壓在主繩之上，形成端正的「6」字形圓圈。此環圈將成為分散張力並鎖定全結的核心喉部。\",\n      \"svgFileName\": \"pr07-step-01.svg\",\n      \"svgLabels\": [\n        \"FIG. 01 // BOWLINE STEP 1: 兔子洞環圈形成\",\n        \"STANDING PART\",\n        \"主繩（站立的大樹）\",\n        \"RABBIT HOLE (環圈)\",\n        \"數字 6 字形兔子洞\",\n        \"WORKING END (兔子)\",\n        \"活動繩頭橫跨在主繩「上方」\",\n        \"[第 1 步關鍵] 活動端壓於主繩上方形成 6 字環\",\n        \"活動端必須保持在主繩上方，方能確立鎖定結構。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"02\",\n      \"title\": \"第 2 步：兔子（繩頭）由洞底「自下而上」穿出兔子洞\",\n      \"description\": \"捏住繩頭（兔子），由剛形成的兔子洞（圓環）底部朝上方鑽出。此時繩頭（兔頭）至少拉出 15~20cm 以上的充足長度，以確保在下一步繞樹時長度充裕。嚴禁由上往下插入，否則會變成一受力就勒緊的危險活套結（Slip Knot），務必嚴格遵守「由洞底（下）往地面（上）」的穿出方向。\",\n      \"actionNote\": \"> 方向確認：兔子必須如破土而出般［由下 ➔ 向上］穿過。反向穿入會變成鎖死並勒傷物體的滑結。\",\n      \"svgFileName\": \"pr07-step-02.svg\",\n      \"svgLabels\": [\n        \"FIG. 02 // BOWLINE STEP 2: 由兔子洞向上鑽出\",\n        \"EMERGE FROM HOLE\",\n        \"由洞穴底部向上鑽出\",\n        \"兔頭預留 15cm\",\n        \"拉出充足的尾繩餘量\",\n        \"MAIN EYE LOOP\",\n        \"承受最終載荷的大環圈\",\n        \"[第 2 步關鍵] 兔子由洞底向上拔地鑽出\",\n        \"由上往下插入將退化為致命活結，請務必嚴格避免。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"03\",\n      \"title\": \"第 3 步：兔子繞過筆直大樹（主繩）的「背後」旋轉半圈\",\n      \"description\": \"引導鑽出兔子洞的繩頭（兔子），逆時針繞過垂直挺立的主繩（樹幹）的「背後（Back）」。若從主繩前方繞過，將無法形成摩擦鎖定結構。繞至大樹後方繞出的動作，將在繩結背面形成至關重要的「套領環（Collar Loop）」，這正是稱人結日後承受千斤重壓仍能 1 秒解開的奇蹟部位。\",\n      \"actionNote\": \"> 背面環繞法則：兔子必須嚴格繞到大樹的「後背」。由前方穿過會破壞幾何形態，導致摩擦自鎖失效。\",\n      \"svgFileName\": \"pr07-step-03.svg\",\n      \"svgLabels\": [\n        \"FIG. 03 // BOWLINE STEP 3: 繞至大樹（主繩）背後\",\n        \"AROUND THE TREE\",\n        \"繞過主繩「後背」\",\n        \"TREE（直立樹幹／主繩）\",\n        \"兔子旋轉所依託的中心軸\",\n        \"RE-ENTRY READY\",\n        \"準備重新鑽入洞穴\",\n        \"[第 3 步關鍵] 鑽出洞穴的兔子繞大樹後方一圈\",\n        \"務必從後方繞過，以形成 1 秒極速解開的關鍵套領環。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"04\",\n      \"title\": \"第 4 步：兔子由上往下重新鑽回最初的兔子洞內\",\n      \"description\": \"繞過大樹後背的繩頭（兔子），重新送入第 2 步最初鑽出的同一個兔子洞內。此時的穿入方向與第 2 步相反，為「由上往下（Down）」。將兔子送入洞穴後，洞內穿入的繩段與當初穿出的繩段將緊密平行（Parallel）排列。至此，所有咬合受力幾何均已完美就位。\",\n      \"actionNote\": \"> 平行排列檢視：確認兔子洞內兩根繩索平行緊貼，不可相互纏繞扭曲，以使摩擦受力均勻分佈。\",\n      \"svgFileName\": \"pr07-step-04.svg\",\n      \"svgLabels\": [\n        \"FIG. 04 // BOWLINE STEP 4: 重新鑽回兔子洞\",\n        \"BACK INTO HOLE\",\n        \"由上往下重新入洞\",\n        \"PARALLEL STRANDS\",\n        \"兩股繩索平順排列\",\n        \"COLLAR LOOP\",\n        \"環抱大樹的後方套領\",\n        \"[第 4 步關鍵] 兔子重新鑽回原來的兔子洞內\",\n        \"將繩頭由上往下送入原洞，洞內兩股繩索須保持平行。\"\n      ]\n    },\n    {\n      \"stepNumber\": \"05\",\n      \"title\": \"第 5 步：雙手對拉完成四向鎖定，體會 1 秒極速解結秘訣\",\n      \"description\": \"一手握緊繩頭（兔子）與大圓環右側繩股，另一手緊握上方主繩（Standing Part），兩手向相反方向發力收緊拉伸。四向張力使內部繩圈緊緊咬合鎖定（Locking）。成型的繩圈在任何重壓下都不會收縮分毫。需要解開時，只需用大拇指將背面 U 字型的套領環（Collar）向後用力扳折（Break the Back），內部摩擦力瞬間歸零，無需刀具 1 秒內即可順滑解脫。\",\n      \"actionNote\": \"> 1 秒速解要訣：切勿用指甲摳挖繩結！找到結背後環抱主繩的 U 型套領，用大拇指向外扳折，繩結即刻應聲而解。\",\n      \"svgFileName\": \"pr07-step-05.svg\",\n      \"svgLabels\": [\n        \"FIG. 05 // BOWLINE STEP 5: 鎖定完成與 1 秒速解\",\n        \"1-SEC QUICK RELEASE\",\n        \"折斷套領（後背）速解技法\",\n        \"大拇指扳折套領環即可瞬間解鎖\",\n        \"PULL STANDING\",\n        \"上方主繩向上強烈拉緊\",\n        \"GRIP TOGETHER\",\n        \"單手捏住繩頭與環圈右股\",\n        \"LOCKED FIXED LOOP\",\n        \"極限載荷下環圈大小恆定不變\",\n        \"[第 5 步關鍵] 雙手反向用力收緊完成四向鎖定\",\n        \"解開時用大拇指扳開背後套領環，無須動刀 1 秒滑脫。\"\n      ]\n    }\n  ],\n  \"fatalMistake\": {\n    \"title\": \"致命錯誤：繩頭露在主環圈外側的「荷蘭式變形稱人結（牛仔稱人結）」\",\n    \"description\": \"在標準規範的稱人結中，收尾的活動繩頭（兔尾）必須完全收攏在主環圈的「內側（Inside）」。若繩頭暴露在環圈外側（Outside），即為結構欠佳的變形結（牛仔稱人結）。在林間拖曳物資或遭遇風暴時，露在外側的繩頭極易被樹枝或岩石刮擦受力，導致整顆繩結在瞬間徹底崩解滑脫。\",\n    \"consequence\": \"後果：因外部刮碰導致繩結意外自解，造成庇護所垮塌或起吊物資墜落事故\"\n  },\n  \"shortsScript\": {\n    \"hook\": \"卡車拉不脫，拇指一折 1 秒解開：野外繩結之王稱人結。\",\n    \"body\": \"在野外若只能學一種繩結，非它莫屬！牢記兔子與樹四步口訣：1，在主繩上方搭個 6 字形兔子洞。2，兔子從洞底鑽上來。3，繞過筆直大樹背後一圈。4，再從上方鑽回兔子洞裡。捏住繩頭拉緊主繩，瞬間鎖定！即便吊起 500 公斤，環圈也絕不縮緊。解開時不用找刀，用大拇指把背後的套領往後一折，1 秒滑脫解開。切記繩頭必須留在環內，露在外面會被樹枝刮脫。\",\n    \"outro\": \"雨雪環境也能離線查閱的技術向量圖解，請至個人檔案連結儲存。\"\n  },\n  \"outcome\": {\n    \"svgFileName\": \"pr07-outcome.svg\",\n    \"title\": \"稱人結（繩結之王）工程技術規格圖\",\n    \"description\": \"標準稱人結工程規範圖，展示受力不變形的固定安全環圈，以及 1 秒扳折套領（Break the Back）的極速解脫機構。\"\n  }\n}\n","content/svgs/02-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <pattern id=\"diag-hatch\" width=\"8\" height=\"8\" patternTransform=\"rotate(45 0 0)\" patternUnits=\"userSpaceOnUse\">\n      <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#333333\" stroke-width=\"1\" />\n    </pattern>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Ember Catcher Leaf positioned under the board & notch opening -->\n  <path d=\"M 180 260 C 240 250, 440 250, 500 260 C 515 285, 430 308, 340 308 C 250 308, 165 285, 180 260 Z\" \n        fill=\"#171717\" stroke=\"#666666\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\" />\n  <text x=\"655\" y=\"298\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">불씨 받침 나뭇잎</text>\n\n  <!-- Hearth Board 3D block (isometric projection) -->\n  <!-- Top Face -->\n  <polygon points=\"120,180 520,180 480,230 80,230\" fill=\"#1f1e1e\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Front Face (Thickness profile) -->\n  <polygon points=\"80,230 480,230 480,265 80,265\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\" />\n  <!-- Right Side Face -->\n  <polygon points=\"480,230 520,180 520,215 480,265\" fill=\"#181818\" stroke=\"#666666\" stroke-width=\"1.2\" />\n\n  <!-- Spindle Socket Hole on Top Surface -->\n  <ellipse cx=\"300\" cy=\"205\" rx=\"26\" ry=\"12\" fill=\"#0d0d0d\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\" />\n  <circle cx=\"300\" cy=\"205\" r=\"4\" fill=\"#E02424\" />\n\n  <!-- 45-degree V-Notch carved from outer edge inward to socket center -->\n  <!-- Wedge cut into top surface and vertical front face -->\n  <polygon points=\"300,205 260,230 340,230\" fill=\"#0d0d0d\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Vertical notch slot cut down through front edge -->\n  <polygon points=\"260,230 340,230 340,265 260,265\" fill=\"#080808\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 45° Angle Indicator Arc inside Notch -->\n  <path d=\"M 285,215 A 20 20 0 0 0 315,215\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <line x1=\"325\" y1=\"222\" x2=\"350\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"355\" y=\"248\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"start\">45° V자 홈 (막대 중심까지 파기)</text>\n\n  <!-- Spindle Axis (Ghosted Shaft entering Socket) -->\n  <path d=\"M 286,45 L 314,45 L 314,175 L 300,205 L 286,175 Z\" fill=\"#242424\" fill-opacity=\"0.85\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"293\" y1=\"55\" x2=\"293\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n  <line x1=\"307\" y1=\"55\" x2=\"307\" y2=\"170\" stroke=\"#444444\" stroke-width=\"1\" />\n\n  <!-- Spindle Dimension lines (Ø 20mm) -->\n  <line x1=\"270\" y1=\"75\" x2=\"286\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <line x1=\"330\" y1=\"75\" x2=\"314\" y2=\"75\" stroke=\"#888888\" stroke-width=\"1\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"340\" y=\"79\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">두께 2cm 가운데 회전 막대</text>\n\n  <!-- Hearth Board Thickness Dimension: 15~20mm -->\n  <line x1=\"65\" y1=\"230\" x2=\"65\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"230\" x2=\"70\" y2=\"230\" stroke=\"#888888\" stroke-width=\"1\" />\n  <line x1=\"60\" y1=\"265\" x2=\"70\" y2=\"265\" stroke=\"#888888\" stroke-width=\"1\" />\n  <text x=\"20\" y=\"282\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"start\">판 두께: 1.5~2cm</text>\n\n  <!-- Hearth Board label -->\n  <text x=\"130\" y=\"215\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">바닥 받침 나무</text>\n\n  <!-- Notch Apex / Center Seating Pointer -->\n  <line x1=\"160\" y1=\"155\" x2=\"295\" y2=\"203\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"110\" y=\"150\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">V자 홈 끝점 (구멍 한가운데와 일치)</text>\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"25\" width=\"255\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"42\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">핵심 준비 포인트:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">V자 홈 끝이 막대 중심에 딱 닿아야 함</text>\n\n  <!-- Carbon Dust Accumulation Zone (Under Notch Opening) -->\n  <ellipse cx=\"300\" cy=\"278\" rx=\"35\" ry=\"8\" fill=\"#E02424\" fill-opacity=\"0.2\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <line x1=\"300\" y1=\"286\" x2=\"300\" y2=\"310\" stroke=\"#E02424\" stroke-width=\"1\" />\n  <text x=\"300\" y=\"322\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">까만 불씨 가루가 모이는 자리</text>\n</svg>\n","content/svgs/02-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Grid borders -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- Hand Socket Block (Top Pressure Block) -->\n  <path d=\"M 285 25 L 375 25 L 390 55 L 270 55 Z\" fill=\"#222222\" stroke=\"#CCCCCC\" stroke-width=\"1.5\"/>\n  <text x=\"330\" y=\"42\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"middle\">손잡이 누름판</text>\n\n  <!-- Vertical Force Vector F_down -->\n  <line x1=\"330\" y1=\"12\" x2=\"330\" y2=\"25\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"345\" y=\"18\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">위에서 체중 실어 누르기 (12~15kg)</text>\n\n  <!-- Spindle Axis (Rotating cylinder) -->\n  <rect x=\"318\" y=\"55\" width=\"24\" height=\"175\" fill=\"#1e1e1e\" stroke=\"#F5F5F5\" stroke-width=\"1.5\"/>\n  \n  <!-- Bow Cord Looped Around Spindle (1 Turn Loop) -->\n  <!-- Bow Stick -->\n  <path d=\"M 60 135 C 180 110, 480 110, 600 135\" fill=\"none\" stroke=\"#888888\" stroke-width=\"6\" stroke-linecap=\"square\"/>\n  <text x=\"110\" y=\"102\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">활대 (길이 65cm 휘어진 나뭇가지)</text>\n\n  <!-- String with Tension & Single Wrap Loop around Spindle -->\n  <path d=\"M 60 135 L 318 140\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"330\" cy=\"142\" rx=\"16\" ry=\"6\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2.5\"/>\n  <path d=\"M 342 144 L 600 135\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- Horizontal Bow Stroke Sawing Arrows -->\n  <line x1=\"180\" y1=\"160\" x2=\"480\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n  <line x1=\"230\" y1=\"160\" x2=\"190\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <line x1=\"430\" y1=\"160\" x2=\"470\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"330\" y=\"175\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">활대 끝에서 끝까지 길게 당기고 밀기</text>\n\n  <!-- Rotation RPM Velocity Vector -->\n  <path d=\"M 360 85 A 25 15 0 1 1 360 105\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\"/>\n  <text x=\"385\" y=\"98\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" font-weight=\"bold\">빠르게 양방향 회전</text>\n\n  <!-- Hearth Board Base -->\n  <rect x=\"200\" y=\"230\" width=\"260\" height=\"40\" fill=\"#141414\" stroke=\"#888888\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"254\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">바닥 받침 나무</text>\n\n  <!-- Friction Contact Heat & Smoke Generation Point -->\n  <circle cx=\"330\" cy=\"230\" r=\"5\" fill=\"#E02424\"/>\n  \n  <!-- Thermal Wave / Heat Glow Ring -->\n  <circle cx=\"330\" cy=\"230\" r=\"14\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <circle cx=\"330\" cy=\"230\" r=\"24\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"1,3\"/>\n  \n  <!-- Smoke Stream SVG Paths -->\n  <path d=\"M 326 225 Q 315 210 322 195 T 310 180\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 334 225 Q 345 208 338 190 T 350 175\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n  <path d=\"M 330 220 Q 330 200 325 185\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n\n  <text x=\"295\" y=\"210\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">하얀 연기가 피어오름</text>\n\n  <!-- Technical Specification Box on the right -->\n  <rect x=\"490\" y=\"215\" width=\"170\" height=\"70\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"500\" y=\"232\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">불씨 만드는 핵심:</text>\n  <text x=\"500\" y=\"248\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">마찰 열기: 400°C 이상</text>\n  <text x=\"500\" y=\"262\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">누르는 힘: 약하게 → 세게</text>\n  <text x=\"500\" y=\"276\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">활대 전체 길이를 끝까지 사용</text>\n</svg>\n","content/svgs/02-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\"/>\n\n  <!-- LEFT SIDE: TINDER NEST & AIRFLOW DYNAMICS -->\n  <!-- Tinder Nest Cup Profile (Bird's nest shape) -->\n  <path d=\"M 60 250 C 90 280, 230 280, 260 250 C 270 210, 240 180, 160 170 C 80 180, 50 210, 60 250 Z\" \n        fill=\"#181818\" stroke=\"#777777\" stroke-width=\"1.5\"/>\n  <!-- Fibers pattern inside nest -->\n  <path d=\"M 70 230 Q 160 255 250 230\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 80 210 Q 160 240 240 210\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n  <path d=\"M 95 195 Q 160 225 225 195\" fill=\"none\" stroke=\"#444444\" stroke-width=\"1\"/>\n\n  <!-- Central Ember Core (Glowing Hot Carbon Coal) -->\n  <ellipse cx=\"160\" cy=\"220\" rx=\"14\" ry=\"10\" fill=\"#E02424\" stroke=\"#FFAA00\" stroke-width=\"1.5\"/>\n  <circle cx=\"160\" cy=\"220\" r=\"4\" fill=\"#FFEE55\"/>\n  <text x=\"160\" y=\"292\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">달궈진 불씨 덩어리 (450°C)</text>\n\n  <!-- Gentle Air Stream Vectors (Breathing 45-degree angle vectors) -->\n  <path d=\"M 70 120 C 100 130, 120 160, 150 195\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <path d=\"M 90 105 C 120 120, 135 155, 158 190\" fill=\"none\" stroke=\"#00D4FF\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" marker-end=\"url(#arrow-white)\"/>\n  <text x=\"75\" y=\"95\" fill=\"#00D4FF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">길고 부드럽게 입김 불기</text>\n\n  <!-- Smoke and Flame Transition Emitters -->\n  <path d=\"M 160 195 Q 150 150 170 110 T 165 70\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  <path d=\"M 170 195 Q 185 145 175 105 T 190 65\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n  \n  <!-- Ignition Flame Burst Outline (Transient stage) -->\n  <path d=\"M 160 160 Q 140 120 160 90 Q 180 120 160 160 Z\" fill=\"#E02424\" fill-opacity=\"0.3\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  <text x=\"160\" y=\"55\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">불꽃이 확 피어오름</text>\n\n  <!-- Cupping Angle 45° Spec -->\n  <line x1=\"260\" y1=\"250\" x2=\"310\" y2=\"200\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n  <text x=\"275\" y=\"268\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8.5\">45도 기울여 들기</text>\n\n  <!-- RIGHT SIDE: TEMPERATURE IGNITION THRESHOLD GRAPH -->\n  <rect x=\"360\" y=\"45\" width=\"295\" height=\"255\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <text x=\"375\" y=\"68\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">입김 불어 불붙이는 온도 변화</text>\n\n  <!-- Graph Axes -->\n  <line x1=\"410\" y1=\"260\" x2=\"630\" y2=\"260\" stroke=\"#666666\" stroke-width=\"1\"/>\n  <line x1=\"410\" y1=\"260\" x2=\"410\" y2=\"90\" stroke=\"#666666\" stroke-width=\"1\"/>\n\n  <text x=\"630\" y=\"276\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\" text-anchor=\"end\">시간 (초)</text>\n  <text x=\"375\" y=\"95\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">온도 (°C)</text>\n\n  <!-- Threshold Line 600°C Flame Point -->\n  <line x1=\"410\" y1=\"125\" x2=\"630\" y2=\"125\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"120\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">600°C 불꽃이 타오르는 온도</text>\n\n  <!-- Threshold Line 400°C Ember Point -->\n  <line x1=\"410\" y1=\"185\" x2=\"630\" y2=\"185\" stroke=\"#FFAA00\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n  <text x=\"415\" y=\"180\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">400°C 불씨가 유지되는 온도</text>\n\n  <!-- Temperature Curve Line -->\n  <path d=\"M 410 255 Q 460 240 500 185 T 570 125 T 620 100\" fill=\"none\" stroke=\"#F5F5F5\" stroke-width=\"2.5\"/>\n  \n  <!-- Key Milestone Dots -->\n  <circle cx=\"500\" cy=\"185\" r=\"4\" fill=\"#FFAA00\"/>\n  <circle cx=\"570\" cy=\"125\" r=\"4\" fill=\"#E02424\"/>\n  \n  <text x=\"505\" y=\"202\" fill=\"#FFAA00\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">30초 기다린 뒤 옮기기 (0초)</text>\n  <text x=\"650\" y=\"145\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\" text-anchor=\"end\">불꽃 점화 (15~20초)</text>\n</svg>\n","content/svgs/03-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"40\" y1=\"285\" x2=\"360\" y2=\"285\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"2 4\"/>\n\n  <!-- 지지 바위 / 밑동 그루터기 (Fork / Boulder) -->\n  <polygon points=\"60,280 80,180 120,180 140,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"240\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">STUMP FORK</text>\n\n  <!-- 3m 주 기둥 (Ridge Pole: 지지대 1m 높이에서 지면으로 경사) -->\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n  <line x1=\"100\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#000000\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n\n  <!-- 치수선: 지지 높이 1m -->\n  <line x1=\"50\" y1=\"180\" x2=\"50\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M47 185 L50 180 L53 185 M47 275 L50 280 L53 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"42\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\" font-weight=\"bold\">1.0m</text>\n\n  <!-- 치수선: 주 기둥 길이 3m -->\n  <line x1=\"110\" y1=\"165\" x2=\"345\" y2=\"265\" stroke=\"#A3A3A3\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"235\" y=\"205\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">RIDGE POLE (3.0m)</text>\n\n  <!-- 1인 누운 신체 치수 프로파일 (점선) -->\n  <ellipse cx=\"220\" cy=\"270\" rx=\"45\" ry=\"8\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n  <circle cx=\"165\" cy=\"265\" r=\"7\" fill=\"none\" stroke=\"#525252\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"210\" y=\"255\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">BODY FIT SPACE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RIDGE POLE &amp; STRUCTURAL ANCHOR</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SECURE 3m HARDWOOD AT 1m CREST TO MINIMIZE INTERNAL AIR VOLUME</text>\n</svg>\n","content/svgs/03-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 주 기둥 (중앙) -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n\n  <!-- 좌우 45도 빗살 갈비뼈 잔가지 (Rib Poles) -->\n  <!-- 좌측 날개 -->\n  <line x1=\"110\" y1=\"175\" x2=\"70\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"105\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"140\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"175\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"210\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"260\" y1=\"250\" x2=\"245\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"265\" x2=\"280\" y2=\"280\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 우측 날개 (원근 입체 표현) -->\n  <line x1=\"110\" y1=\"175\" x2=\"160\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"140\" y1=\"190\" x2=\"195\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"170\" y1=\"205\" x2=\"230\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"200\" y1=\"220\" x2=\"265\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"230\" y1=\"235\" x2=\"300\" y2=\"280\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 가로 엮음 격자망 (Lattice Framework) -->\n  <path d=\"M 65 250 Q 150 200 235 250\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <path d=\"M 75 220 Q 130 185 195 220\" fill=\"none\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n\n  <!-- 45도 각도 호선 인디케이터 -->\n  <path d=\"M 120 280 A 25 25 0 0 1 135 258\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"145\" y=\"270\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">45° SLOPE</text>\n\n  <!-- 간격 표시 (10cm Spacing) -->\n  <line x1=\"70\" y1=\"290\" x2=\"105\" y2=\"290\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"87\" y=\"303\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">&lt; 10cm &gt;</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 45° RIB SKELETON &amp; LATTICE</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DENSELY PACK RIBS EVERY 10cm TO PREVENT DEBRIS COLLAPSE</text>\n</svg>\n","content/svgs/03-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-03 [DEBRIS-HUT-SHELTER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 지면 기준선 -->\n  <line x1=\"40\" y1=\"280\" x2=\"360\" y2=\"280\" stroke=\"#404040\" stroke-width=\"2\"/>\n\n  <!-- 1m 외부 낙엽 돔 윤곽선 (Debris Mound) -->\n  <path d=\"M 50 280 Q 90 90 200 90 Q 310 90 350 280 Z\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 내부 골조 단면 (점선) -->\n  <path d=\"M 100 280 Q 130 180 200 180 Q 270 180 300 280\" fill=\"#050505\" stroke=\"#737373\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n\n  <!-- 바닥 40cm 마른 낙엽 단열 매트리스 (Ground Insulation) -->\n  <rect x=\"105\" y=\"245\" width=\"190\" height=\"35\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"105\" y1=\"262\" x2=\"295\" y2=\"262\" stroke=\"#525252\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"200\" y=\"267\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">40cm GROUND BED [LEAVES]</text>\n\n  <!-- 외벽 1m 두께 치수선 -->\n  <line x1=\"75\" y1=\"180\" x2=\"140\" y2=\"210\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 78 186 L 75 180 L 82 178 M 133 212 L 140 210 L 137 204\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"100\" y=\"188\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"black\">1.0m THICK</text>\n\n  <!-- 외벽 솔잎 비늘 빗물 유도 층 (Thatch / Pine Shingles) -->\n  <path d=\"M 120 120 L 110 135 M 140 105 L 130 120 M 260 105 L 270 120 M 280 120 L 290 135\" stroke=\"#A3A3A3\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"115\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">WATER-SHEDDING PINE THATCH</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: 1m DEBRIS MOUND &amp; 40cm BED</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER SLEEP ON BARE GROUND; PILE LEAVES ARM-DEEP TO SEAL BODY HEAT</text>\n</svg>\n","content/svgs/04-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 작업대 받침돌 (Anvil Stone) -->\n  <polygon points=\"100,280 140,220 260,220 300,280\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"260\" fill=\"#525252\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">ANVIL STONE</text>\n\n  <!-- 가공할 규암 원석 도끼날 (Quartzite Core) -->\n  <polygon points=\"150,220 180,130 230,130 250,220\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 둥근 망치돌 (Hammerstone) -->\n  <circle cx=\"270\" cy=\"100\" r=\"28\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"104\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HAMMER</text>\n\n  <!-- 70도 타격 궤적 벡터 화살표 -->\n  <path d=\"M 255 125 L 215 155\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <polygon points=\"215,155 228,148 221,140\" fill=\"#FFFFFF\"/>\n  <text x=\"260\" y=\"145\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">70° STRIKE</text>\n\n  <!-- 박편 파편 비산 궤적 (Flakes Splitting) -->\n  <polygon points=\"175,145 160,160 170,170\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <polygon points=\"140,180 120,195 135,205\" fill=\"#737373\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"180\" y1=\"150\" x2=\"130\" y2=\"190\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n  <text x=\"110\" y=\"175\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">CHIPPED FLAKES</text>\n\n  <!-- 양날 각도 표시 -->\n  <path d=\"M 180 130 L 165 110 M 230 130 L 245 110\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"205\" y=\"115\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIFACIAL BEVEL</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 70° HAMMERSTONE PERCUSSION FLAKING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STRIKE QUARTZITE RIM AT 70° TO DETACH RAZOR SHARP BIFACIAL FLAKES</text>\n</svg>\n","content/svgs/04-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 참나무 Y자 손잡이 (Hardwood Y-Haft) -->\n  <!-- 메인 손잡이 몸체 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- Y자 갈래 좌측/우측 포크 -->\n  <path d=\"M 185 160 Q 170 120 145 90 L 165 80 Q 195 115 200 140 Q 205 115 235 80 L 255 90 Q 230 120 215 160 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n\n  <!-- 가공된 석기 도끼날 (결합 위치) -->\n  <polygon points=\"120,110 200,60 280,110 230,170 170,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 날 부분 강조선 -->\n  <path d=\"M 120 110 L 200 60 L 280 110\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"85\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">AXE BLADE</text>\n\n  <!-- 요철 결합 음각 가공 표시 (Notch Fit) -->\n  <line x1=\"170\" y1=\"170\" x2=\"160\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <line x1=\"230\" y1=\"170\" x2=\"240\" y2=\"190\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"200\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">FIRE-CARVED MORTISE SEAT</text>\n\n  <!-- 손잡이 규격 치수 -->\n  <line x1=\"225\" y1=\"225\" x2=\"265\" y2=\"225\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"270\" y=\"228\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">Ø 3.5cm OAK</text>\n\n  <!-- 압입 방향 화살표 (Downward Force) -->\n  <line x1=\"200\" y1=\"35\" x2=\"200\" y2=\"55\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"200,55 195,45 205,45\" fill=\"#FFFFFF\"/>\n  <text x=\"200\" y=\"30\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">PRESSURE FIT</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: Y-FORK NOTCH FIT &amp; CHARRED SEAT</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SLIGHTLY CHAR WOOD INTERIOR TO MOLD NEGATIVE CAVITY EXACTLY TO BLADE</text>\n</svg>\n","content/svgs/04-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-04 [PRIMITIVE-STONE-AXE]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 조립된 도끼 손잡이 및 석기 날 -->\n  <rect x=\"185\" y=\"160\" width=\"30\" height=\"130\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <polygon points=\"130,110 200,60 270,110 225,170 175,170\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 8자형 교차 칡 섬유 바인딩 (Figure-8 Lashings) -->\n  <line x1=\"140\" y1=\"120\" x2=\"230\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"145\" y1=\"130\" x2=\"225\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"150\" y1=\"140\" x2=\"220\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <line x1=\"260\" y1=\"120\" x2=\"170\" y2=\"190\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"255\" y1=\"130\" x2=\"175\" y2=\"200\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n  <line x1=\"250\" y1=\"140\" x2=\"180\" y2=\"210\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 수평 감기 밴드 (Frapping Turns) -->\n  <rect x=\"175\" y=\"155\" width=\"50\" height=\"25\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/>\n\n  <!-- 송진 + 숯가루 혼합 코팅층 (Black Pine Pitch Cement) -->\n  <path d=\"M 160 145 Q 200 135 240 145 Q 235 215 200 215 Q 165 215 160 145 Z\" fill=\"#0A0A0A\" fill-opacity=\"0.7\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 3\"/>\n  <text x=\"200\" y=\"235\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">PINE PITCH + CHARCOAL CEMENT</text>\n\n  <!-- 수축 장력 화살표 (Shrinkage Tension) -->\n  <path d=\"M 140 185 L 160 175 M 260 185 L 240 175\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"190\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">WET KUDZU SHRINKAGE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: FIGURE-8 LASHINGS &amp; RESIN SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">WET FIBERS SHRINK TIGHT LIKE IRON; SEAL WITH CHARCOAL PITCH TO LOCK</text>\n</svg>\n","content/svgs/05-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 절단된 식물 줄기 단면 (Cut Stem) -->\n  <rect x=\"180\" y=\"110\" width=\"40\" height=\"110\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"110\" rx=\"20\" ry=\"8\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 유백색 독성 유즙 방출 (Milky White Sap Drop) -->\n  <path d=\"M 195 118 Q 190 145 200 155 Q 210 145 205 118 Z\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <ellipse cx=\"200\" cy=\"170\" rx=\"12\" ry=\"16\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  \n  <!-- 치명적 독성 금지 표식 (Disallowed Cross) -->\n  <circle cx=\"200\" cy=\"170\" r=\"32\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"177\" y1=\"147\" x2=\"223\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"223\" y1=\"147\" x2=\"177\" y2=\"193\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n  <!-- 배제 판별 텍스트 박스 -->\n  <rect x=\"50\" y=\"235\" width=\"300\" height=\"60\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"255\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">1. MILKY SAP (LATEX ALKALOIDS) ➔ DISCARD</text>\n  <text x=\"65\" y=\"272\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">2. BITTER ALMOND ODOR (CYANIDE) ➔ DISCARD</text>\n  <text x=\"65\" y=\"287\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"10\">3. FINE STINGING HAIRS ➔ DISCARD</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: IMMEDIATE VISUAL &amp; OLFACTORY EXCLUSION</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">IMMEDIATELY REJECT ANY SPECIMEN WITH MILKY SAP OR ALMOND SCENT</text>\n</svg>\n","content/svgs/05-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 사람 팔 전완부 윤곽선 (Inner Forearm) -->\n  <path d=\"M 60 160 C 120 155 240 150 340 140 L 340 220 C 240 215 120 220 60 210 Z\" fill=\"#141414\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <text x=\"90\" y=\"190\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\">INNER FOREARM</text>\n\n  <!-- 식물 즙 도포 테스트 스팟 (Test Patch) -->\n  <circle cx=\"210\" cy=\"180\" r=\"18\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <circle cx=\"210\" cy=\"180\" r=\"26\" fill=\"none\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <!-- 즙 도포 화살표 -->\n  <path d=\"M 210 110 L 210 155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"210,155 205,145 215,145\" fill=\"#FFFFFF\"/>\n  <text x=\"210\" y=\"100\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">RUB CRUSHED SAP</text>\n\n  <!-- 15분 경과 스톱워치 다이얼 (15 MIN Stopwatch) -->\n  <circle cx=\"290\" cy=\"180\" r=\"30\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"290\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <line x1=\"290\" y1=\"180\" x2=\"315\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <path d=\"M 290 155 A 25 25 0 0 1 315 180\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <text x=\"290\" y=\"225\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">15 MIN WAIT</text>\n\n  <!-- 이상 반응 감시 체크리스트 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">OBSERVE: ERYTHEMA / ITCHING / HIVES</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; IF BURNING SENSATION OCCURS ➔ RINSE IMMEDIATELY</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: DERMAL CONTACT &amp; 15-MINUTE MONITORING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">RUB JUICE ON SENSITIVE INNER ARM; WAIT 15 MIN FOR HISTAMINE REACTION</text>\n</svg>\n","content/svgs/05-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-05 [EDIBLE-PLANT-TEST]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 입술 및 혀 측면 프로파일 도해 (Oral Profile) -->\n  <path d=\"M 120 120 Q 170 120 190 140 Q 210 160 180 180 Q 210 190 190 220 Q 150 230 110 230\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 혀 (Tongue Extended) -->\n  <path d=\"M 175 175 C 220 170 250 185 240 200 C 220 210 185 200 175 195\" fill=\"#1F1F1F\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"210\" y=\"195\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">TONGUE TIP</text>\n\n  <!-- 식물 잎 미세 조각 안치 (Specimen Fragment) -->\n  <polygon points=\"245,185 260,180 255,195 240,195\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <line x1=\"260\" y1=\"160\" x2=\"252\" y2=\"182\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"265\" y=\"155\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" font-weight=\"bold\">LEAF PIECE (15 MIN)</text>\n\n  <!-- 침 삼킴 금지 경고 배지 (DO NOT SWALLOW) -->\n  <rect x=\"220\" y=\"80\" width=\"130\" height=\"40\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"285\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"black\">DO NOT SWALLOW</text>\n  <text x=\"285\" y=\"112\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">HOLD SALIVA IN MOUTH</text>\n\n  <!-- 단계별 시간 프로토콜 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"258\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP A: OUTER LIP CONTACT ➔ 3 MINUTES</text>\n  <text x=\"65\" y=\"275\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">STEP B: TONGUE TIP CONTACT ➔ 15 MINUTES</text>\n  <text x=\"65\" y=\"290\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\">&gt; IF NUMBNESS OR BITTERNESS ➔ SPIT &amp; RINSE x3</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: LIP &amp; TONGUE TIP PROGRESSIVE CHECK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">NEVER CHEW OR SWALLOW; DETECT NUMBNESS BEFORE ANY INGESTION</text>\n</svg>\n","content/svgs/06-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 지표면 선 -->\n  <line x1=\"40\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <text x=\"50\" y=\"170\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">GROUND LEVEL</text>\n\n  <!-- 깔때기형 원형 웅덩이 단면 (Pit Excavation) -->\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 직경 1.0m 치수선 -->\n  <line x1=\"80\" y1=\"160\" x2=\"320\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 85 155 L 80 160 L 85 165 M 315 155 L 320 160 L 315 165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"152\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"bold\">DIAMETER 1.0m</text>\n\n  <!-- 깊이 50cm 치수선 -->\n  <line x1=\"340\" y1=\"180\" x2=\"340\" y2=\"280\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M 335 185 L 340 180 L 345 185 M 335 275 L 340 280 L 345 275\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"235\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">0.5m</text>\n\n  <!-- 바닥 중앙 토기 안착 홈 (Pot Hollow) -->\n  <rect x=\"180\" y=\"275\" width=\"40\" height=\"15\" fill=\"#262626\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"298\" fill=\"#737373\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">POT HOLLOW</text>\n\n  <!-- 경사벽 생 잎사귀 충진 (Transpiration Foliage) -->\n  <circle cx=\"120\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"150\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"210\" r=\"12\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"245\" r=\"10\" fill=\"#1C1C1C\" stroke=\"#A3A3A3\" stroke-width=\"1\"/>\n  <text x=\"135\" y=\"230\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\">NON-TOXIC LEAVES (2x YIELD)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: 1m CONICAL PIT &amp; FOLIAGE PACK</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">DIG 1m x 0.5m PIT IN SUNNY GROUND; PACK WITH EDIBLE LEAVES FOR TRANSPIRATION</text>\n</svg>\n","content/svgs/06-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 지표면 및 웅덩이 -->\n  <line x1=\"40\" y1=\"180\" x2=\"80\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <line x1=\"320\" y1=\"180\" x2=\"360\" y2=\"180\" stroke=\"#404040\" stroke-width=\"2\"/>\n  <path d=\"M 80 180 Q 140 280 200 280 Q 260 280 320 180\" fill=\"#121212\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Collection Pot) -->\n  <rect x=\"180\" y=\"225\" width=\"40\" height=\"45\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"225\" rx=\"20\" ry=\"6\" fill=\"#141414\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"252\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">COLLECTION POT</text>\n\n  <!-- 상단 수평 밀폐 시트 (Tarp / Large Leaf Membrane) -->\n  <line x1=\"60\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n\n  <!-- 양 끝단 흙/모래 밀폐 둑 (Dirt/Sand Seal Bank) -->\n  <polygon points=\"50,180 85,150 110,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <polygon points=\"290,180 315,150 350,180\" fill=\"#262626\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOIL SEAL</text>\n  <text x=\"320\" y=\"145\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">AIR-TIGHT</text>\n\n  <!-- 밀폐 압력 및 온도 상승 인디케이터 (55°C Greenhouse) -->\n  <rect x=\"140\" y=\"90\" width=\"120\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"105\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">INTERNAL TEMP &gt; 55°C</text>\n  <text x=\"200\" y=\"118\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">SATURATED VAPOR PRESSURE</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: POT CENTERED &amp; PERIMETER AIRTIGHT SEAL</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">ANCHOR EDGES WITH WET SOIL; COMPLETE SEAL REQUIRED FOR 55°C VAPORIZATION</text>\n</svg>\n","content/svgs/06-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-06 [SOLAR-STILL-WATER]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 웅덩이 단면 -->\n  <path d=\"M 80 160 Q 140 280 200 280 Q 260 280 320 160\" fill=\"#121212\" stroke=\"#404040\" stroke-width=\"1.5\"/>\n\n  <!-- 중앙 수거 토기 (Clay Pot) -->\n  <rect x=\"180\" y=\"230\" width=\"40\" height=\"40\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <!-- 모인 순수 증류수 수면 -->\n  <rect x=\"182\" y=\"250\" width=\"36\" height=\"18\" fill=\"#FFFFFF\" fill-opacity=\"0.8\"/>\n  <text x=\"200\" y=\"263\" fill=\"#000000\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"bold\">PURE H2O</text>\n\n  <!-- 역원뿔 형태로 처진 덮개 시트 (Inverted Cone Sheet) -->\n  <path d=\"M 70 160 L 200 210 L 330 160\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n  <!-- 중앙 중심 추 (Weight Stone) -->\n  <ellipse cx=\"200\" cy=\"207\" rx=\"14\" ry=\"7\" fill=\"#1A1A1A\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"200\" y=\"195\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">STONE WEIGHT</text>\n\n  <!-- 간격 확인 (5cm Clearance) -->\n  <line x1=\"225\" y1=\"210\" x2=\"225\" y2=\"230\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"240\" y=\"222\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\">&gt; 5cm GAP</text>\n\n  <!-- 시트 하단 수증기 응결 및 낙하 물방울 (Condensation Droplets) -->\n  <circle cx=\"150\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"175\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"250\" cy=\"180\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"225\" cy=\"195\" r=\"3.5\" fill=\"#FFFFFF\"/>\n  \n  <!-- 중앙 낙하 궤적 (Dripping Line) -->\n  <line x1=\"200\" y1=\"215\" x2=\"200\" y2=\"245\" stroke=\"#FFFFFF\" stroke-width=\"2\" stroke-dasharray=\"2 3\"/>\n  <polygon points=\"200,248 197,242 203,242\" fill=\"#FFFFFF\"/>\n  <text x=\"145\" y=\"228\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\">STERILE CONDENSATE</text>\n\n  <!-- 태양열 복사 화살표 (Solar Radiation Vectors) -->\n  <line x1=\"120\" y1=\"80\" x2=\"140\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"200\" y1=\"70\" x2=\"200\" y2=\"115\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <line x1=\"280\" y1=\"80\" x2=\"260\" y2=\"120\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"65\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">SOLAR THERMAL FLUX</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: INVERTED CONE CONDENSATION DRIP</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STONE DRIVES CONDENSED DROPLETS TO INCLINE PEAK; DRIPS 100% STERILE WATER</text>\n</svg>\n","content/svgs/07-step-01.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 01</text>\n\n  <!-- 소나무 수피 단면 (Pine Bark Trunk) -->\n  <rect x=\"60\" y=\"90\" width=\"70\" height=\"190\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n  <!-- 소나무 상처 및 송진 덩어리 (Resin Globules) -->\n  <polygon points=\"130,130 110,145 130,160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <ellipse cx=\"132\" cy=\"175\" rx=\"8\" ry=\"14\" fill=\"#FFFFFF\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <text x=\"75\" y=\"145\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"9\">PINE TRUNK</text>\n\n  <!-- 긁어모으는 석기 스크레이퍼 -->\n  <polygon points=\"165,150 145,170 155,180\" fill=\"#E5E5E5\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <path d=\"M 160 160 L 140 175\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"140,175 145,168 148,175\" fill=\"#FFFFFF\"/>\n  <text x=\"175\" y=\"165\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\">SCRAPE RAW RESIN</text>\n\n  <!-- 오목한 조리 편평석 (Concave Hearth Stone) -->\n  <path d=\"M 210 210 Q 280 250 350 210 L 330 260 Q 280 270 230 260 Z\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <!-- 녹은 액상 송진 웅덩이 -->\n  <ellipse cx=\"280\" cy=\"225\" rx=\"45\" ry=\"12\" fill=\"#FFFFFF\" fill-opacity=\"0.9\"/>\n  <text x=\"280\" y=\"228\" fill=\"#000000\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">LIQUID RESIN (MELTED)</text>\n\n  <!-- 하부 숯불 간접열 (Charcoal Indirect Heat) -->\n  <circle cx=\"250\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"280\" cy=\"285\" r=\"9\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <circle cx=\"310\" cy=\"280\" r=\"8\" fill=\"#404040\" stroke=\"#737373\" stroke-width=\"1\"/>\n  <path d=\"M 280 275 L 280 250\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n  <text x=\"280\" y=\"302\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\">INDIRECT COAL HEAT (NO DIRECT FLAME)</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 01: RESIN HARVEST &amp; GENTLE INDIRECT MELTING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">SCRAPE HARD AMBER RESIN; MELT GENTLY OVER COALS AWAY FROM OPEN FIRE</text>\n</svg>\n","content/svgs/07-step-02.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 02</text>\n\n  <!-- 조약돌 조제 보울 (Stone Mortar Bowl) -->\n  <ellipse cx=\"200\" cy=\"180\" rx=\"90\" ry=\"35\" fill=\"#1A1A1A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <ellipse cx=\"200\" cy=\"180\" rx=\"75\" ry=\"25\" fill=\"#0F0F0F\" stroke=\"#737373\" stroke-width=\"1\"/>\n\n  <!-- 3:1 혼합 비율 인디케이터 (3:1 Ratio) -->\n  <rect x=\"140\" y=\"80\" width=\"120\" height=\"40\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n  <text x=\"200\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"black\">RATIO 3 : 1</text>\n  <text x=\"200\" y=\"112\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">RESIN (3) + STERILE CHARCOAL (1)</text>\n\n  <!-- 숯가루 살포 투입 궤적 (Charcoal Powder Dusting) -->\n  <circle cx=\"160\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <circle cx=\"170\" cy=\"148\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"190\" cy=\"142\" r=\"3\" fill=\"#FFFFFF\"/>\n  <circle cx=\"210\" cy=\"145\" r=\"2\" fill=\"#FFFFFF\"/>\n  <circle cx=\"230\" cy=\"140\" r=\"2.5\" fill=\"#FFFFFF\"/>\n  <line x1=\"200\" y1=\"125\" x2=\"200\" y2=\"155\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 혼합 교반 스틱 (Wooden Stirring Paddle) -->\n  <line x1=\"260\" y1=\"110\" x2=\"210\" y2=\"185\" stroke=\"#E5E5E5\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <!-- 회전 교반 화살표 (Vigorous Stirring) -->\n  <path d=\"M 175 185 A 25 10 0 1 0 225 185\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <polygon points=\"225,181 231,188 223,191\" fill=\"#FFFFFF\"/>\n\n  <!-- 연고 경화 텍스처 박스 -->\n  <rect x=\"50\" y=\"240\" width=\"300\" height=\"55\" fill=\"#0A0A0A\" stroke=\"#404040\" stroke-width=\"1\"/>\n  <text x=\"65\" y=\"260\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\">ANTISEPTIC: TERPENES + ACTIVATED CARBON</text>\n  <text x=\"65\" y=\"278\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">&gt; BINDS BACTERIA &amp; COATS AGAINST ANAEROBIC TETANUS</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 02: 3:1 STERILE CHARCOAL BLEND &amp; SALVE COMPOUNDING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">STIR CRUSHED CHARCOAL INTO WARM RESIN UNTIL IT FORMS A PLIABLE BLACK SALVE</text>\n</svg>\n","content/svgs/07-step-03.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\">\n  <rect width=\"400\" height=\"400\" fill=\"#050505\"/>\n  <rect x=\"20\" y=\"20\" width=\"360\" height=\"360\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <rect x=\"24\" y=\"24\" width=\"352\" height=\"352\" fill=\"none\" stroke=\"#171717\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n\n  <!-- 헤더 스탬프 -->\n  <text x=\"32\" y=\"44\" fill=\"#737373\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\">PROTOCOL // PR-07 [PINE-RESIN-OINTMENT]</text>\n  <text x=\"368\" y=\"44\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">STEP 03</text>\n\n  <!-- 팔뚝 환부 단면 (Wounded Arm Section) -->\n  <rect x=\"60\" y=\"160\" width=\"280\" height=\"60\" fill=\"#141414\" stroke=\"#737373\" stroke-width=\"1.5\"/>\n\n  <!-- 상처 열상 부위 (Laceration Wound) -->\n  <line x1=\"160\" y1=\"160\" x2=\"240\" y2=\"160\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n  <line x1=\"180\" y1=\"155\" x2=\"220\" y2=\"165\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n\n  <!-- 두꺼운 송진 연고 도포층 (Thick Ointment Seal, 40°C Warm) -->\n  <path d=\"M 140 160 Q 200 140 260 160\" fill=\"#262626\" stroke=\"#FFFFFF\" stroke-width=\"4\"/>\n  <text x=\"200\" y=\"132\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">WARM SALVE SEAL (40°C)</text>\n\n  <!-- 멸균 자작나무 껍질 붕대 감기 (Birch Bark Wrap Bandage) -->\n  <path d=\"M 120 150 L 150 230 M 160 150 L 190 230 M 210 150 L 240 230 M 250 150 L 280 230\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"250\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">BIRCH BARK BANDAGE COMPRESSION</text>\n\n  <!-- 100% 방수 및 혐기성 차단 배지 -->\n  <rect x=\"50\" y=\"80\" width=\"300\" height=\"35\" fill=\"#0A0A0A\" stroke=\"#FFFFFF\" stroke-width=\"1\"/>\n  <text x=\"200\" y=\"95\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"bold\">WATERPROOF + ANTIMICROBIAL BARRIER</text>\n  <text x=\"200\" y=\"107\" fill=\"#A3A3A3\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">CLEAN WITH BOILED WATER BEFORE APPLICATION</text>\n\n  <!-- 하단 캡션 -->\n  <rect x=\"32\" y=\"320\" width=\"336\" height=\"44\" fill=\"#0A0A0A\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"44\" y=\"338\" fill=\"#E5E5E5\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">PHASE 03: WARM APPLICATION &amp; BIRCH BARK DRESSING</text>\n  <text x=\"44\" y=\"353\" fill=\"#737373\" font-family=\"monospace\" font-size=\"9\">COOL TO BODY TEMP (~40°C); APPLY THICK LAYER AND BIND TO HALT SEPSIS</text>\n</svg>\n","content/svgs/pr01-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Background & Frame Gradients -->\n    <linearGradient id=\"bgGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"woodTripod\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a3728\"/>\n      <stop offset=\"50%\" stop-color=\"#73543d\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2b1f\"/>\n    </linearGradient>\n    <linearGradient id=\"cylinderGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#2a2a2a\" stop-opacity=\"0.8\"/>\n      <stop offset=\"30%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"70%\" stop-color=\"#404040\" stop-opacity=\"0.2\"/>\n      <stop offset=\"100%\" stop-color=\"#222222\" stop-opacity=\"0.8\"/>\n    </linearGradient>\n\n    <!-- Filter Layers Gradients -->\n    <linearGradient id=\"muddyWater\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#5c4028\"/>\n      <stop offset=\"100%\" stop-color=\"#422e1c\"/>\n    </linearGradient>\n    <linearGradient id=\"pebbleGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6e6e6e\"/>\n      <stop offset=\"50%\" stop-color=\"#4f4f4f\"/>\n      <stop offset=\"100%\" stop-color=\"#383838\"/>\n    </linearGradient>\n    <linearGradient id=\"coarseSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#998059\"/>\n      <stop offset=\"100%\" stop-color=\"#7a6341\"/>\n    </linearGradient>\n    <linearGradient id=\"fineSand\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#c9ad7d\"/>\n      <stop offset=\"100%\" stop-color=\"#ad9162\"/>\n    </linearGradient>\n    <linearGradient id=\"charcoalGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#222222\"/>\n      <stop offset=\"50%\" stop-color=\"#141414\"/>\n      <stop offset=\"100%\" stop-color=\"#0a0a0a\"/>\n    </linearGradient>\n    <linearGradient id=\"fiberGrad\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#8a7e6b\"/>\n      <stop offset=\"100%\" stop-color=\"#635847\"/>\n    </linearGradient>\n\n    <!-- Purified Water Gradient & Glow -->\n    <linearGradient id=\"pureWater\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\"/>\n      <stop offset=\"50%\" stop-color=\"#0284c7\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\"/>\n    </linearGradient>\n    <radialGradient id=\"dropletGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#bae6fd\" stop-opacity=\"0.9\"/>\n      <stop offset=\"60%\" stop-color=\"#38bdf8\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#0284c7\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"waterSurface\" cx=\"50%\" cy=\"30%\" r=\"70%\">\n      <stop offset=\"0%\" stop-color=\"#7dd3fc\" stop-opacity=\"0.8\"/>\n      <stop offset=\"100%\" stop-color=\"#0369a1\" stop-opacity=\"0.9\"/>\n    </radialGradient>\n\n    <!-- Technical Drop Shadow -->\n    <filter id=\"subtleShadow\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feDropShadow dx=\"0\" dy=\"4\" stdDeviation=\"6\" flood-color=\"#000000\" flood-opacity=\"0.7\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad1)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshair Registration Markers -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Technical Watermark / Metadata -->\n  <text x=\"35\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"74\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 5-TIER STRATIFIED PURIFIER [100% SPEC]</text>\n  <text x=\"765\" y=\"60\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">FLOW RATE: 1.5L / HR</text>\n\n  <!-- Tripod Legs (Behind Cylinder) -->\n  <g id=\"tripod\">\n    <!-- Back Leg -->\n    <polygon points=\"398,50 402,50 435,390 425,390\" fill=\"#3b2b1f\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Left Leg -->\n    <polygon points=\"396,50 400,50 280,395 270,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Right Leg -->\n    <polygon points=\"400,50 404,50 530,395 520,395\" fill=\"url(#woodTripod)\" stroke=\"#261b13\" stroke-width=\"1\"/>\n    <!-- Lashing at Apex -->\n    <ellipse cx=\"400\" cy=\"56\" rx=\"14\" ry=\"7\" fill=\"#695138\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"400\" cy=\"62\" rx=\"13\" ry=\"6\" fill=\"#54402c\" stroke=\"#3b2b1f\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Filter Funnel Housing (Glass/PET/Clay Cutaway) -->\n  <g id=\"filterHousing\" filter=\"url(#subtleShadow)\">\n    <!-- Outer Cylinder Wall -->\n    <path d=\"M 340 90 L 460 90 L 440 270 L 415 310 L 415 330 L 385 330 L 385 310 L 360 270 Z\" fill=\"url(#cylinderGrad)\" stroke=\"#4a4a4a\" stroke-width=\"2\"/>\n\n    <!-- Layer 0: Raw Muddy Water (Top Level) -->\n    <polygon points=\"342,92 458,92 454,120 346,120\" fill=\"url(#muddyWater)\"/>\n    <ellipse cx=\"400\" cy=\"92\" rx=\"58\" ry=\"6\" fill=\"#6e4f33\" stroke=\"#8c6643\" stroke-width=\"1\"/>\n    <!-- Floating particulates in muddy water -->\n    <circle cx=\"370\" cy=\"105\" r=\"1.5\" fill=\"#382617\"/>\n    <circle cx=\"420\" cy=\"102\" r=\"2\" fill=\"#2b1d11\"/>\n    <circle cx=\"395\" cy=\"112\" r=\"1.8\" fill=\"#3d2817\"/>\n\n    <!-- Layer 1: Pebbles & Coarse Gravel -->\n    <polygon points=\"346,120 454,120 450,155 350,155\" fill=\"url(#pebbleGrad)\"/>\n    <!-- Illustrated round pebbles -->\n    <ellipse cx=\"365\" cy=\"130\" rx=\"9\" ry=\"6\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"385\" cy=\"128\" rx=\"8\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"405\" cy=\"132\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"428\" cy=\"129\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"442\" cy=\"133\" rx=\"7\" ry=\"5\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"355\" cy=\"144\" rx=\"8\" ry=\"6\" fill=\"#666\" stroke=\"#333\"/>\n    <ellipse cx=\"378\" cy=\"145\" rx=\"10\" ry=\"7\" fill=\"#777\" stroke=\"#444\"/>\n    <ellipse cx=\"400\" cy=\"144\" rx=\"9\" ry=\"6\" fill=\"#555\" stroke=\"#333\"/>\n    <ellipse cx=\"422\" cy=\"146\" rx=\"8\" ry=\"5\" fill=\"#888\" stroke=\"#444\"/>\n    <ellipse cx=\"440\" cy=\"145\" rx=\"7\" ry=\"5\" fill=\"#666\" stroke=\"#333\"/>\n\n    <!-- Layer 2: Coarse River Sand -->\n    <polygon points=\"350,155 450,155 446,190 354,190\" fill=\"url(#coarseSand)\"/>\n    <!-- Sand speckles -->\n    <line x1=\"358\" y1=\"172\" x2=\"442\" y2=\"172\" stroke=\"#665235\" stroke-dasharray=\"2 3\" stroke-width=\"1\"/>\n    <line x1=\"360\" y1=\"180\" x2=\"440\" y2=\"180\" stroke=\"#665235\" stroke-dasharray=\"3 4\" stroke-width=\"1\"/>\n\n    <!-- Layer 3: Fine Silica Sand -->\n    <polygon points=\"354,190 446,190 442,225 358,225\" fill=\"url(#fineSand)\"/>\n    <line x1=\"362\" y1=\"205\" x2=\"438\" y2=\"205\" stroke=\"#8f764d\" stroke-dasharray=\"1 2\" stroke-width=\"0.8\"/>\n    <line x1=\"364\" y1=\"215\" x2=\"436\" y2=\"215\" stroke=\"#8f764d\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 4: Activated Crushed Charcoal -->\n    <polygon points=\"358,225 442,225 438,265 362,265\" fill=\"url(#charcoalGrad)\"/>\n    <!-- Charcoal granular facets -->\n    <polygon points=\"370,235 382,232 380,245 368,242\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"392,238 406,234 404,248 390,246\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"418,235 430,233 428,245 415,244\" fill=\"#333\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"375,250 388,248 386,260 373,258\" fill=\"#2a2a2a\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"398,252 412,249 410,262 396,260\" fill=\"#383838\" stroke=\"#111\" stroke-width=\"0.8\"/>\n    <polygon points=\"420,250 432,248 430,260 418,258\" fill=\"#222\" stroke=\"#111\" stroke-width=\"0.8\"/>\n\n    <!-- Layer 5: Cloth / Fiber Filter Plug -->\n    <polygon points=\"362,265 438,265 415,310 385,310\" fill=\"url(#fiberGrad)\"/>\n    <path d=\"M 370 275 Q 400 285 430 275 M 378 290 Q 400 300 422 290\" stroke=\"#473f32\" stroke-width=\"1.2\" fill=\"none\"/>\n\n    <!-- Spout Opening & Perforations -->\n    <rect x=\"385\" y=\"310\" width=\"30\" height=\"20\" fill=\"#1f1f1f\" stroke=\"#444\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Flowing Purified Water & Droplet Dynamics -->\n  <g id=\"purifiedDrop\">\n    <!-- Stream Line -->\n    <line x1=\"400\" y1=\"330\" x2=\"400\" y2=\"348\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\" opacity=\"0.8\"/>\n    <!-- Clear Droplet with Radial Glow -->\n    <ellipse cx=\"400\" cy=\"358\" rx=\"6\" ry=\"10\" fill=\"url(#dropletGlow)\"/>\n    <path d=\"M 400 350 C 397 355 395 358 395 362 C 395 365 397 367 400 367 C 403 367 405 365 405 362 C 405 358 403 355 400 350 Z\" fill=\"url(#pureWater)\"/>\n    <circle cx=\"398\" cy=\"360\" r=\"1.5\" fill=\"#ffffff\" opacity=\"0.9\"/>\n  </g>\n\n  <!-- Collection Pot / Water Receptacle -->\n  <g id=\"collectionPot\" filter=\"url(#subtleShadow)\">\n    <!-- Pot Body -->\n    <path d=\"M 330 375 C 330 370 345 365 400 365 C 455 365 470 370 470 375 L 458 420 C 458 428 435 432 400 432 C 365 432 342 428 342 420 Z\" fill=\"#24211d\" stroke=\"#3d3730\" stroke-width=\"2\"/>\n    <!-- Water Level Inside Pot -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"60\" ry=\"10\" fill=\"url(#waterSurface)\"/>\n    <!-- Water Ripple Circles from Droplet Impact -->\n    <ellipse cx=\"400\" cy=\"385\" rx=\"14\" ry=\"3.5\" fill=\"none\" stroke=\"#bae6fd\" stroke-width=\"1.2\" opacity=\"0.8\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"28\" ry=\"6\" fill=\"none\" stroke=\"#7dd3fc\" stroke-width=\"1\" opacity=\"0.6\"/>\n    <ellipse cx=\"400\" cy=\"385\" rx=\"42\" ry=\"8\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"0.8\" opacity=\"0.4\"/>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Labels (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Pebbles -->\n    <line x1=\"435\" y1=\"135\" x2=\"550\" y2=\"135\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"135\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"132\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 1: RIVER PEBBLES</text>\n    <text x=\"560\" y=\"145\" fill=\"#888888\">낙엽·벌레 등 대형 부유물 1차 차단</text>\n\n    <!-- Callout 2: Coarse Sand -->\n    <line x1=\"430\" y1=\"172\" x2=\"550\" y2=\"172\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"430\" cy=\"172\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"169\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 2: COARSE SAND</text>\n    <text x=\"560\" y=\"182\" fill=\"#888888\">굵은 흙 입자 및 모래 부유물 침전</text>\n\n    <!-- Callout 3: Fine Silica Sand -->\n    <line x1=\"425\" y1=\"208\" x2=\"550\" y2=\"208\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"425\" cy=\"208\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"205\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 3: FINE SILICA SAND</text>\n    <text x=\"560\" y=\"218\" fill=\"#888888\">미세 진흙 입자 및 미세 탁도 여과</text>\n\n    <!-- Callout 4: Charcoal -->\n    <line x1=\"420\" y1=\"245\" x2=\"550\" y2=\"245\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"420\" cy=\"245\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"560\" y=\"242\" fill=\"#E02424\" font-weight=\"bold\">STAGE 4: ACTIVATED CHARCOAL</text>\n    <text x=\"560\" y=\"255\" fill=\"#888888\">미세 구멍으로 독소·냄새·유기물 흡착</text>\n\n    <!-- Callout 5: Fiber Plug -->\n    <line x1=\"410\" y1=\"288\" x2=\"550\" y2=\"288\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"410\" cy=\"288\" r=\"2\" fill=\"#666\"/>\n    <text x=\"560\" y=\"285\" fill=\"#ffffff\" font-weight=\"bold\">STAGE 5: FIBER FILTER PLUG</text>\n    <text x=\"560\" y=\"298\" fill=\"#888888\">숯가루 유출 방지 및 최종 유속 조절</text>\n\n    <!-- Callout 6: Potable Water -->\n    <line x1=\"440\" y1=\"390\" x2=\"550\" y2=\"390\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"390\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"560\" y=\"387\" fill=\"#38bdf8\" font-weight=\"bold\">OUTPUT: CLEAR POTABLE WATER</text>\n    <text x=\"560\" y=\"400\" fill=\"#888888\">무색투명 식수 (음용 전 3분 끓임 필수)</text>\n  </g>\n\n  <!-- Technical Callout Leader Lines & Specs (Left Side) -->\n  <g id=\"calloutsLeft\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Spec Box -->\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"150\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"110\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"125\" fill=\"#E02424\" font-weight=\"bold\">CRITICAL METRICS</text>\n\n    <text x=\"55\" y=\"150\" fill=\"#aaa\">· TOTAL HEIGHT: 60-80 CM</text>\n    <text x=\"55\" y=\"170\" fill=\"#aaa\">· COMPACTION: 100% TIGHT</text>\n    <text x=\"55\" y=\"190\" fill=\"#aaa\">· CHARCOAL THICKNESS: 10 CM+</text>\n    <text x=\"55\" y=\"210\" fill=\"#aaa\">· INITIAL FLUSH: DISCARD 1L</text>\n    <text x=\"55\" y=\"230\" fill=\"#aaa\">· WATER PURITY: 99.2% CLARITY</text>\n    <text x=\"55\" y=\"250\" fill=\"#38bdf8\">· BOILING REQ: 3 MIN AT 100°C</text>\n\n    <!-- Raw Water Inflow Indicator -->\n    <path d=\"M 330 75 Q 360 82 375 92\" stroke=\"#8c6643\" stroke-width=\"2\" fill=\"none\"/>\n    <text x=\"320\" y=\"65\" fill=\"#c9ad7d\" font-weight=\"bold\">RAW MUDDY INFLOW (탁수 유입)</text>\n  </g>\n</svg>\n","content/svgs/pr02-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <!-- Dark Tactical Backdrop -->\n    <linearGradient id=\"bgGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0c0c\"/>\n      <stop offset=\"100%\" stop-color=\"#151313\"/>\n    </linearGradient>\n\n    <!-- Wood Shading -->\n    <linearGradient id=\"hearthWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2d1e\"/>\n      <stop offset=\"40%\" stop-color=\"#694d34\"/>\n      <stop offset=\"70%\" stop-color=\"#4d3725\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1f14\"/>\n    </linearGradient>\n    <linearGradient id=\"spindleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#594432\"/>\n      <stop offset=\"50%\" stop-color=\"#806248\"/>\n      <stop offset=\"100%\" stop-color=\"#403022\"/>\n    </linearGradient>\n    <linearGradient id=\"bearingBlock\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#735c45\"/>\n      <stop offset=\"100%\" stop-color=\"#3b2d1e\"/>\n    </linearGradient>\n\n    <!-- Hot Glowing Ember & Fire Gradients -->\n    <radialGradient id=\"emberGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#fffbeb\" stop-opacity=\"1\"/>\n      <stop offset=\"25%\" stop-color=\"#fef08a\" stop-opacity=\"0.9\"/>\n      <stop offset=\"55%\" stop-color=\"#f97316\" stop-opacity=\"0.8\"/>\n      <stop offset=\"85%\" stop-color=\"#dc2626\" stop-opacity=\"0.6\"/>\n      <stop offset=\"100%\" stop-color=\"#7f1d1d\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <linearGradient id=\"flameGrad\" x1=\"0%\" y1=\"100%\" x2=\"0%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#ef4444\"/>\n      <stop offset=\"40%\" stop-color=\"#f97316\"/>\n      <stop offset=\"75%\" stop-color=\"#fde047\"/>\n      <stop offset=\"100%\" stop-color=\"#ffffff\"/>\n    </linearGradient>\n\n    <!-- Smoke Effect Filter -->\n    <filter id=\"smokeBlur\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feGaussianBlur stdDeviation=\"3\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad2)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: BOW DRILL FRICTION FIRE [EMBER IGNITION]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">CORE TEMP: 400°C+</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"185\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">FRICTION MECHANICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· NOTCH ANGLE: 45° V-CUT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· SPINDLE RPM: 400-600</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· EMBER COLOR: DENSE CHERRY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· TINDER PREP: DRIED BAST</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· COAL DUST: BLACK GRAPHITE</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· BLOWING: GENTLE LONG BREATH</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"260\" ry=\"22\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Hearth Board (받침 판재) -->\n  <g id=\"hearthBoard\">\n    <!-- Main Plank Slab (Isometric 3D) -->\n    <polygon points=\"260,335 480,335 460,375 240,375\" fill=\"url(#hearthWood)\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"240,375 460,375 460,395 240,395\" fill=\"#241a10\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n    <polygon points=\"460,375 480,335 480,355 460,395\" fill=\"#1f160e\" stroke=\"#1a140d\" stroke-width=\"2\"/>\n\n    <!-- Burn Socket & 45-degree V-Notch -->\n    <ellipse cx=\"360\" cy=\"350\" rx=\"14\" ry=\"7\" fill=\"#080808\" stroke=\"#111\" stroke-width=\"1.5\"/>\n    <polygon points=\"360,350 348,375 372,375\" fill=\"#050505\"/>\n\n    <!-- Catch Bark Tray Underneath Notch -->\n    <polygon points=\"335,372 385,372 395,388 325,388\" fill=\"#523d2b\" stroke=\"#332417\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Glowing Ember Coal (Hot 400°C) on Catch Tray -->\n  <g id=\"emberHot\">\n    <!-- Concentrated Red/Orange Glow Halo -->\n    <circle cx=\"360\" cy=\"378\" r=\"22\" fill=\"url(#emberGlow)\"/>\n    <!-- Black Carbon Powder Mound with Red Hot Core -->\n    <ellipse cx=\"360\" cy=\"380\" rx=\"12\" ry=\"6\" fill=\"#141414\"/>\n    <circle cx=\"359\" cy=\"379\" r=\"4.5\" fill=\"#ffedd5\"/>\n    <circle cx=\"362\" cy=\"378\" r=\"2\" fill=\"#ffffff\"/>\n    <circle cx=\"357\" cy=\"380\" r=\"1.5\" fill=\"#fde047\"/>\n\n    <!-- Rising Woodsmoke Wisps -->\n    <path d=\"M 360 372 Q 352 340 365 315 Q 375 290 358 260 Q 345 230 360 200\" stroke=\"#e2e8f0\" stroke-width=\"4\" fill=\"none\" opacity=\"0.35\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 362 370 Q 370 335 358 310 Q 348 285 362 255\" stroke=\"#f1f5f9\" stroke-width=\"2.5\" fill=\"none\" opacity=\"0.45\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Spindle (회전봉) & Handhold Bearing Block -->\n  <g id=\"spindleAssembly\">\n    <!-- Vertical Spindle -->\n    <polygon points=\"354,150 366,150 364,348 356,348\" fill=\"url(#spindleWood)\" stroke=\"#261b13\" stroke-width=\"1.5\"/>\n    <!-- Bottom Carved Friction Tip (Charred) -->\n    <polygon points=\"356,345 364,345 362,352 358,352\" fill=\"#171717\"/>\n\n    <!-- Top Handhold Bearing Block -->\n    <path d=\"M 340 148 C 340 135 350 130 360 130 C 370 130 380 135 380 148 L 375 156 L 345 156 Z\" fill=\"url(#bearingBlock)\" stroke=\"#261b13\" stroke-width=\"1.8\"/>\n    <!-- Lubricant / Leaf Cushion Layer in Handhold Socket -->\n    <line x1=\"346\" y1=\"154\" x2=\"374\" y2=\"154\" stroke=\"#4ade80\" stroke-width=\"2\"/>\n  </g>\n\n  <!-- Bow & Taut Cord Wrapped Around Spindle -->\n  <g id=\"bowAndCord\">\n    <!-- Curved Wooden Bow Branch -->\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#785336\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n    <path d=\"M 230 290 Q 290 190 470 230\" fill=\"none\" stroke=\"#47301e\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n\n    <!-- Taut Rawhide / Fiber Bowstring Wrapped Once Around Spindle -->\n    <line x1=\"230\" y1=\"288\" x2=\"355\" y2=\"250\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n    <!-- Wrap Turn around spindle shaft -->\n    <ellipse cx=\"360\" cy=\"250\" rx=\"7\" ry=\"3.5\" fill=\"#8c6c45\" stroke=\"#d4b483\" stroke-width=\"2\"/>\n    <line x1=\"365\" y1=\"250\" x2=\"470\" y2=\"228\" stroke=\"#d4b483\" stroke-width=\"2.5\"/>\n  </g>\n\n  <!-- Tinder Nest with Sprouting Flame (부싯깃 둥지 & 피어난 불꽃) -->\n  <g id=\"tinderNestAndFlame\">\n    <!-- Bird's Nest Bundle of Fibers -->\n    <ellipse cx=\"560\" cy=\"365\" rx=\"55\" ry=\"24\" fill=\"#36291a\" stroke=\"#241b12\" stroke-width=\"2\"/>\n    <path d=\"M 515 360 Q 560 380 605 360 M 520 370 Q 560 385 600 370 M 530 355 Q 560 370 590 355\" stroke=\"#78593a\" stroke-width=\"1.5\" fill=\"none\"/>\n\n    <!-- Blazing Fire Flame Center -->\n    <path d=\"M 560 355 C 540 340 535 305 555 270 C 560 288 568 295 565 275 C 575 285 585 310 580 340 C 585 330 588 318 584 305 C 595 320 592 345 575 355 Z\" fill=\"url(#flameGrad)\" filter=\"url(#smokeBlur)\"/>\n    <path d=\"M 560 355 C 545 342 542 312 555 280 C 559 295 566 300 564 285 C 572 295 580 315 576 342 C 580 334 582 324 579 315 C 588 326 585 346 572 355 Z\" fill=\"url(#flameGrad)\"/>\n    <!-- White Hot Core -->\n    <ellipse cx=\"563\" cy=\"345\" rx=\"8\" ry=\"14\" fill=\"#ffffff\" opacity=\"0.95\"/>\n    <ellipse cx=\"563\" cy=\"345\" rx=\"14\" ry=\"20\" fill=\"#fef08a\" opacity=\"0.7\"/>\n\n    <!-- Rising Flame Sparks & Smoke -->\n    <circle cx=\"550\" cy=\"245\" r=\"1.5\" fill=\"#f97316\"/>\n    <circle cx=\"568\" cy=\"230\" r=\"1.2\" fill=\"#fde047\"/>\n    <circle cx=\"562\" cy=\"210\" r=\"1\" fill=\"#f97316\"/>\n    <path d=\"M 560 260 Q 550 220 565 180 Q 575 150 560 120\" stroke=\"#cbd5e1\" stroke-width=\"3\" fill=\"none\" opacity=\"0.25\" filter=\"url(#smokeBlur)\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Handhold -->\n    <line x1=\"380\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"380\" cy=\"140\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"137\" fill=\"#ffffff\" font-weight=\"bold\">TOP BEARING BLOCK</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">윤활유/풀잎 삽입으로 상단 마찰 최소화</text>\n\n    <!-- Callout 2: Bow & String -->\n    <line x1=\"435\" y1=\"230\" x2=\"565\" y2=\"230\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"435\" cy=\"230\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"227\" fill=\"#ffffff\" font-weight=\"bold\">BOW RIGGING (활비비 구동)</text>\n    <text x=\"570\" y=\"240\" fill=\"#888888\">1회 감김 텐션으로 고속 회전력 전달</text>\n\n    <!-- Callout 3: Ember Coal -->\n    <line x1=\"375\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"380\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"377\" fill=\"#E02424\" font-weight=\"bold\">STAGE 1: 400°C GLOWING EMBER</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">V홈 숯가루가 잉걸불로 자가 연소</text>\n\n    <!-- Callout 4: Flame Nest -->\n    <line x1=\"560\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"560\" cy=\"310\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"307\" fill=\"#f97316\" font-weight=\"bold\">STAGE 2: SUSTAINED OPEN FLAME</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">부싯깃 둥지 감싸 쥐고 완만한 호흡 착화</text>\n  </g>\n</svg>\n","content/svgs/pr03-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0a0f0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141916\"/>\n    </linearGradient>\n\n    <!-- Wood Trunk Gradients -->\n    <linearGradient id=\"ridgepoleWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3f2e1d\"/>\n      <stop offset=\"50%\" stop-color=\"#694f34\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1e12\"/>\n    </linearGradient>\n\n    <!-- Dense Leaf Blanket Texture Gradients -->\n    <linearGradient id=\"leafLayer\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#713f12\"/>\n      <stop offset=\"35%\" stop-color=\"#854d0e\"/>\n      <stop offset=\"70%\" stop-color=\"#a16207\"/>\n      <stop offset=\"100%\" stop-color=\"#4d3800\"/>\n    </linearGradient>\n    <radialGradient id=\"shelterInterior\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#050505\"/>\n      <stop offset=\"80%\" stop-color=\"#111111\"/>\n      <stop offset=\"100%\" stop-color=\"#1a1a1a\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad3)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: A-FRAME DEBRIS HUT [THERMAL SHELTER]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">DEAD-AIR INSULATION: 1.0M</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">SHELTER METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· RIDGEPOLE: 2.5-3.0 M</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· ROOF PITCH: 45° SLANT</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· LEAF THICKNESS: 100 CM</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· GROUND BEDDING: 50 CM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· ENTRANCE: LOW BRAWL FIT</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TEMP RETENTION: +15°C</text>\n  </g>\n\n  <!-- Forest Ground Base -->\n  <polygon points=\"120,410 680,410 740,360 200,360\" fill=\"#141a13\" opacity=\"0.8\"/>\n  <ellipse cx=\"450\" cy=\"390\" rx=\"240\" ry=\"22\" fill=\"#080c09\"/>\n\n  <!-- Debris Hut Main Volume (3D Sloping Dome) -->\n  <g id=\"debrisHutStructure\">\n    <!-- Back End Ground Anchor (Tail) -->\n    <ellipse cx=\"640\" cy=\"350\" rx=\"40\" ry=\"18\" fill=\"#1a140d\"/>\n\n    <!-- Thick 1-Meter Debris Leaf Mound Volume (Roof Shading) -->\n    <path d=\"M 330 155 C 390 145 520 220 650 345 L 610 380 C 490 385 360 385 240 375 C 230 330 260 200 330 155 Z\" fill=\"url(#leafLayer)\" stroke=\"#3f2305\" stroke-width=\"2\"/>\n\n    <!-- Highlighting Leaf Scales / Foliage Tufts -->\n    <g stroke=\"#a16207\" stroke-width=\"1.2\" fill=\"#854d0e\" opacity=\"0.85\">\n      <ellipse cx=\"370\" cy=\"210\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"410\" cy=\"230\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"460\" cy=\"250\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"510\" cy=\"280\" rx=\"24\" ry=\"13\"/>\n      <ellipse cx=\"560\" cy=\"310\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"350\" cy=\"260\" rx=\"20\" ry=\"11\"/>\n      <ellipse cx=\"390\" cy=\"280\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"440\" cy=\"300\" rx=\"24\" ry=\"14\"/>\n      <ellipse cx=\"490\" cy=\"330\" rx=\"25\" ry=\"13\"/>\n      <ellipse cx=\"310\" cy=\"300\" rx=\"18\" ry=\"10\"/>\n      <ellipse cx=\"350\" cy=\"325\" rx=\"22\" ry=\"12\"/>\n      <ellipse cx=\"400\" cy=\"340\" rx=\"24\" ry=\"13\"/>\n    </g>\n\n    <!-- Exterior Weighting Thatch Branches (바람막이 겉가지 격자) -->\n    <g stroke=\"#452e18\" stroke-width=\"3\" stroke-linecap=\"round\">\n      <line x1=\"335\" y1=\"170\" x2=\"270\" y2=\"365\"/>\n      <line x1=\"380\" y1=\"180\" x2=\"330\" y2=\"370\"/>\n      <line x1=\"435\" y1=\"210\" x2=\"395\" y2=\"375\"/>\n      <line x1=\"490\" y1=\"240\" x2=\"465\" y2=\"380\"/>\n      <line x1=\"550\" y1=\"280\" x2=\"530\" y2=\"380\"/>\n      <!-- Cross horizontal sticks -->\n      <line x1=\"290\" y1=\"280\" x2=\"540\" y2=\"305\"/>\n      <line x1=\"260\" y1=\"330\" x2=\"570\" y2=\"350\"/>\n    </g>\n\n    <!-- Front A-Frame Crutch Entrance Structure -->\n    <!-- Left A-Frame Post -->\n    <polygon points=\"230,370 240,370 338,150 330,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Right A-Frame Post -->\n    <polygon points=\"350,370 340,370 330,150 338,150\" fill=\"url(#ridgepoleWood)\" stroke=\"#1a120b\" stroke-width=\"1.5\"/>\n    <!-- Apex Notch Crotch -->\n    <ellipse cx=\"334\" cy=\"150\" rx=\"10\" ry=\"6\" fill=\"#523922\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Ridgepole Extending Through Apex to Back Tail -->\n    <polygon points=\"328,145 342,145 650,345 640,348\" fill=\"url(#ridgepoleWood)\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n    <!-- Small Snug Entrance Opening -->\n    <path d=\"M 260 370 C 260 280 320 280 320 370 Z\" fill=\"url(#shelterInterior)\" stroke=\"#291b10\" stroke-width=\"2\"/>\n\n    <!-- Entrance Door Plug (낙엽 차단 마개) Placed Beside Entry -->\n    <g id=\"doorPlug\">\n      <ellipse cx=\"230\" cy=\"380\" rx=\"26\" ry=\"16\" fill=\"#5c3a14\" stroke=\"#33200b\" stroke-width=\"1.5\"/>\n      <path d=\"M 215 375 Q 230 385 245 375\" stroke=\"#854d0e\" stroke-width=\"1.2\" fill=\"none\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Ridgepole -->\n    <line x1=\"335\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"335\" cy=\"150\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"147\" fill=\"#ffffff\" font-weight=\"bold\">HEAVY RIDGEPOLE (용마루)</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">성인 체중을 견디는 굵은 주 기둥 안착</text>\n\n    <!-- Callout 2: Debris Layer -->\n    <line x1=\"440\" y1=\"240\" x2=\"565\" y2=\"240\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"440\" cy=\"240\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"237\" fill=\"#E02424\" font-weight=\"bold\">1-METER DEBRIS INSULATION</text>\n    <text x=\"570\" y=\"250\" fill=\"#888888\">마른 낙엽 1미터로 영하권 체온 손실 방지</text>\n\n    <!-- Callout 3: Thatch Lattice -->\n    <line x1=\"510\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"310\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"307\" fill=\"#ffffff\" font-weight=\"bold\">THATCH TRELLIS (겉가지 격자)</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">돌풍에 낙엽이 날리지 않게 상단 누름 고정</text>\n\n    <!-- Callout 4: Snug Entrance & Plug -->\n    <line x1=\"285\" y1=\"350\" x2=\"565\" y2=\"350\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"285\" cy=\"350\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"347\" fill=\"#4ade80\" font-weight=\"bold\">LOW ENTRANCE &amp; DOOR PLUG</text>\n    <text x=\"570\" y=\"360\" fill=\"#888888\">기어 들어갈 크기 + 취침 시 마개 차단</text>\n  </g>\n</svg>\n","content/svgs/pr03-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"330\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">움막 크기 핵심 규칙:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">몸이 겨우 들어갈 크기 (어깨 옆 주먹 1개 여유)</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"40\" y1=\"265\" x2=\"640\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n  <line x1=\"60\" y1=\"273\" x2=\"620\" y2=\"273\" stroke=\"#333333\" stroke-width=\"1\" stroke-dasharray=\"6,4\" />\n\n  <!-- Windward Force Vector (Left Side) -->\n  <line x1=\"45\" y1=\"195\" x2=\"115\" y2=\"195\" stroke=\"#E02424\" stroke-width=\"1.8\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"45\" y1=\"215\" x2=\"105\" y2=\"215\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"45\" y=\"182\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바람 불어오는 쪽 (바닥에 고정)</text>\n\n  <!-- Main Ridgepole (3.0~3.5m Hardwood Spine) from (110, 265) to (490, 115) -->\n  <polygon points=\"105,265 492,110 498,124 125,265\" fill=\"#262626\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <!-- Ground Stake / Anchor at Windward Tail -->\n  <polygon points=\"102,248 112,248 112,282 102,282\" fill=\"#E02424\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n\n  <!-- Ridgepole Label & Leader Line -->\n  <line x1=\"280\" y1=\"190\" x2=\"250\" y2=\"132\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"165\" y=\"124\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무: 길이 3.0~3.5m</text>\n\n  <!-- Y-Frame Bipod Support Sticks at Entrance (Apex at 490, 118) -->\n  <line x1=\"445\" y1=\"265\" x2=\"508\" y2=\"92\" stroke=\"#CCCCCC\" stroke-width=\"5\" />\n  <line x1=\"535\" y1=\"265\" x2=\"472\" y2=\"92\" stroke=\"#999999\" stroke-width=\"5\" />\n  <!-- Vine Lashing Node at Apex -->\n  <circle cx=\"490\" cy=\"116\" r=\"11\" fill=\"#141414\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <line x1=\"481\" y1=\"112\" x2=\"499\" y2=\"120\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"481\" y1=\"120\" x2=\"499\" y2=\"112\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n\n  <!-- Lashing Node Label -->\n  <line x1=\"490\" y1=\"102\" x2=\"490\" y2=\"68\" stroke=\"#E02424\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"490\" y=\"60\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">Y자 기둥 2개 맞물려 묶기</text>\n\n  <!-- Interior Prone Body Clearance Envelope (Coffin Spec) -->\n  <path d=\"M 165,258 L 455,258 L 455,212 L 385,205 L 165,242 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <!-- Clearance Gap Arrows (+10cm Fist Tolerance) -->\n  <line x1=\"365\" y1=\"172\" x2=\"365\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"298\" fill=\"#CCCCCC\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"middle\">내부 공간: 몸 둘레 + 10cm (주먹 1개 여유)</text>\n\n  <!-- Vertical Elevation Dimension (0.8 ~ 1.0m) on Right -->\n  <line x1=\"575\" y1=\"116\" x2=\"575\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.2\" />\n  <line x1=\"565\" y1=\"116\" x2=\"585\" y2=\"116\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <line x1=\"565\" y1=\"265\" x2=\"585\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" />\n  <text x=\"655\" y=\"194\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">입구 높이: 0.8~1.0m</text>\n</svg>\n","content/svgs/pr03-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">바닥 냉기 차단 핵심:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">마른 낙엽을 두껍게 깔아 눌린 뒤에도 20cm 유지</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"60\" y1=\"265\" x2=\"620\" y2=\"265\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Cross-Section A-Frame Rib Lattice (Center X = 340, Apex Y = 88) -->\n  <!-- Left & Right Rib Poles at 52° Pitch -->\n  <line x1=\"340\" y1=\"88\" x2=\"185\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <line x1=\"340\" y1=\"88\" x2=\"495\" y2=\"265\" stroke=\"#F5F5F5\" stroke-width=\"4\" />\n  <!-- Secondary Lattice Branches -->\n  <line x1=\"295\" y1=\"138\" x2=\"412\" y2=\"170\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n  <line x1=\"255\" y1=\"184\" x2=\"445\" y2=\"208\" stroke=\"#777777\" stroke-width=\"1.5\" stroke-dasharray=\"5,3\" />\n\n  <!-- Ridgepole Cross-Section Circle at Apex -->\n  <circle cx=\"340\" cy=\"88\" r=\"14\" fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n  <circle cx=\"340\" cy=\"88\" r=\"4\" fill=\"#F5F5F5\" />\n  <line x1=\"354\" y1=\"84\" x2=\"430\" y2=\"56\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"436\" y=\"59\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">중심 기둥 나무 (단면)</text>\n\n  <!-- Rib Pitch Angle Indicator (45° ~ 60°) -->\n  <path d=\"M 222,265 A 36 36 0 0 0 209,238\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n  <line x1=\"252\" y1=\"188\" x2=\"175\" y2=\"145\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"35\" y=\"140\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">양옆 나뭇가지: 45°~60° 각도로 촘촘히 세우기</text>\n\n  <!-- Interior Floor Mattress: Initial 40cm Mound (Dashed) & Compressed 15~20cm Core (Solid) -->\n  <path d=\"M 215,265 Q 340,175 465,265 Z\" fill=\"#1c1b1b\" stroke=\"#888888\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" />\n  <rect x=\"215\" y=\"222\" width=\"250\" height=\"43\" fill=\"#252323\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Texture lines inside mattress -->\n  <line x1=\"230\" y1=\"236\" x2=\"450\" y2=\"236\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"8,4\" />\n  <line x1=\"225\" y1=\"250\" x2=\"455\" y2=\"250\" stroke=\"#666666\" stroke-width=\"1\" stroke-dasharray=\"6,5\" />\n\n  <!-- Mattress Dimension Callout on Right -->\n  <line x1=\"470\" y1=\"235\" x2=\"520\" y2=\"205\" stroke=\"#E02424\" stroke-width=\"1.2\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"655\" y=\"200\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"end\">낙엽 이불: 40cm → 눌린 뒤 20cm</text>\n\n  <!-- Ground Cold Conduction Blocked Vectors (Bottom) -->\n  <line x1=\"270\" y1=\"292\" x2=\"270\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"340\" y1=\"292\" x2=\"340\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"410\" y1=\"292\" x2=\"410\" y2=\"270\" stroke=\"#E02424\" stroke-width=\"1.5\" marker-end=\"url(#arrow-red)\" />\n  <text x=\"340\" y=\"314\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">땅에서 올라오는 찬 기운 완벽 차단</text>\n</svg>","content/svgs/pr03-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow-white\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#F5F5F5\" />\n    </marker>\n    <marker id=\"arrow-red\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <!-- Outer Frame Guideline -->\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4,4\" />\n\n  <!-- Rule Callout Box -->\n  <rect x=\"25\" y=\"24\" width=\"335\" height=\"44\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"41\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">지붕 낙엽 쌓기 &amp; 입구 막기:</text>\n  <text x=\"35\" y=\"58\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\">지붕에 낙엽을 팔 길이(60~90cm)로 쌓고 입구 막기</text>\n\n  <!-- Ground Baseline -->\n  <line x1=\"45\" y1=\"268\" x2=\"635\" y2=\"268\" stroke=\"#666666\" stroke-width=\"2\" />\n\n  <!-- Outer Heavy Deadwood Wind-Armor Layer (Outer Mound) -->\n  <path d=\"M 95,268 Q 340,22 585,268 Z\" fill=\"#191818\" stroke=\"#F5F5F5\" stroke-width=\"2.2\" />\n  <!-- Shingled Debris Layer (60~90cm Thickness Zone) -->\n  <path d=\"M 135,268 Q 340,68 545,268 Z\" fill=\"#222020\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\" />\n\n  <!-- Inner Rib Core & Dead-Air Thermal Chamber -->\n  <polygon points=\"340,142 230,268 450,268\" fill=\"#121212\" stroke=\"#E02424\" stroke-width=\"2\" />\n  <!-- Entrance Debris Plug / Seal Indicator inside Chamber -->\n  <circle cx=\"340\" cy=\"222\" r=\"24\" fill=\"#291414\" stroke=\"#E02424\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" />\n  <path d=\"M 326,222 L 354,222 M 340,208 L 340,236\" stroke=\"#E02424\" stroke-width=\"1.5\" />\n\n  <!-- 60~90cm Thickness Dimension Callout (Left Slope) -->\n  <line x1=\"185\" y1=\"162\" x2=\"255\" y2=\"212\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow-red)\" />\n  <line x1=\"185\" y1=\"162\" x2=\"135\" y2=\"128\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"30\" y=\"120\" fill=\"#F5F5F5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">마른 낙엽 벽: 60~90cm 두께</text>\n\n  <!-- Heavy Deadwood Armor Callout (Right Slope) -->\n  <line x1=\"455\" y1=\"118\" x2=\"505\" y2=\"75\" stroke=\"#AAAAAA\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n  <text x=\"655\" y=\"70\" fill=\"#E5E5E5\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" text-anchor=\"end\">바람에 안 날리게 무거운 가지 덮기</text>\n\n  <!-- Rain / Wind Shedding Vector on Right Slope -->\n  <line x1=\"505\" y1=\"145\" x2=\"575\" y2=\"215\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" marker-end=\"url(#arrow-white)\" />\n  <text x=\"655\" y=\"142\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9.5\" text-anchor=\"end\">빗물이 타고 흐르는 경사면</text>\n\n  <!-- Dead Air Space & Entrance Plug Label (Bottom Center) -->\n  <line x1=\"340\" y1=\"246\" x2=\"340\" y2=\"292\" stroke=\"#E02424\" stroke-width=\"1.2\" />\n  <text x=\"340\" y=\"312\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">따뜻한 공기가 갇힌 내부 &amp; 낙엽 마개</text>\n</svg>","content/svgs/pr04-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0e\"/>\n      <stop offset=\"100%\" stop-color=\"#14171a\"/>\n    </linearGradient>\n\n    <!-- Haft Wood Texture -->\n    <linearGradient id=\"haftWood\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2c1d\"/>\n      <stop offset=\"35%\" stop-color=\"#694e36\"/>\n      <stop offset=\"70%\" stop-color=\"#523c28\"/>\n      <stop offset=\"100%\" stop-color=\"#2b1e12\"/>\n    </linearGradient>\n\n    <!-- Stone Axe Head (Chert / Basalt Flint) -->\n    <linearGradient id=\"flintStone\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#474747\"/>\n      <stop offset=\"40%\" stop-color=\"#2e2e2e\"/>\n      <stop offset=\"80%\" stop-color=\"#1a1a1a\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0f0f\"/>\n    </linearGradient>\n\n    <!-- Pine Pitch Resin Glue -->\n    <linearGradient id=\"pitchResin\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#1c1106\"/>\n      <stop offset=\"50%\" stop-color=\"#42290d\"/>\n      <stop offset=\"100%\" stop-color=\"#0f0802\"/>\n    </linearGradient>\n\n    <!-- Raw Vine Lashing -->\n    <linearGradient id=\"vineLashing\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8895b\"/>\n      <stop offset=\"50%\" stop-color=\"#7a623e\"/>\n      <stop offset=\"100%\" stop-color=\"#4f3e26\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad4)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: PRIMITIVE STONE AXE [BIFACIAL CHERT]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE RATING: 80 KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">AXE SPECIFICATIONS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STONE: RIVER BASALT/FLINT</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· BEVEL: 35° BIFACE EDGE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· HAFT: DRIED OAK / HICKORY</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· BINDING: X-CROSS VINE</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· RESIN: PINE PITCH + ASH</text>\n    <text x=\"55\" y=\"240\" fill=\"#38bdf8\">· CHOPPING EFF: 10 CM / 5 MIN</text>\n  </g>\n\n  <!-- Shadow Under Stone Axe -->\n  <ellipse cx=\"440\" cy=\"380\" rx=\"200\" ry=\"16\" fill=\"#050505\" opacity=\"0.9\"/>\n\n  <!-- Complete Stone Axe Assembly -->\n  <g id=\"axeAssembly\" transform=\"rotate(-15 420 250)\">\n    <!-- Wooden Haft Handle (Diagonal Solid Club) -->\n    <path d=\"M 280 230 C 310 232 440 242 560 250 C 585 252 600 256 600 268 C 600 280 580 282 560 280 C 440 270 310 255 280 250 Z\" fill=\"url(#haftWood)\" stroke=\"#1a120b\" stroke-width=\"2\"/>\n\n    <!-- Forked Cleft / Socket at Head End -->\n    <path d=\"M 285 220 C 265 215 250 200 250 185 L 295 190 C 295 210 285 220 285 220 Z\" fill=\"#241a10\" stroke=\"#120c07\" stroke-width=\"1.5\"/>\n\n    <!-- Chipped Basalt/Flint Stone Axe Blade Head -->\n    <polygon points=\"210,135 295,155 315,225 240,240 185,190\" fill=\"url(#flintStone)\" stroke=\"#111111\" stroke-width=\"2\"/>\n    <!-- Chipping Facets & Flaking Edges (Realistic Bifacial Flakes) -->\n    <polygon points=\"210,135 250,155 235,175 195,160\" fill=\"#3d3d3d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"250,155 295,155 280,185 235,175\" fill=\"#4d4d4d\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"195,160 235,175 225,210 185,190\" fill=\"#262626\" stroke=\"#111\" stroke-width=\"1\"/>\n    <polygon points=\"235,175 280,185 270,220 225,210\" fill=\"#363636\" stroke=\"#222\" stroke-width=\"1\"/>\n    <polygon points=\"280,185 315,225 270,220\" fill=\"#1f1f1f\" stroke=\"#111\" stroke-width=\"1\"/>\n    <!-- Razor-Sharp Front Cutting Edge Highlight -->\n    <path d=\"M 210 135 L 185 190 L 240 240\" fill=\"none\" stroke=\"#e0e0e0\" stroke-width=\"1.8\" stroke-linecap=\"round\"/>\n\n    <!-- Black Pine Pitch Resin Adhesive Layer Sealing Socket -->\n    <ellipse cx=\"285\" cy=\"225\" rx=\"30\" ry=\"20\" fill=\"url(#pitchResin)\" opacity=\"0.95\"/>\n\n    <!-- Tight Criss-Cross Vine / Rawhide Lashings (X-Lashing Pattern) -->\n    <g stroke=\"url(#vineLashing)\" stroke-width=\"3.5\" stroke-linecap=\"round\">\n      <!-- Diagonal Forward Turns -->\n      <line x1=\"260\" y1=\"210\" x2=\"310\" y2=\"255\"/>\n      <line x1=\"265\" y1=\"205\" x2=\"315\" y2=\"250\"/>\n      <line x1=\"270\" y1=\"200\" x2=\"320\" y2=\"245\"/>\n      <!-- Diagonal Backward Turns (Crossing to form X) -->\n      <line x1=\"310\" y1=\"210\" x2=\"260\" y2=\"255\"/>\n      <line x1=\"315\" y1=\"205\" x2=\"265\" y2=\"250\"/>\n      <line x1=\"320\" y1=\"200\" x2=\"270\" y2=\"245\"/>\n      <!-- Tight Frapping Turns Around Socket Base -->\n      <line x1=\"280\" y1=\"250\" x2=\"280\" y2=\"265\" stroke-width=\"4\"/>\n      <line x1=\"288\" y1=\"248\" x2=\"288\" y2=\"263\" stroke-width=\"4\"/>\n    </g>\n\n    <!-- Handle Grip Carvings / Notches -->\n    <line x1=\"520\" y1=\"248\" x2=\"520\" y2=\"276\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"535\" y1=\"250\" x2=\"535\" y2=\"278\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n    <line x1=\"550\" y1=\"252\" x2=\"550\" y2=\"280\" stroke=\"#241a10\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Stone Blade -->\n    <line x1=\"260\" y1=\"140\" x2=\"565\" y2=\"140\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"260\" cy=\"140\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"137\" fill=\"#E02424\" font-weight=\"bold\">CHIPPED BIFACE STONE BLADE</text>\n    <text x=\"570\" y=\"150\" fill=\"#888888\">양면 박편 타제로 세운 35도 예리한 절삭날</text>\n\n    <!-- Callout 2: Resin Seal -->\n    <line x1=\"350\" y1=\"210\" x2=\"565\" y2=\"210\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"350\" cy=\"210\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"207\" fill=\"#ffffff\" font-weight=\"bold\">PINE PITCH COMPOSITE SEAL</text>\n    <text x=\"570\" y=\"220\" fill=\"#888888\">송진과 숯가루 혼합재로 유격 100% 밀봉</text>\n\n    <!-- Callout 3: Cross Lashing -->\n    <line x1=\"330\" y1=\"280\" x2=\"565\" y2=\"280\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"330\" cy=\"280\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"277\" fill=\"#ffffff\" font-weight=\"bold\">X-CROSS VINE LASHING</text>\n    <text x=\"570\" y=\"290\" fill=\"#888888\">충격을 흡수 분산하는 십자 결속 및 프래핑</text>\n\n    <!-- Callout 4: Oak Haft -->\n    <line x1=\"490\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"490\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">HARDENED OAK HAFT</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">불에 그슬려 경화한 묵직한 참나무 손잡이</text>\n  </g>\n</svg>\n","content/svgs/pr04-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n    <marker id=\"arrow-white\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#F5F5F5\" />\n    </marker>\n  </defs>\n\n  <!-- Background technical coordinate lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n  <line x1=\"340\" y1=\"20\" x2=\"340\" y2=\"320\" stroke=\"#222222\" stroke-width=\"1\" />\n\n  <!-- Core River Stone (Base Cobble) -->\n  <path d=\"M 220 275 C 180 265 145 225 155 180 C 165 140 210 130 260 135 C 310 140 345 165 350 210 C 355 250 310 280 220 275 Z\" \n        fill=\"#1c1b1b\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Flake detachment line & fracture cone -->\n  <path d=\"M 310 150 Q 325 180 340 215\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 340 215 C 360 210 395 185 400 160 C 390 145 350 140 310 150 Z\" \n        fill=\"#262626\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Detached Sharp Axe Blade (Separating Flake) -->\n  <path d=\"M 430 190 Q 480 145 520 180 Q 490 225 430 190 Z\" \n        fill=\"#1a1a1a\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 430 190 Q 475 160 520 180\" stroke=\"#E02424\" stroke-width=\"2\" />\n\n  <!-- Hammerstone (Striking Stone) -->\n  <ellipse cx=\"280\" cy=\"70\" rx=\"42\" ry=\"30\" fill=\"#222222\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" transform=\"rotate(-25 280 70)\" />\n  \n  <!-- 45 Degree Kinetic Strike Vector -->\n  <line x1=\"260\" y1=\"85\" x2=\"310\" y2=\"148\" stroke=\"#E02424\" stroke-width=\"3\" marker-end=\"url(#arrow)\" />\n  \n  <!-- 45 Degree Angle Arc & Guide Lines -->\n  <line x1=\"310\" y1=\"150\" x2=\"380\" y2=\"150\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <line x1=\"310\" y1=\"150\" x2=\"260\" y2=\"90\" stroke=\"#737373\" stroke-width=\"1\" stroke-dasharray=\"3 3\" />\n  <path d=\"M 350 150 A 40 40 0 0 0 338 122\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" />\n\n  <!-- Technical dimension line -->\n  <line x1=\"155\" y1=\"295\" x2=\"350\" y2=\"295\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"155\" y1=\"290\" x2=\"155\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"350\" y1=\"290\" x2=\"350\" y2=\"300\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels placed in non-overlapping safe zones -->\n  <rect x=\"25\" y=\"28\" width=\"205\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"44\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 둥근 망치돌 (내리치는 돌)</text>\n\n  <rect x=\"25\" y=\"84\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"100\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 모서리 45° 비스듬히 치기</text>\n\n  <rect x=\"420\" y=\"112\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"128\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">날카로운 돌날 (두께 1~2cm)</text>\n\n  <rect x=\"420\" y=\"245\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"261\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 쪼개져 나온 도끼날 돌조각</text>\n\n  <text x=\"250\" y=\"316\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">③ 바닥에 받친 큰 강돌 (너비 15~20cm)</text>\n</svg>\n","content/svgs/pr04-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Handle (Shaft) -->\n  <path d=\"M 315 170 L 315 275 L 355 275 L 355 170 Z\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Split Cleft Head (Two tines separated) -->\n  <path d=\"M 315 170 C 315 140 280 110 270 70 L 305 70 C 315 105 330 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  <path d=\"M 355 170 C 355 140 390 110 400 70 L 365 70 C 355 105 340 135 335 170 Z\" fill=\"#292828\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n\n  <!-- Split stop safety collar notch -->\n  <line x1=\"300\" y1=\"172\" x2=\"370\" y2=\"172\" stroke=\"#E02424\" stroke-width=\"2.2\" stroke-dasharray=\"3 2\" />\n\n  <!-- Melted Pine Resin + Charcoal Glue Bedding (Inside cleft) -->\n  <path d=\"M 305 130 C 315 150 335 168 335 168 C 335 168 355 150 365 130 C 355 110 315 110 305 130 Z\" \n        fill=\"#78350f\" stroke=\"#d97706\" stroke-width=\"1.5\" />\n  <circle cx=\"325\" cy=\"140\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"132\" r=\"2\" fill=\"#171717\" />\n  <circle cx=\"345\" cy=\"142\" r=\"2.5\" fill=\"#171717\" />\n  <circle cx=\"335\" cy=\"150\" r=\"1.8\" fill=\"#171717\" />\n\n  <!-- Wedged Stone Blade in Slot -->\n  <path d=\"M 230 100 L 440 100 L 415 135 L 255 135 Z\" fill=\"#333333\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 230 100 Q 210 115 255 135\" stroke=\"#E02424\" stroke-width=\"2.5\" />\n\n  <!-- Insertion down vector -->\n  <line x1=\"335\" y1=\"30\" x2=\"335\" y2=\"85\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\" />\n\n  <!-- Dimension callout for handle diameter -->\n  <line x1=\"280\" y1=\"288\" x2=\"390\" y2=\"288\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"280\" y1=\"283\" x2=\"280\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n  <line x1=\"390\" y1=\"283\" x2=\"390\" y2=\"293\" stroke=\"#525252\" stroke-width=\"1\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"420\" y=\"30\" width=\"225\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"430\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">① 위에서 아래로 돌날 끼우기</text>\n\n  <rect x=\"25\" y=\"102\" width=\"175\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"118\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\" font-weight=\"bold\">나무 자르는 앞날</text>\n\n  <rect x=\"445\" y=\"96\" width=\"215\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"455\" y=\"112\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 쪼갠 나무 자루 틈 (5~7cm)</text>\n\n  <rect x=\"430\" y=\"152\" width=\"230\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"440\" y=\"168\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 녹인 송진 + 숯가루 채우기</text>\n\n  <rect x=\"25\" y=\"220\" width=\"255\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"236\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">④ 더 안 갈라지게 아래쪽 먼저 묶기</text>\n\n  <text x=\"335\" y=\"314\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#9E9E9E\" text-anchor=\"middle\">생나무 자루 굵기: 지름 3.5~4cm</text>\n</svg>\n","content/svgs/pr04-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full max-w-2xl h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-reverse\">\n      <path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#E02424\" />\n    </marker>\n  </defs>\n\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"#131313\" />\n  <rect x=\"10\" y=\"10\" width=\"660\" height=\"320\" fill=\"none\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"4 4\" />\n\n  <!-- Wooden Shaft Handle -->\n  <rect x=\"315\" y=\"45\" width=\"45\" height=\"225\" fill=\"#201f1f\" stroke=\"#F5F5F5\" stroke-width=\"1.8\" />\n  \n  <!-- Stone Blade Head Fixed Horizontally -->\n  <path d=\"M 200 90 L 470 90 L 440 145 L 230 145 Z\" fill=\"#2e2d2d\" stroke=\"#F5F5F5\" stroke-width=\"2\" />\n  <path d=\"M 200 90 Q 180 115 230 145\" stroke=\"#E02424\" stroke-width=\"3\" />\n\n  <!-- Cross-Lashing Vine Bands (X-Pattern) -->\n  <line x1=\"280\" y1=\"80\" x2=\"390\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"285\" y1=\"75\" x2=\"395\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n  <line x1=\"390\" y1=\"80\" x2=\"280\" y2=\"160\" stroke=\"#84cc16\" stroke-width=\"4.5\" stroke-linecap=\"round\" />\n  <line x1=\"395\" y1=\"75\" x2=\"285\" y2=\"155\" stroke=\"#4d7c0f\" stroke-width=\"3\" stroke-linecap=\"round\" />\n\n  <!-- Horizontal securing turns around shaft collar -->\n  <rect x=\"305\" y=\"165\" width=\"65\" height=\"40\" fill=\"#3f6212\" stroke=\"#84cc16\" stroke-width=\"1.5\" />\n  <line x1=\"305\" y1=\"175\" x2=\"370\" y2=\"175\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"185\" x2=\"370\" y2=\"185\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n  <line x1=\"305\" y1=\"195\" x2=\"370\" y2=\"195\" stroke=\"#ecfccb\" stroke-width=\"1\" />\n\n  <!-- Inward tension arrows (Shrinkage vectors) -->\n  <line x1=\"250\" y1=\"120\" x2=\"290\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"420\" y1=\"120\" x2=\"380\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n  <line x1=\"337\" y1=\"225\" x2=\"337\" y2=\"208\" stroke=\"#E02424\" stroke-width=\"2\" marker-end=\"url(#arrow)\" />\n\n  <!-- 5 Clear Korean labels in safe zones -->\n  <rect x=\"415\" y=\"30\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"46\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#84cc16\">① 젖은 칡 속껍질 X자로 감기</text>\n\n  <rect x=\"25\" y=\"95\" width=\"160\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"35\" y=\"111\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">② 날카로운 도끼 앞날</text>\n\n  <rect x=\"415\" y=\"172\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"188\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\">③ 자루 아래쪽 가로로 칭칭 감기</text>\n\n  <rect x=\"415\" y=\"232\" width=\"235\" height=\"24\" fill=\"#0e0e0e\" stroke=\"#333333\" stroke-width=\"1\" />\n  <text x=\"425\" y=\"248\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#E02424\">④ 마르면서 30% 줄어들며 꽉 조임</text>\n\n  <text x=\"340\" y=\"308\" font-family=\"'JetBrains Mono', monospace\" font-size=\"11\" fill=\"#F5F5F5\" text-anchor=\"middle\" font-weight=\"bold\">완성 상태: 세게 내리쳐도 돌날이 빠지지 않는 일체형 돌도끼</text>\n</svg>\n","content/svgs/pr05-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0c0d0c\"/>\n      <stop offset=\"100%\" stop-color=\"#141814\"/>\n    </linearGradient>\n\n    <!-- Natural Cordage Fiber Gradients -->\n    <linearGradient id=\"cordLight\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#80623f\"/>\n      <stop offset=\"50%\" stop-color=\"#bda078\"/>\n      <stop offset=\"100%\" stop-color=\"#694d2f\"/>\n    </linearGradient>\n    <linearGradient id=\"cordDark\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#543e26\"/>\n      <stop offset=\"50%\" stop-color=\"#8a6c47\"/>\n      <stop offset=\"100%\" stop-color=\"#402d1a\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad5)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Title & Top Metrics -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: 2-PLY REVERSE-WRAPPED NATURAL CORDAGE</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">TENSILE LOAD: 90+ KGF</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">CORDAGE METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· STRUCTURE: 2-PLY REVERSE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· STRAND TWIST: CLOCKWISE</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· PLY INTERLOCK: COUNTER-CW</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· SPLICING: 1/3 STAGGERED</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· DIAMETER: 8.0 MM UNIFORM</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· TENSILE BREAK: 92.4 KGF</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"385\" rx=\"180\" ry=\"18\" fill=\"#060606\" opacity=\"0.9\"/>\n\n  <!-- Coiled Rope Bundle (원형 코일 다발) -->\n  <g id=\"ropeCoil\">\n    <!-- Back Loop Turns -->\n    <ellipse cx=\"400\" cy=\"270\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"10\"/>\n    <ellipse cx=\"402\" cy=\"265\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\"/>\n    <ellipse cx=\"398\" cy=\"260\" rx=\"80\" ry=\"50\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n\n    <!-- Front Loop Turns -->\n    <ellipse cx=\"400\" cy=\"275\" rx=\"95\" ry=\"65\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n    <ellipse cx=\"405\" cy=\"280\" rx=\"90\" ry=\"60\" fill=\"none\" stroke=\"url(#cordDark)\" stroke-width=\"9\"/>\n    <ellipse cx=\"395\" cy=\"285\" rx=\"85\" ry=\"55\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"10\"/>\n\n    <!-- Center Binding Collar (다발 고정 묶음) -->\n    <rect x=\"382\" y=\"210\" width=\"36\" height=\"135\" rx=\"6\" fill=\"#4d3722\" stroke=\"#2b1d10\" stroke-width=\"2\"/>\n    <!-- Individual Wrap Wrappings Around Center -->\n    <g stroke=\"url(#cordLight)\" stroke-width=\"5\" stroke-linecap=\"round\">\n      <line x1=\"384\" y1=\"225\" x2=\"416\" y2=\"225\"/>\n      <line x1=\"384\" y1=\"240\" x2=\"416\" y2=\"240\"/>\n      <line x1=\"384\" y1=\"255\" x2=\"416\" y2=\"255\"/>\n      <line x1=\"384\" y1=\"270\" x2=\"416\" y2=\"270\"/>\n      <line x1=\"384\" y1=\"285\" x2=\"416\" y2=\"285\"/>\n      <line x1=\"384\" y1=\"300\" x2=\"416\" y2=\"300\"/>\n      <line x1=\"384\" y1=\"315\" x2=\"416\" y2=\"315\"/>\n      <line x1=\"384\" y1=\"330\" x2=\"416\" y2=\"330\"/>\n    </g>\n\n    <!-- Trailing Working End with Figure-8 Stopper Knot -->\n    <path d=\"M 400 340 Q 370 380 320 375 Q 290 370 270 380\" fill=\"none\" stroke=\"url(#cordLight)\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n    <!-- Figure-8 Knot Ball -->\n    <circle cx=\"270\" cy=\"380\" r=\"10\" fill=\"#735435\" stroke=\"#3b2b1a\" stroke-width=\"2\"/>\n    <path d=\"M 264 374 Q 270 386 276 374\" stroke=\"#d4b483\" stroke-width=\"2.5\" fill=\"none\"/>\n  </g>\n\n  <!-- Zoom Loupe Window for Micro Reverse-Wrap Detail -->\n  <g id=\"microDetailWindow\" transform=\"translate(180, 110)\">\n    <!-- Lens Circle -->\n    <circle cx=\"150\" cy=\"50\" r=\"48\" fill=\"#141414\" stroke=\"#444\" stroke-width=\"2\"/>\n    <!-- Interior 2-Ply Braid Micro Strands -->\n    <g stroke-width=\"4.5\" stroke-linecap=\"round\">\n      <!-- Strand A (Dark Bast) -->\n      <path d=\"M 115 35 Q 130 30 145 45 Q 160 60 175 45 Q 190 30 195 40\" fill=\"none\" stroke=\"#694d2f\"/>\n      <!-- Strand B (Light Kudzu) -->\n      <path d=\"M 115 55 Q 130 65 145 45 Q 160 25 175 45 Q 190 65 195 55\" fill=\"none\" stroke=\"#c4a57b\"/>\n      <!-- Surface Twisting Hatch Lines -->\n      <line x1=\"124\" y1=\"38\" x2=\"128\" y2=\"44\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"154\" y1=\"48\" x2=\"158\" y2=\"54\" stroke=\"#3d2b18\" stroke-width=\"1.2\"/>\n      <line x1=\"138\" y1=\"48\" x2=\"142\" y2=\"54\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n      <line x1=\"168\" y1=\"38\" x2=\"172\" y2=\"44\" stroke=\"#edd6b6\" stroke-width=\"1.2\"/>\n    </g>\n    <!-- Loupe Label -->\n    <text x=\"150\" y=\"88\" fill=\"#888\" font-family=\"monospace\" font-size=\"8\" text-anchor=\"middle\">5X MAGNIFICATION</text>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Reverse Wrap Mechanics -->\n    <line x1=\"375\" y1=\"150\" x2=\"565\" y2=\"150\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"150\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"147\" fill=\"#E02424\" font-weight=\"bold\">2-PLY REVERSE INTERLOCK</text>\n    <text x=\"570\" y=\"160\" fill=\"#888888\">자체 마찰력으로 당길수록 더 단단히 조임</text>\n\n    <!-- Callout 2: Center Collar -->\n    <line x1=\"418\" y1=\"250\" x2=\"565\" y2=\"250\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"418\" cy=\"250\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"247\" fill=\"#ffffff\" font-weight=\"bold\">EXPEDITION COIL PACK</text>\n    <text x=\"570\" y=\"260\" fill=\"#888888\">엉킴 없이 즉각 풀리는 야전 휴대 권취</text>\n\n    <!-- Callout 3: Tensile Strength -->\n    <line x1=\"480\" y1=\"310\" x2=\"565\" y2=\"310\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"480\" cy=\"310\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"570\" y=\"307\" fill=\"#4ade80\" font-weight=\"bold\">TENSILE BREAK: 90+ KGF</text>\n    <text x=\"570\" y=\"320\" fill=\"#888888\">성인 체중 및 쉘터 가이라인 완벽 지지</text>\n\n    <!-- Callout 4: Figure-8 Stopper -->\n    <line x1=\"280\" y1=\"380\" x2=\"565\" y2=\"380\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"280\" cy=\"380\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"377\" fill=\"#38bdf8\" font-weight=\"bold\">FIGURE-8 STOPPER KNOT</text>\n    <text x=\"570\" y=\"390\" fill=\"#888888\">말단 올 풀림을 영구 방지하는 8자 마감</text>\n  </g>\n</svg>\n","content/svgs/pr05-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid & Guide lines -->\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Outer circle (Stem cross section) -->\n  <circle cx=\"190\" cy=\"175\" r=\"95\" fill=\"#1C1814\" stroke=\"#8B5A2B\" stroke-width=\"5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"82\" fill=\"#242820\" stroke=\"#E5E5E5\" stroke-dasharray=\"3 3\" stroke-width=\"2.5\" />\n  <circle cx=\"190\" cy=\"175\" r=\"45\" fill=\"#151515\" stroke=\"#444444\" stroke-width=\"2\" />\n  <circle cx=\"190\" cy=\"175\" r=\"6\" fill=\"#666666\" />\n\n  <!-- Stone scraper tool peeling bark -->\n  <path d=\"M175,78 L240,48 L228,92 Z\" fill=\"#3A3A3A\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <path d=\"M195,85 Q235,90 265,70\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n\n  <!-- Bent living vine diagram -->\n  <path d=\"M350,245 Q430,135 545,195\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"6\"/>\n  <circle cx=\"350\" cy=\"245\" r=\"4\" fill=\"#10B981\"/>\n  <circle cx=\"545\" cy=\"195\" r=\"4\" fill=\"#10B981\"/>\n\n  <!-- Peel strand visualization -->\n  <path d=\"M265,125 C305,105 350,135 395,115\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"5\"/>\n  <path d=\"M275,145 C315,125 360,155 405,135\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"4\"/>\n\n  <!-- Callout lines -->\n  <line x1=\"240\" y1=\"58\" x2=\"295\" y2=\"48\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"265\" y1=\"120\" x2=\"295\" y2=\"95\" stroke=\"#8B5A2B\" stroke-width=\"1.2\"/>\n  <line x1=\"270\" y1=\"165\" x2=\"295\" y2=\"145\" stroke=\"#E5E5E5\" stroke-width=\"1.2\"/>\n  <line x1=\"190\" y1=\"175\" x2=\"295\" y2=\"205\" stroke=\"#888888\" stroke-width=\"1.2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"300\" y=\"52\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 돌 모서리로 거친 겉껍질만 살살 긁어내기</text>\n  <text x=\"300\" y=\"98\" fill=\"#C49A6C\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 잘 부러지는 갈색 겉껍질 (긁어내어 버림)</text>\n  <text x=\"300\" y=\"148\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 질기고 하얀 속껍질 섬유층 (밧줄 핵심 재료)</text>\n  <text x=\"300\" y=\"208\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 가운데 딱딱한 나무 속심 (빼내고 버림)</text>\n  <text x=\"260\" y=\"295\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 구부렸을 때 부러지지 않고 휘어지는 살아있는 줄기</text>\n</svg>","content/svgs/pr05-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Water stream / pool zone on left -->\n  <rect x=\"70\" y=\"80\" width=\"130\" height=\"90\" fill=\"#102528\" stroke=\"#007788\" stroke-width=\"1.5\"/>\n  <path d=\"M75,115 Q135,95 195,115\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M75,135 Q135,155 195,135\" fill=\"none\" stroke=\"#00B4D8\" stroke-width=\"2\"/>\n  <path d=\"M90,100 Q120,150 170,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"3\"/>\n\n  <!-- Flat anvil stone in center -->\n  <polygon points=\"240,225 450,225 470,265 220,265\" fill=\"#282828\" stroke=\"#666666\" stroke-width=\"2\"/>\n\n  <!-- Round hand hammer stone -->\n  <ellipse cx=\"335\" cy=\"145\" rx=\"36\" ry=\"26\" fill=\"#3D3D3D\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"335\" y1=\"175\" x2=\"335\" y2=\"210\" stroke=\"#E02424\" stroke-width=\"2.5\" stroke-dasharray=\"3 3\"/>\n  <polygon points=\"330,205 335,218 340,205\" fill=\"#E02424\"/>\n\n  <!-- Crushed soft fiber on the stone -->\n  <path d=\"M270,220 C310,210 350,230 400,220\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <path d=\"M280,217 C320,223 360,215 395,221\" stroke=\"#9E9E9E\" stroke-width=\"2\"/>\n\n  <!-- Two split bundles on right -->\n  <path d=\"M490,145 Q525,180 575,170\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <path d=\"M490,215 Q525,195 575,225\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"4\"/>\n  <circle cx=\"490\" cy=\"180\" r=\"14\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"70\" y=\"55\" fill=\"#00B4D8\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 냇물에 20분 이상 담가 부드럽게 불린 속껍질</text>\n  <text x=\"250\" y=\"98\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 둥근 돌로 살살 두드려 섬유 결 쪼개기</text>\n  <text x=\"380\" y=\"135\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">③ 머리카락처럼 부드럽게 풀어진 섬유 다발</text>\n  <text x=\"380\" y=\"255\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 손가락 굵기로 똑같이 나눈 두 가닥</text>\n  <text x=\"190\" y=\"298\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 바닥에 흔들리지 않게 받친 평평한 강돌</text>\n</svg>","content/svgs/pr05-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Left finished twisted rope -->\n  <g transform=\"translate(95, 165)\">\n    <path d=\"M0,0 C20,-15 40,15 60,0 C80,-15 100,15 120,0 C140,-15 160,15 180,0\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"10\"/>\n    <path d=\"M0,0 C20,15 40,-15 60,0 C80,15 100,-15 120,0 C140,15 160,-15 180,0\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  </g>\n\n  <!-- Left hand pinch point -->\n  <circle cx=\"275\" cy=\"165\" r=\"18\" fill=\"#1E1E1E\" stroke=\"#E02424\" stroke-width=\"2.5\"/>\n  <circle cx=\"275\" cy=\"165\" r=\"4\" fill=\"#E02424\"/>\n\n  <!-- Top strand twisting outward (away from body) -->\n  <path d=\"M290,157 Q365,115 445,110\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"7\"/>\n  <path d=\"M365,120 C370,95 390,90 400,105\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"3\"/>\n  <polygon points=\"400,97 407,107 395,110\" fill=\"#10B981\"/>\n\n  <!-- Bottom strand crossing over towards body -->\n  <path d=\"M290,173 Q355,215 445,220\" fill=\"none\" stroke=\"#888888\" stroke-width=\"7\"/>\n  <path d=\"M375,135 C405,155 395,185 385,200\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"3\" stroke-dasharray=\"4 2\"/>\n  <polygon points=\"380,193 383,207 393,198\" fill=\"#D97706\"/>\n\n  <!-- Double lock icon/diagram on right -->\n  <rect x=\"490\" y=\"115\" width=\"110\" height=\"95\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1.5\"/>\n  <path d=\"M520,162 L570,162 M545,137 L545,187\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <circle cx=\"545\" cy=\"162\" r=\"18\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Labels -->\n  <text x=\"250\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 위쪽 가닥: 몸 바깥쪽(↑)으로 단단히 비틀기</text>\n  <text x=\"70\" y=\"115\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 서로 되감기며 톱니처럼 맞물린 밧줄 무늬</text>\n  <text x=\"70\" y=\"218\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 왼손 엄지·검지로 꼬인 자리 꽉 눌러 잡기</text>\n  <text x=\"250\" y=\"258\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 비튼 위 가닥을 아래 가닥 너머 몸 쪽(↓)으로 넘기기</text>\n  <text x=\"280\" y=\"298\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 손을 놓아도 절대 풀리지 않는 역방향 잠금 구조</text>\n</svg>","content/svgs/pr05-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Top strand: Thinned old strand + New thick strand overlap -->\n  <g transform=\"translate(80, 120)\">\n    <path d=\"M0,20 L160,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M160,20 L260,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M160,10 L260,10\" stroke=\"#10B981\" stroke-width=\"3\"/>\n    <path d=\"M260,10 L430,10\" stroke=\"#10B981\" stroke-width=\"6\"/>\n    <line x1=\"160\" y1=\"-5\" x2=\"260\" y2=\"-5\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"160\" y1=\"-10\" x2=\"160\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n    <line x1=\"260\" y1=\"-10\" x2=\"260\" y2=\"0\" stroke=\"#E02424\" stroke-width=\"1.5\"/>\n  </g>\n\n  <!-- Bottom strand: Staggered junction 15cm further right -->\n  <g transform=\"translate(80, 200)\">\n    <path d=\"M0,20 L300,20\" stroke=\"#888888\" stroke-width=\"5\"/>\n    <path d=\"M300,20 L400,20\" stroke=\"#888888\" stroke-width=\"2.5\" stroke-dasharray=\"2 2\"/>\n    <path d=\"M300,10 L400,10\" stroke=\"#D97706\" stroke-width=\"3\"/>\n    <path d=\"M400,10 L470,10\" stroke=\"#D97706\" stroke-width=\"6\"/>\n    <line x1=\"210\" y1=\"45\" x2=\"350\" y2=\"45\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/>\n    <polygon points=\"210,41 202,45 210,49\" fill=\"#E5E5E5\"/>\n    <polygon points=\"350,41 358,45 350,49\" fill=\"#E5E5E5\"/>\n  </g>\n\n  <!-- Smooth twisted rope preview on far right -->\n  <path d=\"M520,165 C545,150 570,180 595,165\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"8\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"75\" y=\"58\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">① 끝이 10cm쯤 남아 가늘어진 기존 가닥</text>\n  <text x=\"235\" y=\"96\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">② 새 섬유 다발을 10cm 나란히 겹쳐 대기</text>\n  <text x=\"75\" y=\"178\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 겹친 두 줄을 한 가닥처럼 함께 비틀어 감기</text>\n  <text x=\"360\" y=\"232\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">④ 불룩해지지 않고 매끄럽게 이어진 연결부</text>\n  <text x=\"150\" y=\"295\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 위·아래 이음매 위치를 한 뼘(15cm) 어긋나게 배치</text>\n</svg>","content/svgs/pr05-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto max-w-[680px]\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"0\" y=\"0\" width=\"680\" height=\"340\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Tree trunk on left -->\n  <rect x=\"95\" y=\"75\" width=\"55\" height=\"205\" fill=\"#221C18\" stroke=\"#665544\" stroke-width=\"3\"/>\n  <path d=\"M95,115 L150,115 M95,175 L150,175 M95,235 L150,235\" stroke=\"#443322\" stroke-width=\"1\"/>\n\n  <!-- Rope wrapped around tree trunk -->\n  <ellipse cx=\"122\" cy=\"155\" rx=\"33\" ry=\"12\" fill=\"none\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n  <line x1=\"155\" y1=\"155\" x2=\"425\" y2=\"155\" stroke=\"#E5E5E5\" stroke-width=\"6\"/>\n\n  <!-- End eye knot -->\n  <g transform=\"translate(425, 155)\">\n    <circle cx=\"20\" cy=\"0\" r=\"16\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"5\"/>\n    <rect x=\"0\" y=\"-8\" width=\"12\" height=\"16\" fill=\"#E02424\" stroke=\"#E5E5E5\" stroke-width=\"1\"/>\n  </g>\n\n  <!-- Stone scraper trimming loose fuzz -->\n  <polygon points=\"310,115 350,100 340,130\" fill=\"#444444\" stroke=\"#E5E5E5\" stroke-width=\"1.5\"/>\n  <path d=\"M290,152 L295,140 M305,152 L310,143 M320,152 L325,141\" stroke=\"#9E9E9E\" stroke-width=\"1.5\"/>\n\n  <!-- Body weight tension indicator arrow -->\n  <g transform=\"translate(310, 168)\">\n    <line x1=\"0\" y1=\"10\" x2=\"65\" y2=\"10\" stroke=\"#E02424\" stroke-width=\"3\"/>\n    <polygon points=\"65,5 77,10 65,15\" fill=\"#E02424\"/>\n  </g>\n\n  <!-- Practical usage box on right -->\n  <rect x=\"495\" y=\"105\" width=\"110\" height=\"110\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\"/>\n  <line x1=\"510\" y1=\"135\" x2=\"590\" y2=\"135\" stroke=\"#10B981\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"160\" x2=\"590\" y2=\"160\" stroke=\"#E5E5E5\" stroke-width=\"2\"/>\n  <line x1=\"510\" y1=\"185\" x2=\"590\" y2=\"185\" stroke=\"#D97706\" stroke-width=\"2\"/>\n\n  <!-- 5 Clean, Non-Overlapping Top-Level Labels -->\n  <text x=\"270\" y=\"62\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">① 끝부분 3cm를 접어 묶은 풀림 방지 마감 매듭</text>\n  <text x=\"175\" y=\"102\" fill=\"#9E9E9E\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\">② 삐져나온 잔털을 돌날로 깔끔하게 정리</text>\n  <text x=\"175\" y=\"212\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">③ 나무 기둥에 걸고 몸무게(50kg+)를 실어 당겨보기</text>\n  <text x=\"175\" y=\"255\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">④ 완성된 5mm 굵기 야생 밧줄 (5m 길이)</text>\n  <text x=\"210\" y=\"298\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"11\" font-weight=\"bold\">⑤ 움막 기둥 묶기·돌도끼 고정·활비비 줄로 즉시 활용</text>\n</svg>","content/svgs/pr06-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGrad6\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0e0c0b\"/>\n      <stop offset=\"100%\" stop-color=\"#17120f\"/>\n    </linearGradient>\n\n    <!-- Clay & Terracotta Plaster Gradients -->\n    <linearGradient id=\"clayPlaster\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#a8653b\"/>\n      <stop offset=\"40%\" stop-color=\"#8c4e26\"/>\n      <stop offset=\"80%\" stop-color=\"#693717\"/>\n      <stop offset=\"100%\" stop-color=\"#45230c\"/>\n    </linearGradient>\n    <linearGradient id=\"stoneBlock\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#4a4a4a\"/>\n      <stop offset=\"50%\" stop-color=\"#737373\"/>\n      <stop offset=\"100%\" stop-color=\"#3d3d3d\"/>\n    </linearGradient>\n\n    <!-- Glowing Firebox Interior -->\n    <radialGradient id=\"hearthFireGlow\" cx=\"50%\" cy=\"60%\" r=\"55%\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\n      <stop offset=\"20%\" stop-color=\"#fef08a\"/>\n      <stop offset=\"50%\" stop-color=\"#f97316\"/>\n      <stop offset=\"80%\" stop-color=\"#dc2626\"/>\n      <stop offset=\"100%\" stop-color=\"#140804\"/>\n    </radialGradient>\n\n    <filter id=\"heatBlur\" x=\"-10%\" y=\"-10%\" width=\"120%\" height=\"120%\">\n      <feGaussianBlur stdDeviation=\"2\"/>\n    </filter>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGrad6)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: STONE &amp; TEMPERED CLAY HEARTH [650°C SPEC]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">MAX TEMP: 650°C</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">HEARTH METRICS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· BASE: U-SHAPE RIVER STONE</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· CLAY WALL: 50 MM THICK</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· DRAFT: REAR EXHAUST FLUE</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· COOKTOP: LEVEL STONE RIM</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· FUEL EFF: 3X WOOD SAVING</text>\n    <text x=\"55\" y=\"240\" fill=\"#f97316\">· CORE TEMP: 650°C INTENSE</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"390\" rx=\"220\" ry=\"20\" fill=\"#050302\" opacity=\"0.9\"/>\n\n  <!-- Clay & Stone Hearth Structure (3D Perspective) -->\n  <g id=\"hearth3D\">\n    <!-- Foundation River Stones Layer (Base Tier) -->\n    <g id=\"baseStones\">\n      <ellipse cx=\"290\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"340\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"400\" cy=\"380\" rx=\"38\" ry=\"20\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"460\" cy=\"375\" rx=\"35\" ry=\"19\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"510\" cy=\"365\" rx=\"32\" ry=\"18\" fill=\"url(#stoneBlock)\" stroke=\"#222\" stroke-width=\"1.5\"/>\n    </g>\n\n    <!-- Main Terracotta Clay Domed Wall Body -->\n    <path d=\"M 270 360 C 270 230 330 180 400 180 C 470 180 530 230 530 360 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"2\"/>\n\n    <!-- Clay Drying Cracks & Straw Binder Texture -->\n    <g stroke=\"#52240b\" stroke-width=\"1.2\" fill=\"none\" opacity=\"0.7\">\n      <path d=\"M 320 250 Q 335 265 330 285\"/>\n      <path d=\"M 470 240 Q 460 260 475 275\"/>\n      <path d=\"M 360 210 Q 380 220 375 235\"/>\n      <path d=\"M 430 215 Q 420 230 435 245\"/>\n    </g>\n\n    <!-- Top Level Cooking Platform Rim (돌판/냄비 얹는 조리구) -->\n    <ellipse cx=\"400\" cy=\"180\" rx=\"55\" ry=\"18\" fill=\"#4d4d4d\" stroke=\"#262626\" stroke-width=\"2\"/>\n    <ellipse cx=\"400\" cy=\"180\" rx=\"42\" ry=\"13\" fill=\"#171717\" stroke=\"#333\" stroke-width=\"1.5\"/>\n\n    <!-- Rear Vertical Chimney Flue (후면 배기 굴뚝) -->\n    <g id=\"chimneyFlue\">\n      <path d=\"M 465 190 L 485 130 L 515 130 L 505 210 Z\" fill=\"url(#clayPlaster)\" stroke=\"#381907\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"500\" cy=\"130\" rx=\"15\" ry=\"6\" fill=\"#140804\" stroke=\"#381907\" stroke-width=\"1.2\"/>\n      <!-- Hot Chimney Exhaust Heat Shimmer -->\n      <path d=\"M 500 125 Q 492 95 505 75 Q 515 55 500 35\" stroke=\"#f97316\" stroke-width=\"2\" fill=\"none\" opacity=\"0.4\" filter=\"url(#heatBlur)\"/>\n      <path d=\"M 504 125 Q 512 90 498 70\" stroke=\"#fef08a\" stroke-width=\"1.5\" fill=\"none\" opacity=\"0.5\" filter=\"url(#heatBlur)\"/>\n    </g>\n\n    <!-- Front Firebox Mouth (연소실 아치 개구부) -->\n    <path d=\"M 335 365 C 335 250 465 250 465 365 Z\" fill=\"#0d0401\" stroke=\"#260f04\" stroke-width=\"2\"/>\n    <!-- Intense Glowing Radiant Embers in Firebox -->\n    <ellipse cx=\"400\" cy=\"340\" rx=\"60\" ry=\"24\" fill=\"url(#hearthFireGlow)\"/>\n\n    <!-- Firewood Logs & Core Flames Inside -->\n    <!-- Charred Log 1 -->\n    <polygon points=\"350,355 425,325 435,335 360,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Charred Log 2 -->\n    <polygon points=\"445,355 375,325 365,335 435,365\" fill=\"#1c1109\" stroke=\"#080402\" stroke-width=\"1\"/>\n    <!-- Active Flame Tongues -->\n    <path d=\"M 400 345 C 385 330 380 300 400 270 C 405 285 412 290 410 275 C 418 285 425 305 420 330 C 425 320 428 310 424 298 C 432 312 430 335 415 345 Z\" fill=\"#f97316\" filter=\"url(#heatBlur)\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"14\" ry=\"18\" fill=\"#fef08a\"/>\n    <ellipse cx=\"402\" cy=\"335\" rx=\"8\" ry=\"10\" fill=\"#ffffff\"/>\n\n    <!-- Inflow Air Draft Direction Arrows (하단 산소 흡입) -->\n    <g stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"none\">\n      <path d=\"M 300 375 Q 330 365 350 355\"/>\n      <path d=\"M 500 375 Q 470 365 450 355\"/>\n    </g>\n  </g>\n\n  <!-- Technical Callouts (Right Side) -->\n  <g id=\"calloutsRight\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Chimney Flue -->\n    <line x1=\"505\" y1=\"130\" x2=\"565\" y2=\"130\" stroke=\"#f97316\" stroke-width=\"1\"/>\n    <circle cx=\"505\" cy=\"130\" r=\"2\" fill=\"#f97316\"/>\n    <text x=\"570\" y=\"127\" fill=\"#f97316\" font-weight=\"bold\">REAR EXHAUST CHIMNEY</text>\n    <text x=\"570\" y=\"140\" fill=\"#888888\">후면 굴뚝 상승 기류로 불완전연소 방지</text>\n\n    <!-- Callout 2: Top Cooktop Rim -->\n    <line x1=\"455\" y1=\"180\" x2=\"565\" y2=\"180\" stroke=\"#666\" stroke-width=\"1\"/>\n    <circle cx=\"455\" cy=\"180\" r=\"2\" fill=\"#666\"/>\n    <text x=\"570\" y=\"177\" fill=\"#ffffff\" font-weight=\"bold\">LEVEL COOKING RIM</text>\n    <text x=\"570\" y=\"190\" fill=\"#888888\">냄비·판석을 안정되게 얹는 직화 가열구</text>\n\n    <!-- Callout 3: 5cm Clay Wall -->\n    <line x1=\"510\" y1=\"260\" x2=\"565\" y2=\"260\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <circle cx=\"510\" cy=\"260\" r=\"2\" fill=\"#E02424\"/>\n    <text x=\"570\" y=\"257\" fill=\"#E02424\" font-weight=\"bold\">5CM CLAY INSULATION</text>\n    <text x=\"570\" y=\"270\" fill=\"#888888\">볏짚 황토 미장으로 열기를 가두어 650°C 유지</text>\n\n    <!-- Callout 4: Arch Inflow Draft -->\n    <line x1=\"465\" y1=\"340\" x2=\"565\" y2=\"340\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"465\" cy=\"340\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"570\" y=\"337\" fill=\"#38bdf8\" font-weight=\"bold\">INFLOW DRAFT ARCH</text>\n    <text x=\"570\" y=\"350\" fill=\"#888888\">바람을 막고 하단 산소를 흡입하는 아치 입구</text>\n  </g>\n</svg>\n","content/svgs/pr06-step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-step1\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 01 // CLAY TEMPERING &amp; FIBER MATRIX BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Material 1: 붉은 찰흙 2바가지 -->\n          <g transform=\"translate(100, 70)\">\n            <ellipse cx=\"45\" cy=\"45\" rx=\"38\" ry=\"24\" fill=\"#1C1815\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            <path d=\"M 20 45 Q 45 15 70 45\" stroke=\"#D97706\" stroke-width=\"1\" fill=\"none\" stroke-dasharray=\"2,2\" />\n            <circle cx=\"45\" cy=\"35\" r=\"4\" fill=\"#D97706\" />\n          </g>\n          <text x=\"80\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 붉은 찰흙 2바가지\n          </text>\n          <text x=\"80\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            끈끈한 점력의 기본 바탕재\n          </text>\n\n          <!-- Plus Sign 1 -->\n          <text x=\"210\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 2: 굵은 모래 1바가지 -->\n          <g transform=\"translate(235, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#151717\" stroke=\"#06B6D4\" stroke-width=\"1.5\" />\n            <!-- Sand speckles -->\n            <circle cx=\"28\" cy=\"38\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"42\" cy=\"32\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"50\" cy=\"42\" r=\"1.5\" fill=\"#06B6D4\" />\n            <circle cx=\"35\" cy=\"45\" r=\"1.5\" fill=\"#06B6D4\" />\n          </g>\n          <text x=\"235\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 굵은 모래 1바가지\n          </text>\n          <text x=\"235\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            마를 때 오그라듦 방지\n          </text>\n\n          <!-- Plus Sign 2 -->\n          <text x=\"350\" y=\"115\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n          <!-- Material 3: 잘게 자른 마른 풀잎 -->\n          <g transform=\"translate(375, 75)\">\n            <ellipse cx=\"40\" cy=\"40\" rx=\"34\" ry=\"20\" fill=\"#141914\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <!-- Grass fiber lines -->\n            <line x1=\"25\" y1=\"36\" x2=\"40\" y2=\"44\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"38\" y1=\"32\" x2=\"52\" y2=\"40\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n            <line x1=\"30\" y1=\"46\" x2=\"48\" y2=\"42\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n          <text x=\"375\" y=\"155\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 잘게 자른 마른 풀잎\n          </text>\n          <text x=\"375\" y=\"175\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            뼈대 역할을 하는 보강 섬유\n          </text>\n\n          <!-- Arrow downward to kneading and ball -->\n          <path d=\"M 290 190 L 290 220\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-step1)\" />\n\n          <!-- Process 4: 물을 조금씩 부어가며 발로 치대기 -->\n          <rect x=\"80\" y=\"235\" width=\"220\" height=\"65\" fill=\"#141414\" stroke=\"#333333\" stroke-width=\"1\" />\n          <text x=\"95\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 물을 조금씩 부어가며 발로 치대기\n          </text>\n          <text x=\"95\" y=\"282\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            한 번에 많이 붓지 말고 뒤집으며 밟기\n          </text>\n\n          <!-- Process 5: 차진 반죽 덩어리 판정 -->\n          <g transform=\"translate(350, 225)\">\n            <!-- Clay ball -->\n            <circle cx=\"65\" cy=\"40\" r=\"32\" fill=\"#1C1815\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <!-- Inner smooth contour -->\n            <path d=\"M 45 40 Q 65 20 85 40\" stroke=\"#888888\" stroke-width=\"1\" fill=\"none\" />\n            <circle cx=\"65\" cy=\"40\" r=\"4\" fill=\"#10B981\" />\n          </g>\n          <text x=\"470\" y=\"255\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 차진 반죽 덩어리 완성\n          </text>\n          <text x=\"470\" y=\"278\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            주먹 크기로 둥글게 뭉쳐도\n          </text>\n          <text x=\"470\" y=\"295\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            겉면에 실금이 가지 않는 상태\n          </text>\n        </svg>","content/svgs/pr06-step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-wind\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 02 // FOUNDATION LAYOUT &amp; AIR ENTRY SCHEMATIC\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Center U-Shape Stone Structure (Top-Down View) -->\n          <g transform=\"translate(180, 75)\">\n            <!-- Base Ground Insulation Bed (모래/자갈층) -->\n            <rect x=\"0\" y=\"0\" width=\"220\" height=\"190\" fill=\"#121212\" stroke=\"#262626\" stroke-width=\"1\" stroke-dasharray=\"3,3\" />\n\n            <!-- U-shaped Mud Bed -->\n            <path d=\"M 40 170 L 40 50 Q 110 10 180 50 L 180 170\" fill=\"none\" stroke=\"#654321\" stroke-width=\"36\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n\n            <!-- Stones in U-Shape -->\n            <!-- Left arm stones -->\n            <circle cx=\"40\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"40\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"45\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Curve stones -->\n            <circle cx=\"70\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"110\" cy=\"30\" r=\"16\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"150\" cy=\"45\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right arm stones -->\n            <circle cx=\"175\" cy=\"80\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"120\" r=\"15\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <circle cx=\"180\" cy=\"160\" r=\"14\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Front Opening (장작 입구 폭 20cm) -->\n            <line x1=\"56\" y1=\"165\" x2=\"164\" y2=\"165\" stroke=\"#F59E0B\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\" />\n            <line x1=\"56\" y1=\"160\" x2=\"56\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n            <line x1=\"164\" y1=\"160\" x2=\"164\" y2=\"170\" stroke=\"#F59E0B\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm) -->\n          <text x=\"80\" y=\"290\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 장작 넣는 입구 (한 뼘 너비 20cm)\n          </text>\n          <text x=\"80\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            불길 조절과 공기 공급에 알맞은 입구 폭\n          </text>\n\n          <!-- Label 2: U자형으로 둘러앉힌 마른 돌 -->\n          <line x1=\"180\" y1=\"130\" x2=\"120\" y2=\"100\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"85\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② U자형 주먹만 한 마른 돌\n          </text>\n          <text x=\"75\" y=\"103\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            기초를 지탱하는 1차 뼈대\n          </text>\n\n          <!-- Label 3: 돌 틈새를 메운 진흙 반죽 -->\n          <line x1=\"395\" y1=\"145\" x2=\"450\" y2=\"120\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"115\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 틈새를 메운 진흙 반죽\n          </text>\n          <text x=\"455\" y=\"133\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 사이 공기 누출 완전 차단\n          </text>\n\n          <!-- Label 4: 바닥 모래·자갈 단열층 -->\n          <line x1=\"290\" y1=\"180\" x2=\"450\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n          <text x=\"455\" y=\"185\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 바닥 마른 모래·자갈 단열층\n          </text>\n          <text x=\"455\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 땅바닥 습기와 냉기 차단\n          </text>\n\n          <!-- Label 5: 바람 불어오는 반대 방향 -->\n          <g transform=\"translate(420, 245)\">\n            <path d=\"M 0 15 L 45 15\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n            <path d=\"M 5 28 L 50 28\" stroke=\"#06B6D4\" stroke-width=\"1.5\" marker-end=\"url(#arrow-wind)\" />\n          </g>\n          <text x=\"390\" y=\"290\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 바람 불어오는 반대쪽으로 입구 배치\n          </text>\n          <text x=\"390\" y=\"308\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강풍에 불티가 역류하거나 꺼지지 않도록 보호\n          </text>\n        </svg>","content/svgs/pr06-step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-swirl\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 03 // DOME CHAMBER CROSS-SECTION &amp; THERMAL CURVATURE\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Cutaway Dome Silhouette -->\n          <g transform=\"translate(190, 70)\">\n            <!-- Outer Mud Layer -->\n            <path d=\"M 30 190 C 30 70 80 20 150 20 C 220 20 270 70 270 190\" fill=\"none\" stroke=\"#8B5A2B\" stroke-width=\"40\" stroke-linecap=\"round\" />\n\n            <!-- Embedded Staggered Stones (Cross section) -->\n            <!-- Left wall stones -->\n            <ellipse cx=\"40\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"44\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"58\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"85\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Top apex stones -->\n            <ellipse cx=\"125\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"175\" cy=\"32\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <!-- Right wall stones -->\n            <ellipse cx=\"215\" cy=\"55\" rx=\"12\" ry=\"8\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"242\" cy=\"90\" rx=\"12\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"256\" cy=\"130\" rx=\"13\" ry=\"9\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n            <ellipse cx=\"260\" cy=\"170\" rx=\"14\" ry=\"10\" fill=\"#222222\" stroke=\"#E5E5E5\" stroke-width=\"1.5\" />\n\n            <!-- Smooth Interior Heat Reflector Surface -->\n            <path d=\"M 50 190 C 50 90 90 40 150 40 C 210 40 250 90 250 190\" fill=\"#141414\" stroke=\"#F59E0B\" stroke-width=\"2\" />\n\n            <!-- Rotating Heat Swirl Inside Chamber -->\n            <path d=\"M 120 160 Q 150 100 180 140 Q 150 170 135 120\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-swirl)\" />\n\n            <!-- Dimension: Height 45cm (무릎 높이) -->\n            <line x1=\"295\" y1=\"20\" x2=\"295\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <line x1=\"290\" y1=\"20\" x2=\"300\" y2=\"20\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <line x1=\"290\" y1=\"190\" x2=\"300\" y2=\"190\" stroke=\"#06B6D4\" stroke-width=\"1\" />\n            <text x=\"305\" y=\"110\" fill=\"#06B6D4\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\">45cm</text>\n          </g>\n\n          <!-- Label 1: 돌과 진흙을 엇갈려 쌓은 벽체 단면 -->\n          <line x1=\"210\" y1=\"180\" x2=\"130\" y2=\"150\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"125\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 엇갈려 쌓은 벽체 단면\n          </text>\n          <text x=\"75\" y=\"143\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            돌 틈에 진흙을 채워 무너짐 방지\n          </text>\n\n          <!-- Label 2: 손바닥 두께(약 5cm) 단열벽 -->\n          <line x1=\"430\" y1=\"180\" x2=\"480\" y2=\"150\" stroke=\"#D97706\" stroke-width=\"1\" />\n          <text x=\"470\" y=\"130\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 손바닥 두께(약 5cm) 진흙벽\n          </text>\n          <text x=\"470\" y=\"148\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            바깥으로 새는 열 손실 완벽 차단\n          </text>\n\n          <!-- Label 3: 안쪽 벽면 매끄러운 열 반사 곡면 -->\n          <line x1=\"270\" y1=\"130\" x2=\"150\" y2=\"225\" stroke=\"#F59E0B\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"235\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 매끄러운 열 반사 곡면\n          </text>\n          <text x=\"75\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            손에 물을 묻혀 반질반질하게 다듬기\n          </text>\n\n          <!-- Label 4: 열기가 모여 회전하는 연소실 내부 -->\n          <text x=\"210\" y=\"295\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 열기가 모여 회전하는 둥근 연소실 내부\n          </text>\n\n          <!-- Label 5: 무릎 높이(약 45cm) 전체 외형선 -->\n          <text x=\"460\" y=\"235\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 무릎 높이(약 45cm) 외형선\n          </text>\n          <text x=\"460\" y=\"253\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            취사 안정성과 축열 용적 최적화\n          </text>\n        </svg>","content/svgs/pr06-step-04.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <defs>\n            <marker id=\"arrow-draft-blue\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#06B6D4\" />\n            </marker>\n            <marker id=\"arrow-draft-red\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#E02424\" />\n            </marker>\n            <marker id=\"arrow-smoke\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n              <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#888888\" />\n            </marker>\n          </defs>\n\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 04 // AIR DRAFT PERSPECTIVE &amp; EXHAUST BLUEPRINT\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Perspective Cutaway Chamber -->\n          <g transform=\"translate(160, 65)\">\n            <!-- Outer structure wireframe / body -->\n            <path d=\"M 30 180 L 30 120 Q 50 40 160 30 L 260 50 Q 320 80 330 180 Z\" fill=\"#151515\" stroke=\"#333333\" stroke-width=\"1\" />\n\n            <!-- Flat Top Cooking Rim (냄비 얹는 자리) -->\n            <ellipse cx=\"160\" cy=\"40\" rx=\"36\" ry=\"12\" fill=\"#202020\" stroke=\"#E5E5E5\" stroke-width=\"2\" />\n            <path d=\"M 124 40 Q 160 52 196 40\" stroke=\"#888888\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n\n            <!-- Clay Spacer Knobs (틈새 돌기) -->\n            <circle cx=\"128\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"160\" cy=\"51\" r=\"3\" fill=\"#F59E0B\" />\n            <circle cx=\"192\" cy=\"38\" r=\"3\" fill=\"#F59E0B\" />\n\n            <!-- Rear Chimney Flue (뒤편 굴뚝 구멍) -->\n            <ellipse cx=\"275\" cy=\"55\" rx=\"18\" ry=\"8\" fill=\"#111111\" stroke=\"#888888\" stroke-width=\"1.5\" />\n            <path d=\"M 275 55 Q 290 20 285 5\" stroke=\"#888888\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-smoke)\" />\n\n            <!-- Front Air/Wood Opening (앞쪽 하부 흡입구) -->\n            <path d=\"M 30 180 Q 70 120 110 180\" fill=\"#0C0C0C\" stroke=\"#06B6D4\" stroke-width=\"2\" />\n\n            <!-- Internal Fire Draft Flow -->\n            <!-- Blue Oxygen entry -->\n            <path d=\"M 10 165 L 60 160\" stroke=\"#06B6D4\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-blue)\" />\n            <!-- Red Flame Rising to pot -->\n            <path d=\"M 80 155 Q 120 110 155 60\" stroke=\"#E02424\" stroke-width=\"2.5\" marker-end=\"url(#arrow-draft-red)\" />\n            <!-- Red Heat to rear chimney -->\n            <path d=\"M 140 100 Q 210 90 265 65\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3,3\" marker-end=\"url(#arrow-draft-red)\" />\n          </g>\n\n          <!-- Label 1: 앞쪽 하부 공기 흡입구 -->\n          <text x=\"75\" y=\"260\" fill=\"#06B6D4\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 앞쪽 하부 공기 흡입구 (산소 유입)\n          </text>\n          <text x=\"75\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            차가운 신선한 공기가 빨려 들어가는 길목\n          </text>\n\n          <!-- Label 2: 윗부분 평평한 조리용 구멍 -->\n          <line x1=\"320\" y1=\"100\" x2=\"220\" y2=\"70\" stroke=\"#E5E5E5\" stroke-width=\"1\" />\n          <text x=\"75\" y=\"90\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 윗부분 평평한 조리용 구멍\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비나 평평한 돌판을 얹는 화구\n          </text>\n\n          <!-- Label 3: 뒤편 상단 굴뚝 구멍 -->\n          <text x=\"445\" y=\"85\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 뒤편 상단 굴뚝 구멍\n          </text>\n          <text x=\"445\" y=\"103\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            매운 연기를 뒤로 뽑아내는 배출구\n          </text>\n\n          <!-- Label 4: 붉은 화살표 열기 순환 -->\n          <text x=\"400\" y=\"185\" fill=\"#E02424\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 솟구치는 열기 순환선\n          </text>\n          <text x=\"400\" y=\"203\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            연소실 안을 회전하며 냄비 바닥을 달굼\n          </text>\n\n          <!-- Label 5: 냄비를 얹어도 공기가 통하는 틈새 -->\n          <text x=\"390\" y=\"260\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 냄비 받침 통기 틈새 돌기\n          </text>\n          <text x=\"390\" y=\"278\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            냄비를 얹어도 불길이 막혀 꺼지지 않는 여유 공간\n          </text>\n        </svg>","content/svgs/pr06-step-05.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg viewBox=\"0 0 680 340\" class=\"w-full h-auto block\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Blueprint Header -->\n          <text x=\"75\" y=\"40\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">\n            FIG. 05 // CONTROLLED DEHYDRATION &amp; CERAMIC HARDENING\n          </text>\n          <line x1=\"75\" y1=\"48\" x2=\"605\" y2=\"48\" stroke=\"#222222\" stroke-width=\"1\" />\n\n          <!-- Main Curing Stove Illustration -->\n          <g transform=\"translate(180, 70)\">\n            <!-- Left Side (Dark Wet Clay) transitioning to Right Side (Bright Baked Ocher) -->\n            <path d=\"M 40 180 C 40 80 80 40 140 40 L 180 40 C 240 40 280 80 280 180 Z\" fill=\"#2A1E14\" stroke=\"#D97706\" stroke-width=\"1.5\" />\n            \n            <!-- Baked Ocher Highlight on right half -->\n            <path d=\"M 160 40 C 220 40 260 80 260 180 L 160 180 Z\" fill=\"#422812\" opacity=\"0.6\" />\n\n            <!-- Rising Steam Lines (외벽 수증기) -->\n            <path d=\"M 80 50 Q 70 30 85 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 120 45 Q 110 25 125 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 200 45 Q 190 25 205 5\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n            <path d=\"M 240 50 Q 230 30 245 10\" stroke=\"#888888\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\" fill=\"none\" />\n\n            <!-- Weak Ember Fire at Entry (작은 불씨) -->\n            <ellipse cx=\"60\" cy=\"175\" rx=\"20\" ry=\"8\" fill=\"#111111\" stroke=\"#333333\" stroke-width=\"1\" />\n            <circle cx=\"55\" cy=\"173\" r=\"3\" fill=\"#E02424\" />\n            <circle cx=\"65\" cy=\"175\" r=\"4\" fill=\"#F59E0B\" />\n            <circle cx=\"60\" cy=\"170\" r=\"2.5\" fill=\"#E5E5E5\" />\n\n            <!-- Small Surface Hairline Cracks being patched -->\n            <line x1=\"190\" y1=\"90\" x2=\"210\" y2=\"105\" stroke=\"#E5E5E5\" stroke-width=\"1\" stroke-dasharray=\"2,2\" />\n            <!-- Patch indicator circle -->\n            <circle cx=\"200\" cy=\"98\" r=\"8\" fill=\"none\" stroke=\"#10B981\" stroke-width=\"1.5\" />\n          </g>\n\n          <!-- Label 1: 입구에 지핀 작은 잔가지 불씨 -->\n          <text x=\"75\" y=\"270\" fill=\"#F59E0B\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ① 입구 작은 잔가지 불씨 (약한 열기)\n          </text>\n          <text x=\"75\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            강한 불 대신 은은한 열기로 시작\n          </text>\n\n          <!-- Label 2: 외벽에서 김(수증기)이 빠져나가는 모습 -->\n          <text x=\"75\" y=\"90\" fill=\"#AAAAAA\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ② 외벽 수증기 증발선\n          </text>\n          <text x=\"75\" y=\"108\" fill=\"#666666\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            내부 수분이 천천히 기화\n          </text>\n\n          <!-- Label 3: 진흙 색상 변화 -->\n          <text x=\"440\" y=\"90\" fill=\"#D97706\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ③ 색상 변화 관찰\n          </text>\n          <text x=\"440\" y=\"108\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            짙은 고동색 → 밝은 황토색\n          </text>\n\n          <!-- Label 4: 손을 댔을 때 따뜻한 열감 -->\n          <text x=\"440\" y=\"170\" fill=\"#10B981\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ④ 따뜻한 건조 완료 판정\n          </text>\n          <text x=\"440\" y=\"188\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            축축함 없이 외벽 전체가 훈훈\n          </text>\n\n          <!-- Label 5: 갈라진 미세 틈을 덧바를 진흙 반죽 여분 -->\n          <text x=\"390\" y=\"270\" fill=\"#E5E5E5\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"12\" font-weight=\"bold\">\n            ⑤ 미세 실금 덧바름 보수\n          </text>\n          <text x=\"390\" y=\"288\" fill=\"#888888\" font-family=\"'Space Grotesk', sans-serif\" font-size=\"10\">\n            남은 진흙 반죽으로 틈새 메우기\n          </text>\n        </svg>","content/svgs/pr07-outcome.svg":"<svg viewBox=\"0 0 800 450\" xmlns=\"http://www.w3.org/2000/svg\" class=\"w-full h-auto\">\n  <defs>\n    <linearGradient id=\"bgGradBowline\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0a0c0f\"/>\n      <stop offset=\"100%\" stop-color=\"#12161c\"/>\n    </linearGradient>\n\n    <!-- Timber Anchor Post Gradients -->\n    <linearGradient id=\"anchorPost\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#3d2c1e\"/>\n      <stop offset=\"50%\" stop-color=\"#694e36\"/>\n      <stop offset=\"100%\" stop-color=\"#2a1e14\"/>\n    </linearGradient>\n\n    <!-- Rope 3D Tubular Shading -->\n    <linearGradient id=\"mainRopeGold\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#b45309\"/>\n      <stop offset=\"50%\" stop-color=\"#fbbf24\"/>\n      <stop offset=\"100%\" stop-color=\"#78350f\"/>\n    </linearGradient>\n    <linearGradient id=\"workingTailGreen\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#14532d\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Technical Canvas Backdrop -->\n  <rect x=\"0\" y=\"0\" width=\"800\" height=\"450\" fill=\"url(#bgGradBowline)\"/>\n  <rect x=\"15\" y=\"15\" width=\"770\" height=\"420\" fill=\"none\" stroke=\"#222222\" stroke-width=\"1\"/>\n\n  <!-- Crosshairs -->\n  <path d=\"M 25 35 L 45 35 M 35 25 L 35 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 35 L 755 35 M 765 25 L 765 45\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 25 415 L 45 415 M 35 405 L 35 425\" stroke=\"#444\" stroke-width=\"1\"/>\n  <path d=\"M 775 415 L 755 415 M 765 405 L 765 425\" stroke=\"#444\" stroke-width=\"1\"/>\n\n  <!-- Metadata -->\n  <text x=\"35\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" letter-spacing=\"1\">ARCHIVE // OUTCOME SPECIFICATION</text>\n  <text x=\"35\" y=\"70\" fill=\"#E02424\" font-family=\"monospace\" font-size=\"11\" font-weight=\"bold\">TARGET: BOWLINE KNOT (매듭의 왕) [KING OF KNOTS SPEC]</text>\n  <text x=\"765\" y=\"55\" fill=\"#555\" font-family=\"monospace\" font-size=\"10\" text-anchor=\"end\">RELEASE TIME: 1.0 SEC</text>\n\n  <!-- Left Spec Box -->\n  <g id=\"specBoxLeft\" font-family=\"monospace\" font-size=\"10\">\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"155\" fill=\"#141414\" stroke=\"#333\" stroke-width=\"1\"/>\n    <rect x=\"45\" y=\"100\" width=\"180\" height=\"22\" fill=\"#1f1f1f\"/>\n    <text x=\"55\" y=\"115\" fill=\"#E02424\" font-weight=\"bold\">BOWLINE SPECS</text>\n    <text x=\"55\" y=\"140\" fill=\"#aaa\">· KNOT TYPE: FIXED LOOP</text>\n    <text x=\"55\" y=\"160\" fill=\"#aaa\">· SLIPPAGE: ZERO (0%)</text>\n    <text x=\"55\" y=\"180\" fill=\"#aaa\">· STRENGTH EFF: 75% RATING</text>\n    <text x=\"55\" y=\"200\" fill=\"#aaa\">· JAMMING: 100% JAM-PROOF</text>\n    <text x=\"55\" y=\"220\" fill=\"#aaa\">· RELEASE: BREAK THE BACK</text>\n    <text x=\"55\" y=\"240\" fill=\"#4ade80\">· LOAD CAPACITY: 500+ KG</text>\n  </g>\n\n  <!-- Ground Plane Shadow -->\n  <ellipse cx=\"430\" cy=\"400\" rx=\"230\" ry=\"18\" fill=\"#050608\" opacity=\"0.9\"/>\n\n  <!-- Anchor Timber Post (Right Anchor) -->\n  <!-- 1. Rope segment passing BEHIND post (Drawn before post) -->\n  <path d=\"M 440 310 C 470 330 520 330 550 310\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 440 310 C 470 330 520 330 550 310\" stroke=\"url(#mainRopeGold)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- 2. Timber Post Standing Solid -->\n  <polygon points=\"480,220 520,220 515,410 475,410\" fill=\"url(#anchorPost)\" stroke=\"#1a120b\" stroke-width=\"2\"/>\n  <ellipse cx=\"500\" cy=\"220\" rx=\"20\" ry=\"8\" fill=\"#4d3826\" stroke=\"#261b11\" stroke-width=\"1.5\"/>\n\n  <!-- 3. Rope segment passing IN FRONT OF post (Drawn after post) -->\n  <path d=\"M 550 310 C 530 270 470 270 440 280\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 550 310 C 530 270 470 270 440 280\" stroke=\"url(#mainRopeGold)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Main Bowline Knot Rigging Under Tension -->\n  <!-- Standing Line from top anchor -->\n  <path d=\"M 330 75 L 330 190\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <path d=\"M 330 75 L 330 190\" stroke=\"url(#mainRopeGold)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- The Nipper Loop Ring (토끼굴) -->\n  <path d=\"M 330 190 C 290 200 280 240 320 250 C 350 255 365 230 350 205 C 345 195 330 190 330 190\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 330 190 C 290 200 280 240 320 250 C 350 255 365 230 350 205 C 345 195 330 190 330 190\" stroke=\"url(#mainRopeGold)\" stroke-width=\"10\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Collar Loop (뒤통수 칼라 링) Wrapped Around Standing Line -->\n  <path d=\"M 325 245 C 310 230 305 195 330 185 C 360 175 375 210 350 245\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 325 245 C 310 230 305 195 330 185 C 360 175 375 210 350 245\" stroke=\"url(#workingTailGreen)\" stroke-width=\"10\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Working End Tail (Parallel beside eye loop line) -->\n  <path d=\"M 345 240 L 375 285\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n  <path d=\"M 345 240 L 375 285\" stroke=\"url(#workingTailGreen)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n\n  <!-- Loop Lead Going to Timber Post Anchor -->\n  <path d=\"M 320 250 C 310 280 370 300 440 310\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 320 250 C 310 280 370 300 440 310\" stroke=\"url(#mainRopeGold)\" stroke-width=\"10\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 440 280 C 400 270 365 260 345 240\" stroke=\"#050505\" stroke-width=\"16\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 440 280 C 400 270 365 260 345 240\" stroke=\"url(#mainRopeGold)\" stroke-width=\"10\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Tension Direction Arrows -->\n  <g stroke=\"#E02424\" stroke-width=\"2.5\" fill=\"none\">\n    <line x1=\"330\" y1=\"130\" x2=\"330\" y2=\"95\"/>\n    <polygon points=\"330,88 323,102 337,102\" fill=\"#E02424\"/>\n    <line x1=\"420\" y1=\"285\" x2=\"455\" y2=\"295\"/>\n    <polygon points=\"462,297 448,290 452,304\" fill=\"#E02424\"/>\n  </g>\n\n  <!-- Right Technical Panel: 1-Second Quick Release Mechanism -->\n  <g id=\"quickReleasePanel\">\n    <rect x=\"565\" y=\"90\" width=\"195\" height=\"180\" fill=\"#141414\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <rect x=\"565\" y=\"90\" width=\"195\" height=\"24\" fill=\"#241010\"/>\n    <text x=\"575\" y=\"106\" fill=\"#E02424\" font-weight=\"bold\">1-SEC BREAK-THE-BACK</text>\n\n    <!-- Finger Action Diagram -->\n    <text x=\"575\" y=\"132\" fill=\"#ffffff\" font-weight=\"bold\">칼라(뒤통수) 꺾기 원리</text>\n    <text x=\"575\" y=\"148\" fill=\"#aaa\">1. 매듭 뒤편 둥근 칼라 고리 확인</text>\n    <text x=\"575\" y=\"164\" fill=\"#aaa\">2. 엄지로 칼라를 바깥쪽으로 젖힘</text>\n    <text x=\"575\" y=\"180\" fill=\"#aaa\">3. 마찰 락 즉시 풀려 1초 만에 해체</text>\n\n    <!-- Mini Vector of the Release Action -->\n    <path d=\"M 610 230 C 630 205 670 205 690 230\" stroke=\"#fbbf24\" stroke-width=\"6\" fill=\"none\"/>\n    <line x1=\"650\" y1=\"235\" x2=\"650\" y2=\"210\" stroke=\"#4ade80\" stroke-width=\"2.5\"/>\n    <polygon points=\"650,202 643,215 657,215\" fill=\"#4ade80\"/>\n    <text x=\"660\" y=\"222\" fill=\"#4ade80\" font-size=\"9\">PUSH UP</text>\n    <text x=\"575\" y=\"255\" fill=\"#4ade80\" font-weight=\"bold\">JAM-PROOF // 칼날 불필요</text>\n  </g>\n\n  <!-- Technical Callouts -->\n  <g id=\"callouts\" font-family=\"monospace\" font-size=\"10\" fill=\"#cccccc\">\n    <!-- Callout 1: Standing Line -->\n    <line x1=\"330\" y1=\"130\" x2=\"380\" y2=\"130\" stroke=\"#888\" stroke-width=\"1\"/>\n    <circle cx=\"330\" cy=\"130\" r=\"2\" fill=\"#888\"/>\n    <text x=\"390\" y=\"126\" fill=\"#ffffff\" font-weight=\"bold\" text-anchor=\"start\">STANDING PART</text>\n    <text x=\"390\" y=\"139\" fill=\"#888888\" text-anchor=\"start\">하중을 받는 주 원줄</text>\n\n    <!-- Callout 2: Fixed Loop -->\n    <line x1=\"460\" y1=\"310\" x2=\"460\" y2=\"350\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n    <circle cx=\"460\" cy=\"310\" r=\"2\" fill=\"#38bdf8\"/>\n    <text x=\"460\" y=\"365\" fill=\"#38bdf8\" font-weight=\"bold\">FIXED EYE LOOP</text>\n    <text x=\"460\" y=\"378\" fill=\"#888888\">하중에도 줄어들지 않는 고리</text>\n\n    <!-- Callout 3: Working Tail -->\n    <line x1=\"375\" y1=\"280\" x2=\"330\" y2=\"330\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n    <circle cx=\"375\" cy=\"280\" r=\"2\" fill=\"#4ade80\"/>\n    <text x=\"320\" y=\"335\" fill=\"#4ade80\" font-weight=\"bold\" text-anchor=\"end\">WORKING END TAIL</text>\n    <text x=\"320\" y=\"348\" fill=\"#888888\" text-anchor=\"end\">고리 안쪽으로 단단히 잠김</text>\n  </g>\n</svg>\n","content/svgs/pr07-step-01.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"bg01\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"standingRope\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#c2883e\"/>\n      <stop offset=\"50%\" stop-color=\"#f5b867\"/>\n      <stop offset=\"100%\" stop-color=\"#946123\"/>\n    </linearGradient>\n    <linearGradient id=\"workingRope\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#166534\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg01)\"/>\n  <rect x=\"10\" y=\"10\" width=\"380\" height=\"380\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"20\" y=\"30\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 01 // BOWLINE STEP 1: 토끼굴 고리 형성</text>\n  <line x1=\"20\" y1=\"38\" x2=\"380\" y2=\"38\" stroke=\"#262626\" stroke-width=\"1\"/>\n\n  <!-- Standing Part of Rope (원줄 / 나무 기둥줄) -->\n  <!-- Outline Shadow -->\n  <path d=\"M 200 45 L 200 130\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 45 L 200 130\" stroke=\"url(#standingRope)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- The 6-shaped Loop (토끼굴) -->\n  <!-- Loop Back Arc (underneath) -->\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170 C 225 140 185 130 160 145\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170 C 225 140 185 130 160 145\" stroke=\"url(#standingRope)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Working End (작동 줄 - 녹색 토끼 줄) Crossing OVER the Standing Line -->\n  <!-- Crossing Segment with Clean Masking Shadow -->\n  <path d=\"M 160 145 C 130 160 100 210 110 270 L 115 310\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 160 145 C 130 160 100 210 110 270 L 115 310\" stroke=\"url(#workingRope)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Motion Twist Arrow Showing Clockwise Loop Formation -->\n  <path d=\"M 175 160 C 160 175 165 205 185 210 C 205 215 220 195 215 175\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"1.8\" stroke-dasharray=\"3 3\"/>\n  <polygon points=\"218,170 210,180 224,180\" fill=\"#E02424\"/>\n\n  <!-- Target Center Marker of the Rabbit Hole -->\n  <circle cx=\"190\" cy=\"180\" r=\"16\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <circle cx=\"190\" cy=\"180\" r=\"3\" fill=\"#38bdf8\"/>\n\n  <!-- Callout Indicators & Labels -->\n  <!-- 1. Standing Line Label (Top Right) -->\n  <line x1=\"205\" y1=\"80\" x2=\"280\" y2=\"80\" stroke=\"#888\" stroke-width=\"1\"/>\n  <circle cx=\"205\" cy=\"80\" r=\"2\" fill=\"#888\"/>\n  <text x=\"290\" y=\"78\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">STANDING PART</text>\n  <text x=\"290\" y=\"91\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 (서 있는 나무)</text>\n\n  <!-- 2. Rabbit Hole Label (Center Left) -->\n  <line x1=\"174\" y1=\"180\" x2=\"80\" y2=\"180\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <circle cx=\"174\" cy=\"180\" r=\"2\" fill=\"#38bdf8\"/>\n  <text x=\"20\" y=\"177\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RABBIT HOLE (고리)</text>\n  <text x=\"20\" y=\"190\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">숫자 6 모양의 토끼굴</text>\n\n  <!-- 3. Over-Cross Rule Label (Lower Right) -->\n  <rect x=\"180\" y=\"250\" width=\"200\" height=\"42\" fill=\"#181818\" stroke=\"#333\" stroke-width=\"1\"/>\n  <text x=\"190\" y=\"267\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">WORKING END (토끼)</text>\n  <text x=\"190\" y=\"281\" fill=\"#e0e0e0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">작동 끝단이 원줄 '위'로 교차</text>\n\n  <!-- Bottom Instruction Box -->\n  <rect x=\"20\" y=\"335\" width=\"360\" height=\"45\" fill=\"#141414\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"30\" y=\"352\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">[1단계 핵심] 원줄 위에 작동 줄을 얹어 6자 루프 형성</text>\n  <text x=\"30\" y=\"368\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">작동 줄이 반드시 원줄의 위쪽에 위치해야 잠금 구조가 완성됩니다.</text>\n</svg>","content/svgs/pr07-step-02.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"bg02\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"standingRope2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#c2883e\"/>\n      <stop offset=\"50%\" stop-color=\"#f5b867\"/>\n      <stop offset=\"100%\" stop-color=\"#946123\"/>\n    </linearGradient>\n    <linearGradient id=\"workingRope2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#166534\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg02)\"/>\n  <rect x=\"10\" y=\"10\" width=\"380\" height=\"380\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"20\" y=\"30\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 02 // BOWLINE STEP 2: 토끼굴 상향 탈출</text>\n  <line x1=\"20\" y1=\"38\" x2=\"380\" y2=\"38\" stroke=\"#262626\" stroke-width=\"1\"/>\n\n  <!-- Standing Part of Rope (원줄) -->\n  <path d=\"M 200 45 L 200 130\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 45 L 200 130\" stroke=\"url(#standingRope2)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Lower Main Loop Hanging Down (큰 메인 고리 형성 부) -->\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"url(#standingRope2)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- The 6-Loop (토끼굴) Ring Structure -->\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"url(#standingRope2)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Working End (녹색 토끼 줄) Penetrating UPWARDS from underneath the hole -->\n  <!-- Layer under loop entering back-to-front -->\n  <path d=\"M 250 280 C 240 240 200 220 190 200 L 190 120\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 250 280 C 240 240 200 220 190 200 L 190 120\" stroke=\"url(#workingRope2)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Front Crossing Over Ring Edge -->\n  <path d=\"M 200 130 C 175 135 160 145 160 145\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 130 C 175 135 160 145 160 145\" stroke=\"url(#standingRope2)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Upward Motion Vector Arrow (수직 상향 화살표) -->\n  <line x1=\"190\" y1=\"180\" x2=\"190\" y2=\"105\" stroke=\"#4ade80\" stroke-width=\"2.5\"/>\n  <polygon points=\"190,95 183,110 197,110\" fill=\"#4ade80\"/>\n\n  <!-- Callouts -->\n  <!-- 1. Upward Exit Label (Top Left) -->\n  <rect x=\"25\" y=\"70\" width=\"145\" height=\"42\" fill=\"#181818\" stroke=\"#333\" stroke-width=\"1\"/>\n  <text x=\"35\" y=\"87\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">EMERGE FROM HOLE</text>\n  <text x=\"35\" y=\"101\" fill=\"#e0e0e0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">굴 아래에서 위로 탈출</text>\n\n  <!-- 2. Rabbit Head Working Tip (Top Center) -->\n  <circle cx=\"190\" cy=\"120\" r=\"10\" fill=\"none\" stroke=\"#4ade80\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <text x=\"210\" y=\"115\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">토끼 머리 15cm</text>\n  <text x=\"210\" y=\"128\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">충분한 길이 인출</text>\n\n  <!-- 3. Lower Loop Description (Bottom Right) -->\n  <text x=\"260\" y=\"270\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">MAIN EYE LOOP</text>\n  <text x=\"260\" y=\"284\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">최종 하중을 받을 큰 고리</text>\n\n  <!-- Bottom Instruction Box -->\n  <rect x=\"20\" y=\"335\" width=\"360\" height=\"45\" fill=\"#141414\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"30\" y=\"352\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">[2단계 핵심] 굴 밑바닥에서 위쪽으로 토끼를 쑥 뽑아 올림</text>\n  <text x=\"30\" y=\"368\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">위에서 아래로 찌르면 매듭이 풀리는 올가미가 되므로 절대 주의하십시오.</text>\n</svg>","content/svgs/pr07-step-03.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"bg03\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"standingRope3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#c2883e\"/>\n      <stop offset=\"50%\" stop-color=\"#f5b867\"/>\n      <stop offset=\"100%\" stop-color=\"#946123\"/>\n    </linearGradient>\n    <linearGradient id=\"workingRope3\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#166534\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg03)\"/>\n  <rect x=\"10\" y=\"10\" width=\"380\" height=\"380\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"20\" y=\"30\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 03 // BOWLINE STEP 3: 나무(원줄) 뒤편 선회</text>\n  <line x1=\"20\" y1=\"38\" x2=\"380\" y2=\"38\" stroke=\"#262626\" stroke-width=\"1\"/>\n\n  <!-- Working Rope Behind the Standing Part (Draw First) -->\n  <path d=\"M 190 120 C 190 85 240 70 260 85 C 275 100 240 125 185 125\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 190 120 C 190 85 240 70 260 85 C 275 100 240 125 185 125\" stroke=\"url(#workingRope3)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Standing Part of Rope (원줄 나무 - Drawn in FRONT of the working rope) -->\n  <path d=\"M 200 45 L 200 130\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 45 L 200 130\" stroke=\"url(#standingRope3)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Working Rope Emerging to the Left (Drawn in Front) -->\n  <path d=\"M 185 125 C 150 125 140 160 160 185\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 185 125 C 150 125 140 160 160 185\" stroke=\"url(#workingRope3)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Main Hanging Eye Loop -->\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"url(#standingRope3)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- The 6-Loop (토끼굴) Ring Structure -->\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"url(#standingRope3)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Motion Curving Arrow Behind Tree -->\n  <path d=\"M 200 100 Q 255 80 250 110 Q 230 130 170 130\" fill=\"none\" stroke=\"#E02424\" stroke-width=\"2\" stroke-dasharray=\"3 3\"/>\n  <polygon points=\"160,130 172,124 172,136\" fill=\"#E02424\"/>\n\n  <!-- Callouts -->\n  <!-- 1. Around Behind Tree (Top Right) -->\n  <rect x=\"235\" y=\"55\" width=\"145\" height=\"42\" fill=\"#181818\" stroke=\"#333\" stroke-width=\"1\"/>\n  <text x=\"245\" y=\"72\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">AROUND THE TREE</text>\n  <text x=\"245\" y=\"86\" fill=\"#e0e0e0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄 '뒤쪽'을 감아 돔</text>\n\n  <!-- 2. Standing Trunk (Top Left) -->\n  <line x1=\"200\" y1=\"65\" x2=\"130\" y2=\"65\" stroke=\"#888\" stroke-width=\"1\"/>\n  <circle cx=\"200\" cy=\"65\" r=\"2\" fill=\"#888\"/>\n  <text x=\"50\" y=\"62\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">TREE (나무 기둥줄)</text>\n  <text x=\"50\" y=\"75\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">토끼가 돌아 나갈 중심 축</text>\n\n  <!-- 3. Target Re-Entry Point (Center Left) -->\n  <circle cx=\"170\" cy=\"190\" r=\"12\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <text x=\"20\" y=\"210\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">RE-ENTRY READY</text>\n  <text x=\"20\" y=\"223\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">다시 굴로 진입할 준비</text>\n\n  <!-- Bottom Instruction Box -->\n  <rect x=\"20\" y=\"335\" width=\"360\" height=\"45\" fill=\"#141414\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"30\" y=\"352\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">[3단계 핵심] 굴에서 나온 토끼가 원줄 뒤편을 감싸 돎</text>\n  <text x=\"30\" y=\"368\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">반드시 원줄의 '뒤'로 돌아야 단단히 조여지는 칼라(Collar) 루프가 만들어집니다.</text>\n</svg>","content/svgs/pr07-step-04.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"bg04\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"standingRope4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#c2883e\"/>\n      <stop offset=\"50%\" stop-color=\"#f5b867\"/>\n      <stop offset=\"100%\" stop-color=\"#946123\"/>\n    </linearGradient>\n    <linearGradient id=\"workingRope4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#166534\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg04)\"/>\n  <rect x=\"10\" y=\"10\" width=\"380\" height=\"380\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"20\" y=\"30\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 04 // BOWLINE STEP 4: 토끼굴 재진입</text>\n  <line x1=\"20\" y1=\"38\" x2=\"380\" y2=\"38\" stroke=\"#262626\" stroke-width=\"1\"/>\n\n  <!-- Back Turn of Working Rope Behind Tree -->\n  <path d=\"M 210 130 C 210 85 255 75 270 90 C 285 110 240 125 180 125\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 210 130 C 210 85 255 75 270 90 C 285 110 240 125 180 125\" stroke=\"url(#workingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Standing Part of Rope (원줄 나무 - Drawn in Front) -->\n  <path d=\"M 200 45 L 200 130\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 200 45 L 200 130\" stroke=\"url(#standingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Main Hanging Eye Loop -->\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 160 145 C 130 160 110 220 130 280 C 150 320 220 320 250 280 C 270 250 260 210 240 170\" stroke=\"url(#standingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- The 6-Loop (토끼굴) Ring Structure -->\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 200 130 C 130 140 130 220 200 230 C 240 235 260 210 240 170\" stroke=\"url(#standingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- First Upward Strand (from Step 2) -->\n  <path d=\"M 230 250 C 220 210 210 170 210 130\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 230 250 C 220 210 210 170 210 130\" stroke=\"url(#workingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Working End Diving DOWN into the Rabbit Hole (Drawn in Front) -->\n  <path d=\"M 180 125 C 150 135 155 180 175 220 L 180 250\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 180 125 C 150 135 155 180 175 220 L 180 250\" stroke=\"url(#workingRope4)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Downward Motion Vector Arrow -->\n  <line x1=\"162\" y1=\"145\" x2=\"175\" y2=\"215\" stroke=\"#4ade80\" stroke-width=\"2.5\"/>\n  <polygon points=\"178,225 168,212 181,210\" fill=\"#4ade80\"/>\n\n  <!-- Callouts -->\n  <!-- 1. Diving Down Label (Top Left) -->\n  <rect x=\"25\" y=\"65\" width=\"145\" height=\"42\" fill=\"#181818\" stroke=\"#333\" stroke-width=\"1\"/>\n  <text x=\"35\" y=\"82\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">BACK INTO HOLE</text>\n  <text x=\"35\" y=\"96\" fill=\"#e0e0e0\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">위에서 아래로 재진입</text>\n\n  <!-- 2. Parallel Pair in the Loop (Center Right) -->\n  <circle cx=\"195\" cy=\"235\" r=\"16\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/>\n  <line x1=\"211\" y1=\"235\" x2=\"265\" y2=\"235\" stroke=\"#38bdf8\" stroke-width=\"1\"/>\n  <text x=\"275\" y=\"232\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PARALLEL STRANDS</text>\n  <text x=\"275\" y=\"245\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">두 가닥이 나란히 정렬</text>\n\n  <!-- 3. Collar Forming (Top Right) -->\n  <line x1=\"250\" y1=\"110\" x2=\"310\" y2=\"140\" stroke=\"#f5b867\" stroke-width=\"1\"/>\n  <circle cx=\"250\" cy=\"110\" r=\"2\" fill=\"#f5b867\"/>\n  <text x=\"275\" y=\"152\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">COLLAR LOOP</text>\n  <text x=\"275\" y=\"165\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">나무를 감싼 뒤통수 고리</text>\n\n  <!-- Bottom Instruction Box -->\n  <rect x=\"20\" y=\"335\" width=\"360\" height=\"45\" fill=\"#141414\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"30\" y=\"352\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">[4단계 핵심] 토끼가 굴 속으로 다시 쏙 들어감</text>\n  <text x=\"30\" y=\"368\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">나무를 돌아 나온 끝단을 처음 나왔던 토끼굴에 위에서 아래로 찔러 넣습니다.</text>\n</svg>","content/svgs/pr07-step-05.svg":"<svg viewBox=\"0 0 400 400\" class=\"w-full h-full\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradient id=\"bg05\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#0d0d0d\"/>\n      <stop offset=\"100%\" stop-color=\"#141414\"/>\n    </linearGradient>\n    <linearGradient id=\"standingRope5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#c2883e\"/>\n      <stop offset=\"50%\" stop-color=\"#f5b867\"/>\n      <stop offset=\"100%\" stop-color=\"#946123\"/>\n    </linearGradient>\n    <linearGradient id=\"workingRope5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#15803d\"/>\n      <stop offset=\"50%\" stop-color=\"#4ade80\"/>\n      <stop offset=\"100%\" stop-color=\"#166534\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Background Canvas -->\n  <rect width=\"400\" height=\"400\" fill=\"url(#bg05)\"/>\n  <rect x=\"10\" y=\"10\" width=\"380\" height=\"380\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/>\n\n  <!-- Blueprint Header -->\n  <text x=\"20\" y=\"30\" fill=\"#666666\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" letter-spacing=\"1\">FIG. 05 // BOWLINE STEP 5: 락킹 및 1초 해체</text>\n  <line x1=\"20\" y1=\"38\" x2=\"380\" y2=\"38\" stroke=\"#262626\" stroke-width=\"1\"/>\n\n  <!-- Standing Line Under Strong Tension (Upward) -->\n  <path d=\"M 180 45 L 180 150\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 180 45 L 180 150\" stroke=\"url(#standingRope5)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Tightened Nipper Loop (조여진 토끼굴 루프) -->\n  <path d=\"M 180 150 C 150 160 140 190 170 200 C 195 205 205 185 195 165 C 190 155 180 150 180 150\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 180 150 C 150 160 140 190 170 200 C 195 205 205 185 195 165 C 190 155 180 150 180 150\" stroke=\"url(#standingRope5)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Collar Loop Around Standing Line (뒤통수 칼라 링) -->\n  <path d=\"M 175 195 C 160 185 155 155 180 145 C 205 140 215 170 195 195\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 175 195 C 160 185 155 155 180 145 C 205 140 215 170 195 195\" stroke=\"url(#workingRope5)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Parallel Working Tail & Main Eye Loop (Tightly Pinched Together) -->\n  <!-- Working End Tail -->\n  <path d=\"M 190 190 L 220 230\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\"/>\n  <path d=\"M 190 190 L 220 230\" stroke=\"url(#workingRope5)\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n\n  <!-- Main Fixed Eye Loop (Hanging Rigid Below) -->\n  <path d=\"M 170 200 C 130 240 120 280 150 310 C 180 330 220 330 240 300 C 260 270 240 230 220 200\" stroke=\"#050505\" stroke-width=\"14\" stroke-linecap=\"round\" fill=\"none\"/>\n  <path d=\"M 170 200 C 130 240 120 280 150 310 C 180 330 220 330 240 300 C 260 270 240 230 220 200\" stroke=\"url(#standingRope5)\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"none\"/>\n\n  <!-- Cinching Grip Indicator (Hand Grip Zone) -->\n  <ellipse cx=\"205\" cy=\"215\" rx=\"20\" ry=\"24\" fill=\"none\" stroke=\"#4ade80\" stroke-width=\"1.8\" stroke-dasharray=\"3 2\"/>\n\n  <!-- Tension Vector Arrows -->\n  <!-- Upward Pull on Standing Line -->\n  <line x1=\"180\" y1=\"90\" x2=\"180\" y2=\"55\" stroke=\"#E02424\" stroke-width=\"2.5\"/>\n  <polygon points=\"180,48 173,62 187,62\" fill=\"#E02424\"/>\n\n  <!-- Downward Pull on Eye Loop -->\n  <line x1=\"205\" y1=\"260\" x2=\"205\" y2=\"295\" stroke=\"#E02424\" stroke-width=\"2.5\"/>\n  <polygon points=\"205,302 198,288 212,288\" fill=\"#E02424\"/>\n\n  <!-- 1-Sec Quick Release \"Break the Back\" Indicator Box (Right Side) -->\n  <g id=\"quickReleaseBox\">\n    <rect x=\"250\" y=\"70\" width=\"135\" height=\"100\" fill=\"#181818\" stroke=\"#E02424\" stroke-width=\"1\"/>\n    <text x=\"260\" y=\"88\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">1-SEC QUICK RELEASE</text>\n    <text x=\"260\" y=\"103\" fill=\"#ffffff\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">뒤통수(칼라) 꺾기 비법</text>\n\n    <!-- Finger Push Motion Diagram -->\n    <path d=\"M 280 145 C 295 125 320 125 335 145\" stroke=\"#f5b867\" stroke-width=\"4\" fill=\"none\"/>\n    <line x1=\"307\" y1=\"148\" x2=\"307\" y2=\"128\" stroke=\"#4ade80\" stroke-width=\"2\"/>\n    <polygon points=\"307,122 302,132 312,132\" fill=\"#4ade80\"/>\n    <text x=\"260\" y=\"160\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">엄지로 칼라를 꺾으면 즉시 해체</text>\n  </g>\n\n  <!-- Callouts -->\n  <!-- 1. Pull Standing Line (Top Left) -->\n  <text x=\"40\" y=\"75\" fill=\"#f5b867\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">PULL STANDING</text>\n  <text x=\"40\" y=\"88\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">원줄을 위로 강하게 당김</text>\n\n  <!-- 2. Grip Together (Center Right) -->\n  <line x1=\"225\" y1=\"215\" x2=\"270\" y2=\"215\" stroke=\"#4ade80\" stroke-width=\"1\"/>\n  <circle cx=\"225\" cy=\"215\" r=\"2\" fill=\"#4ade80\"/>\n  <text x=\"280\" y=\"212\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">GRIP TOGETHER</text>\n  <text x=\"280\" y=\"225\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">끝단과 고리를 한 손에 쥠</text>\n\n  <!-- 3. Fixed Loop (Bottom Left) -->\n  <text x=\"25\" y=\"280\" fill=\"#38bdf8\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">LOCKED FIXED LOOP</text>\n  <text x=\"25\" y=\"293\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">하중을 받아도 크기 불변</text>\n\n  <!-- Bottom Instruction Box -->\n  <rect x=\"20\" y=\"335\" width=\"360\" height=\"45\" fill=\"#141414\" stroke=\"#262626\" stroke-width=\"1\"/>\n  <text x=\"30\" y=\"352\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"10\" font-weight=\"bold\">[5단계 핵심] 양손으로 잡고 반대로 당겨 락킹 체결</text>\n  <text x=\"30\" y=\"368\" fill=\"#888888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"9\">풀 때는 매듭 뒤편 칼라 링을 엄지로 젖히면 칼 없이 1초 만에 풀립니다.</text>\n</svg>","content/svgs/step-01.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 190\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Grid background lines -->\n  <line x1=\"20\" y1=\"20\" x2=\"260\" y2=\"20\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"95\" x2=\"260\" y2=\"95\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"20\" y1=\"170\" x2=\"260\" y2=\"170\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"140\" y1=\"10\" x2=\"140\" y2=\"180\" stroke=\"#222\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></line>\n\n  <!-- Bottle / Cylinder Cone Outer Contour -->\n  <path d=\"M70 25 L210 25 L180 145 L155 165 L125 165 L100 145 Z\" stroke=\"#F5F5F5\" stroke-width=\"1.5\" fill=\"#161616\"></path>\n\n  <!-- Flow direction arrows on top (Raw water input) -->\n  <path d=\"M140 8 L140 22 M136 18 L140 22 L144 18\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n  <text x=\"148\" y=\"18\" fill=\"#AAAAAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\">흙탕물 붓기</text>\n\n  <!-- Layer 1: Pebbles (Top) -->\n  <path d=\"M74 38 L206 38 L197 62 L83 62 Z\" fill=\"#222222\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Gravel particles -->\n  <circle cx=\"100\" cy=\"48\" r=\"4.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"120\" cy=\"52\" r=\"5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"140\" cy=\"46\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"160\" cy=\"53\" r=\"5.5\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <circle cx=\"180\" cy=\"47\" r=\"4\" stroke=\"#FFFFFF\" stroke-width=\"1\" fill=\"none\"></circle>\n  <!-- Text label -->\n  <line x1=\"196\" y1=\"50\" x2=\"202\" y2=\"50\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"46\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">1. 자갈 (큰 먼지 걸러냄)</text>\n\n  <!-- Layer 2: Fine Sand -->\n  <path d=\"M83 62 L197 62 L189 95 L91 95 Z\" fill=\"#1b1b1b\" stroke=\"#444\" stroke-width=\"0.75\"></path>\n  <!-- Sand stippling lines -->\n  <line x1=\"100\" y1=\"72\" x2=\"180\" y2=\"72\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <line x1=\"96\" y1=\"80\" x2=\"184\" y2=\"80\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  <line x1=\"102\" y1=\"88\" x2=\"178\" y2=\"88\" stroke=\"#666\" stroke-width=\"0.8\" stroke-dasharray=\"1 3\"></line>\n  <!-- Text label -->\n  <line x1=\"75\" y1=\"78\" x2=\"88\" y2=\"78\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"74\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">2. 고운 모래 (작은 먼지)</text>\n\n  <!-- Layer 3: Charcoal Powder -->\n  <path d=\"M91 95 L189 95 L180 132 L100 132 Z\" fill=\"#080808\" stroke=\"#555\" stroke-width=\"0.75\"></path>\n  <!-- Charcoal hatch pattern -->\n  <line x1=\"105\" y1=\"104\" x2=\"175\" y2=\"104\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"108\" y1=\"113\" x2=\"172\" y2=\"113\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <line x1=\"112\" y1=\"122\" x2=\"168\" y2=\"122\" stroke=\"#444\" stroke-width=\"1.2\"></line>\n  <rect x=\"128\" y=\"102\" width=\"24\" height=\"20\" stroke=\"#FFF\" stroke-width=\"0.8\" fill=\"none\"></rect>\n  <text x=\"131\" y=\"115\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" font-weight=\"bold\">숯가루</text>\n  <!-- Text label -->\n  <line x1=\"185\" y1=\"115\" x2=\"195\" y2=\"115\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"275\" y=\"111\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"end\">3. 숯가루 (독소·냄새 제거)</text>\n\n  <!-- Layer 4: Cloth Mesh Base -->\n  <path d=\"M100 132 L180 132 L165 152 L115 152 Z\" fill=\"#2d2d2d\" stroke=\"#666\" stroke-width=\"0.75\"></path>\n  <path d=\"M110 142 L170 142\" stroke=\"#FFF\" stroke-width=\"1\" stroke-dasharray=\"2 1\"></path>\n  <!-- Text label -->\n  <line x1=\"108\" y1=\"145\" x2=\"35\" y2=\"145\" stroke=\"#777\" stroke-width=\"0.8\"></line>\n  <text x=\"5\" y=\"148\" fill=\"#EEEEEE\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\">4. 천·이끼 마개 (입구 막기)</text>\n\n  <!-- Dripping water drops (Clear water output) -->\n  <line x1=\"140\" y1=\"165\" x2=\"140\" y2=\"178\" stroke=\"#FFFFFF\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <circle cx=\"140\" cy=\"183\" r=\"2.5\" fill=\"#FFFFFF\"></circle>\n</svg>","content/svgs/step-02.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 150\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Vessel receiving unfiltered and discarding 1st flush -->\n  <!-- Bucket 1 (Discard - Turbid) -->\n  <rect x=\"35\" y=\"65\" width=\"70\" height=\"60\" stroke=\"#666\" stroke-width=\"1.2\" fill=\"#141414\"></rect>\n  <line x1=\"35\" y1=\"95\" x2=\"105\" y2=\"95\" stroke=\"#444\" stroke-width=\"1\"></line>\n  <path d=\"M40 100 Q70 105 100 100\" stroke=\"#777\" stroke-width=\"0.75\" stroke-dasharray=\"2 2\"></path>\n  <text x=\"42\" y=\"85\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[첫 1~2컵 버리기]</text>\n  <text x=\"44\" y=\"115\" fill=\"#777\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">검은 숯가루 섞인 물</text>\n  <line x1=\"70\" y1=\"40\" x2=\"70\" y2=\"60\" stroke=\"#E02424\" stroke-width=\"1.2\" stroke-dasharray=\"2 2\"></line>\n  <path d=\"M68 55 L70 60 L72 55\" stroke=\"#E02424\" stroke-width=\"1.2\"></path>\n\n  <!-- Flow divider symbol -->\n  <text x=\"125\" y=\"85\" fill=\"#FFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"12\">→</text>\n\n  <!-- Bucket 2 (Keep - Clean Pre-filtered) -->\n  <rect x=\"165\" y=\"65\" width=\"75\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"165\" y1=\"90\" x2=\"240\" y2=\"90\" stroke=\"#888\" stroke-width=\"1\"></line>\n  <!-- Water level indicator -->\n  <line x1=\"170\" y1=\"105\" x2=\"235\" y2=\"105\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <line x1=\"170\" y1=\"115\" x2=\"235\" y2=\"115\" stroke=\"#FFF\" stroke-width=\"0.75\" stroke-dasharray=\"3 2\"></line>\n  <text x=\"175\" y=\"82\" fill=\"#FFFFFF\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" font-weight=\"bold\">[맑은 물 받아 쓰기]</text>\n  <text x=\"175\" y=\"135\" fill=\"#999\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">투명해진 깨끗한 물</text>\n  <line x1=\"202\" y1=\"40\" x2=\"202\" y2=\"60\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></line>\n  <path d=\"M200 55 L202 60 L204 55\" stroke=\"#FFFFFF\" stroke-width=\"1.2\"></path>\n\n  <!-- Drip speed gauge -->\n  <text x=\"15\" y=\"25\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"8\" text-anchor=\"start\">떨어지는 속도: 1초에 1~2방울</text>\n  <circle cx=\"202\" cy=\"22\" r=\"3\" fill=\"#FFF\"></circle>\n</svg>","content/svgs/step-03.svg":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg class=\"w-full max-w-[320px] h-auto\" viewBox=\"0 0 280 155\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- Boiling Pot Diagram -->\n  <rect x=\"30\" y=\"45\" width=\"80\" height=\"60\" stroke=\"#FFF\" stroke-width=\"1.5\" fill=\"#181818\"></rect>\n  <line x1=\"20\" y1=\"55\" x2=\"30\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <line x1=\"110\" y1=\"55\" x2=\"120\" y2=\"55\" stroke=\"#FFF\" stroke-width=\"1.5\"></line>\n  <!-- Rolling boil violent bubbles -->\n  <circle cx=\"50\" cy=\"75\" r=\"4\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"70\" cy=\"65\" r=\"5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"90\" cy=\"72\" r=\"3.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"60\" cy=\"85\" r=\"3\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <circle cx=\"80\" cy=\"88\" r=\"4.5\" stroke=\"#FFF\" stroke-width=\"1\"></circle>\n  <!-- Steam waves -->\n  <path d=\"M50 35 Q55 25 50 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M70 35 Q75 25 70 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <path d=\"M90 35 Q95 25 90 15\" stroke=\"#888\" stroke-width=\"1\"></path>\n  <!-- Campfire underneath -->\n  <path d=\"M40 115 L70 106 L100 115\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <path d=\"M55 125 L70 110 L85 125\" stroke=\"#E02424\" stroke-width=\"1.5\"></path>\n  <text x=\"70\" y=\"137\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"middle\">100°C 불에 끓이기</text>\n\n  <!-- Threshold timer graph on right -->\n  <line x1=\"145\" y1=\"120\" x2=\"255\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  <line x1=\"145\" y1=\"25\" x2=\"145\" y2=\"120\" stroke=\"#555\" stroke-width=\"1\"></line>\n  \n  <!-- Curve -->\n  <path d=\"M145 110 Q175 95 190 40 L250 40\" stroke=\"#FFFFFF\" stroke-width=\"1.5\" fill=\"none\"></path>\n  <line x1=\"190\" y1=\"20\" x2=\"190\" y2=\"120\" stroke=\"#E02424\" stroke-width=\"0.8\" stroke-dasharray=\"2 2\"></line>\n  \n  <text x=\"148\" y=\"35\" fill=\"#AAA\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\">100°C</text>\n  <text x=\"192\" y=\"32\" fill=\"#E02424\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" font-weight=\"bold\">3분 이상 끓이기</text>\n  <text x=\"255\" y=\"65\" fill=\"#4ade80\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7.5\" text-anchor=\"end\">세균 99.9% 제거</text>\n  \n  <text x=\"200\" y=\"133\" fill=\"#888\" font-family=\"'JetBrains Mono', monospace\" font-size=\"7\" text-anchor=\"middle\">팔팔 끓이는 시간 (분)</text>\n</svg>","NEXT_TOPIC_PROMPT.md":"# 📌 차기 생존 프로토콜 기획서: PR-08 - 나뭇가지 3개와 바위로 짐승 잡는 법 (숫자 4 모양 돌 덫)\n\n- **도메인**: 야생 식량 & 수렵 공학 > 무동력 중력식 낙하 덫 제작 (Tier 1)\n- **위급도**: CRITICAL\n- **결핍 상황**: 야생 식물 채집만으로는 필수 지방과 단백질을 채울 수 없어 급격한 근육 손실과 체력 고갈이 일어납니다. 맨몸으로 동물을 쫓는 것은 지나친 칼로리 낭비이므로, 자는 동안에도 스스로 작동하는 중력식 함정이 반드시 필요합니다.\n- **과학 원리**: 지레의 원리와 아슬아슬한 마찰력의 균형을 이용합니다. 세 개의 나뭇가지를 '숫자 4' 형태로 맞물려 무거운 바위를 지탱하다가, 미끼를 건드리는 미세한 힘(수평 분력)으로 균형이 깨지면 바위의 위치 에너지가 즉시 낙하 충격으로 전환됩니다.\n- **투입 자연물**:\n  - 손가락 굵기의 단단한 마른 나뭇가지 3개\n  - 넓적하고 무거운 돌 (10~15kg)\n  - 끝을 뾰족하게 다듬을 날카로운 돌 조각\n\n---\n\n## 🖼️ [필수 사전 프리뷰] 16:9 초고화질 완성 결과물 도면 (Target Outcome)\n- **도면 파일명**: `pr08-outcome.svg` (16:9 와이드스크린, 800×450)\n- **도면 내용**: 완성되어 실전에 세팅된 4자 덫과 거치된 15kg 평평한 바위의 전체 입체 투시도. 3대 접점(트리거)에 작용하는 마찰 평형선 및 미세 터치 시의 낙하 분력 방향 화살표, 트리거 제원 패널을 모노라인/입체 셰이딩으로 표현.\n\n---\n\n## 📋 3단계 도면 및 실행 지침\n\n### [Step 01] 세 가지 핵심 나뭇가지 다듬기\n- **실행**: 손가락 굵기의 곧은 나뭇가지 세 개를 준비합니다. 첫 번째는 바닥에 세울 '수직 기둥(끝을 끌 모양으로 깎음)', 두 번째는 돌을 받칠 '대각선 버팀대(양 끝에 홈을 팜)', 세 번째는 미끼를 꽂을 '수평 미끼대(기둥과 맞물릴 홈을 팜)'로 돌날을 이용해 깎아냅니다.\n- **도면 파일명**: `pr08-step-01.svg`\n- **도면 초점**: 수직 기둥, 대각선 버팀목, 수평 미끼대의 홈 가공 단면도 및 치수 비례도\n\n### [Step 02] 숫자 4 모양으로 홈 맞물리기\n- **실행**: 수직 기둥의 윗부분에 대각선 버팀대의 윗홈을 걸칩니다. 이어 수평 미끼대를 기둥의 중간 홈에 대고, 대각선 버팀대의 아랫홈을 미끼대의 끝단 홈에 걸어 세 막대가 서로 밀어내는 힘만으로 자립하는 '숫자 4' 뼈대를 완성합니다.\n- **도면 파일명**: `pr08-step-02.svg`\n- **도면 초점**: 세 막대가 결합되어 '4' 형태를 이루는 마찰 결속 지점의 확대 구조도\n\n### [Step 03] 바위 거치 및 미끼 장착\n- **실행**: 미끼대 안쪽 끝에 열매나 벌레 등 먹이를 꽂은 뒤, 결합된 틀의 대각선 막대 윗부분에 10~15kg의 넓적한 바위를 조심스럽게 기대어 놓습니다. 바위 밑으로 짐승이 머리를 넣고 미끼를 살짝 당기는 즉시 뼈대가 무너지도록 민감도를 점검합니다.\n- **도면 파일명**: `pr08-step-03.svg`\n- **도면 초점**: 기울어진 바위 아래 4자 뼈대와 안쪽 미끼가 세팅된 전체 측면 입체 투시도\n\n---\n\n## ⚠️ 꼭 피해야 할 실수 (Fatal Mistake)\n- **흔한 실수**: 돌이 너무 가볍거나, 막대 결합 홈을 너무 깊게 파서 뻑뻑하게 만드는 실수\n- **위험한 결과**: 짐승이 미끼를 흔들어도 덫이 떨어지지 않아 밥만 빼앗기거나, 돌에 맞아도 다치기만 한 채 도망쳐 덫의 위치만 노출됨\n- **핵심 주의사항**: 돌 무게는 잡으려는 동물 체중의 3~5배 이상 무거워야 하며, 결합 홈은 걸릴 듯 말 듯 날카롭고 얕게 다듬어 스치기만 해도 0.1초 만에 풀리도록 설치해야 함\n\n---\n\n## 🎨 스티치(Stitch) 생성용 마스터 프롬프트\n```text\nA precise field blueprint drawn with charcoal and graphite on aged dark slate, illustrating the Figure-4 Deadfall Trap mechanics.\n- Target Outcome (16:9 Widescreen): Full perspective of the set trap under a 15kg flat rock with tension equilibrium vectors, sensitive trigger points, and quick-collapse mechanism.\n- Step 1: The three wooden triggers with exact notch dimensions (vertical post, diagonal support, horizontal bait stick).\n- Step 2: The exploded mechanical assembly forming the numeral '4' shape under counter-pressure.\n- Step 3: Full field deployment showing the rock leaning at 45 degrees over the bait stick trigger.\nUtilitarian Brutalism style, pure monochrome technical linework, zero text-graphic collision, strict physical accuracy.\n```\n"};

export function ensureContentAvailable() {
  const defaultProtocolsDir = path.join(projectRoot, 'content/protocols');
  const defaultLocalesDir = path.join(projectRoot, 'content/protocols/locales');
  if (
    fs.existsSync(defaultProtocolsDir) &&
    fs.readdirSync(defaultProtocolsDir).some((f) => f.endsWith('.json')) &&
    fs.existsSync(defaultLocalesDir) &&
    fs.readdirSync(defaultLocalesDir).some((f) => f.endsWith('.es.json'))
  ) {
    return projectRoot;
  }

  const fallbackRoot = path.join(os.tmpdir(), 'survival-bundled-root');
  for (const [relPath, content] of Object.entries(EMBEDDED_CONTENT)) {
    const targetPath = path.join(fallbackRoot, relPath);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    fs.writeFileSync(targetPath, content, 'utf-8');
  }
  process.env.SURVIVAL_ROOT_DIR = fallbackRoot;
  return fallbackRoot;
}
